{
  "name": "Tower of Echoes: Isekai Survivors",
  "description": "A 2D top-down action roguelike set in a fantasy world. Choose your archetype, climb the Goddess Tower, and build powerful automatic combos."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum GameState {
  LOBBY = 'LOBBY',
  PLAYING = 'PLAYING',
  PAUSED = 'PAUSED', // Upgrading is a paused state
  GAME_OVER = 'GAME_OVER',
  VICTORY = 'VICTORY'
}

export enum Archetype {
  WARRIOR = 'WARRIOR', // Melee, Tanky
  ARCHER = 'ARCHER',   // Ranged, Fast
  MAGE = 'MAGE'        // Area, Magic
}

export interface Stats {
  maxHp: number;
  hp: number;
  damage: number;
  speed: number;
  defense: number;
  cooldownReduction: number; // 0 to 1
  pickupRange: number;
  areaSize: number;
}

export interface Player {
  x: number;
  y: number;
  archetype: Archetype;
  stats: Stats;
  level: number;
  xp: number;
  xpToNextLevel: number;
  weaponTimer: number;
  facing: number; // angle in radians
}

export interface Enemy {
  id: string;
  x: number;
  y: number;
  type: 'SLIME' | 'GOBLIN' | 'DEMON';
  hp: number;
  maxHp: number;
  speed: number;
  damage: number;
  radius: number;
}

export interface Projectile {
  id: string;
  x: number;
  y: number;
  vx: number;
  vy: number;
  damage: number;
  duration: number;
  radius: number;
  type: 'ARROW' | 'MAGIC_ORB' | 'SWORD_SLASH' | 'AURA';
  color: string;
  pierce: number;
}

export interface Particle {
  id: string;
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  color: string;
  size: number;
}

export interface DamageNumber {
  id: string;
  x: number;
  y: number;
  value: number;
  life: number;
  isCrit: boolean;
}

export interface Upgrade {
  id: string;
  name: string;
  description: string;
  type: 'STAT' | 'WEAPON' | 'PASSIVE';
  icon: string;
  rarity: 'COMMON' | 'RARE' | 'EPIC' | 'LEGENDARY';
  apply: (player: Player) => void;
}

export interface WaveConfig {
  duration: number; // in seconds
  enemyCount: number;
  spawnRate: number; // ms between spawns
}

import { Archetype, Stats, WaveConfig } from './types';

// Canvas
export const CANVAS_WIDTH = window.innerWidth;
export const CANVAS_HEIGHT = window.innerHeight;

// Game Settings
export const WAVE_DURATION = 120; // 2 minutes per wave as requested
export const TOTAL_WAVES = 10;
export const FPS = 60;

// Colors
export const COLORS = {
  background: '#1a1a2e',
  grid: '#16213e',
  uiBg: 'rgba(15, 23, 42, 0.9)',
  [Archetype.WARRIOR]: '#3b82f6', // Blue
  [Archetype.ARCHER]: '#22c55e',  // Green
  [Archetype.MAGE]: '#a855f7',    // Purple
  enemy: '#ef4444',
  xp: '#fbbf24',
  text: '#f8fafc'
};

// Initial Stats
export const BASE_STATS: Record<Archetype, Stats> = {
  [Archetype.WARRIOR]: {
    maxHp: 200, hp: 200, damage: 15, speed: 3, defense: 5,
    cooldownReduction: 0, pickupRange: 100, areaSize: 1.0
  },
  [Archetype.ARCHER]: {
    maxHp: 100, hp: 100, damage: 10, speed: 5, defense: 0,
    cooldownReduction: 0, pickupRange: 120, areaSize: 1.0
  },
  [Archetype.MAGE]: {
    maxHp: 120, hp: 120, damage: 25, speed: 3.5, defense: 1,
    cooldownReduction: 0.1, pickupRange: 150, areaSize: 1.2
  }
};

export const UPGRADES_LIST = [
  { id: 'str_up', name: 'Might', desc: 'Increases Damage by 10%', type: 'STAT', rarity: 'COMMON' },
  { id: 'spd_up', name: 'Haste', desc: 'Increases Movement Speed', type: 'STAT', rarity: 'COMMON' },
  { id: 'hp_up', name: 'Vitality', desc: 'Increases Max HP', type: 'STAT', rarity: 'COMMON' },
  { id: 'cdr_up', name: 'Focus', desc: 'Reduces Cooldowns by 5%', type: 'STAT', rarity: 'RARE' },
  { id: 'area_up', name: 'Expansion', desc: 'Increases Area of Effect', type: 'STAT', rarity: 'RARE' },
  { id: 'heal', name: 'Recovery', desc: 'Heal 30% HP instantly', type: 'STAT', rarity: 'COMMON' },
];

export const WAVE_CONFIGS: WaveConfig[] = Array(10).fill({
  duration: WAVE_DURATION,
  enemyCount: 50,
  spawnRate: 500
}).map((config, i) => ({
  ...config,
  enemyCount: 50 + (i * 20),
  spawnRate: Math.max(100, 500 - (i * 30))
}));

