        <div className="flex gap-8">
           <span className="flex items-center gap-2 hover:text-white cursor-pointer transition-colors"><Store size={16}/> Merchant</span>
           <span className="flex items-center gap-2 hover:text-white cursor-pointer transition-colors"><MapPin size={16}/> Island Map</span>
        </div>
