};

export const UPGRADES_LIST: Upgrade[] = [
  { id: 'str_up', name: 'Might', description: 'Increases Damage by 10%', type: 'STAT', rarity: 'COMMON' },
  { id: 'spd_up', name: 'Haste', description: 'Increases Movement Speed', type: 'STAT', rarity: 'COMMON' },
  { id: 'hp_up', name: 'Vitality', description: 'Increases Max HP', type: 'STAT', rarity: 'COMMON' },
  { id: 'cdr_up', name: 'Focus', description: 'Reduces Cooldowns by 5%', type: 'STAT', rarity: 'RARE' },
  { id: 'area_up', name: 'Expansion', description: 'Increases Area of Effect', type: 'STAT', rarity: 'RARE' },
  { id: 'heal', name: 'Recovery', description: 'Heal 30% HP instantly', type: 'STAT', rarity: 'COMMON' },
];

export const WAVE_CONFIGS: WaveConfig[] = Array(10).fill({
  duration: WAVE_DURATION,
  enemyCount: 50,
  spawnRate: 500
}).map((config, i) => ({
  ...config,
  enemyCount: 50 + (i * 20),
