import React, { useEffect, useRef, useState } from 'react';
import { Player, Enemy, Projectile, GameState, Archetype, Particle, DamageNumber, Upgrade } from '../types';
import { CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, BASE_STATS, WAVE_CONFIGS, UPGRADES_LIST, WAVE_DURATION } from '../constants';
import { UpgradeModal } from './UpgradeModal';
import { Heart, Clock, Skull, Zap } from 'lucide-react';

interface GameCanvasProps {
  archetype: Archetype;
  onGameOver: () => void;
}

export const GameCanvas: React.FC<GameCanvasProps> = ({ archetype, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Game State Refs (Mutable for performance)
  const gameStateRef = useRef<GameState>(GameState.PLAYING);
  const playerRef = useRef<Player>({
    x: 0, y: 0,
    archetype,
    stats: JSON.parse(JSON.stringify(BASE_STATS[archetype])),
    level: 1,
    xp: 0,
    xpToNextLevel: 100,
    weaponTimer: 0,
    facing: 0
  });
  const enemiesRef = useRef<Enemy[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const damageNumbersRef = useRef<DamageNumber[]>([]);
  const keysRef = useRef<{ [key: string]: boolean }>({});

  // Time and Wave management
  const timeRef = useRef<number>(0); // Total playtime in seconds
  const waveRef = useRef<number>(0);
  const waveTimerRef = useRef<number>(0); // Time in current wave
  const lastSpawnTimeRef = useRef<number>(0);

  // Upgrade State (React State for UI)
  const [showUpgrade, setShowUpgrade] = useState(false);
  const [upgradeOptions, setUpgradeOptions] = useState<Upgrade[]>([]);
  const [lastUpgrade, setLastUpgrade] = useState<Upgrade | null>(null);
  const [hudStats, setHudStats] = useState({ hp: 100, maxHp: 100, time: 0, wave: 1, level: 1, killCount: 0 });

  // Mouse position for aiming
  const mouseRef = useRef({ x: 0, y: 0 });

  // Initialize
  useEffect(() => {
    // Input listeners
    const handleKeyDown = (e: KeyboardEvent) => { keysRef.current[e.code] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keysRef.current[e.code] = false; };
    const handleMouseMove = (e: MouseEvent) => {
      mouseRef.current = { 
        x: e.clientX - CANVAS_WIDTH / 2, 
        y: e.clientY - CANVAS_HEIGHT / 2 
      };
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousemove', handleMouseMove);

    let animationFrameId: number;
    let lastTime = performance.now();

    const loop = (timestamp: number) => {
      const dt = (timestamp - lastTime) / 1000;
      lastTime = timestamp;

      if (gameStateRef.current === GameState.PLAYING) {
        update(dt);
      }
      draw();
      animationFrameId = requestAnimationFrame(loop);
    };

    animationFrameId = requestAnimationFrame(loop);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousemove', handleMouseMove);
      cancelAnimationFrame(animationFrameId);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // --- Logic Helpers ---

  const spawnEnemy = () => {
    const config = WAVE_CONFIGS[waveRef.current] || WAVE_CONFIGS[WAVE_CONFIGS.length - 1];
    if (enemiesRef.current.length >= config.enemyCount) return;

    // Spawn randomly outside screen
    const angle = Math.random() * Math.PI * 2;
    const distance = Math.max(CANVAS_WIDTH, CANVAS_HEIGHT) / 2 + 100;
    const ex = playerRef.current.x + Math.cos(angle) * distance;
    const ey = playerRef.current.y + Math.sin(angle) * distance;

    const types: ('SLIME' | 'GOBLIN' | 'DEMON')[] = ['SLIME', 'GOBLIN', 'DEMON'];
    const type = types[Math.min(2, Math.floor(waveRef.current / 3))];

    let stats = { hp: 20, maxHp: 20, speed: 100, damage: 5, radius: 15 };
    if (type === 'GOBLIN') stats = { hp: 50, maxHp: 50, speed: 130, damage: 10, radius: 18 };
    if (type === 'DEMON') stats = { hp: 150, maxHp: 150, speed: 90, damage: 20, radius: 25 };

    // Scale with wave
    const scaling = 1 + (waveRef.current * 0.2);
    stats.hp *= scaling;
    stats.maxHp *= scaling;
    stats.damage *= scaling;

    enemiesRef.current.push({
      id: Math.random().toString(),
      x: ex,
      y: ey,
      type,
      ...stats
    });
  };

  const createDamageNumber = (x: number, y: number, damage: number, isCrit: boolean) => {
    damageNumbersRef.current.push({
      id: Math.random().toString(),
      x: x + (Math.random() * 20 - 10),
      y: y - 20,
      value: Math.floor(damage),
      life: 1,
      isCrit
    });
  };

  const createParticle = (x: number, y: number, color: string) => {
     particlesRef.current.push({
       id: Math.random().toString(),
       x, y,
       vx: (Math.random() - 0.5) * 100,
       vy: (Math.random() - 0.5) * 100,
       life: 0.5 + Math.random() * 0.5,
       maxLife: 1,
       color,
       size: Math.random() * 3 + 1
     });
  };

  const triggerUpgrade = () => {
    gameStateRef.current = GameState.PAUSED;

    // Generate random upgrades
    const options: Upgrade[] = [];
    for(let i=0; i<4; i++) {
        const rand = UPGRADES_LIST[Math.floor(Math.random() * UPGRADES_LIST.length)];
        // Clone to avoid reference issues
        options.push({...rand, id: rand.id + Math.random()}); 
    }

    setUpgradeOptions(options);
    setShowUpgrade(true);
  };

  const applyUpgrade = (upgrade: Upgrade) => {
    const player = playerRef.current;

    // Actual upgrade logic
    if (upgrade.name === 'Might') player.stats.damage *= 1.1;
    if (upgrade.name === 'Haste') player.stats.speed *= 1.1;
    if (upgrade.name === 'Vitality') { player.stats.maxHp += 50; player.stats.hp += 50; }
    if (upgrade.name === 'Focus') player.stats.cooldownReduction = Math.min(0.8, player.stats.cooldownReduction + 0.05);
    if (upgrade.name === 'Recovery') player.stats.hp = Math.min(player.stats.maxHp, player.stats.hp + (player.stats.maxHp * 0.3));
    if (upgrade.name === 'Expansion') player.stats.areaSize *= 1.2;

    setLastUpgrade(upgrade);
    setShowUpgrade(false);
    gameStateRef.current = GameState.PLAYING;

    // Reset wave timer if it was a wave clear
    if (waveTimerRef.current >= WAVE_CONFIGS[0].duration) {
         waveRef.current++;
         waveTimerRef.current = 0;
    }
  };

  // --- Main Update Loop ---

  const update = (dt: number) => {
    const player = playerRef.current;

    // 1. Time Management
    timeRef.current += dt;
    waveTimerRef.current += dt;

    // Check Wave End (every 2 minutes)
    const currentConfig = WAVE_CONFIGS[waveRef.current] || WAVE_CONFIGS[9];
    if (waveTimerRef.current >= currentConfig.duration) {
      triggerUpgrade();
      return; // Stop update for this frame
    }

    // 2. Player Movement
    let dx = 0;
    let dy = 0;
    if (keysRef.current['KeyW'] || keysRef.current['ArrowUp']) dy -= 1;
    if (keysRef.current['KeyS'] || keysRef.current['ArrowDown']) dy += 1;
    if (keysRef.current['KeyA'] || keysRef.current['ArrowLeft']) dx -= 1;
    if (keysRef.current['KeyD'] || keysRef.current['ArrowRight']) dx += 1;

    // Normalize diagonal
    if (dx !== 0 || dy !== 0) {
      const length = Math.sqrt(dx * dx + dy * dy);
      dx /= length;
      dy /= length;
      player.x += dx * player.stats.speed * 60 * dt; // speed 5 * 60 = 300px/s
      player.y += dy * player.stats.speed * 60 * dt;
      player.facing = Math.atan2(dy, dx);
    }

    // 3. Spawning
    if (Date.now() - lastSpawnTimeRef.current > currentConfig.spawnRate) {
      spawnEnemy();
      lastSpawnTimeRef.current = Date.now();
    }

    // 4. Combat (Auto Attack)
    player.weaponTimer -= dt;
    if (player.weaponTimer <= 0) {
      // Find nearest enemy
      let nearestDist = Infinity;
      let target: Enemy | null = null;

      enemiesRef.current.forEach(e => {
        const dist = Math.hypot(e.x - player.x, e.y - player.y);
        if (dist < nearestDist) {
          nearestDist = dist;
          target = e;
        }
      });

      // Attack Logic based on Archetype
      let didAttack = false;
      const cooldownBase = 1.0 * (1 - player.stats.cooldownReduction);

      if (player.archetype === Archetype.WARRIOR) {
        // Area slash around player
        projectilesRef.current.push({
          id: Math.random().toString(),
          x: player.x, y: player.y,
          vx: 0, vy: 0,
          damage: player.stats.damage,
          duration: 0.3,
          radius: 80 * player.stats.areaSize,
          type: 'SWORD_SLASH',
          color: COLORS[Archetype.WARRIOR],
          pierce: 999
        });
        player.weaponTimer = 0.8 * cooldownBase;
        didAttack = true;
      } 
      else if (player.archetype === Archetype.ARCHER && target && nearestDist < 600) {
        // Fire arrow
        const angle = Math.atan2(target.y - player.y, target.x - player.x);
        projectilesRef.current.push({
          id: Math.random().toString(),
          x: player.x, y: player.y,
          vx: Math.cos(angle) * 600,
          vy: Math.sin(angle) * 600,
          damage: player.stats.damage,
          duration: 2,
          radius: 5 * player.stats.areaSize,
          type: 'ARROW',
          color: COLORS[Archetype.ARCHER],
          pierce: 1
        });
        player.weaponTimer = 0.4 * cooldownBase;
        didAttack = true;
      }
      else if (player.archetype === Archetype.MAGE && target && nearestDist < 500) {
         // Magic Orb
         projectilesRef.current.push({
          id: Math.random().toString(),
          x: target.x, y: target.y, // Spawns ON enemy
          vx: 0, vy: 0,
          damage: player.stats.damage * 1.5,
          duration: 1.5,
          radius: 60 * player.stats.areaSize,
          type: 'MAGIC_ORB', // Persistent area
          color: COLORS[Archetype.MAGE],
          pierce: 999
        });
        player.weaponTimer = 1.5 * cooldownBase;
        didAttack = true;
      }

      if (!didAttack) {
         player.weaponTimer = 0.1; // Check again soon if no target found
      }
    }

    // 5. Update Projectiles
    projectilesRef.current = projectilesRef.current.filter(p => {
      p.duration -= dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;

      // Follow player if it's a melee slash
      if (p.type === 'SWORD_SLASH') {
        p.x = player.x;
        p.y = player.y;
      }

      return p.duration > 0;
    });

    // 6. Update Enemies & Collision
    enemiesRef.current = enemiesRef.current.filter(enemy => {
      // Move towards player
      const angle = Math.atan2(player.y - enemy.y, player.x - enemy.x);
      enemy.x += Math.cos(angle) * enemy.speed * dt;
      enemy.y += Math.sin(angle) * enemy.speed * dt;

      // Player Collision (Damage)
      const distToPlayer = Math.hypot(enemy.x - player.x, enemy.y - player.y);
      if (distToPlayer < 20 + enemy.radius) {
        const damage = Math.max(1, enemy.damage - player.stats.defense);
        player.stats.hp -= damage * dt; // DPS
        if (Math.random() > 0.9) createDamageNumber(player.x, player.y, damage, false); // Visual clutter reduction
      }

      // Projectile Collision
      projectilesRef.current.forEach(proj => {
         const dist = Math.hypot(proj.x - enemy.x, proj.y - enemy.y);
         if (dist < proj.radius + enemy.radius) {
            // Hit!
            // Simple invulnerability frame logic could go here, but for now we rely on pierce or destroy
            if (proj.pierce > 0) {
               // Only take damage once per projectile ID roughly (simplified)
               // Actual implementations use a 'hitList' on projectile
               enemy.hp -= proj.damage * 60 * dt; // Apply damage scaled by frame (hacky for continuous hitboxes)

               if (proj.type === 'ARROW') {
                   proj.pierce--;
                   enemy.hp -= proj.damage; // Instant damage for arrow
                   createDamageNumber(enemy.x, enemy.y, proj.damage, false);
               } else {
                   // AoE damage tick
                   if (Math.random() > 0.9) createDamageNumber(enemy.x, enemy.y, proj.damage, false);
               }
            }
         }
      });

      if (enemy.hp <= 0) {
        // Die
        for(let i=0; i<5; i++) createParticle(enemy.x, enemy.y, COLORS.xp);
        player.xp += 10;
        return false;
      }
      return true;
    });

    // 7. Update Particles
    particlesRef.current = particlesRef.current.filter(p => {
      p.life -= dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      return p.life > 0;
    });

    // 8. Update Numbers
    damageNumbersRef.current = damageNumbersRef.current.filter(d => {
        d.life -= dt;
        d.y -= 20 * dt; // Float up
        return d.life > 0;
    });

    // 9. Game Over check
    if (player.stats.hp <= 0) {
        gameStateRef.current = GameState.GAME_OVER;
        onGameOver();
    }

    // Sync HUD
    setHudStats({
        hp: player.stats.hp,
        maxHp: player.stats.maxHp,
        time: timeRef.current,
        wave: waveRef.current + 1,
        level: player.level,
        killCount: 0 // Not tracked yet
    });
  };

  // --- Rendering ---

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Reset Canvas
    canvas.width = CANVAS_WIDTH;
    canvas.height = CANVAS_HEIGHT;

    // Camera Transform
    ctx.save();
    const cx = CANVAS_WIDTH / 2 - playerRef.current.x;
    const cy = CANVAS_HEIGHT / 2 - playerRef.current.y;
    ctx.translate(cx, cy);

    // 1. Draw Background Grid (Simulate world movement)
    ctx.strokeStyle = COLORS.grid;
    ctx.lineWidth = 1;
    const gridSize = 100;

    // Viewport cull optimization
    const startX = Math.floor((playerRef.current.x - CANVAS_WIDTH/2) / gridSize) * gridSize;
    const startY = Math.floor((playerRef.current.y - CANVAS_HEIGHT/2) / gridSize) * gridSize;

    for (let x = startX; x < startX + CANVAS_WIDTH + gridSize; x += gridSize) {
      ctx.beginPath(); ctx.moveTo(x, startY); ctx.lineTo(x, startY + CANVAS_HEIGHT + gridSize); ctx.stroke();
    }
    for (let y = startY; y < startY + CANVAS_HEIGHT + gridSize; y += gridSize) {
      ctx.beginPath(); ctx.moveTo(startX, y); ctx.lineTo(startX + CANVAS_WIDTH + gridSize, y); ctx.stroke();
    }

    // 2. Draw Floor Decoration (Center of Island/Tower Base)
    if (Math.abs(playerRef.current.x) < 1000 && Math.abs(playerRef.current.y) < 1000) {
        ctx.fillStyle = '#1e293b';
        ctx.beginPath(); ctx.arc(0,0, 400, 0, Math.PI*2); ctx.fill();
        ctx.strokeStyle = '#334155';
        ctx.lineWidth = 5;
        ctx.stroke();
    }

    // 3. Draw Enemies
    enemiesRef.current.forEach(e => {
       ctx.fillStyle = COLORS.enemy;
       ctx.beginPath(); ctx.arc(e.x, e.y, e.radius, 0, Math.PI * 2); ctx.fill();
       // Health bar
       ctx.fillStyle = 'red';
       ctx.fillRect(e.x - 10, e.y - e.radius - 8, 20, 4);
       ctx.fillStyle = 'lime';
       ctx.fillRect(e.x - 10, e.y - e.radius - 8, 20 * (e.hp/e.maxHp), 4);
    });

    // 4. Draw Player
    const p = playerRef.current;
    ctx.fillStyle = COLORS[p.archetype];
    ctx.shadowBlur = 15;
    ctx.shadowColor = COLORS[p.archetype];

    ctx.beginPath();
    // Simple shape variation based on class
    if (p.archetype === Archetype.WARRIOR) ctx.rect(p.x - 15, p.y - 15, 30, 30);
    else if (p.archetype === Archetype.ARCHER) {
        ctx.moveTo(p.x + 15, p.y); ctx.lineTo(p.x-10, p.y+10); ctx.lineTo(p.x-10, p.y-10);
    }
    else ctx.arc(p.x, p.y, 15, 0, Math.PI * 2);

    ctx.fill();
    ctx.shadowBlur = 0;

    // 5. Draw Projectiles
    projectilesRef.current.forEach(proj => {
        ctx.fillStyle = proj.color;
        ctx.globalAlpha = 0.7;

        if (proj.type === 'SWORD_SLASH') {
           ctx.beginPath(); ctx.arc(proj.x, proj.y, proj.radius, 0, Math.PI*2); ctx.stroke();
           ctx.fillStyle = `${proj.color}33`; // Transparent
           ctx.fill();
        } else if (proj.type === 'MAGIC_ORB') {
           ctx.beginPath(); ctx.arc(proj.x, proj.y, proj.radius, 0, Math.PI*2); ctx.fill();
           ctx.strokeStyle = '#fff'; ctx.stroke();
        } else {
           ctx.beginPath(); ctx.arc(proj.x, proj.y, proj.radius, 0, Math.PI*2); ctx.fill();
        }
        ctx.globalAlpha = 1;
    });

    // 6. Draw Particles
    particlesRef.current.forEach(part => {
        ctx.fillStyle = part.color;
        ctx.globalAlpha = part.life / part.maxLife;
        ctx.beginPath(); ctx.arc(part.x, part.y, part.size, 0, Math.PI*2); ctx.fill();
        ctx.globalAlpha = 1;
    });

    // 7. Draw Damage Numbers
    ctx.font = 'bold 16px sans-serif';
    ctx.textAlign = 'center';
    damageNumbersRef.current.forEach(dn => {
        ctx.fillStyle = dn.isCrit ? '#facc15' : '#fff';
        ctx.fillText(Math.floor(dn.value).toString(), dn.x, dn.y);
    });

    ctx.restore();
  };

  // --- HUD Component ---
  const formatTime = (secs: number) => {
    const m = Math.floor(secs / 60);
    const s = Math.floor(secs % 60);
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  return (
    <div className="relative w-full h-full">
      <canvas ref={canvasRef} className="block w-full h-full cursor-crosshair" />

      {/* HUD Layer */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start pointer-events-none">
        {/* Health & XP */}
        <div className="flex flex-col gap-2 w-64">
           <div className="bg-slate-900/80 border border-slate-700 rounded-lg p-2 backdrop-blur-sm">
              <div className="flex items-center gap-2 mb-1">
                 <Heart className="text-red-500 fill-red-500" size={20} />
                 <span className="font-bold text-lg">{Math.ceil(hudStats.hp)} / {Math.ceil(hudStats.maxHp)}</span>
              </div>
              <div className="w-full h-2 bg-slate-700 rounded-full overflow-hidden">
                 <div className="h-full bg-red-500 transition-all duration-300" style={{width: `${(hudStats.hp/hudStats.maxHp)*100}%`}}></div>
              </div>
           </div>

           <div className="bg-slate-900/80 border border-slate-700 rounded-lg p-2 backdrop-blur-sm">
              <div className="flex justify-between text-xs text-yellow-400 font-bold uppercase mb-1">
                  <span>Level {hudStats.level}</span>
                  <span>XP</span>
              </div>
              <div className="w-full h-1 bg-slate-700 rounded-full overflow-hidden">
                 <div className="h-full bg-yellow-400" style={{width: '45%'}}></div>
              </div>
           </div>
        </div>

        {/* Timer & Wave */}
        <div className="flex flex-col items-center bg-slate-900/80 border border-slate-700 rounded-lg p-3 backdrop-blur-sm px-6">
           <div className="text-3xl font-mono font-bold text-white tracking-widest">{formatTime(hudStats.time)}</div>
           <div className="text-slate-400 text-sm flex items-center gap-2">
             <Skull size={14} /> Wave {hudStats.wave}
           </div>
           {/* Wave Progress Bar */}
           <div className="w-full h-1 bg-slate-700 mt-2 rounded-full overflow-hidden">
               <div className="h-full bg-blue-500 transition-all duration-1000" 
                    style={{width: `${(waveTimerRef.current / WAVE_DURATION) * 100}%`}}></div>
           </div>
        </div>

        {/* Mini-map / Objectives placeholder */}
        <div className="w-32 opacity-0 md:opacity-100">
           {/* Intentionally empty for balance */}
        </div>
      </div>

      {showUpgrade && (
        <UpgradeModal 
          options={upgradeOptions} 
          memoryOption={lastUpgrade}
          onSelect={applyUpgrade} 
        />
      )}
    </div>
  );
};

export enum GameState {
  CHAR_SELECT = 'CHAR_SELECT', // Menu de seleção
  ISLAND = 'ISLAND',           // Lobby jogável (Andar livre)
  TOWER = 'TOWER',             // Gameplay de combate
  PAUSED = 'PAUSED',           // Tela de Upgrade
  GAME_OVER = 'GAME_OVER',
  VICTORY = 'VICTORY'
}

export enum Archetype {
  WARRIOR = 'WARRIOR', // Guerreiro
  ARCHER = 'ARCHER',   // Arqueiro
  MAGE = 'MAGE'        // Mago
}

export interface Stats {
  maxHp: number;
  hp: number;
  damage: number;
  speed: number;
  defense: number;
  cooldownReduction: number; // 0 a 1
  pickupRange: number;
  areaSize: number;
}

export interface Player {
  x: number;
  y: number;
  archetype: Archetype;
  stats: Stats;
  level: number;
  xp: number;
  xpToNextLevel: number;

  // Cooldowns
  weaponTimer: number;
  skill1Timer: number; // Habilidade Secundária (Direita)
  skill1MaxCooldown: number;
  dashTimer: number;   // Habilidade Movimento (Espaço)
  dashMaxCooldown: number;

  facing: number; // radianos (olhando para o mouse)
  isMoving: boolean;
}

export interface Enemy {
  id: string;
  x: number;
  y: number;
  type: 'SLIME' | 'GOBLIN' | 'DEMON';
  hp: number;
  maxHp: number;
  speed: number;
  damage: number;
  radius: number; // Raio visual
  hitboxRadius: number; // Raio de colisão (menor)
  frame: number; // Para animação
}

export interface Projectile {
  id: string;
  x: number;
  y: number;
  vx: number;
  vy: number;
  damage: number;
  duration: number;
  radius: number;
  type: 'ARROW' | 'MAGIC_ORB' | 'SWORD_SLASH' | 'AXE_THROW' | 'FIREBALL' | 'ICE_SHARD';
  color: string;
  pierce: number;
}

export interface Particle {
  id: string;
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  color: string;
  size: number;
}

export interface DamageNumber {
  id: string;
  x: number;
  y: number;
  value: number;
  life: number;
  isCrit: boolean;
}

export interface Upgrade {
  id: string;
  name: string;
  description: string;
  type: 'STAT' | 'WEAPON' | 'PASSIVE';
  rarity: 'COMMON' | 'RARE' | 'EPIC' | 'LEGENDARY';
}

export interface WaveConfig {
  duration: number; // em segundos
  enemyCount: number;
  spawnRate: number; // ms entre spawns
}

