  return (
    <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md animate-in fade-in duration-300">
      <div className="w-full max-w-5xl px-4">
        <div className="text-center mb-10">
          <h2 className="text-4xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-amber-200 to-yellow-500 mb-2">
            Ecos de Poder
          </h2>
          <p className="text-slate-300">Escolha uma bênção para fortalecer sua alma na Torre.</p>
        </div>

        <div className="grid grid-cols-5 gap-4">
          {options.slice(0, 4).map((upgrade, idx) => (
            <button
              key={`${upgrade.id}-${idx}`}
              onClick={() => onSelect(upgrade)}
              className="bg-slate-800 border border-slate-600 hover:border-yellow-400 hover:bg-slate-700 rounded-lg p-4 h-80 flex flex-col items-center justify-between transition-all hover:-translate-y-1 hover:shadow-xl hover:shadow-yellow-500/20 group relative overflow-hidden"
            >
               {/* Rarity Glow */}
               <div className={`absolute top-0 right-0 p-1 px-3 text-xs font-bold rounded-bl-lg
                 ${upgrade.rarity === 'COMMON' ? 'bg-slate-600' : ''}
                 ${upgrade.rarity === 'RARE' ? 'bg-blue-600' : ''}
                 ${upgrade.rarity === 'EPIC' ? 'bg-purple-600' : ''}
                 ${upgrade.rarity === 'LEGENDARY' ? 'bg-amber-600' : ''}
               `}>
                 {upgrade.rarity}
               </div>

              <div className="mt-8 p-4 bg-slate-900 rounded-full ring-2 ring-slate-700 group-hover:ring-yellow-400 transition-all">
                {getIcon(upgrade.type)}
              </div>
              <div className="text-center">
                <h3 className="text-xl font-bold text-white mb-2">{upgrade.name}</h3>
                <p className="text-sm text-slate-400">{upgrade.description}</p>
              </div>
              <div className="w-full py-2 bg-slate-700 rounded text-sm group-hover:bg-yellow-500 group-hover:text-black font-semibold transition-colors">
                Selecionar
              </div>
            </button>
          ))}

          {/* Memory Slot (5th Slot) */}
          <button
            onClick={() => memoryOption ? onSelect(memoryOption) : onSelect(options[0])}
            disabled={!memoryOption && !options[0]}
            className="bg-slate-900 border border-purple-500/50 hover:border-purple-400 hover:bg-slate-800 rounded-lg p-4 h-80 flex flex-col items-center justify-between transition-all hover:-translate-y-1 hover:shadow-xl hover:shadow-purple-500/20 group relative"
          >
            <div className="absolute top-2 left-2 text-purple-400">
               <Repeat size={16} />
            </div>
             <div className="absolute top-0 right-0 bg-purple-900/80 p-1 px-3 text-xs font-bold rounded-bl-lg text-purple-200">
                 MEMÓRIA
               </div>

            <div className="mt-8 p-4 bg-purple-900/30 rounded-full ring-2 ring-purple-900 group-hover:ring-purple-400 transition-all">
               <RefreshCcw className="text-purple-300" />
            </div>
            <div className="text-center">
              <h3 className="text-xl font-bold text-purple-200 mb-2">
                {memoryOption ? "Repetir Último" : "Eco Vazio"}
              </h3>
              <p className="text-sm text-purple-300/70">
                {memoryOption 
                  ? `Duplicar escolha anterior: ${memoryOption.name}` 
                  : "O eco está silencioso. (Aleatório)"}
              </p>
            </div>
             <div className="w-full py-2 bg-purple-900/50 rounded text-sm group-hover:bg-purple-500 group-hover:text-white font-semibold transition-colors">
                {memoryOption ? "Repetir" : "Aleatório"}
              </div>
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { Player, Enemy, Projectile, GameState, Archetype, Particle, DamageNumber, Upgrade } from '../types';
import { CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, BASE_STATS, WAVE_CONFIGS, UPGRADES_LIST, WAVE_DURATION, SKILL_CONFIG } from '../constants';
import { UpgradeModal } from './UpgradeModal';
import { Heart, Skull, Zap, MapPin, MousePointer2 } from 'lucide-react';

interface GameCanvasProps {
  archetype: Archetype;
  onGameOver: () => void;
}

export const GameCanvas: React.FC<GameCanvasProps> = ({ archetype, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const islandCanvasRef = useRef<HTMLCanvasElement | null>(null); // Buffer para o mapa da ilha

  // Game State
  const gameStateRef = useRef<GameState>(GameState.ISLAND); // Começa na ilha
  const playerRef = useRef<Player>({
    x: 0, y: 0, // 0,0 é o centro da ilha
    archetype,
    stats: JSON.parse(JSON.stringify(BASE_STATS[archetype])),
    level: 1,
    xp: 0,
    xpToNextLevel: 100,
    weaponTimer: 0,
    skill1Timer: 0,
    skill1MaxCooldown: SKILL_CONFIG[archetype].skill1Cd,
    dashTimer: 0,
    dashMaxCooldown: SKILL_CONFIG[archetype].dashCd,
    facing: 0,
    isMoving: false
  });

  const enemiesRef = useRef<Enemy[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const damageNumbersRef = useRef<DamageNumber[]>([]);
  const keysRef = useRef<{ [key: string]: boolean }>({});

  // Time management
  const timeRef = useRef<number>(0); 
  const waveRef = useRef<number>(0);
  const waveTimerRef = useRef<number>(0);
  const lastSpawnTimeRef = useRef<number>(0);

  // UI State
  const [showUpgrade, setShowUpgrade] = useState(false);
  const [upgradeOptions, setUpgradeOptions] = useState<Upgrade[]>([]);
  const [lastUpgrade, setLastUpgrade] = useState<Upgrade | null>(null);
  const [hudData, setHudData] = useState({ 
      hp: 100, maxHp: 100, time: 0, wave: 1, level: 1, 
      state: GameState.ISLAND, skill1Cd: 0, dashCd: 0 
  });

  const mouseRef = useRef({ x: 0, y: 0 });

  // --- Inicialização de Assets Procedurais ---
  useEffect(() => {
    // Criar o mapa da ilha offscreen apenas uma vez
    if (!islandCanvasRef.current) {
        const iCanvas = document.createElement('canvas');
        iCanvas.width = 2000;
        iCanvas.height = 2000;
        const iCtx = iCanvas.getContext('2d');
        if (iCtx) {
            // Fundo Água
            iCtx.fillStyle = '#0f172a';
            iCtx.fillRect(0,0, 2000, 2000);

            // Ilha (Círculo Irregular)
            iCtx.fillStyle = '#1e293b'; // Base rochosa
            iCtx.beginPath();
            iCtx.arc(1000, 1000, 800, 0, Math.PI*2);
            iCtx.fill();

            // Grama
            iCtx.fillStyle = '#064e3b';
            iCtx.beginPath();
            iCtx.arc(1000, 1000, 750, 0, Math.PI*2);
            iCtx.fill();

            // Rio Procedural
            iCtx.strokeStyle = '#3b82f6';
            iCtx.lineWidth = 60;
            iCtx.beginPath();
            iCtx.moveTo(250, 1000);
            iCtx.bezierCurveTo(500, 1200, 1500, 800, 1750, 1000);
            iCtx.stroke();

            // Ponte
            iCtx.fillStyle = '#78350f';
            iCtx.fillRect(950, 900, 100, 200);

            // Base da Torre (Entrada)
            iCtx.fillStyle = '#334155';
            iCtx.beginPath();
            iCtx.arc(1000, 600, 100, 0, Math.PI*2);
            iCtx.fill();
            iCtx.fillStyle = '#0f172a'; // Porta
            iCtx.fillRect(970, 620, 60, 80);

            // Texto da Torre
            iCtx.fillStyle = '#94a3b8';
            iCtx.font = 'bold 20px serif';
            iCtx.textAlign = 'center';
            iCtx.fillText("Torre da Deusa", 1000, 580);
            iCtx.font = '16px sans-serif';
            iCtx.fillText("(Entre para Iniciar)", 1000, 730);
        }
        islandCanvasRef.current = iCanvas;
    }
  }, []);

  // --- Game Loop Setup ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { 
        if (e.code === 'Space') e.preventDefault();
        keysRef.current[e.code] = true; 
    };
    const handleKeyUp = (e: KeyboardEvent) => { keysRef.current[e.code] = false; };
    const handleMouseMove = (e: MouseEvent) => {
      const rect = canvasRef.current?.getBoundingClientRect();
      if(rect) {
          mouseRef.current = { 
            x: e.clientX - rect.left - rect.width / 2, 
            y: e.clientY - rect.top - rect.height / 2 
          };
      }
    };
    const handleMouseDown = (e: MouseEvent) => {
       if (e.button === 2) keysRef.current['MouseRight'] = true; // Skill 1
       if (e.button === 0) keysRef.current['MouseLeft'] = true;
    };
    const handleMouseUp = (e: MouseEvent) => {
       if (e.button === 2) keysRef.current['MouseRight'] = false;
       if (e.button === 0) keysRef.current['MouseLeft'] = false;
    };
    const handleContextMenu = (e: MouseEvent) => e.preventDefault();

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    window.addEventListener('contextmenu', handleContextMenu);

    let animationFrameId: number;
    let lastTime = performance.now();

    const loop = (timestamp: number) => {
      const dt = Math.min((timestamp - lastTime) / 1000, 0.1); // Cap dt
      lastTime = timestamp;

      if (gameStateRef.current === GameState.TOWER || gameStateRef.current === GameState.ISLAND) {
        update(dt);
      }
      draw();
      animationFrameId = requestAnimationFrame(loop);
    };

    animationFrameId = requestAnimationFrame(loop);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
      window.removeEventListener('contextmenu', handleContextMenu);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  // --- Lógica Principal (Update) ---
  const update = (dt: number) => {
    const player = playerRef.current;

    // 1. Atualizar Mira
    player.facing = Math.atan2(mouseRef.current.y, mouseRef.current.x);

    // 2. Movimento
    let dx = 0;
    let dy = 0;
    if (keysRef.current['KeyW'] || keysRef.current['ArrowUp']) dy -= 1;
    if (keysRef.current['KeyS'] || keysRef.current['ArrowDown']) dy += 1;
    if (keysRef.current['KeyA'] || keysRef.current['ArrowLeft']) dx -= 1;
    if (keysRef.current['KeyD'] || keysRef.current['ArrowRight']) dx += 1;

    player.isMoving = dx !== 0 || dy !== 0;

    if (player.isMoving) {
      const length = Math.sqrt(dx * dx + dy * dy);
      dx /= length;
      dy /= length;
      player.x += dx * player.stats.speed * 60 * dt;
      player.y += dy * player.stats.speed * 60 * dt;
    }

    // Limites de Mapa (Ilha vs Torre)
    const limit = gameStateRef.current === GameState.ISLAND ? 1000 : 800;
    if (Math.abs(player.x) > limit) player.x = Math.sign(player.x) * limit;
    if (Math.abs(player.y) > limit) player.y = Math.sign(player.y) * limit;

    // Lógica Específica da ILHA (Lobby)
    if (gameStateRef.current === GameState.ISLAND) {
        // Checar entrada na torre (Posição fixa simulada em 0, -400 relativo ao centro da ilha que é 0,0, mas no canvas desenhamos em 1000, 600.
        // O player está em coordenadas relativas ao centro (0,0). A torre no canvas procedural está em 1000, 600. O centro do canvas procedural é 1000,1000.
        // Então a torre está em (0, -400).
        const distToTower = Math.hypot(player.x - 0, player.y - (-400));
        if (distToTower < 80) {
            gameStateRef.current = GameState.TOWER;
            player.x = 0;
            player.y = 0;
            createParticle(0, 0, '#fff', 20); // Efeito de entrada
        }

        // Regeneração rápida no lobby
        if (player.stats.hp < player.stats.maxHp) player.stats.hp += 100 * dt;
    }

    // Lógica Específica da TORRE (Combate)
    if (gameStateRef.current === GameState.TOWER) {
        timeRef.current += dt;
        waveTimerRef.current += dt;

        // Gerenciamento de Onda
        const currentConfig = WAVE_CONFIGS[waveRef.current] || WAVE_CONFIGS[9];
        if (waveTimerRef.current >= currentConfig.duration) {
            triggerUpgrade();
            return;
        }

        // Spawning
        if (Date.now() - lastSpawnTimeRef.current > currentConfig.spawnRate && enemiesRef.current.length < currentConfig.enemyCount) {
            spawnEnemy();
            lastSpawnTimeRef.current = Date.now();
        }

        // Update Habilidades & Cooldowns
        player.skill1Timer = Math.max(0, player.skill1Timer - dt);
        player.dashTimer = Math.max(0, player.dashTimer - dt);
        player.weaponTimer -= dt;

        // Ataque Principal (Auto-fire towards mouse)
        if (player.weaponTimer <= 0) { // Removido !player.isMoving para permitir atirar andando
             useMainAttack();
        }

        // Habilidade 1 (Direita Mouse)
        if (keysRef.current['MouseRight'] && player.skill1Timer <= 0) {
            useSkill1();
            player.skill1Timer = player.skill1MaxCooldown * (1 - player.stats.cooldownReduction);
        }

        // Dash (Espaço)
        if (keysRef.current['Space'] && player.dashTimer <= 0) {
            useDash();
            player.dashTimer = player.dashMaxCooldown * (1 - player.stats.cooldownReduction);
        }
    }

    // 4. Update Entidades
    updateProjectiles(dt);
    updateEnemies(dt);
    updateParticles(dt);

    // 5. Update UI Data
    setHudData({
        hp: player.stats.hp, maxHp: player.stats.maxHp,
        time: timeRef.current, wave: waveRef.current + 1, level: player.level,
        state: gameStateRef.current,
        skill1Cd: player.skill1Timer, dashCd: player.dashTimer
    });

    if (player.stats.hp <= 0 && gameStateRef.current === GameState.TOWER) {
        gameStateRef.current = GameState.GAME_OVER;
        onGameOver();
    }
  };

  // --- Sistema de Habilidades ---

  const useMainAttack = () => {
      const p = playerRef.current;
      const cdBase = 1.0 * (1 - p.stats.cooldownReduction);
      const angle = p.facing;

      if (p.archetype === Archetype.WARRIOR) {
          // Golpe de Espada (Arco)
          projectilesRef.current.push({
              id: Math.random().toString(), x: p.x, y: p.y, vx: 0, vy: 0,
              damage: p.stats.damage, duration: 0.3, radius: 80 * p.stats.areaSize,
              type: 'SWORD_SLASH', color: '#fff', pierce: 999
          });
          p.weaponTimer = 0.6 * cdBase;
      } 
      else if (p.archetype === Archetype.ARCHER) {
          // Flecha
          projectilesRef.current.push({
              id: Math.random().toString(), x: p.x, y: p.y,
              vx: Math.cos(angle) * 800, vy: Math.sin(angle) * 800,
              damage: p.stats.damage, duration: 2, radius: 8 * p.stats.areaSize,
              type: 'ARROW', color: '#fff', pierce: 1
          });
          p.weaponTimer = 0.4 * cdBase;
      }
      else if (p.archetype === Archetype.MAGE) {
          // Orbe Arcano
          projectilesRef.current.push({
              id: Math.random().toString(), x: p.x, y: p.y,
              vx: Math.cos(angle) * 500, vy: Math.sin(angle) * 500,
              damage: p.stats.damage, duration: 1.5, radius: 15 * p.stats.areaSize,
              type: 'MAGIC_ORB', color: '#a855f7', pierce: 2
          });
          p.weaponTimer = 0.5 * cdBase;
      }
  };

  const useSkill1 = () => {
      const p = playerRef.current;
      const angle = p.facing;

      if (p.archetype === Archetype.WARRIOR) {
          // Giro de Machado (360 damage)
          for(let i=0; i<8; i++) {
              createParticle(p.x, p.y, '#ef4444', 5);
          }
          projectilesRef.current.push({
              id: Math.random().toString(), x: p.x, y: p.y, vx: 0, vy: 0,
              damage: p.stats.damage * 2, duration: 0.5, radius: 120 * p.stats.areaSize,
              type: 'SWORD_SLASH', color: '#ef4444', pierce: 999
          });
      }
      else if (p.archetype === Archetype.ARCHER) {
          // Disparo Múltiplo (Shotgun)
          for(let i = -2; i <= 2; i++) {
              const spread = angle + (i * 0.2);
              projectilesRef.current.push({
                id: Math.random().toString(), x: p.x, y: p.y,
                vx: Math.cos(spread) * 800, vy: Math.sin(spread) * 800,
                damage: p.stats.damage * 0.8, duration: 2, radius: 8,
                type: 'ARROW', color: '#22c55e', pierce: 2
            });
          }
      }
      else if (p.archetype === Archetype.MAGE) {
          // Super Nova
          projectilesRef.current.push({
              id: Math.random().toString(), x: mouseRef.current.x + p.x, y: mouseRef.current.y + p.y, // Mira no mouse (bug de coordenadas relativas, ajustado: mouseRef é relativo ao centro)
              vx: 0, vy: 0,
              damage: p.stats.damage * 3, duration: 1.0, radius: 150 * p.stats.areaSize,
              type: 'MAGIC_ORB', color: '#3b82f6', pierce: 999
          });
      }
  };

  const useDash = () => {
      const p = playerRef.current;
      const angle = p.isMoving ? Math.atan2(p.y - (p.y + (keysRef.current['KeyS']?1:0) - (keysRef.current['KeyW']?1:0)), p.x - (p.x + (keysRef.current['KeyD']?1:0) - (keysRef.current['KeyA']?1:0))) + Math.PI : p.facing;

      // Empurrão físico
      p.x += Math.cos(angle) * 150;
      p.y += Math.sin(angle) * 150;

      // Partículas de fumaça
      for(let i=0; i<5; i++) createParticle(p.x, p.y, '#fff', 3);
  };

  // --- Helpers de Update ---

  const spawnEnemy = () => {
    const angle = Math.random() * Math.PI * 2;
    const distance = 800; // Fora da tela
    const ex = playerRef.current.x + Math.cos(angle) * distance;
    const ey = playerRef.current.y + Math.sin(angle) * distance;

    const types: ('SLIME' | 'GOBLIN' | 'DEMON')[] = ['SLIME', 'GOBLIN', 'DEMON'];
    const typeIdx = Math.min(2, Math.floor(waveRef.current / 3));
    const type = types[typeIdx];

    let stats = { hp: 30, maxHp: 30, speed: 80, damage: 5, radius: 20, hitboxRadius: 15 };
    if (type === 'GOBLIN') stats = { hp: 60, maxHp: 60, speed: 110, damage: 10, radius: 25, hitboxRadius: 18 };
    if (type === 'DEMON') stats = { hp: 180, maxHp: 180, speed: 70, damage: 25, radius: 35, hitboxRadius: 25 };

    const scaling = 1 + (waveRef.current * 0.3);
    stats.hp *= scaling;
    stats.maxHp *= scaling;
    stats.damage *= scaling;

    enemiesRef.current.push({
      id: Math.random().toString(), x: ex, y: ey, type, ...stats, frame: 0
    });
  };

  const updateEnemies = (dt: number) => {
    const player = playerRef.current;
    enemiesRef.current = enemiesRef.current.filter(enemy => {
      // Movimento Simples
      const angle = Math.atan2(player.y - enemy.y, player.x - enemy.x);
      enemy.x += Math.cos(angle) * enemy.speed * dt;
      enemy.y += Math.sin(angle) * enemy.speed * dt;
      enemy.frame += dt * 5;

      // Colisão com Jogador
      const distToPlayer = Math.hypot(enemy.x - player.x, enemy.y - player.y);
      if (distToPlayer < enemy.hitboxRadius + 15) { // 15 é raio do player
        const damage = Math.max(1, enemy.damage - player.stats.defense);
        player.stats.hp -= damage * dt;
        if(Math.random() > 0.95) createDamageNumber(player.x, player.y, damage, false);
      }

      // Colisão com Projéteis
      projectilesRef.current.forEach(proj => {
          const dist = Math.hypot(proj.x - enemy.x, proj.y - enemy.y);
          if (dist < proj.radius + enemy.hitboxRadius) {
              if (proj.pierce > 0) {
                  const isTick = proj.type === 'SWORD_SLASH' || proj.type === 'MAGIC_ORB';
                  // Se for tick, aplica dano por segundo, se for tiro, dano instantaneo
                  const dmg = isTick ? proj.damage * 10 * dt : proj.damage;

                  // Evita dano absurdo em ticks, mas garante hit em projéteis únicos
                  if (!isTick) {
                      proj.pierce--;
                      enemy.hp -= dmg;
                      createDamageNumber(enemy.x, enemy.y, dmg, Math.random() > 0.8);
                      createParticle(enemy.x, enemy.y, proj.color, 3);
                  } else {
                      enemy.hp -= dmg; // Dano continuo
                      if(Math.random() > 0.8) createDamageNumber(enemy.x, enemy.y, dmg, false);
                  }
              }
          }
      });

      if (enemy.hp <= 0) {
          player.xp += 10;
          createParticle(enemy.x, enemy.y, COLORS.xp, 8);
          return false;
      }
      return true;
    });
  };

  const updateProjectiles = (dt: number) => {
      const p = playerRef.current;
      projectilesRef.current = projectilesRef.current.filter(proj => {
          proj.duration -= dt;
          if (proj.type === 'SWORD_SLASH') { // Espada segue o player
              proj.x = p.x;
              proj.y = p.y;
          } else {
              proj.x += proj.vx * dt;
              proj.y += proj.vy * dt;
          }
          return proj.duration > 0;
      });
  };

  const updateParticles = (dt: number) => {
      particlesRef.current = particlesRef.current.filter(p => {
          p.life -= dt;
          p.x += p.vx * dt;
          p.y += p.vy * dt;
          return p.life > 0;
      });
      damageNumbersRef.current = damageNumbersRef.current.filter(d => {
          d.life -= dt;
          d.y -= 30 * dt;
          return d.life > 0;
      });
  };

  const createDamageNumber = (x: number, y: number, value: number, isCrit: boolean) => {
    damageNumbersRef.current.push({
      id: Math.random().toString(), x: x + (Math.random()*20-10), y: y - 20,
      value: Math.floor(value), life: 0.8, isCrit
    });
  };

  const createParticle = (x: number, y: number, color: string, count: number = 1) => {
      for(let i=0; i<count; i++) {
        particlesRef.current.push({
            id: Math.random().toString(), x, y,
            vx: (Math.random() - 0.5) * 200, vy: (Math.random() - 0.5) * 200,
            life: 0.3 + Math.random() * 0.4, maxLife: 0.7, color, size: Math.random() * 4 + 2
        });
      }
  };

  const triggerUpgrade = () => {
    gameStateRef.current = GameState.PAUSED;
    const options: Upgrade[] = [];
    for(let i=0; i<4; i++) {
        const rand = UPGRADES_LIST[Math.floor(Math.random() * UPGRADES_LIST.length)];
        options.push({...rand, id: rand.id + Math.random()}); 
    }
    setUpgradeOptions(options);
    setShowUpgrade(true);
  };

  const applyUpgrade = (upgrade: Upgrade) => {
    const player = playerRef.current;
    if (upgrade.name.includes('Força')) player.stats.damage *= 1.1;
    if (upgrade.name.includes('Pés')) player.stats.speed *= 1.1;
    if (upgrade.name.includes('Vitalidade')) { player.stats.maxHp += 50; player.stats.hp += 50; }
    if (upgrade.name.includes('Foco')) player.stats.cooldownReduction = Math.min(0.8, player.stats.cooldownReduction + 0.05);
    if (upgrade.name.includes('Cura')) player.stats.hp = Math.min(player.stats.maxHp, player.stats.hp + (player.stats.maxHp * 0.3));
    if (upgrade.name.includes('Expansão')) player.stats.areaSize *= 1.2;

    setLastUpgrade(upgrade);
    setShowUpgrade(false);
    gameStateRef.current = GameState.TOWER;

    if (waveTimerRef.current >= WAVE_CONFIGS[0].duration) {
         waveRef.current++;
         waveTimerRef.current = 0;
    }
  };

  // --- RENDERING ---

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas || !canvas.getContext('2d')) return;
    const ctx = canvas.getContext('2d')!;

    canvas.width = CANVAS_WIDTH;
    canvas.height = CANVAS_HEIGHT;

    // Camera
    ctx.save();
    const cx = CANVAS_WIDTH / 2 - playerRef.current.x;
    const cy = CANVAS_HEIGHT / 2 - playerRef.current.y;
    ctx.translate(cx, cy);

    // 1. Cenário
    if (gameStateRef.current === GameState.ISLAND) {
        // Desenhar buffer da ilha
        if (islandCanvasRef.current) {
            ctx.drawImage(islandCanvasRef.current, -1000, -1000); // 0,0 do player é 1000,1000 no canvas da ilha
        }
    } else {
        // Chão da Torre (Grid Dungeon)
        ctx.fillStyle = '#0f172a';
        const startX = Math.floor((playerRef.current.x - CANVAS_WIDTH/2)/100)*100;
        const startY = Math.floor((playerRef.current.y - CANVAS_HEIGHT/2)/100)*100;

        ctx.fillStyle = '#1e293b';
        ctx.fillRect(playerRef.current.x - CANVAS_WIDTH/2, playerRef.current.y - CANVAS_HEIGHT/2, CANVAS_WIDTH, CANVAS_HEIGHT);

        ctx.strokeStyle = '#334155';
        ctx.lineWidth = 2;
        ctx.beginPath();
        for(let x=startX; x<startX+CANVAS_WIDTH+100; x+=100) { ctx.moveTo(x, startY); ctx.lineTo(x, startY+CANVAS_HEIGHT+200); }
        for(let y=startY; y<startY+CANVAS_HEIGHT+100; y+=100) { ctx.moveTo(startX, y); ctx.lineTo(startX+CANVAS_WIDTH+200, y); }
        ctx.stroke();
    }

    // 2. Inimigos
    enemiesRef.current.forEach(e => {
        ctx.save();
        ctx.translate(e.x, e.y);
        // Sombra
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        ctx.beginPath(); ctx.ellipse(0, e.radius, e.radius, e.radius*0.4, 0, 0, Math.PI*2); ctx.fill();

        // Sprite
        if (e.type === 'SLIME') {
            const bounce = Math.sin(e.frame) * 5;
            ctx.fillStyle = '#10b981';
            ctx.beginPath(); 
            ctx.arc(0, 0 - bounce, e.radius, Math.PI, 0); 
            ctx.lineTo(e.radius, 0);
            ctx.bezierCurveTo(e.radius, e.radius*0.5, -e.radius, e.radius*0.5, -e.radius, 0);
            ctx.fill();
            // Olhos
            ctx.fillStyle = 'white'; ctx.beginPath(); ctx.arc(-5, -5-bounce, 5, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(5, -5-bounce, 5, 0, Math.PI*2); ctx.fill();
            ctx.fillStyle = 'black'; ctx.beginPath(); ctx.arc(-5, -5-bounce, 2, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(5, -5-bounce, 2, 0, Math.PI*2); ctx.fill();
        } else if (e.type === 'GOBLIN') {
             ctx.fillStyle = '#65a30d'; // Verde pele
             ctx.beginPath(); ctx.arc(0, 0, e.radius, 0, Math.PI*2); ctx.fill();
             // Orelhas
             ctx.beginPath(); ctx.moveTo(-e.radius, -5); ctx.lineTo(-e.radius-10, -15); ctx.lineTo(-e.radius+5, -10); ctx.fill();
             ctx.beginPath(); ctx.moveTo(e.radius, -5); ctx.lineTo(e.radius+10, -15); ctx.lineTo(e.radius-5, -10); ctx.fill();
             // Adaga
             ctx.fillStyle = '#cbd5e1';
             ctx.fillRect(10, 5, 20, 5);
        } else {
            // Demon
            ctx.fillStyle = '#7f1d1d';
            ctx.beginPath(); ctx.arc(0, 0, e.radius, 0, Math.PI*2); ctx.fill();
            // Chifres
            ctx.strokeStyle = '#fca5a5'; ctx.lineWidth = 4;
            ctx.beginPath(); ctx.moveTo(-10, -20); ctx.lineTo(-20, -40); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(10, -20); ctx.lineTo(20, -40); ctx.stroke();
        }

        // HP Bar
        if (e.hp < e.maxHp) {
            ctx.fillStyle = 'red'; ctx.fillRect(-15, -e.radius - 15, 30, 4);
            ctx.fillStyle = 'lime'; ctx.fillRect(-15, -e.radius - 15, 30 * (e.hp/e.maxHp), 4);
        }
        ctx.restore();
    });

    // 3. Player
    const p = playerRef.current;
    ctx.save();
    ctx.translate(p.x, p.y);
    // Sombra
    ctx.fillStyle = 'rgba(0,0,0,0.4)';
    ctx.beginPath(); ctx.ellipse(0, 15, 15, 6, 0, 0, Math.PI*2); ctx.fill();

    // Rotação visual para mira
    ctx.rotate(p.facing + Math.PI/2); // +PI/2 pq desenhamos apontando pra cima (Y negativo), mas 0rad é direita

    // Desenho do Arquétipo
    if (p.archetype === Archetype.WARRIOR) {
        // Capa
        ctx.fillStyle = '#b91c1c';
        ctx.fillRect(-12, -10, 24, 25);
        // Corpo
        ctx.fillStyle = '#94a3b8'; // Armadura
        ctx.beginPath(); ctx.arc(0, 0, 16, 0, Math.PI*2); ctx.fill();
        ctx.strokeStyle = '#475569'; ctx.lineWidth = 2; ctx.stroke();
        // Espada
        ctx.fillStyle = '#e2e8f0';
        ctx.fillRect(12, -20, 6, 40); // Lâmina
        ctx.fillStyle = '#475569';
        ctx.fillRect(8, 10, 14, 4); // Guarda
    } else if (p.archetype === Archetype.ARCHER) {
        // Capuz
        ctx.fillStyle = '#166534';
        ctx.beginPath(); ctx.arc(0, 0, 14, 0, Math.PI*2); ctx.fill();
        // Arco
        ctx.strokeStyle = '#854d0e'; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(0, -5, 20, 0, Math.PI, true); ctx.stroke();
    } else {
        // Mago
        // Manto
        ctx.fillStyle = '#581c87';
        ctx.beginPath(); ctx.arc(0, 0, 14, 0, Math.PI*2); ctx.fill();
        // Cajado
        ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.moveTo(10, 10); ctx.lineTo(10, -20); ctx.stroke();
        ctx.fillStyle = '#3b82f6'; ctx.beginPath(); ctx.arc(10, -25, 5, 0, Math.PI*2); ctx.fill();
    }
    ctx.restore();

    // 4. Projéteis
    projectilesRef.current.forEach(proj => {
        ctx.save();
        ctx.translate(proj.x, proj.y);
        ctx.fillStyle = proj.color;

        if (proj.type === 'ARROW') {
            const rot = Math.atan2(proj.vy, proj.vx);
            ctx.rotate(rot);
            ctx.fillRect(-10, -2, 20, 4);
        } else if (proj.type === 'SWORD_SLASH') {
             // Efeito de corte
             ctx.strokeStyle = proj.color;
             ctx.lineWidth = 4;
             ctx.beginPath(); ctx.arc(0, 0, proj.radius, 0, Math.PI*2); ctx.stroke();
             ctx.globalAlpha = 0.2; ctx.fill(); ctx.globalAlpha = 1;
        } else {
            // Bolas de magia
            ctx.beginPath(); ctx.arc(0, 0, proj.radius, 0, Math.PI*2); ctx.fill();
            ctx.shadowBlur = 10; ctx.shadowColor = proj.color; ctx.stroke(); ctx.shadowBlur = 0;
        }
        ctx.restore();
    });

    // 5. Partículas
    particlesRef.current.forEach(pt => {
        ctx.globalAlpha = pt.life / pt.maxLife;
        ctx.fillStyle = pt.color;
        ctx.beginPath(); ctx.arc(pt.x, pt.y, pt.size, 0, Math.PI*2); ctx.fill();
        ctx.globalAlpha = 1;
    });

    // 6. Números de Dano
    ctx.font = 'bold 16px sans-serif';
    ctx.textAlign = 'center';
    damageNumbersRef.current.forEach(dn => {
        ctx.fillStyle = dn.isCrit ? '#facc15' : '#fff';
        ctx.strokeStyle = 'black';
        ctx.lineWidth = 2;
        ctx.strokeText(Math.floor(dn.value).toString(), dn.x, dn.y);
        ctx.fillText(Math.floor(dn.value).toString(), dn.x, dn.y);
    });

    // Mira do Mouse
    const m = mouseRef.current;
    // Precisamos desenhar a mira relativa ao canvas (não transformada pela camera) OU transformar a posição da camera.
    // Como estamos no contexto transformado (camera), precisamos adicionar a posição do player de volta.
    // Melhor desenhar HUD/Mouse fora do restore()
    ctx.restore();

    // Desenhar Mira
    const mouseX = mouseRef.current.x + CANVAS_WIDTH/2;
    const mouseY = mouseRef.current.y + CANVAS_HEIGHT/2;
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(mouseX, mouseY, 10, 0, Math.PI*2); ctx.stroke();
    ctx.beginPath(); ctx.arc(mouseX, mouseY, 2, 0, Math.PI*2); ctx.fill();

  };

  // --- HUD ---
  const formatTime = (secs: number) => {
    const m = Math.floor(secs / 60);
    const s = Math.floor(secs % 60);
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  return (
    <div className="relative w-full h-full">
      <canvas ref={canvasRef} className="block w-full h-full cursor-none" />

      {/* HUD Layer */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start pointer-events-none">

        {/* Stats Jogador */}
        <div className="flex flex-col gap-2 w-72">
           {/* Barra de Vida */}
           <div className="bg-slate-900/90 border border-slate-600 rounded-lg p-3 backdrop-blur-sm shadow-xl">
              <div className="flex items-center gap-2 mb-1 text-red-400">
                 <Heart size={20} fill="currentColor" />
                 <span className="font-bold text-lg">{Math.ceil(hudData.hp)} / {Math.ceil(hudData.maxHp)}</span>
              </div>
              <div className="w-full h-3 bg-slate-800 rounded-full overflow-hidden border border-slate-700">
                 <div className="h-full bg-gradient-to-r from-red-600 to-red-400 transition-all duration-300" 
                      style={{width: `${(hudData.hp/hudData.maxHp)*100}%`}}></div>
              </div>
           </div>

           {/* Barra de XP */}
           <div className="bg-slate-900/90 border border-slate-600 rounded-lg p-2 backdrop-blur-sm shadow-xl flex items-center gap-3">
              <div className="bg-slate-800 px-2 rounded font-bold text-yellow-500 text-sm">NÍVEL {hudData.level}</div>
              <div className="flex-1 h-2 bg-slate-800 rounded-full overflow-hidden">
                 <div className="h-full bg-yellow-400" style={{width: '45%'}}></div>
              </div>
           </div>
        </div>

        {/* Informações da Onda / Lobby */}
        <div className="flex flex-col items-center bg-slate-900/90 border border-slate-600 rounded-lg p-3 backdrop-blur-sm px-8 shadow-xl">
           {hudData.state === GameState.ISLAND ? (
               <div className="flex items-center gap-2 text-blue-400">
                   <MapPin size={20} />
                   <span className="font-bold tracking-widest uppercase">Ilha de Início</span>
               </div>
           ) : (
               <>
                <div className="text-4xl font-mono font-bold text-white tracking-widest drop-shadow-md">{formatTime(hudData.time)}</div>
                <div className="text-slate-400 text-sm flex items-center gap-2 mt-1">
                    <Skull size={14} /> ONDA {hudData.wave}
                </div>
                {/* Progresso da Onda */}
                <div className="w-full h-1 bg-slate-700 mt-2 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 transition-all duration-1000" 
                            style={{width: `${(waveTimerRef.current / WAVE_DURATION) * 100}%`}}></div>
                </div>
               </>
           )}
        </div>

        {/* Skills HUD */}
        <div className="flex gap-4">
            {/* Skill 1 (Direita) */}
            <div className="relative group">
                <div className={`w-14 h-14 rounded-lg border-2 flex items-center justify-center bg-slate-900 shadow-xl transition-all
                    ${hudData.skill1Cd > 0 ? 'border-red-900 opacity-70' : 'border-blue-400 scale-105'}`}>
                    <MousePointer2 size={24} className={hudData.skill1Cd > 0 ? 'text-slate-500' : 'text-blue-400'} />
                    {hudData.skill1Cd > 0 && (
                        <span className="absolute text-lg font-bold text-white">{Math.ceil(hudData.skill1Cd)}</span>
                    )}
                </div>
                <div className="absolute -bottom-6 left-0 w-full text-center text-xs font-bold bg-black/50 rounded">R-Click</div>
            </div>

            {/* Dash (Espaço) */}
            <div className="relative group">
                <div className={`w-14 h-14 rounded-lg border-2 flex items-center justify-center bg-slate-900 shadow-xl transition-all
                    ${hudData.dashCd > 0 ? 'border-red-900 opacity-70' : 'border-green-400 scale-105'}`}>
                    <Zap size={24} className={hudData.dashCd > 0 ? 'text-slate-500' : 'text-green-400'} />
                    {hudData.dashCd > 0 && (
                        <span className="absolute text-lg font-bold text-white">{Math.ceil(hudData.dashCd)}</span>
                    )}
                </div>
                <div className="absolute -bottom-6 left-0 w-full text-center text-xs font-bold bg-black/50 rounded">SPACE</div>
            </div>
        </div>
      </div>

      {/* Tutorial / Mensagem na Ilha */}
      {hudData.state === GameState.ISLAND && (
          <div className="absolute bottom-10 left-0 w-full text-center pointer-events-none animate-pulse">
              <p className="text-xl font-bold text-white drop-shadow-md bg-black/30 inline-block px-4 py-2 rounded">
                  Vá até a Torre ao Norte para iniciar o desafio
              </p>
          </div>
      )}

      {showUpgrade && (
        <UpgradeModal 
          options={upgradeOptions} 
          memoryOption={lastUpgrade}
          onSelect={applyUpgrade} 
        />
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Lobby } from './components/Lobby';
import { GameCanvas } from './components/GameCanvas';
import { GameState, Archetype } from './types';
import { Skull, RotateCcw } from 'lucide-react';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.CHAR_SELECT);
  const [selectedArchetype, setSelectedArchetype] = useState<Archetype>(Archetype.WARRIOR);

  const handleStartGame = (archetype: Archetype) => {
    setSelectedArchetype(archetype);
    setGameState(GameState.ISLAND); // Vai para o Lobby jogável
  };

  const handleGameOver = () => {
    setGameState(GameState.GAME_OVER);
  };

  const handleReturnToLobby = () => {
    setGameState(GameState.CHAR_SELECT);
  };

  return (
    <div className="w-screen h-screen overflow-hidden bg-slate-950 font-sans select-none text-white">
      {gameState === GameState.CHAR_SELECT && (
        <Lobby onStart={handleStartGame} />
      )}

      {(gameState === GameState.ISLAND || gameState === GameState.TOWER || gameState === GameState.PLAYING) && (
        <GameCanvas 
          archetype={selectedArchetype} 
          onGameOver={handleGameOver} 
        />
      )}

      {gameState === GameState.GAME_OVER && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/90 animate-in fade-in zoom-in duration-500">
          <div className="text-center p-8 bg-slate-900 border border-red-900 rounded-2xl shadow-2xl shadow-red-900/20 max-w-md w-full">
            <Skull size={80} className="mx-auto text-red-500 mb-6 animate-bounce" />
            <h2 className="text-5xl font-bold text-red-500 mb-2 font-serif">FIM DE JOGO</h2>
            <p className="text-slate-400 mb-8">A Torre rejeitou sua alma... por enquanto.</p>

            <button
              onClick={handleReturnToLobby}
