  CHAR_SELECT = 'CHAR_SELECT',
  ISLAND = 'ISLAND',
  TOWER = 'TOWER',
  PAUSED = 'PAUSED',
  GAME_OVER = 'GAME_OVER',
  VICTORY = 'VICTORY'
}

export enum Archetype {
  WARRIOR = 'WARRIOR',
  ARCHER = 'ARCHER',
  MAGE = 'MAGE'
}

export interface Stats {
  maxHp: number;
  hp: number;
  damage: number;
  speed: number;
  defense: number;
  cooldownReduction: number;
  pickupRange: number;
  areaSize: number;
}

export interface Item {
  id: string;
  name: string;
  icon: string;
  cooldown: number;
  duration?: number;
  effect: (player: Player, enemies: Enemy[]) => void;
  description: string;
}

export interface Player {
  x: number;
  y: number;
  z: number; // Altura para pulo/knockup
  archetype: Archetype;
  stats: Stats;
  level: number;
  xp: number;
  xpToNextLevel: number;

  // Cooldowns
  weaponTimer: number;
  skill1Timer: number; // Right Click
  skill1MaxCooldown: number;
  dashTimer: number;   // Space
  dashMaxCooldown: number;

  // Item Slot
  activeItem: Item | null;
  itemTimer: number;
  itemMaxCooldown: number;

  facing: number;
  isMoving: boolean;
  color: string;
}

export interface Enemy {
  id: string;
  x: number;
  y: number;
  z: number;
  type: 'SLIME' | 'GOBLIN' | 'DEMON' | 'BOSS_GOLEM' | 'BOSS_LICH';
  isBoss: boolean;
  hp: number;
  maxHp: number;
  speed: number;
  damage: number;
  radius: number;
  hitboxRadius: number;
  frame: number;
  attackTimer?: number; // Para bosses
}

export interface Projectile {
  id: string;
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  damage: number;
  duration: number;
  radius: number;
  type: 'ARROW' | 'MAGIC_ORB' | 'SWORD_SLASH' | 'BOSS_SMASH' | 'FIRE_ZONE';
