import React, { useEffect, useRef, useState } from 'react';
import { Player, Enemy, Projectile, GameState, Archetype, Particle, DamageNumber, Upgrade, Item, StaticObject, Cloud } from '../types';
import { CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, BASE_STATS, WAVE_CONFIGS, UPGRADES_LIST, SKILL_CONFIG } from '../constants';
import { UpgradeModal } from './UpgradeModal';
import { Heart, Skull, Zap, MousePointer2, Sword, Box, Crosshair, Wind } from 'lucide-react';

interface GameCanvasProps {
  archetype: Archetype;
  onGameOver: () => void;
}

// --- Helpers de Cor ---
const adjustColor = (color: string, amount: number) => {
    let usePound = false;
    if (color[0] === "#") {
        color = color.slice(1);
        usePound = true;
    }
    const num = parseInt(color, 16);
    let r = (num >> 16) + amount;
    if (r > 255) r = 255; else if (r < 0) r = 0;
    let b = ((num >> 8) & 0x00FF) + amount;
    if (b > 255) b = 255; else if (b < 0) b = 0;
    let g = (num & 0x0000FF) + amount;
    if (g > 255) g = 255; else if (g < 0) g = 0;
    return (usePound ? "#" : "") + (g | (b << 8) | (r << 16)).toString(16).padStart(6, '0');
};

// --- Funções Auxiliares Isométricas ---
// Mundo -> Tela
const toIso = (x: number, y: number, z: number = 0) => {
  const isoX = (x - y);
  const isoY = (x + y) / 2 - z;
  return { x: isoX, y: isoY };
};

// Tela -> Mundo (Inverso aproximado, assumindo z=0 para o chão)
// x_screen = x_world - y_world
// y_screen = (x_world + y_world) / 2
// 2 * y_screen = x_world + y_world
// x_world = y_screen + x_screen/2
// y_world = y_screen - x_screen/2
const toWorld = (screenX: number, screenY: number) => {
    const worldX = screenY + screenX / 2;
    const worldY = screenY - screenX / 2;
    return { x: worldX, y: worldY };
};

export const GameCanvas: React.FC<GameCanvasProps> = ({ archetype, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Estado do Jogo (Refs para performance no loop)
  const gameStateRef = useRef<GameState>(GameState.ISLAND);
  const playerRef = useRef<Player>({
    x: 0, y: 0, z: 0,
    archetype,
    stats: JSON.parse(JSON.stringify(BASE_STATS[archetype])),
    level: 1, xp: 0, xpToNextLevel: 100,
    weaponTimer: 0, skill1Timer: 0, skill1MaxCooldown: SKILL_CONFIG[archetype].skill1Cd,
    dashTimer: 0, dashMaxCooldown: SKILL_CONFIG[archetype].dashCd,
    activeItem: null, itemTimer: 0, itemMaxCooldown: 0,
    facing: 0, isMoving: false, color: COLORS[archetype]
  });

  const enemiesRef = useRef<Enemy[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const damageNumbersRef = useRef<DamageNumber[]>([]);
  const staticObjectsRef = useRef<StaticObject[]>([]);
  const cloudsRef = useRef<Cloud[]>([]);
  const keysRef = useRef<{ [key: string]: boolean }>({});

  // Gerenciamento de Tempo e Ondas
  const timeRef = useRef<number>(0); 
  const waveRef = useRef<number>(0);
  const waveTimerRef = useRef<number>(0);
  const lastSpawnTimeRef = useRef<number>(0);
  const isRainingRef = useRef<boolean>(false);
  const rainTimerRef = useRef<number>(0);

  // Estado React para UI
  const [showUpgrade, setShowUpgrade] = useState(false);
  const [upgradeOptions, setUpgradeOptions] = useState<Upgrade[]>([]);
  const [lastUpgrade, setLastUpgrade] = useState<Upgrade | null>(null);
  const [hudData, setHudData] = useState({ 
      hp: 100, maxHp: 100, xp: 0, xpNext: 100, time: 0, wave: 1, level: 1, 
      state: GameState.ISLAND, skill1Cd: 0, dashCd: 0, itemCd: 0,
      activeItem: null as Item | null, bossHp: 0, bossMaxHp: 0
  });

  // Mouse em coordenadas da tela (relativo ao centro)
  const mouseScreenRef = useRef({ x: 0, y: 0 });
  // Mouse em coordenadas do mundo (calculado no loop)
  const mouseWorldRef = useRef({ x: 0, y: 0 });

  // --- Inicialização de Cenário ---
  useEffect(() => {
    // Gerar objetos da ilha (Árvores e Casas)
    const objects: StaticObject[] = [];

    // Casas na Vila
    objects.push({ id: 'h1', x: -200, y: -200, type: 'HOUSE', size: 100 });
    objects.push({ id: 'h2', x: 200, y: -250, type: 'HOUSE', size: 120 });
    objects.push({ id: 'h3', x: -300, y: 100, type: 'HOUSE', size: 90 });

    // Floresta ao redor
    for(let i=0; i<40; i++) {
        const angle = Math.random() * Math.PI * 2;
        const dist = 500 + Math.random() * 800;
        objects.push({ 
            id: `t${i}`, 
            x: Math.cos(angle) * dist, 
            y: Math.sin(angle) * dist, 
            type: 'TREE', 
            size: 40 + Math.random() * 40 
        });
    }
    staticObjectsRef.current = objects;

    // Gerar Nuvens Iniciais
    for(let i=0; i<8; i++) {
        cloudsRef.current.push({
            x: (Math.random() - 0.5) * 2000,
            y: (Math.random() - 0.5) * 2000,
            speed: 10 + Math.random() * 20,
            size: 200 + Math.random() * 300,
            opacity: 0.1 + Math.random() * 0.2
        });
    }
  }, []);

  // --- Game Loop Setup ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { 
        if (e.code === 'Space') e.preventDefault();
        keysRef.current[e.code] = true;
    };
    const handleKeyUp = (e: KeyboardEvent) => { keysRef.current[e.code] = false; };
    const handleMouseMove = (e: MouseEvent) => {
      const rect = canvasRef.current?.getBoundingClientRect();
      if(rect) {
          // Coordenadas relativas ao centro da tela
          mouseScreenRef.current = { 
            x: e.clientX - rect.left - rect.width / 2, 
            y: e.clientY - rect.top - rect.height / 2 
          };
      }
    };
    const handleMouseDown = (e: MouseEvent) => {
       if (e.button === 0) keysRef.current['MouseLeft'] = true;
    };
    const handleMouseUp = (e: MouseEvent) => {
       if (e.button === 0) keysRef.current['MouseLeft'] = false;
    };
    const handleContextMenu = (e: MouseEvent) => e.preventDefault();

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    window.addEventListener('contextmenu', handleContextMenu);

    let animationFrameId: number;
    let lastTime = performance.now();

    const loop = (timestamp: number) => {
      const dt = Math.min((timestamp - lastTime) / 1000, 0.1);
      lastTime = timestamp;

      if (gameStateRef.current === GameState.TOWER || gameStateRef.current === GameState.ISLAND) {
        update(dt);
      }
      draw();
      animationFrameId = requestAnimationFrame(loop);
    };

    animationFrameId = requestAnimationFrame(loop);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
      window.removeEventListener('contextmenu', handleContextMenu);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  // --- LÓGICA DE ATUALIZAÇÃO ---
  const update = (dt: number) => {
    const player = playerRef.current;

    // 1. Calcular Mouse no Mundo (World Coordinates)
    // O Mouse na tela é relativo ao centro (onde o player está desenhado visualmente)
    // Então para converter para mundo, somamos a posição do player ao deslocamento convertido
    const isoMouse = toWorld(mouseScreenRef.current.x, mouseScreenRef.current.y);
    mouseWorldRef.current = {
        x: player.x + isoMouse.x,
        y: player.y + isoMouse.y
    };

    // Atualizar Facing com base no mouse do MUNDO
    player.facing = Math.atan2(mouseWorldRef.current.y - player.y, mouseWorldRef.current.x - player.x);

    // 2. Movimento Isométrico
    let dx = 0;
    let dy = 0;
    if (keysRef.current['KeyW'] || keysRef.current['ArrowUp']) { dx -= 1; dy -= 1; } // Cima
    if (keysRef.current['KeyS'] || keysRef.current['ArrowDown']) { dx += 1; dy += 1; } // Baixo
    if (keysRef.current['KeyA'] || keysRef.current['ArrowLeft']) { dx -= 1; dy += 1; } // Esquerda
    if (keysRef.current['KeyD'] || keysRef.current['ArrowRight']) { dx += 1; dy -= 1; } // Direita

    player.isMoving = dx !== 0 || dy !== 0;

    if (player.isMoving) {
      const length = Math.sqrt(dx * dx + dy * dy);
      dx /= length;
      dy /= length;

      const speed = player.stats.speed * 60 * dt;
      player.x += dx * speed;
      player.y += dy * speed;
    }

    // Física de Pulo (Z)
    if (player.z > 0) {
        player.z -= 150 * dt; 
        if (player.z < 0) player.z = 0;
    }

    // Colisão com Limites
    const limit = gameStateRef.current === GameState.ISLAND ? 1500 : 900;
    if (Math.abs(player.x) > limit) player.x = Math.sign(player.x) * limit;
    if (Math.abs(player.y) > limit) player.y = Math.sign(player.y) * limit;

    // --- Lógica de Estado ---

    if (gameStateRef.current === GameState.ISLAND) {
        // Torre está no Norte
        const distToTower = Math.hypot(player.x - 0, player.y - (-600)); 
        if (distToTower < 150) {
            gameStateRef.current = GameState.TOWER;
            player.x = 0; player.y = 0;
            enemiesRef.current = [];
            projectilesRef.current = [];
            waveRef.current = 0;
            timeRef.current = 0;
            rainTimerRef.current = 0;
        }
        if (player.stats.hp < player.stats.maxHp) player.stats.hp += 100 * dt;
    }

    if (gameStateRef.current === GameState.TOWER) {
        timeRef.current += dt;
        waveTimerRef.current += dt;
        player.skill1Timer -= dt;
        player.dashTimer -= dt;
        player.itemTimer -= dt;
        player.weaponTimer -= dt;

        // Chuva dinâmica a cada 1 minuto (dura 20s)
        rainTimerRef.current += dt;
        if (rainTimerRef.current > 60) {
             isRainingRef.current = true;
             if (rainTimerRef.current > 80) {
                 rainTimerRef.current = 0;
                 isRainingRef.current = false;
             }
        }

        // Spawn de Chuva
        if (isRainingRef.current) {
            for(let i=0; i<5; i++) {
                const angle = Math.random() * Math.PI * 2;
                const dist = Math.random() * 800; // Raio ao redor do player
                particlesRef.current.push({
                    id: Math.random().toString(), 
                    x: player.x + Math.cos(angle)*dist - 400, // Offset para cair em diagonal
                    y: player.y + Math.sin(angle)*dist - 400, 
                    z: 500,
                    vx: 100, vy: 100, vz: -800,
                    life: 0.6, maxLife: 0.6, color: '#a5f3fc', size: 2, type: 'RAIN'
                });
            }
        }

        const currentConfig = WAVE_CONFIGS[waveRef.current] || WAVE_CONFIGS[WAVE_CONFIGS.length-1];
        const bossAlive = enemiesRef.current.some(e => e.isBoss);

        // Checar fim de onda
        if (!bossAlive && waveTimerRef.current >= currentConfig.duration) {
             triggerUpgrade();
        } 
        // Spawn
        else if (!bossAlive && enemiesRef.current.length < currentConfig.enemyCount && Date.now() - lastSpawnTimeRef.current > currentConfig.spawnRate) {
             if (currentConfig.boss && !enemiesRef.current.some(e => e.isBoss)) {
                 spawnBoss(currentConfig.boss);
             } else if (!currentConfig.boss) {
                 spawnEnemy();
             }
             lastSpawnTimeRef.current = Date.now();
        }

        // CONTROLES NOVOS
        // Ataque Básico (Mouse Left)
        if (keysRef.current['MouseLeft'] && player.weaponTimer <= 0) useMainAttack();

        // Skill 1 (Q)
        if (keysRef.current['KeyQ'] && player.skill1Timer <= 0) {
            useSkill1();
            player.skill1Timer = player.skill1MaxCooldown * (1 - player.stats.cooldownReduction);
        }

        // Dash (E)
        if (keysRef.current['KeyE'] && player.dashTimer <= 0) {
            useDash();
            player.dashTimer = player.dashMaxCooldown * (1 - player.stats.cooldownReduction);
        }

        // Item Ativo (R)
        if (keysRef.current['KeyR']) {
            activateItem();
        }
    }

    // Updates Gerais
    updateClouds(dt);
    updateProjectiles(dt);
    updateEnemies(dt);
    updateParticles(dt);

    // Sync HUD
    const boss = enemiesRef.current.find(e => e.isBoss);
    setHudData({
        hp: player.stats.hp, maxHp: player.stats.maxHp,
        xp: player.xp, xpNext: player.xpToNextLevel,
        time: timeRef.current, wave: waveRef.current + 1, level: player.level,
        state: gameStateRef.current,
        skill1Cd: player.skill1Timer, dashCd: player.dashTimer, itemCd: player.itemTimer,
        activeItem: player.activeItem,
        bossHp: boss ? boss.hp : 0, bossMaxHp: boss ? boss.maxHp : 0
    });

    if (player.stats.hp <= 0 && gameStateRef.current === GameState.TOWER) {
        gameStateRef.current = GameState.GAME_OVER;
        onGameOver();
    }
  };

  const activateItem = () => {
     const p = playerRef.current;
     if (p.activeItem && p.itemTimer <= 0) {
         p.activeItem.effect(p, enemiesRef.current);
         p.itemTimer = p.activeItem.cooldown;
     }
  };

  // --- AÇÕES DO JOGADOR ---
  const useMainAttack = () => {
     const p = playerRef.current;
     const angle = p.facing;

     // Converter ângulo para vetor de mundo
     const vx = Math.cos(angle) * 800;
     const vy = Math.sin(angle) * 800;

     if (p.archetype === Archetype.WARRIOR) {
         projectilesRef.current.push({
             id: Math.random().toString(), x: p.x, y: p.y, z: 20, vx: 0, vy: 0,
             damage: p.stats.damage, duration: 0.3, radius: 100 * p.stats.areaSize,
             type: 'SWORD_SLASH', color: '#fff', pierce: 999
         });
         p.weaponTimer = 0.6 * (1 - p.stats.cooldownReduction);
     } else {
         projectilesRef.current.push({
             id: Math.random().toString(), x: p.x, y: p.y, z: 30, vx, vy,
             damage: p.stats.damage, duration: 1.5, radius: 15,
             type: p.archetype === Archetype.ARCHER ? 'ARROW' : 'MAGIC_ORB', 
             color: p.color, pierce: p.archetype === Archetype.MAGE ? 2 : 1
         });
         p.weaponTimer = (p.archetype === Archetype.ARCHER ? 0.4 : 0.5) * (1 - p.stats.cooldownReduction);
     }
  };

  const useSkill1 = () => {
      const p = playerRef.current;
      createParticle(p.x, p.y, 20, '#fff', 10);

      if(p.archetype === Archetype.WARRIOR) {
          projectilesRef.current.push({
             id: Math.random().toString(), x: p.x, y: p.y, z: 20, vx: 0, vy: 0,
             damage: p.stats.damage * 2.5, duration: 0.5, radius: 160 * p.stats.areaSize,
             type: 'SWORD_SLASH', color: '#ef4444', pierce: 999
         });
      } else {
          // Explosão no Mouse (Corrigido para mira exata)
          projectilesRef.current.push({
             id: Math.random().toString(), x: mouseWorldRef.current.x, y: mouseWorldRef.current.y, z: 0, vx: 0, vy: 0,
             damage: p.stats.damage * 3, duration: 1.2, radius: 120 * p.stats.areaSize,
             type: 'FIRE_ZONE', color: p.archetype === Archetype.MAGE ? '#9333ea' : '#ef4444', pierce: 999
         });
      }
  };

  const useDash = () => {
      const p = playerRef.current;
      // Dash na direção do movimento ou do mouse se parado
      let angle = p.facing;
      if (p.isMoving) {
          // Recalcular angulo de movimento baseado nas teclas
          let dx = 0, dy = 0;
          if (keysRef.current['KeyW']) { dx -= 1; dy -= 1; }
          if (keysRef.current['KeyS']) { dx += 1; dy += 1; }
          if (keysRef.current['KeyA']) { dx -= 1; dy += 1; }
          if (keysRef.current['KeyD']) { dx += 1; dy -= 1; }
          angle = Math.atan2(dy, dx);
      }

      const vx = Math.cos(angle) * 1200; // Dash rápido
      const vy = Math.sin(angle) * 1200;

      p.x += vx * 0.2; // 0.2s de movimento instantaneo
      p.y += vy * 0.2;
      p.z = 40; 
      createParticle(p.x, p.y, 10, '#fff', 5);
  };

  // --- ENTITY HELPERS ---
  const spawnBoss = (type: 'BOSS_GOLEM' | 'BOSS_LICH') => {
      const dist = 600;
      const angle = Math.random() * Math.PI * 2;
      enemiesRef.current.push({
          id: 'boss', x: playerRef.current.x + Math.cos(angle)*dist, y: playerRef.current.y + Math.sin(angle)*dist, z: 0,
          type, isBoss: true,
          hp: 2000 * (1 + waveRef.current * 0.5), maxHp: 2000 * (1 + waveRef.current * 0.5),
          speed: 40, damage: 40, radius: 60, hitboxRadius: 50, frame: 0, attackTimer: 2
      });
  };

  const spawnEnemy = () => {
    const angle = Math.random() * Math.PI * 2;
    const distance = 900; 
    const ex = playerRef.current.x + Math.cos(angle) * distance;
    const ey = playerRef.current.y + Math.sin(angle) * distance;
    const type = waveRef.current < 5 ? 'SLIME' : (waveRef.current < 10 ? 'GOBLIN' : 'DEMON');

    enemiesRef.current.push({
      id: Math.random().toString(), x: ex, y: ey, z: 0, type, isBoss: false,
      hp: 50 + waveRef.current * 10, maxHp: 50 + waveRef.current * 10,
      speed: 80 + Math.random()*20, damage: 10 + waveRef.current,
      radius: 20, hitboxRadius: 15, frame: 0
    });
  };

  const updateClouds = (dt: number) => {
      cloudsRef.current.forEach(c => {
          c.x += c.speed * dt;
          if (c.x > 2000) c.x = -2000;
      });
  };

  const updateEnemies = (dt: number) => {
      const p = playerRef.current;
      enemiesRef.current = enemiesRef.current.filter(e => {
          const dx = p.x - e.x;
          const dy = p.y - e.y;
          const dist = Math.hypot(dx, dy);

          if(dist > e.hitboxRadius) {
              e.x += (dx/dist) * e.speed * dt;
              e.y += (dy/dist) * e.speed * dt;
          }

          if(dist < e.hitboxRadius + 20) {
              p.stats.hp -= e.damage * dt;
          }

          projectilesRef.current.forEach(proj => {
               const pDist = Math.hypot(proj.x - e.x, proj.y - e.y);
               if(pDist < proj.radius + e.hitboxRadius) {
                   if(proj.pierce > 0) {
                       const dmg = (proj.type === 'SWORD_SLASH' || proj.type === 'FIRE_ZONE') ? proj.damage * 5 * dt : proj.damage;
                       if (proj.type === 'ARROW' || proj.type === 'MAGIC_ORB') proj.pierce--;
                       e.hp -= dmg;
                       if (Math.random() > 0.8) createDamageNumber(e.x, e.y, e.z + 40, dmg, Math.random()>0.8);

                       if(e.hp <= 0 && !e.isBoss) {
                           createParticle(e.x, e.y, e.z, '#ef4444', 3);
                       }
                   }
               }
          });

          if(e.hp <= 0) {
              p.xp += e.isBoss ? 500 : 10;
              if(p.xp >= p.xpToNextLevel) {
                  p.level++;
                  p.xp -= p.xpToNextLevel;
                  p.xpToNextLevel *= 1.2;
                  p.stats.damage *= 1.1;
                  p.stats.maxHp *= 1.1;
                  p.stats.hp = p.stats.maxHp;
                  createDamageNumber(p.x, p.y, p.z+60, 0, true); 
              }
              return false;
          }
          return true;
      });
  };

  const updateProjectiles = (dt: number) => {
      projectilesRef.current = projectilesRef.current.filter(proj => {
          proj.duration -= dt;
          if(proj.type === 'SWORD_SLASH') {
              proj.x = playerRef.current.x; proj.y = playerRef.current.y;
          } else {
              proj.x += proj.vx * dt; proj.y += proj.vy * dt;
          }
          return proj.duration > 0;
      });
  };

  const updateParticles = (dt: number) => {
      particlesRef.current = particlesRef.current.filter(p => {
          p.life -= dt;
          p.x += p.vx * dt;
          p.y += p.vy * dt;
          p.z += p.vz * dt;
          if (p.type !== 'RAIN') p.vz -= 300 * dt; // Gravidade

          if(p.z < 0) {
              p.z = 0;
              if (p.type === 'RAIN') {
                  // Splash de chuva
                  return false; 
              }
          }
          return p.life > 0;
      });
      damageNumbersRef.current = damageNumbersRef.current.filter(d => { d.life -= dt; d.z += 40 * dt; return d.life > 0; });
  };

  const createParticle = (x: number, y: number, z: number, color: string, count: number) => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(), x, y, z,
              vx: (Math.random()-0.5)*150, vy: (Math.random()-0.5)*150, vz: Math.random()*150 + 50,
              life: 0.5, maxLife: 0.5, color, size: Math.random()*4+2
          });
      }
  };

  const createDamageNumber = (x: number, y: number, z: number, val: number, crit: boolean) => {
      if (val < 1) return;
      damageNumbersRef.current.push({id: Math.random().toString(), x, y, z, value: val, life: 0.8, isCrit: crit});
  };

  const triggerUpgrade = () => {
    gameStateRef.current = GameState.PAUSED;
    const options: Upgrade[] = [];
    const rollItem = !playerRef.current.activeItem && Math.random() > 0.5;

    for(let i=0; i<4; i++) {
        let pool = UPGRADES_LIST;
        if (rollItem && i === 0) pool = UPGRADES_LIST.filter(u => u.type === 'ITEM');
        const rand = pool[Math.floor(Math.random() * pool.length)];
        options.push({...rand, id: rand.id + Math.random()}); 
    }
    setUpgradeOptions(options);
    setShowUpgrade(true);
  };

  const applyUpgrade = (upgrade: Upgrade) => {
      const p = playerRef.current;
      if (upgrade.type === 'ITEM' && upgrade.itemRef) {
          p.activeItem = upgrade.itemRef;
      } else {
        if (upgrade.name.includes('Força')) p.stats.damage *= 1.15;
        if (upgrade.name.includes('Velocidade')) p.stats.speed *= 1.1;
        if (upgrade.name.includes('Vida')) { p.stats.maxHp += 50; p.stats.hp += 50; }
        if (upgrade.name.includes('Tempo')) p.stats.cooldownReduction = Math.min(0.7, p.stats.cooldownReduction + 0.08);
        if (upgrade.name.includes('Expansão')) p.stats.areaSize *= 1.2;
      }
      setLastUpgrade(upgrade);
      setShowUpgrade(false);
      gameStateRef.current = GameState.TOWER;

      if (waveTimerRef.current >= WAVE_CONFIGS[0].duration) {
         waveRef.current++;
         waveTimerRef.current = 0;
      }
  };

  // --- RENDERIZAÇÃO ---
  const drawIsoSprite = (ctx: CanvasRenderingContext2D, entity: any, type: string) => {
      const { x, y } = toIso(entity.x, entity.y, entity.z);

      // Sombra
      const shadow = toIso(entity.x, entity.y, 0);
      ctx.fillStyle = 'rgba(0,0,0,0.3)';
      ctx.beginPath();
      ctx.ellipse(shadow.x, shadow.y, type === 'BOSS' ? 40 : 15, type === 'BOSS' ? 20 : 8, 0, 0, Math.PI*2);
      ctx.fill();

      const layers = type === 'BOSS' ? 12 : 6;
      const scale = 2;

      for(let i=0; i<layers; i++) {
          const ly = y - (i * scale * 2);
          let w = 20; let h = 20;
          let color = entity.color || '#fff';

          if (type === 'PLAYER') {
             if (i === 0) { color = '#333'; w = 14; }
             else if (i < 3) { w = 18; }
             else if (i === 4) { color = '#fca5a5'; w = 14; }
             else if (i === 5) { 
                 color = entity.archetype === Archetype.MAGE ? '#6b21a8' : 
                        (entity.archetype === Archetype.ARCHER ? '#166534' : '#991b1b');
                 w = 16;
             }
             ctx.fillStyle = color;
             ctx.fillRect(x - w/2, ly - w/2, w, w);
             if (i === 2) { ctx.fillStyle = '#ccc'; ctx.fillRect(x + 10, ly - 5, 4, 15); }
          } 
          else if (type === 'BOSS') {
             w = 60 - i*2; h = 60 - i*2;
             ctx.fillStyle = i % 2 === 0 ? '#7f1d1d' : '#991b1b';
             ctx.fillRect(x - w/2, ly - h/2, w, h);
          }
          else if (type === 'SLIME') {
             w = 24 - i*3; 
             ctx.fillStyle = '#4ade80';
             ctx.beginPath(); ctx.arc(x, ly, w/2, 0, Math.PI*2); ctx.fill();
          } 
          else if (type === 'TREE') {
              w = entity.size * (1 - i/10); 
              h = w;
              ctx.fillStyle = i === 0 ? '#451a03' : '#14532d'; // Tronco e folhas
              if (i > 2) ctx.fillStyle = '#166534';
              if (i === 0) w = w / 3; // Tronco fino
              ctx.fillRect(x - w/2, ly - h/2, w, h);
          }
          else if (type === 'HOUSE') {
              w = entity.size; h = entity.size;
              ctx.fillStyle = i < 4 ? '#78350f' : '#dc2626'; // Madeira e Telhado
              if (i >= 4) { // Telhado piramide
                 w = w * (1 - (i-4)/6);
                 h = h * (1 - (i-4)/6);
              }
              ctx.fillRect(x - w/2, ly - h/2, w, h);
              if (i===2) { // Porta
                  ctx.fillStyle = '#000';
                  ctx.fillRect(x - 10, ly - 10, 20, 30);
              }
          }
          else {
             w = 24;
             ctx.fillStyle = type === 'DEMON' ? '#b91c1c' : '#65a30d';
             ctx.fillRect(x - w/2, ly - w/2, w, w);
          }
      }
  };

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = CANVAS_WIDTH;
    canvas.height = CANVAS_HEIGHT;

    ctx.fillStyle = gameStateRef.current === GameState.ISLAND ? COLORS.background : '#020617'; // Noite na torre
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Camera
    const playerPos = toIso(playerRef.current.x, playerRef.current.y, playerRef.current.z);
    const camX = CANVAS_WIDTH / 2 - playerPos.x;
    const camY = CANVAS_HEIGHT / 2 - playerPos.y;

    ctx.save();
    ctx.translate(camX, camY);

    // Desenhar Terreno
    const tileSize = 100;
    const range = 12;
    const px = Math.floor(playerRef.current.x / tileSize);
    const py = Math.floor(playerRef.current.y / tileSize);

    for (let i = px - range; i <= px + range; i++) {
        for (let j = py - range; j <= py + range; j++) {
            const wx = i * tileSize;
            const wy = j * tileSize;

            let color = COLORS.grass;
            let topColor = COLORS.grassHighlight;
            let h = 0;

            if (gameStateRef.current === GameState.ISLAND) {
                 const dist = Math.hypot(wx, wy);
                 if (dist > 1400) { color = COLORS.water; topColor = COLORS.waterHighlight; h = -20; }
                 else if (Math.abs(wx) < 150 && Math.abs(wy - (-600)) < 150) { color = COLORS.stone; topColor = COLORS.stoneHighlight; h = 10; }
            } else {
                 // Estilo Masmorra
                 color = '#1e293b'; 
                 topColor = (i+j)%2===0 ? '#334155' : '#1e293b';
                 if (Math.abs(wx) > 900 || Math.abs(wy) > 900) { h = 100; color = '#020617'; topColor = '#0f172a'; }
            }

            const iso = toIso(wx, wy, 0);

            // Desenho do Bloco
            ctx.beginPath();
            ctx.moveTo(iso.x, iso.y - h);
            ctx.lineTo(iso.x + tileSize, iso.y - h + tileSize/2);
            ctx.lineTo(iso.x, iso.y - h + tileSize);
            ctx.lineTo(iso.x - tileSize, iso.y - h + tileSize/2);
            ctx.fillStyle = topColor;
            ctx.fill();

            if (h !== 0 && h > -10) {
                 ctx.fillStyle = adjustColor(color, -40);
                 ctx.beginPath();
                 ctx.moveTo(iso.x + tileSize, iso.y - h + tileSize/2);
                 ctx.lineTo(iso.x + tileSize, iso.y + tileSize/2);
                 ctx.lineTo(iso.x, iso.y + tileSize);
                 ctx.lineTo(iso.x, iso.y - h + tileSize);
                 ctx.fill();

                 ctx.fillStyle = adjustColor(color, -20);
                 ctx.beginPath();
                 ctx.moveTo(iso.x - tileSize, iso.y - h + tileSize/2);
                 ctx.lineTo(iso.x - tileSize, iso.y + tileSize/2);
                 ctx.lineTo(iso.x, iso.y + tileSize);
                 ctx.lineTo(iso.x, iso.y - h + tileSize);
                 ctx.fill();
            }
        }
    }

    // Efeito de Chão Molhado (Reflexo)
    if (isRainingRef.current) {
        ctx.globalAlpha = 0.1;
        ctx.fillStyle = '#fff';
        ctx.fillRect(playerPos.x - 1000, playerPos.y - 1000, 2000, 2000);
        ctx.globalAlpha = 1.0;
    }

    // Depth Sorting de TUDO (Player, Inimigos, Arvores, Casas)
    const renderList: any[] = [
        { type: 'PLAYER', obj: playerRef.current, y: toIso(playerRef.current.x, playerRef.current.y).y },
        ...enemiesRef.current.map(e => ({ type: e.isBoss ? 'BOSS' : e.type, obj: e, y: toIso(e.x, e.y).y })),
        ...particlesRef.current.map(p => ({ type: p.type || 'PARTICLE', obj: p, y: toIso(p.x, p.y).y })),
    ];

    // Adicionar objetos estáticos apenas na ilha
    if (gameStateRef.current === GameState.ISLAND) {
        staticObjectsRef.current.forEach(obj => {
            renderList.push({ type: obj.type, obj, y: toIso(obj.x, obj.y).y });
        });
    }

    renderList.sort((a, b) => a.y - b.y);

    renderList.forEach(item => {
        if (item.type === 'PARTICLE' || item.type === 'RAIN') {
             const { x, y } = toIso(item.obj.x, item.obj.y, item.obj.z);
             ctx.fillStyle = item.obj.color;
             if (item.type === 'RAIN') {
                 ctx.strokeStyle = item.obj.color;
                 ctx.lineWidth = 1;
                 ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x-2, y+10); ctx.stroke();
             } else {
                 ctx.beginPath(); ctx.arc(x, y, item.obj.size, 0, Math.PI*2); ctx.fill();
             }
        } else {
             drawIsoSprite(ctx, item.obj, item.type);
             // HP Bars
             if (['PLAYER', 'SLIME', 'GOBLIN', 'DEMON', 'BOSS'].includes(item.type) && item.obj.hp < item.obj.maxHp) {
                 const { x, y } = toIso(item.obj.x, item.obj.y, item.obj.z + (item.type === 'BOSS' ? 80 : 30));
                 const w = item.type === 'BOSS' ? 80 : 30;
                 ctx.fillStyle = 'black'; ctx.fillRect(x - w/2, y - 5, w, 4);
                 ctx.fillStyle = 'red'; ctx.fillRect(x - w/2, y - 5, w * (item.obj.hp/item.obj.maxHp), 4);
             }
        }
    });

    // Projéteis
    projectilesRef.current.forEach(p => {
        const { x, y } = toIso(p.x, p.y, p.z);
        ctx.fillStyle = p.color;
        if (p.type === 'SWORD_SLASH') {
             ctx.strokeStyle = 'white'; ctx.lineWidth = 2;
             ctx.beginPath(); ctx.ellipse(x, y, p.radius, p.radius*0.5, 0, 0, Math.PI*2); ctx.stroke();
        } else if (p.type === 'FIRE_ZONE') {
             ctx.fillStyle = 'rgba(239, 68, 68, 0.3)';
             ctx.beginPath(); ctx.ellipse(x, y, p.radius, p.radius*0.5, 0, 0, Math.PI*2); ctx.fill();
        } else {
             ctx.beginPath(); ctx.arc(x, y, 5, 0, Math.PI*2); ctx.fill();
        }
    });

    // MIRA ISOMÉTRICA (Cursor no chão)
    const aim = toIso(mouseWorldRef.current.x, mouseWorldRef.current.y, 0);
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(playerPos.x, playerPos.y); // Linha do player à mira
    ctx.lineTo(aim.x, aim.y);
    ctx.stroke();

    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.ellipse(aim.x, aim.y, 10, 5, 0, 0, Math.PI*2); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(aim.x - 15, aim.y); ctx.lineTo(aim.x + 15, aim.y); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(aim.x, aim.y - 10); ctx.lineTo(aim.x, aim.y + 10); ctx.stroke();

    ctx.restore();

    // CLIMA & EFEITOS DE TELA (Screen Space)
    if (gameStateRef.current === GameState.TOWER) {
        // Névoa
        const gradient = ctx.createRadialGradient(CANVAS_WIDTH/2, CANVAS_HEIGHT/2, 100, CANVAS_WIDTH/2, CANVAS_HEIGHT/2, 800);
        gradient.addColorStop(0, 'rgba(0,0,0,0)');
        gradient.addColorStop(1, 'rgba(2, 6, 23, 0.6)');
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

        // Nuvens
        cloudsRef.current.forEach(c => {
             // Simular projeção
             const cx = c.x + camX * 0.2; // Parallax
             const cy = c.y + camY * 0.2;

             ctx.fillStyle = `rgba(200, 200, 255, ${c.opacity})`;
             ctx.beginPath();
             ctx.arc(cx, cy, c.size, 0, Math.PI*2);
             ctx.arc(cx + c.size*0.8, cy + c.size*0.2, c.size*0.8, 0, Math.PI*2);
             ctx.fill();
        });
    }

    // Damage Numbers
    ctx.font = 'bold 16px sans-serif';
    damageNumbersRef.current.forEach(dn => {
        const pos = toIso(dn.x, dn.y, dn.z);
        const sx = pos.x + camX;
        const sy = pos.y + camY;
        ctx.fillStyle = dn.isCrit ? '#facc15' : 'white';
        ctx.strokeStyle = 'black'; ctx.lineWidth = 2;
        ctx.strokeText(Math.floor(dn.value).toString(), sx, sy);
        ctx.fillText(Math.floor(dn.value).toString(), sx, sy);
    });
  };

  const formatTime = (s: number) => `${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;

  return (
    <div className="relative w-full h-full bg-[#0f172a] cursor-none">
      <canvas ref={canvasRef} className="block w-full h-full cursor-none" />

      {/* --- HUD CENTRALIZADA --- */}
      <div className="absolute inset-x-0 bottom-4 flex flex-col items-center pointer-events-none">

          {/* Boss Bar */}
          {hudData.bossHp > 0 && (
              <div className="mb-8 w-[600px] bg-slate-900 border-2 border-red-900 p-1 rounded-lg">
                  <div className="flex justify-between text-red-500 font-bold mb-1 px-2 uppercase tracking-widest">
                      <span>Chefe da Torre</span>
                      <span>{Math.ceil(hudData.bossHp)}/{Math.ceil(hudData.bossMaxHp)}</span>
                  </div>
                  <div className="h-4 w-full bg-slate-800 rounded overflow-hidden">
                      <div className="h-full bg-red-600 transition-all" style={{width: `${(hudData.bossHp/hudData.bossMaxHp)*100}%`}}></div>
                  </div>
              </div>
          )}

          <div className="flex items-end gap-4">
              {/* HP & Info */}
              <div className="bg-slate-900/90 border border-slate-600 rounded-xl p-4 backdrop-blur-md shadow-2xl w-64">
                   <div className="flex items-center gap-2 text-red-400 font-bold text-xl mb-2">
                       <Heart fill="currentColor" /> {Math.ceil(hudData.hp)}
                   </div>
                   <div className="h-3 bg-slate-800 rounded-full overflow-hidden border border-slate-700 mb-2">
                       <div className="h-full bg-red-500" style={{width: `${(hudData.hp/hudData.maxHp)*100}%`}}></div>
                   </div>
                   <div className="flex justify-between text-xs text-slate-400 font-mono">
                       <span>LVL {hudData.level}</span>
                       <span>XP {Math.floor(hudData.xp)}/{Math.floor(hudData.xpNext)}</span>
                   </div>
              </div>

              {/* Skills Bar */}
              <div className="flex gap-2 p-3 bg-slate-900/90 border border-slate-600 rounded-xl backdrop-blur-md shadow-2xl">
                  {/* Basic Attack */}
                  <div className="w-16 h-16 bg-slate-800 rounded border border-slate-600 flex flex-col items-center justify-center grayscale opacity-75">
                      <Sword size={24} />
                      <span className="text-[10px] mt-1 font-bold text-slate-400">MOUSE</span>
                  </div>

                  {/* Skill 1 (Q) */}
                  <div className="relative w-16 h-16 bg-slate-800 rounded border border-blue-500 flex flex-col items-center justify-center overflow-hidden">
                      <Crosshair size={24} className="text-blue-400" />
                      <span className="text-[10px] mt-1 font-bold text-blue-200">Q</span>
                      {hudData.skill1Cd > 0 && (
                          <div className="absolute inset-0 bg-black/60 flex items-center justify-center font-bold text-white text-lg">
                              {Math.ceil(hudData.skill1Cd)}
                          </div>
                      )}
                  </div>

                  {/* Dash (E) */}
                  <div className="relative w-16 h-16 bg-slate-800 rounded border border-green-500 flex flex-col items-center justify-center overflow-hidden">
                      <Wind size={24} className="text-green-400" />
                      <span className="text-[10px] mt-1 font-bold text-green-200">E</span>
                      {hudData.dashCd > 0 && (
                          <div className="absolute inset-0 bg-black/60 flex items-center justify-center font-bold text-white text-lg">
                              {Math.ceil(hudData.dashCd)}
                          </div>
                      )}
                  </div>

                  {/* Item Ativo (R) */}
                  <div className={`relative w-16 h-16 rounded border flex flex-col items-center justify-center overflow-hidden
                      ${hudData.activeItem ? 'bg-slate-800 border-amber-500' : 'bg-slate-900 border-slate-700 opacity-50'}`}>
                      {hudData.activeItem ? (
                          <>
                            <span className="text-2xl">{hudData.activeItem.icon}</span>
                            <span className="text-[10px] mt-1 font-bold text-amber-200">R</span>
                          </>
                      ) : <Box size={24} className="text-slate-600" />}

                      {hudData.itemCd > 0 && (
                          <div className="absolute inset-0 bg-black/60 flex items-center justify-center font-bold text-white text-lg">
                              {Math.ceil(hudData.itemCd)}
                          </div>
                      )}
                  </div>
              </div>

              {/* Wave Info */}
              {hudData.state === GameState.TOWER && (
                  <div className="bg-slate-900/90 border border-slate-600 rounded-xl p-4 backdrop-blur-md shadow-2xl w-40 text-center">
                      <div className="text-2xl font-mono font-bold text-white mb-1">{formatTime(hudData.time)}</div>
                      <div className="text-xs text-slate-400 flex items-center justify-center gap-1">
                          <Skull size={12} /> WAVE {hudData.wave}
                      </div>
                      {isRainingRef.current && (
                          <div className="text-[10px] text-blue-300 animate-pulse mt-1">CHUVA FORTE</div>
                      )}
                  </div>
              )}
          </div>
      </div>

      {/* Tutorial Ilha */}
      {hudData.state === GameState.ISLAND && (
          <div className="absolute top-10 w-full text-center pointer-events-none">
              <span className="bg-slate-900/80 px-4 py-2 rounded-full text-slate-200 border border-slate-700 shadow-lg">
                  Explore a ilha. Pressione Q, E, R para testar habilidades. Vá ao Norte.
              </span>
          </div>
      )}

      {showUpgrade && (
        <UpgradeModal 
          options={upgradeOptions} 
          memoryOption={lastUpgrade}
          onSelect={applyUpgrade} 
        />
      )}
    </div>
  );
};

