import React, { useEffect, useRef, useState } from 'react';
import { Player, Enemy, Projectile, GameState, Archetype, Particle, DamageNumber, Upgrade, Item, StaticObject } from '../types';
import { CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, BASE_STATS, WAVE_CONFIGS, UPGRADES_LIST, SKILL_CONFIG } from '../constants';
import { UpgradeModal } from './UpgradeModal';
import { Heart, Skull, Zap, MousePointer2, Sword, Box, Crosshair, Wind } from 'lucide-react';

interface GameCanvasProps {
  archetype: Archetype;
  onGameOver: () => void;
}

// Helper de Cor para Hex
const adjustColor = (color: string, amount: number) => {
    let usePound = false;
    if (color[0] === "#") {
        color = color.slice(1);
        usePound = true;
    }
    const num = parseInt(color, 16);
    let r = (num >> 16) + amount;
    if (r > 255) r = 255; else if (r < 0) r = 0;
    let b = ((num >> 8) & 0x00FF) + amount;
    if (b > 255) b = 255; else if (b < 0) b = 0;
    let g = (num & 0x0000FF) + amount;
    if (g > 255) g = 255; else if (g < 0) g = 0;
    return (usePound ? "#" : "") + (g | (b << 8) | (r << 16)).toString(16).padStart(6, '0');
};

const toIso = (x: number, y: number, z: number = 0) => {
  const isoX = (x - y);
  const isoY = (x + y) / 2 - z;
  return { x: isoX, y: isoY };
};

// Conversão Tela -> Mundo (Baseada no centro 0,0)
const toWorldVector = (screenX: number, screenY: number) => {
    const worldX = screenY + screenX / 2;
    const worldY = screenY - screenX / 2;
    return { x: worldX, y: worldY };
};

// Função LERP para câmera suave
const lerp = (start: number, end: number, t: number) => {
  return start * (1 - t) + end * t;
};

export const GameCanvas: React.FC<GameCanvasProps> = ({ archetype, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Estado do Jogo
  const gameStateRef = useRef<GameState>(GameState.ISLAND);
  const playerRef = useRef<Player>({
    x: 0, y: 0, z: 0,
    archetype,
    stats: JSON.parse(JSON.stringify(BASE_STATS[archetype])),
    level: 1, xp: 0, xpToNextLevel: 100,
    weaponTimer: 0, skill1Timer: 0, skill1MaxCooldown: SKILL_CONFIG[archetype].skill1Cd,
    dashTimer: 0, dashMaxCooldown: SKILL_CONFIG[archetype].dashCd,
    activeItem: null, itemTimer: 0, itemMaxCooldown: 0,
    facing: 0, isMoving: false, color: COLORS[archetype], animFrame: 0
  });

  const enemiesRef = useRef<Enemy[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const damageNumbersRef = useRef<DamageNumber[]>([]);
  const staticObjectsRef = useRef<StaticObject[]>([]);
  const keysRef = useRef<{ [key: string]: boolean }>({});

  // Refs de Sistema
  const cameraRef = useRef({ x: 0, y: 0 }); // Câmera com LERP
  const shakeRef = useRef(0); // Screen Shake intensity
  const timeRef = useRef<number>(0); 
  const waveRef = useRef<number>(0);
  const waveTimerRef = useRef<number>(0);
  const lastSpawnTimeRef = useRef<number>(0);
  const isRainingRef = useRef<boolean>(false);
  const rainTimerRef = useRef<number>(0);

  // UI State
  const [showUpgrade, setShowUpgrade] = useState(false);
  const [upgradeOptions, setUpgradeOptions] = useState<Upgrade[]>([]);
  const [lastUpgrade, setLastUpgrade] = useState<Upgrade | null>(null);
  const [hudData, setHudData] = useState({ 
      hp: 100, maxHp: 100, xp: 0, xpNext: 100, time: 0, wave: 1, level: 1, 
      state: GameState.ISLAND, skill1Cd: 0, dashCd: 0, itemCd: 0,
      activeItem: null as Item | null, bossHp: 0, bossMaxHp: 0
  });

  const mouseScreenRef = useRef({ x: 0, y: 0 });
  const mouseWorldRef = useRef({ x: 0, y: 0 });

  // --- Inicialização ---
  useEffect(() => {
    const objects: StaticObject[] = [];
    objects.push({ id: 'h1', x: -200, y: -200, type: 'HOUSE', size: 100 });
    objects.push({ id: 'h2', x: 200, y: -250, type: 'HOUSE', size: 120 });
    objects.push({ id: 'h3', x: -300, y: 100, type: 'HOUSE', size: 90 });
    objects.push({ id: 'lamp1', x: 50, y: -500, type: 'LAMP', size: 20 });

    for(let i=0; i<40; i++) {
        const angle = Math.random() * Math.PI * 2;
        const dist = 500 + Math.random() * 800;
        objects.push({ id: `t${i}`, x: Math.cos(angle) * dist, y: Math.sin(angle) * dist, type: 'TREE', size: 40 + Math.random() * 40 });
    }
    staticObjectsRef.current = objects;
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { 
        if (e.code === 'Space') e.preventDefault();
        keysRef.current[e.code] = true;
    };
    const handleKeyUp = (e: KeyboardEvent) => { keysRef.current[e.code] = false; };
    const handleMouseMove = (e: MouseEvent) => {
      const rect = canvasRef.current?.getBoundingClientRect();
      if(rect) {
          mouseScreenRef.current = { 
            x: e.clientX - rect.left - rect.width / 2, 
            y: e.clientY - rect.top - rect.height / 2 
          };
      }
    };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) keysRef.current['MouseLeft'] = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) keysRef.current['MouseLeft'] = false; };
    const handleContextMenu = (e: MouseEvent) => e.preventDefault();

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    window.addEventListener('contextmenu', handleContextMenu);

    let animationFrameId: number;
    let lastTime = performance.now();

    const loop = (timestamp: number) => {
      const dt = Math.min((timestamp - lastTime) / 1000, 0.1);
      lastTime = timestamp;

      if (gameStateRef.current === GameState.TOWER || gameStateRef.current === GameState.ISLAND) {
        update(dt);
      }
      draw(dt);
      animationFrameId = requestAnimationFrame(loop);
    };

    animationFrameId = requestAnimationFrame(loop);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
      window.removeEventListener('contextmenu', handleContextMenu);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  // --- UPDATE ---
  const update = (dt: number) => {
    const player = playerRef.current;

    // Calcular Mouse no Mundo (Corrigido com Câmera)
    // Screen = World - CameraPos (Inverted logic because CameraPos is translation)
    // Se a câmera move para a esquerda (-x), os objetos movem para a direita.
    // O mouse é relativo à tela.
    // Preciso calcular onde na grade isométrica o mouse está.

    // Passo 1: Converter Offset da Tela para Vetor Isométrico
    const isoVector = toWorldVector(mouseScreenRef.current.x, mouseScreenRef.current.y);

    // Passo 2: Calcular a posição da câmera no mundo (inverso do que desenhamos)
    // No draw: translate(cameraRef.x, cameraRef.y).
    // cameraRef.x tende a -playerIso.x
    // Então para obter a posição absoluta do mouse:
    // MouseWorld = PlayerPos + isoVector (Se a câmera estivesse perfeita no player)

    // Como a câmera tem LERP, precisamos usar a posição real do centro da tela projetada no mundo.
    // O centro da tela é (CANVAS_WIDTH/2, CANVAS_HEIGHT/2).
    // O translate move o mundo.
    // A posição 0,0 da tela corresponde ao ponto (-camX, -camY) do mundo desenhado (screen space).
    // Vamos simplificar: A mira deve ser relativa ao JOGADOR se o jogador estiver no centro.
    // Mas o jogador não está sempre no centro.

    // Correção Robusta:
    // O vetor 'isoVector' é a distância do CENTRO DA TELA até o MOUSE no espaço isométrico.
    // O centro da tela, no mundo, é aproximadamente a posição do jogador (com lag do lerp).
    // Vamos pegar a posição do centro da tela no mundo:
    // CenterWorld = Inverso de toIso(-cameraRef.x, -cameraRef.y)? Não.

    // Vamos usar a posição do jogador + o vetor do mouse. É o mais intuitivo para controles top-down,
    // mesmo se a câmera estiver atrasada, você quer mirar relativo ao seu boneco.
    // ENTRETANTO, se a câmera estiver atrasada, e você mirar no canto da tela, você quer clicar NAQUELE chão.
    // Vamos usar a posição visual do jogador + mouseScreen corrigido.

    // Melhor approach: Calcular mouseWorld baseado no Player visual.
    // O Player é desenhado em `playerPos` (Iso).
    // O Mouse está em `mouseScreenRef` (Pixel offset do centro).
    // Se somarmos `mouseScreenRef` convertido para Iso ao `playerRef`, teremos a posição real?
    // Quase. Se a câmera estiver atrasada, o jogador não está no centro.

    // Correção Final:
    // O offset do jogador em relação ao centro da tela é:
    // PlayerScreenOffset = toIso(player) + cameraRef
    // MouseScreenOffset = mouseScreenRef
    // DeltaScreen = MouseScreenOffset - PlayerScreenOffset
    // TargetWorld = Player + toWorldVector(DeltaScreen)

    const playerIso = toIso(player.x, player.y, player.z);
    const playerScreenX = playerIso.x + cameraRef.current.x;
    const playerScreenY = playerIso.y + cameraRef.current.y;

    const deltaScreenX = mouseScreenRef.current.x - playerScreenX;
    const deltaScreenY = mouseScreenRef.current.y - playerScreenY;

    const deltaWorld = toWorldVector(deltaScreenX, deltaScreenY);

    mouseWorldRef.current = {
        x: player.x + deltaWorld.x,
        y: player.y + deltaWorld.y
    };

    player.facing = Math.atan2(mouseWorldRef.current.y - player.y, mouseWorldRef.current.x - player.x);

    // Movimento
    let dx = 0;
    let dy = 0;
    if (keysRef.current['KeyW'] || keysRef.current['ArrowUp']) { dx -= 1; dy -= 1; }
    if (keysRef.current['KeyS'] || keysRef.current['ArrowDown']) { dx += 1; dy += 1; }
    if (keysRef.current['KeyA'] || keysRef.current['ArrowLeft']) { dx -= 1; dy += 1; }
    if (keysRef.current['KeyD'] || keysRef.current['ArrowRight']) { dx += 1; dy -= 1; }

    player.isMoving = dx !== 0 || dy !== 0;
    if (player.isMoving) {
      const length = Math.sqrt(dx * dx + dy * dy);
      dx /= length; dy /= length;
      const speed = player.stats.speed * 60 * dt;
      player.x += dx * speed;
      player.y += dy * speed;
      player.animFrame += dt * 10;
    } else {
        player.animFrame = 0;
    }

    if (player.z > 0) {
        player.z -= 150 * dt; 
        if (player.z < 0) player.z = 0;
    }

    const limit = gameStateRef.current === GameState.ISLAND ? 1500 : 900;
    if (Math.abs(player.x) > limit) player.x = Math.sign(player.x) * limit;
    if (Math.abs(player.y) > limit) player.y = Math.sign(player.y) * limit;

    // Camera Lerp
    const targetCamX = -playerIso.x; 
    const targetCamY = -playerIso.y;
    cameraRef.current.x = lerp(cameraRef.current.x, targetCamX, 0.1);
    cameraRef.current.y = lerp(cameraRef.current.y, targetCamY, 0.1);

    // Lógica de Estados
    if (gameStateRef.current === GameState.ISLAND) {
        const distToTower = Math.hypot(player.x - 0, player.y - (-600)); 
        if (distToTower < 150) {
            gameStateRef.current = GameState.TOWER;
            player.x = 0; player.y = 0;
            enemiesRef.current = [];
            projectilesRef.current = [];
            waveRef.current = 0;
            timeRef.current = 0;
            rainTimerRef.current = 0;
        }
        if (player.stats.hp < player.stats.maxHp) player.stats.hp += 100 * dt;
    }

    if (gameStateRef.current === GameState.TOWER) {
        timeRef.current += dt;
        waveTimerRef.current += dt;
        player.skill1Timer -= dt;
        player.dashTimer -= dt;
        player.itemTimer -= dt;
        player.weaponTimer -= dt;

        // Chuva: Começa aos 60s, dura 60s. Repete.
        rainTimerRef.current += dt;
        if (!isRainingRef.current && rainTimerRef.current > 60) {
             isRainingRef.current = true;
             rainTimerRef.current = 0; // Reset para contar duração
        }
        if (isRainingRef.current && rainTimerRef.current > 60) {
             isRainingRef.current = false;
             rainTimerRef.current = 0; // Reset para contar intervalo
        }

        if (isRainingRef.current) {
            for(let i=0; i<8; i++) { // Mais chuva
                const angle = Math.random() * Math.PI * 2;
                const dist = Math.random() * 900; 
                particlesRef.current.push({
                    id: Math.random().toString(), 
                    x: player.x + Math.cos(angle)*dist - 400, 
                    y: player.y + Math.sin(angle)*dist - 400, 
                    z: 500, vx: 100, vy: 100, vz: -900,
                    life: 0.6, maxLife: 0.6, color: '#a5f3fc', size: 2, type: 'RAIN'
                });
            }
        }

        const currentConfig = WAVE_CONFIGS[waveRef.current] || WAVE_CONFIGS[WAVE_CONFIGS.length-1];
        const bossAlive = enemiesRef.current.some(e => e.isBoss);

        if (!bossAlive && waveTimerRef.current >= currentConfig.duration) {
             triggerUpgrade();
        } 
        else if (!bossAlive && enemiesRef.current.length < currentConfig.enemyCount && Date.now() - lastSpawnTimeRef.current > currentConfig.spawnRate) {
             if (currentConfig.boss && !enemiesRef.current.some(e => e.isBoss)) {
                 spawnBoss(currentConfig.boss);
             } else if (!currentConfig.boss) {
                 spawnEnemy();
             }
             lastSpawnTimeRef.current = Date.now();
        }

        if (keysRef.current['MouseLeft'] && player.weaponTimer <= 0) useMainAttack();
        if (keysRef.current['KeyQ'] && player.skill1Timer <= 0) {
            useSkill1();
            player.skill1Timer = player.skill1MaxCooldown * (1 - player.stats.cooldownReduction);
        }
        if (keysRef.current['KeyE'] && player.dashTimer <= 0) {
            useDash();
            player.dashTimer = player.dashMaxCooldown * (1 - player.stats.cooldownReduction);
        }
        if (keysRef.current['KeyR']) activateItem();
    }

    if (shakeRef.current > 0) shakeRef.current -= dt * 30;
    if (shakeRef.current < 0) shakeRef.current = 0;

    updateProjectiles(dt);
    updateEnemies(dt);
    updateParticles(dt);

    const boss = enemiesRef.current.find(e => e.isBoss);
    setHudData({
        hp: player.stats.hp, maxHp: player.stats.maxHp,
        xp: player.xp, xpNext: player.xpToNextLevel,
        time: timeRef.current, wave: waveRef.current + 1, level: player.level,
        state: gameStateRef.current,
        skill1Cd: player.skill1Timer, dashCd: player.dashTimer, itemCd: player.itemTimer,
        activeItem: player.activeItem,
        bossHp: boss ? boss.hp : 0, bossMaxHp: boss ? boss.maxHp : 0
    });

    if (player.stats.hp <= 0 && gameStateRef.current === GameState.TOWER) {
        gameStateRef.current = GameState.GAME_OVER;
        onGameOver();
    }
  };

  const activateItem = () => {
     const p = playerRef.current;
     if (p.activeItem && p.itemTimer <= 0) {
         p.activeItem.effect(p, enemiesRef.current);
         p.itemTimer = p.activeItem.cooldown;
     }
  };

  const useMainAttack = () => {
     const p = playerRef.current;
     const angle = p.facing;

     // Correção da velocidade do projétil isométrico
     // Como o mundo é achatado visualmente, o vetor 1,1 viaja visualmente diferente.
     // Mas a lógica do jogo roda em Top-Down 2D puro, apenas o render é iso.
     // Então o Math.cos/sin está correto para a lógica.
     const vx = Math.cos(angle) * 800;
     const vy = Math.sin(angle) * 800;

     if (p.archetype === Archetype.WARRIOR) {
         projectilesRef.current.push({
             id: Math.random().toString(), x: p.x, y: p.y, z: 20, vx: 0, vy: 0,
             damage: p.stats.damage, duration: 0.3, radius: 100 * p.stats.areaSize,
             type: 'SWORD_SLASH', color: '#60a5fa', pierce: 999
         });
         p.weaponTimer = 0.6 * (1 - p.stats.cooldownReduction);
     } else {
         projectilesRef.current.push({
             id: Math.random().toString(), x: p.x, y: p.y, z: 30, vx, vy,
             damage: p.stats.damage, duration: 1.5, radius: 15,
             type: p.archetype === Archetype.ARCHER ? 'ARROW' : 'MAGIC_ORB', 
             color: p.color, pierce: p.archetype === Archetype.MAGE ? 2 : 0 // 0 pierce = some no primeiro hit
         });
         p.weaponTimer = (p.archetype === Archetype.ARCHER ? 0.4 : 0.5) * (1 - p.stats.cooldownReduction);
     }
  };

  const useSkill1 = () => {
      const p = playerRef.current;
      createParticle(p.x, p.y, 20, '#fff', 10);
      shakeRef.current = 5; 

      if(p.archetype === Archetype.WARRIOR) {
          projectilesRef.current.push({
             id: Math.random().toString(), x: p.x, y: p.y, z: 20, vx: 0, vy: 0,
             damage: p.stats.damage * 2.5, duration: 0.5, radius: 160 * p.stats.areaSize,
             type: 'SWORD_SLASH', color: '#ef4444', pierce: 999
         });
      } else {
          projectilesRef.current.push({
             id: Math.random().toString(), x: mouseWorldRef.current.x, y: mouseWorldRef.current.y, z: 0, vx: 0, vy: 0,
             damage: p.stats.damage * 3, duration: 1.2, radius: 120 * p.stats.areaSize,
             type: 'FIRE_ZONE', color: p.archetype === Archetype.MAGE ? '#9333ea' : '#ef4444', pierce: 999
         });
      }
  };

  const useDash = () => {
      const p = playerRef.current;
      let angle = p.facing;
      if (p.isMoving) {
          let dx = 0, dy = 0;
          if (keysRef.current['KeyW']) { dx -= 1; dy -= 1; }
          if (keysRef.current['KeyS']) { dx += 1; dy += 1; }
          if (keysRef.current['KeyA']) { dx -= 1; dy += 1; }
          if (keysRef.current['KeyD']) { dx += 1; dy -= 1; }
          if (dx !== 0 || dy !== 0) angle = Math.atan2(dy, dx);
      }
      const vx = Math.cos(angle) * 1200;
      const vy = Math.sin(angle) * 1200;
      p.x += vx * 0.2; 
      p.y += vy * 0.2;
      p.z = 40; 
      createParticle(p.x, p.y, 10, '#fff', 5);
  };

  const spawnBoss = (type: 'BOSS_GOLEM' | 'BOSS_LICH') => {
      const dist = 600;
      const angle = Math.random() * Math.PI * 2;
      enemiesRef.current.push({
          id: 'boss', x: playerRef.current.x + Math.cos(angle)*dist, y: playerRef.current.y + Math.sin(angle)*dist, z: 0,
          type, isBoss: true,
          hp: 2000 * (1 + waveRef.current * 0.5), maxHp: 2000 * (1 + waveRef.current * 0.5),
          speed: 40, damage: 40, radius: 60, hitboxRadius: 50, frame: 0, attackTimer: 2, vx: 0, vy: 0, hitFlash: 0
      });
      shakeRef.current = 20; 
  };

  const spawnEnemy = () => {
    const angle = Math.random() * Math.PI * 2;
    const distance = 900; 
    const ex = playerRef.current.x + Math.cos(angle) * distance;
    const ey = playerRef.current.y + Math.sin(angle) * distance;
    const type = waveRef.current < 5 ? 'SLIME' : (waveRef.current < 10 ? 'GOBLIN' : 'DEMON');

    // Balanceamento de HP (Começa bem baixo para satisfação)
    let hp = 30 + waveRef.current * 8;
    if (type === 'GOBLIN') hp += 30;
    if (type === 'DEMON') hp += 100;

    enemiesRef.current.push({
      id: Math.random().toString(), x: ex, y: ey, z: 0, type, isBoss: false,
      hp: hp, maxHp: hp,
      speed: 80 + Math.random()*20, damage: 10 + waveRef.current,
      radius: 20, hitboxRadius: 15, frame: 0, vx: 0, vy: 0, hitFlash: 0
    });
  };

  const updateEnemies = (dt: number) => {
      const p = playerRef.current;
      enemiesRef.current = enemiesRef.current.filter(e => {
          // Hit Flash Decay
          if (e.hitFlash > 0) e.hitFlash -= dt;

          // Physics
          e.x += e.vx * dt; e.y += e.vy * dt;
          e.vx *= 0.9; e.vy *= 0.9;

          const dx = p.x - e.x;
          const dy = p.y - e.y;
          const dist = Math.hypot(dx, dy);

          if(dist > e.hitboxRadius) {
              if (Math.abs(e.vx) < 10 && Math.abs(e.vy) < 10) {
                  e.x += (dx/dist) * e.speed * dt;
                  e.y += (dy/dist) * e.speed * dt;
              }
          }

          if(dist < e.hitboxRadius + 20) {
              p.stats.hp -= e.damage * dt;
              shakeRef.current = Math.max(shakeRef.current, 2); 
          }

          projectilesRef.current.forEach(proj => {
               // Se projétil já morreu, ignora
               if (proj.duration <= 0) return;

               const pDist = Math.hypot(proj.x - e.x, proj.y - e.y);
               if(pDist < proj.radius + e.hitboxRadius) {
                   // COLISÃO
                   const isAoe = proj.type === 'SWORD_SLASH' || proj.type === 'FIRE_ZONE';
                   const dmg = isAoe ? proj.damage * 5 * dt : proj.damage;
                   const isCrit = Math.random() > 0.8;
                   const finalDmg = isCrit ? dmg * 1.5 : dmg;

                   // Knockback & Flash
                   e.hitFlash = 0.15; // 150ms branco
                   if (proj.type === 'ARROW' || proj.type === 'MAGIC_ORB') {
                       const kAngle = Math.atan2(e.y - proj.y, e.x - proj.x);
                       const force = 300;
                       e.vx = Math.cos(kAngle) * force;
                       e.vy = Math.sin(kAngle) * force;

                       // Consome Pierce / Mata Projétil
                       if (!isAoe) {
                           proj.pierce--;
                           if (proj.pierce < 0) {
                               proj.duration = 0; // MORRE INSTANTANEAMENTE
                           }
                       }
                   } else if (proj.type === 'SWORD_SLASH') {
                        const kAngle = Math.atan2(e.y - p.y, e.x - p.x);
                        e.vx = Math.cos(kAngle) * 50;
                        e.vy = Math.sin(kAngle) * 50;
                   }

                   e.hp -= finalDmg;

                   // Só spawna numero se for dano único ou a cada X frames para AoE
                   if (!isAoe || Math.random() > 0.8) {
                       createDamageNumber(e.x, e.y, e.z + 40, finalDmg, isCrit);
                   }

                   if(e.hp <= 0 && !e.isBoss) {
                       createParticle(e.x, e.y, e.z, '#ef4444', 6, 'BLOOD');
                   }
               }
          });

          if(e.hp <= 0) {
              p.xp += e.isBoss ? 500 : 10;
              if(p.xp >= p.xpToNextLevel) {
                  p.level++;
                  p.xp -= p.xpToNextLevel;
                  p.xpToNextLevel *= 1.2;
                  p.stats.damage *= 1.1;
                  p.stats.maxHp *= 1.1;
                  p.stats.hp = p.stats.maxHp;
                  createDamageNumber(p.x, p.y, p.z+60, 0, true); 
                  shakeRef.current = 5; 
              }
              return false;
          }
          return true;
      });
  };

  const updateProjectiles = (dt: number) => {
      projectilesRef.current = projectilesRef.current.filter(proj => {
          proj.duration -= dt;
          if(proj.type === 'SWORD_SLASH') {
              proj.x = playerRef.current.x; proj.y = playerRef.current.y;
          } else {
              proj.x += proj.vx * dt; proj.y += proj.vy * dt;
          }
          return proj.duration > 0;
      });
  };

  const updateParticles = (dt: number) => {
      particlesRef.current = particlesRef.current.filter(p => {
          p.life -= dt;
          p.x += p.vx * dt;
          p.y += p.vy * dt;
          p.z += p.vz * dt;
          if (p.type !== 'RAIN') p.vz -= 300 * dt; 

          if(p.z < 0) {
              p.z = 0;
              if (p.type === 'RAIN') {
                  createParticle(p.x, p.y, 0, '#fff', 1, 'SPARK');
                  return false; 
              }
              if (p.type === 'BLOOD') {
                  p.vx = 0; p.vy = 0; 
              }
          }
          return p.life > 0;
      });
      damageNumbersRef.current = damageNumbersRef.current.filter(d => { d.life -= dt; d.z += 40 * dt; return d.life > 0; });
  };

  const createParticle = (x: number, y: number, z: number, color: string, count: number, type: 'SPARK'|'BLOOD'|'RAIN' = 'SPARK') => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(), x, y, z,
              vx: (Math.random()-0.5)*150, vy: (Math.random()-0.5)*150, vz: Math.random()*150 + 50,
              life: type === 'BLOOD' ? 3 : 0.5, maxLife: 0.5, color, size: Math.random()*3+2, type
          });
      }
  };

  const createDamageNumber = (x: number, y: number, z: number, val: number, crit: boolean) => {
      if (val < 1) return;
      damageNumbersRef.current.push({id: Math.random().toString(), x, y, z, value: val, life: 0.8, isCrit: crit});
  };

  const triggerUpgrade = () => {
    gameStateRef.current = GameState.PAUSED;
    const options: Upgrade[] = [];
    const rollItem = !playerRef.current.activeItem && Math.random() > 0.5;
    for(let i=0; i<4; i++) {
        let pool = UPGRADES_LIST;
        if (rollItem && i === 0) pool = UPGRADES_LIST.filter(u => u.type === 'ITEM');
        const rand = pool[Math.floor(Math.random() * pool.length)];
        options.push({...rand, id: rand.id + Math.random()}); 
    }
    setUpgradeOptions(options);
    setShowUpgrade(true);
  };

  const applyUpgrade = (upgrade: Upgrade) => {
      const p = playerRef.current;
      if (upgrade.type === 'ITEM' && upgrade.itemRef) {
          p.activeItem = upgrade.itemRef;
      } else {
        if (upgrade.name.includes('Força')) p.stats.damage *= 1.15;
        if (upgrade.name.includes('Velocidade')) p.stats.speed *= 1.1;
        if (upgrade.name.includes('Vida')) { p.stats.maxHp += 50; p.stats.hp += 50; }
        if (upgrade.name.includes('Tempo')) p.stats.cooldownReduction = Math.min(0.7, p.stats.cooldownReduction + 0.08);
        if (upgrade.name.includes('Expansão')) p.stats.areaSize *= 1.2;
      }
      setLastUpgrade(upgrade);
      setShowUpgrade(false);
      gameStateRef.current = GameState.TOWER;
      if (waveTimerRef.current >= WAVE_CONFIGS[0].duration) {
         waveRef.current++;
         waveTimerRef.current = 0;
      }
  };

  // --- RENDERIZAÇÃO ---
  const drawIsoSprite = (ctx: CanvasRenderingContext2D, entity: any, type: string) => {
      let bounce = 0;
      if ((type === 'PLAYER' || type === 'GOBLIN' || type === 'DEMON') && entity.animFrame) {
          bounce = Math.abs(Math.sin(entity.animFrame)) * 5;
      }

      const { x, y } = toIso(entity.x, entity.y, entity.z + bounce);

      // Hit Flash (Branco Puro se tomou dano recentemente)
      if (entity.hitFlash && entity.hitFlash > 0) {
          ctx.save();
          // Desenha sombra
          const shadow = toIso(entity.x, entity.y, 0);
          ctx.fillStyle = 'rgba(0,0,0,0.4)';
          ctx.beginPath(); ctx.ellipse(shadow.x, shadow.y, 15, 8, 0, 0, Math.PI*2); ctx.fill();

          // Desenha corpo branco
          ctx.fillStyle = '#ffffff';
          const h = type === 'BOSS' ? 60 : 20;
          const w = type === 'BOSS' ? 60 : 20;
          ctx.fillRect(x - w/2, y - h, w, h);
          ctx.restore();
          return; // Pula o resto do desenho normal
      }

      // Sombra
      if (entity.z < 10) {
          const shadow = toIso(entity.x, entity.y, 0);
          ctx.fillStyle = 'rgba(0,0,0,0.4)';
          ctx.beginPath();
          ctx.ellipse(shadow.x, shadow.y, type === 'BOSS' ? 40 : 12, type === 'BOSS' ? 20 : 6, 0, 0, Math.PI*2);
          ctx.fill();
      }

      const layers = type === 'BOSS' ? 12 : 6;
      const scale = 2;

      for(let i=0; i<layers; i++) {
          const ly = y - (i * scale * 2);
          let w = 20; let h = 20;
          let color = entity.color || '#fff';

          if (type === 'PLAYER') {
             if (i === 0) { color = '#1e293b'; w = 14; } 
             else if (i < 3) { w = 18; }
             else if (i === 4) { color = '#fca5a5'; w = 14; }
             else if (i === 5) { 
                 color = entity.archetype === Archetype.MAGE ? '#6b21a8' : 
                        (entity.archetype === Archetype.ARCHER ? '#166534' : '#991b1b');
                 w = 16;
             }
             ctx.fillStyle = color;
             ctx.fillRect(x - w/2, ly - w/2, w, w);
             if (i === 2) { ctx.fillStyle = '#94a3b8'; ctx.fillRect(x + 10, ly - 5, 4, 15); }
          } 
          else if (type === 'BOSS') {
             w = 60 - i*2; h = 60 - i*2;
             ctx.fillStyle = i % 2 === 0 ? '#7f1d1d' : '#991b1b';
             ctx.shadowBlur = 10; ctx.shadowColor = 'red';
             ctx.fillRect(x - w/2, ly - h/2, w, h);
             ctx.shadowBlur = 0;
          }
          else if (type === 'SLIME') {
             w = 24 - i*3; 
             ctx.fillStyle = i > 3 ? '#86efac' : '#22c55e';
             ctx.beginPath(); ctx.arc(x, ly, w/2, 0, Math.PI*2); ctx.fill();
          } 
          else if (type === 'TREE') {
              w = entity.size * (1 - i/10); h = w;
              ctx.fillStyle = i === 0 ? '#451a03' : '#14532d';
              if (i > 2) ctx.fillStyle = '#166534';
              if (i === 0) w = w / 3;
              ctx.fillRect(x - w/2, ly - h/2, w, h);
          }
          else if (type === 'HOUSE') {
              w = entity.size; h = entity.size;
              ctx.fillStyle = i < 4 ? '#78350f' : '#dc2626';
              if (i >= 4) { w = w * (1 - (i-4)/6); h = h * (1 - (i-4)/6); }
              ctx.fillRect(x - w/2, ly - h/2, w, h);
              if (i===2) { ctx.fillStyle = '#000'; ctx.fillRect(x - 10, ly - 10, 20, 30); }
          }
          else if (type === 'LAMP') {
             w = 6;
             if (i < 8) ctx.fillStyle = '#333';
             else { ctx.fillStyle = '#fbbf24'; ctx.shadowBlur = 20; ctx.shadowColor = 'orange'; }
             ctx.fillRect(x - w/2, ly - w*2, w, w*2);
             ctx.shadowBlur = 0;
          }
          else { 
             w = 24;
             ctx.fillStyle = type === 'DEMON' ? '#b91c1c' : '#65a30d';
             ctx.fillRect(x - w/2, ly - w/2, w, w);
          }
      }
  };

  const draw = (dt: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    canvas.width = CANVAS_WIDTH;
    canvas.height = CANVAS_HEIGHT;

    ctx.fillStyle = gameStateRef.current === GameState.ISLAND ? COLORS.background : '#020617'; 
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // LERP da Camera
    const playerPos = toIso(playerRef.current.x, playerRef.current.y, playerRef.current.z);
    const camTargetX = CANVAS_WIDTH / 2 - playerPos.x;
    const camTargetY = CANVAS_HEIGHT / 2 - playerPos.y;
    cameraRef.current.x = lerp(cameraRef.current.x, camTargetX, 0.1);
    cameraRef.current.y = lerp(cameraRef.current.y, camTargetY, 0.1);

    const shakeX = (Math.random() - 0.5) * shakeRef.current;
    const shakeY = (Math.random() - 0.5) * shakeRef.current;

    ctx.save();
    ctx.translate(cameraRef.current.x + shakeX, cameraRef.current.y + shakeY);

    // Desenhar Terreno
    const tileSize = 100;
    const range = 14; 
    const px = Math.floor(playerRef.current.x / tileSize);
    const py = Math.floor(playerRef.current.y / tileSize);

    for (let i = px - range; i <= px + range; i++) {
        for (let j = py - range; j <= py + range; j++) {
            const wx = i * tileSize;
            const wy = j * tileSize;

            let color = COLORS.grass;
            let topColor = COLORS.grassHighlight;
            let h = 0;

            if (gameStateRef.current === GameState.ISLAND) {
                 const dist = Math.hypot(wx, wy);
                 if (dist > 1400) { color = COLORS.water; topColor = COLORS.waterHighlight; h = -20; }
                 else if (Math.abs(wx) < 150 && Math.abs(wy - (-600)) < 150) { color = COLORS.stone; topColor = COLORS.stoneHighlight; h = 10; }
            } else {
                 const noise = (Math.sin(i*0.5) + Math.cos(j*0.5)) * 10; 
                 const isFloor = (i+j)%2===0;
                 color = '#1e293b'; 
                 topColor = isFloor ? adjustColor('#334155', noise) : adjustColor('#1e293b', noise);
                 if (Math.abs(wx) > 900 || Math.abs(wy) > 900) { h = 100; color = '#020617'; topColor = '#0f172a'; }
            }

            const iso = toIso(wx, wy, 0);

            ctx.beginPath();
            ctx.moveTo(iso.x, iso.y - h);
            ctx.lineTo(iso.x + tileSize, iso.y - h + tileSize/2);
            ctx.lineTo(iso.x, iso.y - h + tileSize);
            ctx.lineTo(iso.x - tileSize, iso.y - h + tileSize/2);
            ctx.fillStyle = topColor;
            ctx.fill();

            if (h !== 0 && h > -10) {
                 ctx.fillStyle = adjustColor(color, -40);
                 ctx.beginPath();
                 ctx.moveTo(iso.x + tileSize, iso.y - h + tileSize/2);
                 ctx.lineTo(iso.x + tileSize, iso.y + tileSize/2);
                 ctx.lineTo(iso.x, iso.y + tileSize);
                 ctx.lineTo(iso.x, iso.y - h + tileSize);
                 ctx.fill();

                 ctx.fillStyle = adjustColor(color, -20);
                 ctx.beginPath();
                 ctx.moveTo(iso.x - tileSize, iso.y - h + tileSize/2);
                 ctx.lineTo(iso.x - tileSize, iso.y + tileSize/2);
                 ctx.lineTo(iso.x, iso.y + tileSize);
                 ctx.lineTo(iso.x, iso.y - h + tileSize);
                 ctx.fill();
            }
        }
    }

    // Efeito de Chão Molhado
    if (isRainingRef.current) {
        ctx.globalAlpha = 0.1;
        ctx.fillStyle = '#fff';
        ctx.fillRect(playerRef.current.x - 1000, playerRef.current.y - 1000, 2000, 2000); 
        ctx.globalAlpha = 1.0;
    }

    // Depth Sorting
    const renderList: any[] = [
        { type: 'PLAYER', obj: playerRef.current, y: toIso(playerRef.current.x, playerRef.current.y).y },
        ...enemiesRef.current.map(e => ({ type: e.isBoss ? 'BOSS' : e.type, obj: e, y: toIso(e.x, e.y).y })),
        ...particlesRef.current.map(p => ({ type: p.type || 'PARTICLE', obj: p, y: toIso(p.x, p.y).y })),
    ];

    if (gameStateRef.current === GameState.ISLAND) {
        staticObjectsRef.current.forEach(obj => {
            renderList.push({ type: obj.type, obj, y: toIso(obj.x, obj.y).y });
        });
    }

    renderList.sort((a, b) => a.y - b.y);

    renderList.forEach(item => {
        if (item.type === 'PARTICLE' || item.type === 'RAIN' || item.type === 'BLOOD' || item.type === 'SPARK') {
             const { x, y } = toIso(item.obj.x, item.obj.y, item.obj.z);
             ctx.fillStyle = item.obj.color;

             if (item.type === 'RAIN') {
                 ctx.strokeStyle = item.obj.color;
                 ctx.lineWidth = 1;
                 ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x-2, y+10); ctx.stroke();
             } else if (item.type === 'BLOOD') {
                 ctx.globalAlpha = 0.7;
                 ctx.beginPath(); ctx.ellipse(x, y, item.obj.size*2, item.obj.size, 0, 0, Math.PI*2); ctx.fill();
                 ctx.globalAlpha = 1.0;
             } else {
                 ctx.shadowBlur = 5; ctx.shadowColor = item.obj.color;
                 ctx.beginPath(); ctx.arc(x, y, item.obj.size, 0, Math.PI*2); ctx.fill();
                 ctx.shadowBlur = 0;
             }
        } else {
             drawIsoSprite(ctx, item.obj, item.type);

             // HP Bars Globais
             if (item.obj.hp < item.obj.maxHp && item.obj.hp > 0 && item.type !== 'PARTICLE') {
                 const isBoss = item.type === 'BOSS';
                 const offsetZ = isBoss ? 80 : 30;
                 const { x, y } = toIso(item.obj.x, item.obj.y, item.obj.z + offsetZ);
                 const w = isBoss ? 80 : 20;
                 const h = 4;

                 ctx.fillStyle = '#000'; 
                 ctx.fillRect(x - w/2 - 1, y - 5 - 1, w + 2, h + 2); // Borda

                 ctx.fillStyle = '#1e293b'; 
                 ctx.fillRect(x - w/2, y - 5, w, h); // Fundo

                 ctx.fillStyle = isBoss ? '#dc2626' : '#ef4444'; 
                 ctx.fillRect(x - w/2, y - 5, w * (item.obj.hp/item.obj.maxHp), h); // Vida
             }
        }
    });

    // Projéteis
    projectilesRef.current.forEach(p => {
        const { x, y } = toIso(p.x, p.y, p.z);
        ctx.fillStyle = p.color;
        ctx.shadowBlur = 10; ctx.shadowColor = p.color;

        if (p.type === 'SWORD_SLASH') {
             ctx.strokeStyle = 'white'; ctx.lineWidth = 2;
             ctx.beginPath(); ctx.ellipse(x, y, p.radius, p.radius*0.5, 0, 0, Math.PI*2); ctx.stroke();
        } else if (p.type === 'FIRE_ZONE') {
             ctx.fillStyle = 'rgba(239, 68, 68, 0.4)';
             ctx.beginPath(); ctx.ellipse(x, y, p.radius, p.radius*0.5, 0, 0, Math.PI*2); ctx.fill();
        } else {
             ctx.beginPath(); ctx.arc(x, y, 5, 0, Math.PI*2); ctx.fill();
        }
        ctx.shadowBlur = 0;
    });

    // Mira Corrigida
    const aim = toIso(mouseWorldRef.current.x, mouseWorldRef.current.y, 0);
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.2)';
    ctx.setLineDash([5, 5]);
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(playerPos.x, playerPos.y); ctx.lineTo(aim.x, aim.y); ctx.stroke();
    ctx.setLineDash([]);

    ctx.shadowBlur = 5; ctx.shadowColor = 'white';
    ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.ellipse(aim.x, aim.y, 10, 5, 0, 0, Math.PI*2); ctx.stroke();
    ctx.shadowBlur = 0;

    ctx.restore();

    // --- POS-PROCESSAMENTO E HUD ---
    if (gameStateRef.current === GameState.TOWER) {
        const cx = CANVAS_WIDTH / 2;
        const cy = CANVAS_HEIGHT / 2;
        const gradient = ctx.createRadialGradient(cx, cy, 150, cx, cy, 900);
        gradient.addColorStop(0, 'rgba(0,0,0,0)'); 
        gradient.addColorStop(0.5, 'rgba(0,0,0,0.3)');
        gradient.addColorStop(1, 'rgba(0,0,0,0.95)'); 
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    }

    // Damage Numbers
    ctx.font = 'bold 20px "Cinzel", serif';
    damageNumbersRef.current.forEach(dn => {
        const pos = toIso(dn.x, dn.y, dn.z);
        const sx = pos.x + cameraRef.current.x;
        const sy = pos.y + cameraRef.current.y;

        ctx.fillStyle = dn.isCrit ? '#facc15' : 'white';
        ctx.strokeStyle = 'black'; ctx.lineWidth = 3;
        const scale = dn.isCrit ? 1.5 : 1;
        const offset = (1 - dn.life) * 60;

        // Efeito de pulo no número
        ctx.save();
        ctx.translate(sx, sy - offset);
        if (dn.isCrit) ctx.scale(1.2, 1.2);
        ctx.strokeText(Math.floor(dn.value).toString(), 0, 0);
        ctx.fillText(Math.floor(dn.value).toString(), 0, 0);
        ctx.restore();
    });
  };

  const formatTime = (s: number) => `${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;

  return (
    <div className="relative w-full h-full bg-[#0f172a] cursor-none select-none overflow-hidden font-mono">
      <canvas ref={canvasRef} className="block w-full h-full cursor-none" />

      {/* --- HUD CENTRALIZADA --- */}
      <div className="absolute inset-x-0 bottom-4 flex flex-col items-center pointer-events-none">

          {/* Boss Bar */}
          {hudData.bossHp > 0 && (
              <div className="mb-8 w-[600px] bg-slate-900 border-2 border-red-900 p-1 rounded-lg shadow-[0_0_20px_rgba(220,38,38,0.5)]">
                  <div className="flex justify-between text-red-500 font-bold mb-1 px-2 uppercase tracking-widest font-serif">
                      <span>Terror da Torre</span>
                      <span>{Math.ceil(hudData.bossHp)}/{Math.ceil(hudData.bossMaxHp)}</span>
                  </div>
                  <div className="h-4 w-full bg-slate-800 rounded overflow-hidden">
                      <div className="h-full bg-red-600 transition-all duration-200" style={{width: `${(hudData.bossHp/hudData.bossMaxHp)*100}%`}}></div>
                  </div>
              </div>
          )}

          <div className="flex items-end gap-4">
              {/* HP & Info */}
              <div className="bg-slate-900/90 border border-slate-600 rounded-xl p-4 backdrop-blur-md shadow-2xl w-64">
                   <div className="flex items-center gap-2 text-red-400 font-bold text-xl mb-2 font-serif">
                       <Heart fill="currentColor" /> {Math.ceil(hudData.hp)}
                   </div>
                   <div className="h-3 bg-slate-800 rounded-full overflow-hidden border border-slate-700 mb-2">
                       <div className="h-full bg-red-500 transition-all duration-300" style={{width: `${(hudData.hp/hudData.maxHp)*100}%`}}></div>
                   </div>
                   <div className="flex justify-between text-xs text-slate-400 font-mono">
                       <span>LVL {hudData.level}</span>
                       <span>XP {Math.floor(hudData.xp)}/{Math.floor(hudData.xpNext)}</span>
                   </div>
              </div>

              {/* Skills Bar */}
              <div className="flex gap-2 p-3 bg-slate-900/90 border border-slate-600 rounded-xl backdrop-blur-md shadow-2xl">
                  {/* Basic Attack */}
                  <div className="w-16 h-16 bg-slate-800 rounded border border-slate-600 flex flex-col items-center justify-center grayscale opacity-75">
                      <Sword size={24} />
                      <span className="text-[10px] mt-1 font-bold text-slate-400">MOUSE</span>
                  </div>

                  {/* Skill 1 (Q) */}
                  <div className={`relative w-16 h-16 rounded border flex flex-col items-center justify-center overflow-hidden transition-colors
                      ${hudData.skill1Cd <= 0 ? 'bg-blue-900/50 border-blue-400' : 'bg-slate-800 border-slate-600'}`}>
                      <Crosshair size={24} className={hudData.skill1Cd <= 0 ? "text-blue-400" : "text-slate-500"} />
                      <span className="text-[10px] mt-1 font-bold text-blue-200">Q</span>
                      {hudData.skill1Cd > 0 && (
                          <div className="absolute inset-0 bg-black/60 flex items-center justify-center font-bold text-white text-lg font-mono">
                              {Math.ceil(hudData.skill1Cd)}
                          </div>
                      )}
                  </div>

                  {/* Dash (E) */}
                  <div className={`relative w-16 h-16 rounded border flex flex-col items-center justify-center overflow-hidden transition-colors
                      ${hudData.dashCd <= 0 ? 'bg-green-900/50 border-green-400' : 'bg-slate-800 border-slate-600'}`}>
                      <Wind size={24} className={hudData.dashCd <= 0 ? "text-green-400" : "text-slate-500"} />
                      <span className="text-[10px] mt-1 font-bold text-green-200">E</span>
                      {hudData.dashCd > 0 && (
                          <div className="absolute inset-0 bg-black/60 flex items-center justify-center font-bold text-white text-lg font-mono">
                              {Math.ceil(hudData.dashCd)}
                          </div>
                      )}
                  </div>

                  {/* Item Ativo (R) */}
                  <div className={`relative w-16 h-16 rounded border flex flex-col items-center justify-center overflow-hidden
                      ${hudData.activeItem ? 'bg-amber-900/30 border-amber-500' : 'bg-slate-900 border-slate-700 opacity-50'}`}>
                      {hudData.activeItem ? (
                          <>
                            <span className="text-2xl filter drop-shadow-lg">{hudData.activeItem.icon}</span>
                            <span className="text-[10px] mt-1 font-bold text-amber-200">R</span>
                          </>
                      ) : <Box size={24} className="text-slate-600" />}

                      {hudData.itemCd > 0 && (
                          <div className="absolute inset-0 bg-black/60 flex items-center justify-center font-bold text-white text-lg font-mono">
                              {Math.ceil(hudData.itemCd)}
                          </div>
                      )}
                  </div>
              </div>

              {/* Wave Info */}
              {hudData.state === GameState.TOWER && (
                  <div className="bg-slate-900/90 border border-slate-600 rounded-xl p-4 backdrop-blur-md shadow-2xl w-40 text-center">
                      <div className="text-2xl font-mono font-bold text-white mb-1">{formatTime(hudData.time)}</div>
                      <div className="text-xs text-slate-400 flex items-center justify-center gap-1 font-serif">
                          <Skull size={12} /> WAVE {hudData.wave}
                      </div>
                      {isRainingRef.current && (
                          <div className="text-[10px] text-blue-300 animate-pulse mt-1 font-serif">TEMPESTADE</div>
                      )}
                  </div>
              )}
          </div>
      </div>

      {/* Tutorial Ilha */}
      {hudData.state === GameState.ISLAND && (
          <div className="absolute top-10 w-full text-center pointer-events-none">
              <span className="bg-slate-900/80 px-6 py-3 rounded-full text-slate-200 border border-slate-700 shadow-lg font-serif tracking-wider">
                  Siga para o Norte para entrar na Torre
              </span>
          </div>
      )}

      {showUpgrade && (
        <UpgradeModal 
          options={upgradeOptions} 
          memoryOption={lastUpgrade}
          onSelect={applyUpgrade} 
        />
      )}
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { Player, Enemy, Projectile, GameState, Archetype, Particle, DamageNumber, Upgrade, Item, StaticObject } from '../types';
import { CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, BASE_STATS, WAVE_CONFIGS, UPGRADES_LIST, SKILL_CONFIG } from '../constants';
import { UpgradeModal } from './UpgradeModal';
import { Heart, Skull, Zap, MousePointer2, Sword, Box, Crosshair, Wind } from 'lucide-react';

interface GameCanvasProps {
  archetype: Archetype;
  onGameOver: () => void;
}

// Helper de Cor para Hex
const adjustColor = (color: string, amount: number) => {
    let usePound = false;
    if (color[0] === "#") {
        color = color.slice(1);
        usePound = true;
    }
    const num = parseInt(color, 16);
    let r = (num >> 16) + amount;
    if (r > 255) r = 255; else if (r < 0) r = 0;
    let b = ((num >> 8) & 0x00FF) + amount;
    if (b > 255) b = 255; else if (b < 0) b = 0;
    let g = (num & 0x0000FF) + amount;
    if (g > 255) g = 255; else if (g < 0) g = 0;
    return (usePound ? "#" : "") + (g | (b << 8) | (r << 16)).toString(16).padStart(6, '0');
};

// Isometric Math
const toIso = (x: number, y: number, z: number = 0) => {
  const isoX = (x - y);
  const isoY = (x + y) / 2 - z;
  return { x: isoX, y: isoY };
};

// Inverse Isometric Math (Screen/Iso -> World)
// x_iso = x - y
// y_iso = (x + y) / 2
// => x = y_iso + x_iso / 2
// => y = y_iso - x_iso / 2
const toWorldFromIso = (isoX: number, isoY: number) => {
    const x = isoY + isoX / 2;
    const y = isoY - isoX / 2;
    return { x, y };
};

const lerp = (start: number, end: number, t: number) => {
  return start * (1 - t) + end * t;
};

export const GameCanvas: React.FC<GameCanvasProps> = ({ archetype, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Game State Refs
  const gameStateRef = useRef<GameState>(GameState.ISLAND);
  const playerRef = useRef<Player>({
    x: 0, y: 0, z: 0,
    archetype,
    stats: JSON.parse(JSON.stringify(BASE_STATS[archetype])),
    level: 1, xp: 0, xpToNextLevel: 100,
    weaponTimer: 0, skill1Timer: 0, skill1MaxCooldown: SKILL_CONFIG[archetype].skill1Cd,
    dashTimer: 0, dashMaxCooldown: SKILL_CONFIG[archetype].dashCd,
    activeItem: null, itemTimer: 0, itemMaxCooldown: 0,
    facing: 0, isMoving: false, color: COLORS[archetype], animFrame: 0
  });

  const enemiesRef = useRef<Enemy[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const damageNumbersRef = useRef<DamageNumber[]>([]);
  const staticObjectsRef = useRef<StaticObject[]>([]);
  const keysRef = useRef<{ [key: string]: boolean }>({});

  // System Refs
  const cameraRef = useRef({ x: 0, y: 0 }); 
  const shakeRef = useRef(0); 
  const hitStopRef = useRef(0); // Freeze frame timer
  const timeRef = useRef<number>(0); 
  const waveRef = useRef<number>(0);
  const waveTimerRef = useRef<number>(0);
  const lastSpawnTimeRef = useRef<number>(0);
  const isRainingRef = useRef<boolean>(false);
  const rainTimerRef = useRef<number>(0);

  // UI State
  const [showUpgrade, setShowUpgrade] = useState(false);
  const [upgradeOptions, setUpgradeOptions] = useState<Upgrade[]>([]);
  const [lastUpgrade, setLastUpgrade] = useState<Upgrade | null>(null);
  const [hudData, setHudData] = useState({ 
      hp: 100, maxHp: 100, xp: 0, xpNext: 100, time: 0, wave: 1, level: 1, 
      state: GameState.ISLAND, skill1Cd: 0, dashCd: 0, itemCd: 0,
      activeItem: null as Item | null, bossHp: 0, bossMaxHp: 0
  });

  const mouseScreenRef = useRef({ x: 0, y: 0 }); // Relative to Center (0,0 is center of screen)
  const mouseWorldRef = useRef({ x: 0, y: 0 });

  // --- Init ---
  useEffect(() => {
    const objects: StaticObject[] = [];
    // Ilha
    if (gameStateRef.current === GameState.ISLAND) {
        objects.push({ id: 'h1', x: -200, y: -200, type: 'HOUSE', size: 100 });
        objects.push({ id: 'h2', x: 200, y: -250, type: 'HOUSE', size: 120 });
        objects.push({ id: 'h3', x: -300, y: 100, type: 'HOUSE', size: 90 });
        objects.push({ id: 'lamp1', x: 50, y: -500, type: 'LAMP', size: 20 });
        for(let i=0; i<40; i++) {
            const angle = Math.random() * Math.PI * 2;
            const dist = 500 + Math.random() * 800;
            objects.push({ id: `t${i}`, x: Math.cos(angle) * dist, y: Math.sin(angle) * dist, type: 'TREE', size: 40 + Math.random() * 40 });
        }
    }
    staticObjectsRef.current = objects;
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { if (e.code === 'Space') e.preventDefault(); keysRef.current[e.code] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keysRef.current[e.code] = false; };
    const handleMouseMove = (e: MouseEvent) => {
      const rect = canvasRef.current?.getBoundingClientRect();
      if(rect) {
          // 0,0 is CENTER of canvas
          mouseScreenRef.current = { 
            x: e.clientX - rect.left - rect.width / 2, 
            y: e.clientY - rect.top - rect.height / 2 
          };
      }
    };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) keysRef.current['MouseLeft'] = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) keysRef.current['MouseLeft'] = false; };
    const handleContextMenu = (e: MouseEvent) => e.preventDefault();

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    window.addEventListener('contextmenu', handleContextMenu);

    let animationFrameId: number;
    let lastTime = performance.now();

    const loop = (timestamp: number) => {
      const dtRaw = (timestamp - lastTime) / 1000;
      const dt = Math.min(dtRaw, 0.1);
      lastTime = timestamp;

      // Hit Stop Logic (Freeze Frame)
      if (hitStopRef.current > 0) {
          hitStopRef.current -= dtRaw;
          // Ainda desenha, mas não atualiza lógica de movimento
          draw(dt); 
          animationFrameId = requestAnimationFrame(loop);
          return;
      }

      if (gameStateRef.current === GameState.TOWER || gameStateRef.current === GameState.ISLAND) {
        update(dt);
      }
      draw(dt);
      animationFrameId = requestAnimationFrame(loop);
    };

    animationFrameId = requestAnimationFrame(loop);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
      window.removeEventListener('contextmenu', handleContextMenu);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  // --- UPDATE ---
  const update = (dt: number) => {
    const player = playerRef.current;

    // --- 1. CÂMERA (Player Centric) ---
    // A câmera deve tentar centralizar o jogador no mundo Isométrico.
    // PlayerPosISO é onde o jogador "está" na tela se a câmera fosse 0,0.
    const playerIso = toIso(player.x, player.y, player.z);

    // O alvo da câmera é o inverso da posição do jogador, para trazê-lo ao (0,0) relativo
    const targetCamX = -playerIso.x;
    const targetCamY = -playerIso.y;

    // Smooth Follow
    cameraRef.current.x = lerp(cameraRef.current.x, targetCamX, 0.1);
    cameraRef.current.y = lerp(cameraRef.current.y, targetCamY, 0.1);

    // --- 2. MIRA (Baseada na Câmera Atual) ---
    // Screen = IsoWorld + Camera + CenterOffset
    // IsoWorld = Screen - CenterOffset - Camera
    // MouseScreenRef já é (Screen - CenterOffset)
    const mouseIsoX = mouseScreenRef.current.x - cameraRef.current.x;
    const mouseIsoY = mouseScreenRef.current.y - cameraRef.current.y;

    // Converter de volta para World Coordinates (Top Down) para lógica
    const mouseWorld = toWorldFromIso(mouseIsoX, mouseIsoY);
    mouseWorldRef.current = { x: mouseWorld.x + player.x, y: mouseWorld.y + player.y }; // Ajuste relativo ao scroll

    // Correção Final: A função toWorldFromIso assume 0,0.
    // A câmera move o mundo. Se a câmera moveu -100, o mundo moveu -100.
    // O mouse está na posição X da tela.
    // Posição no Mundo = InversoIso(MouseTela - Camera)
    mouseWorldRef.current = toWorldFromIso(mouseIsoX, mouseIsoY);

    player.facing = Math.atan2(mouseWorldRef.current.y - player.y, mouseWorldRef.current.x - player.x);

    // --- 3. INPUT MOVIMENTO ---
    let dx = 0;
    let dy = 0;
    if (keysRef.current['KeyW'] || keysRef.current['ArrowUp']) { dx -= 1; dy -= 1; }
    if (keysRef.current['KeyS'] || keysRef.current['ArrowDown']) { dx += 1; dy += 1; }
    if (keysRef.current['KeyA'] || keysRef.current['ArrowLeft']) { dx -= 1; dy += 1; }
    if (keysRef.current['KeyD'] || keysRef.current['ArrowRight']) { dx += 1; dy -= 1; }

    player.isMoving = dx !== 0 || dy !== 0;
    if (player.isMoving) {
      const length = Math.sqrt(dx * dx + dy * dy);
      dx /= length; dy /= length;
      const speed = player.stats.speed * 60 * dt;
      player.x += dx * speed;
      player.y += dy * speed;
      player.animFrame += dt * 10;
    } else {
        player.animFrame = 0;
    }

    // Física Z (Pulo/Knockup)
    if (player.z > 0) {
        player.z -= 150 * dt; 
        if (player.z < 0) player.z = 0;
    }

    // Limites do Mundo
    const limit = gameStateRef.current === GameState.ISLAND ? 1500 : 900;
    if (Math.abs(player.x) > limit) player.x = Math.sign(player.x) * limit;
    if (Math.abs(player.y) > limit) player.y = Math.sign(player.y) * limit;

    // State Transitions
    if (gameStateRef.current === GameState.ISLAND) {
        const distToTower = Math.hypot(player.x - 0, player.y - (-600)); 
        if (distToTower < 150) {
            gameStateRef.current = GameState.TOWER;
            player.x = 0; player.y = 0;
            enemiesRef.current = [];
            projectilesRef.current = [];
            waveRef.current = 0;
            timeRef.current = 0;
            rainTimerRef.current = 0;
            staticObjectsRef.current = []; // Limpa objetos da ilha
        }
        if (player.stats.hp < player.stats.maxHp) player.stats.hp += 100 * dt;
    }

    if (gameStateRef.current === GameState.TOWER) {
        timeRef.current += dt;
        waveTimerRef.current += dt;
        player.skill1Timer -= dt;
        player.dashTimer -= dt;
        player.itemTimer -= dt;
        player.weaponTimer -= dt;

        // Chuva Ciclica
        rainTimerRef.current += dt;
        if (!isRainingRef.current && rainTimerRef.current > 60) {
             isRainingRef.current = true;
             rainTimerRef.current = 0;
        }
        if (isRainingRef.current && rainTimerRef.current > 60) {
             isRainingRef.current = false;
             rainTimerRef.current = 0;
        }

        if (isRainingRef.current) {
            for(let i=0; i<8; i++) {
                const angle = Math.random() * Math.PI * 2;
                const dist = Math.random() * 900; 
                particlesRef.current.push({
                    id: Math.random().toString(), 
                    x: player.x + Math.cos(angle)*dist - 400, 
                    y: player.y + Math.sin(angle)*dist - 400, 
                    z: 500, vx: 100, vy: 100, vz: -900,
                    life: 0.6, maxLife: 0.6, color: '#a5f3fc', size: 2, type: 'RAIN'
                });
            }
        }

        const currentConfig = WAVE_CONFIGS[waveRef.current] || WAVE_CONFIGS[WAVE_CONFIGS.length-1];
        const bossAlive = enemiesRef.current.some(e => e.isBoss);

        if (!bossAlive && waveTimerRef.current >= currentConfig.duration) {
             triggerUpgrade();
        } 
        else if (!bossAlive && enemiesRef.current.length < currentConfig.enemyCount && Date.now() - lastSpawnTimeRef.current > currentConfig.spawnRate) {
             if (currentConfig.boss && !enemiesRef.current.some(e => e.isBoss)) {
                 spawnBoss(currentConfig.boss);
             } else if (!currentConfig.boss) {
                 spawnEnemy();
             }
             lastSpawnTimeRef.current = Date.now();
        }

        if (keysRef.current['MouseLeft'] && player.weaponTimer <= 0) useMainAttack();
        if (keysRef.current['KeyQ'] && player.skill1Timer <= 0) {
            useSkill1();
            player.skill1Timer = player.skill1MaxCooldown * (1 - player.stats.cooldownReduction);
        }
        if (keysRef.current['KeyE'] && player.dashTimer <= 0) {
            useDash();
            player.dashTimer = player.dashMaxCooldown * (1 - player.stats.cooldownReduction);
        }
        if (keysRef.current['KeyR']) activateItem();
    }

    if (shakeRef.current > 0) shakeRef.current -= dt * 30;
    if (shakeRef.current < 0) shakeRef.current = 0;

    updateProjectiles(dt);
    updateEnemies(dt);
    updateParticles(dt);

    const boss = enemiesRef.current.find(e => e.isBoss);
    setHudData({
        hp: player.stats.hp, maxHp: player.stats.maxHp,
        xp: player.xp, xpNext: player.xpToNextLevel,
        time: timeRef.current, wave: waveRef.current + 1, level: player.level,
        state: gameStateRef.current,
        skill1Cd: player.skill1Timer, dashCd: player.dashTimer, itemCd: player.itemTimer,
        activeItem: player.activeItem,
        bossHp: boss ? boss.hp : 0, bossMaxHp: boss ? boss.maxHp : 0
    });

    if (player.stats.hp <= 0 && gameStateRef.current === GameState.TOWER) {
        gameStateRef.current = GameState.GAME_OVER;
        onGameOver();
    }
  };

  const activateItem = () => {
     const p = playerRef.current;
     if (p.activeItem && p.itemTimer <= 0) {
         p.activeItem.effect(p, enemiesRef.current);
         p.itemTimer = p.activeItem.cooldown;
     }
  };

  const useMainAttack = () => {
     const p = playerRef.current;
     const angle = p.facing;

     const vx = Math.cos(angle) * 800;
     const vy = Math.sin(angle) * 800;

     if (p.archetype === Archetype.WARRIOR) {
         projectilesRef.current.push({
             id: Math.random().toString(), x: p.x, y: p.y, z: 20, vx: 0, vy: 0,
             damage: p.stats.damage, duration: 0.3, radius: 100 * p.stats.areaSize,
             type: 'SWORD_SLASH', color: '#60a5fa', pierce: 999
         });
         p.weaponTimer = 0.6 * (1 - p.stats.cooldownReduction);
     } else {
         projectilesRef.current.push({
             id: Math.random().toString(), x: p.x, y: p.y, z: 30, vx, vy,
             damage: p.stats.damage, duration: 1.5, radius: 15,
             type: p.archetype === Archetype.ARCHER ? 'ARROW' : 'MAGIC_ORB', 
             color: p.color, pierce: p.archetype === Archetype.MAGE ? 2 : 0
         });
         p.weaponTimer = (p.archetype === Archetype.ARCHER ? 0.4 : 0.5) * (1 - p.stats.cooldownReduction);
     }
  };

  const useSkill1 = () => {
      const p = playerRef.current;
      createParticle(p.x, p.y, 20, '#fff', 10);
      shakeRef.current = 5; 

      if(p.archetype === Archetype.WARRIOR) {
          projectilesRef.current.push({
             id: Math.random().toString(), x: p.x, y: p.y, z: 20, vx: 0, vy: 0,
             damage: p.stats.damage * 2.5, duration: 0.5, radius: 160 * p.stats.areaSize,
             type: 'SWORD_SLASH', color: '#ef4444', pierce: 999
         });
      } else {
          projectilesRef.current.push({
             id: Math.random().toString(), x: mouseWorldRef.current.x, y: mouseWorldRef.current.y, z: 0, vx: 0, vy: 0,
             damage: p.stats.damage * 3, duration: 1.2, radius: 120 * p.stats.areaSize,
             type: 'FIRE_ZONE', color: p.archetype === Archetype.MAGE ? '#9333ea' : '#ef4444', pierce: 999
         });
      }
  };

  const useDash = () => {
      const p = playerRef.current;
      let angle = p.facing;
      if (p.isMoving) {
          let dx = 0, dy = 0;
          if (keysRef.current['KeyW']) { dx -= 1; dy -= 1; }
          if (keysRef.current['KeyS']) { dx += 1; dy += 1; }
          if (keysRef.current['KeyA']) { dx -= 1; dy += 1; }
          if (keysRef.current['KeyD']) { dx += 1; dy -= 1; }
          if (dx !== 0 || dy !== 0) angle = Math.atan2(dy, dx);
      }
      const vx = Math.cos(angle) * 1200;
      const vy = Math.sin(angle) * 1200;
      p.x += vx * 0.2; 
      p.y += vy * 0.2;
      p.z = 40; 
      createParticle(p.x, p.y, 10, '#fff', 5);
  };

  const spawnBoss = (type: 'BOSS_GOLEM' | 'BOSS_LICH') => {
      const dist = 600;
      const angle = Math.random() * Math.PI * 2;
      enemiesRef.current.push({
          id: 'boss', x: playerRef.current.x + Math.cos(angle)*dist, y: playerRef.current.y + Math.sin(angle)*dist, z: 0,
          type, isBoss: true,
          hp: 2000 * (1 + waveRef.current * 0.5), maxHp: 2000 * (1 + waveRef.current * 0.5),
          speed: 40, damage: 40, radius: 60, hitboxRadius: 50, frame: 0, attackTimer: 2, vx: 0, vy: 0, hitFlash: 0
      });
      shakeRef.current = 20; 
  };

  const spawnEnemy = () => {
    const angle = Math.random() * Math.PI * 2;
    const distance = 900; 
    const ex = playerRef.current.x + Math.cos(angle) * distance;
    const ey = playerRef.current.y + Math.sin(angle) * distance;
    const type = waveRef.current < 5 ? 'SLIME' : (waveRef.current < 10 ? 'GOBLIN' : 'DEMON');

    // Balanceamento de HP ("One Shot" feel para inimigos básicos)
    let hp = 30 + waveRef.current * 8;
    if (type === 'GOBLIN') hp += 30;
    if (type === 'DEMON') hp += 100;

    enemiesRef.current.push({
      id: Math.random().toString(), x: ex, y: ey, z: 0, type, isBoss: false,
      hp: hp, maxHp: hp,
      speed: 80 + Math.random()*20, damage: 10 + waveRef.current,
      radius: 20, hitboxRadius: 15, frame: 0, vx: 0, vy: 0, hitFlash: 0
    });
  };

  const updateEnemies = (dt: number) => {
      const p = playerRef.current;
      enemiesRef.current = enemiesRef.current.filter(e => {
          if (e.hitFlash > 0) e.hitFlash -= dt;

          // Physics
          e.x += e.vx * dt; e.y += e.vy * dt;
          e.vx *= 0.9; e.vy *= 0.9;

          const dx = p.x - e.x;
          const dy = p.y - e.y;
          const dist = Math.hypot(dx, dy);

          if(dist > e.hitboxRadius) {
              if (Math.abs(e.vx) < 10 && Math.abs(e.vy) < 10) {
                  e.x += (dx/dist) * e.speed * dt;
                  e.y += (dy/dist) * e.speed * dt;
              }
          }

          if(dist < e.hitboxRadius + 20) {
              p.stats.hp -= e.damage * dt;
              shakeRef.current = Math.max(shakeRef.current, 2); 
          }

          projectilesRef.current.forEach(proj => {
               if (proj.duration <= 0) return;

               const pDist = Math.hypot(proj.x - e.x, proj.y - e.y);
               if(pDist < proj.radius + e.hitboxRadius) {
                   const isAoe = proj.type === 'SWORD_SLASH' || proj.type === 'FIRE_ZONE';
                   const dmg = isAoe ? proj.damage * 5 * dt : proj.damage;
                   const isCrit = Math.random() > 0.8;
                   const finalDmg = isCrit ? dmg * 1.5 : dmg;

                   e.hitFlash = 0.15; 
                   if (proj.type === 'ARROW' || proj.type === 'MAGIC_ORB') {
                       const kAngle = Math.atan2(e.y - proj.y, e.x - proj.x);
                       const force = 300;
                       e.vx = Math.cos(kAngle) * force;
                       e.vy = Math.sin(kAngle) * force;

                       if (!isAoe) {
                           proj.pierce--;
                           if (proj.pierce < 0) proj.duration = 0;
                       }
                   } else if (proj.type === 'SWORD_SLASH') {
                        const kAngle = Math.atan2(e.y - p.y, e.x - p.x);
                        e.vx = Math.cos(kAngle) * 50;
                        e.vy = Math.sin(kAngle) * 50;
                   }

                   e.hp -= finalDmg;

                   if (!isAoe || Math.random() > 0.8) {
                       createDamageNumber(e.x, e.y, e.z + 40, finalDmg, isCrit);
                   }

                   if(e.hp <= 0 && !e.isBoss) {
                       createParticle(e.x, e.y, e.z, '#ef4444', 6, 'BLOOD');
                       hitStopRef.current = 0.05; // 50ms Freeze Frame no kill
                   }
               }
          });

          if(e.hp <= 0) {
              p.xp += e.isBoss ? 500 : 10;
              if(p.xp >= p.xpToNextLevel) {
                  p.level++;
                  p.xp -= p.xpToNextLevel;
                  p.xpToNextLevel *= 1.2;
                  p.stats.damage *= 1.1;
                  p.stats.maxHp *= 1.1;
                  p.stats.hp = p.stats.maxHp;
                  createDamageNumber(p.x, p.y, p.z+60, 0, true); 
                  shakeRef.current = 5; 
              }
              return false;
          }
          return true;
      });
  };

  const updateProjectiles = (dt: number) => {
      projectilesRef.current = projectilesRef.current.filter(proj => {
          proj.duration -= dt;
          if(proj.type === 'SWORD_SLASH') {
              proj.x = playerRef.current.x; proj.y = playerRef.current.y;
          } else {
              proj.x += proj.vx * dt; proj.y += proj.vy * dt;
          }
          return proj.duration > 0;
      });
  };

  const updateParticles = (dt: number) => {
      particlesRef.current = particlesRef.current.filter(p => {
          p.life -= dt;
          p.x += p.vx * dt;
          p.y += p.vy * dt;
          p.z += p.vz * dt;
          if (p.type !== 'RAIN') p.vz -= 300 * dt; 

          if(p.z < 0) {
              p.z = 0;
              if (p.type === 'RAIN') {
                  createParticle(p.x, p.y, 0, '#fff', 1, 'SPARK');
                  return false; 
              }
              if (p.type === 'BLOOD') {
                  p.vx = 0; p.vy = 0; 
              }
          }
          return p.life > 0;
      });
      damageNumbersRef.current = damageNumbersRef.current.filter(d => { d.life -= dt; d.z += 40 * dt; return d.life > 0; });
  };

  const createParticle = (x: number, y: number, z: number, color: string, count: number, type: 'SPARK'|'BLOOD'|'RAIN' = 'SPARK') => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(), x, y, z,
              vx: (Math.random()-0.5)*150, vy: (Math.random()-0.5)*150, vz: Math.random()*150 + 50,
              life: type === 'BLOOD' ? 3 : 0.5, maxLife: 0.5, color, size: Math.random()*3+2, type
          });
      }
  };

  const createDamageNumber = (x: number, y: number, z: number, val: number, crit: boolean) => {
      if (val < 1) return;
      damageNumbersRef.current.push({id: Math.random().toString(), x, y, z, value: val, life: 0.8, isCrit: crit});
  };

  const triggerUpgrade = () => {
    gameStateRef.current = GameState.PAUSED;
    const options: Upgrade[] = [];
    const rollItem = !playerRef.current.activeItem && Math.random() > 0.5;
    for(let i=0; i<4; i++) {
        let pool = UPGRADES_LIST;
        if (rollItem && i === 0) pool = UPGRADES_LIST.filter(u => u.type === 'ITEM');
        const rand = pool[Math.floor(Math.random() * pool.length)];
        options.push({...rand, id: rand.id + Math.random()}); 
    }
    setUpgradeOptions(options);
    setShowUpgrade(true);
  };

  const applyUpgrade = (upgrade: Upgrade) => {
      const p = playerRef.current;
      if (upgrade.type === 'ITEM' && upgrade.itemRef) {
          p.activeItem = upgrade.itemRef;
      } else {
        if (upgrade.name.includes('Força')) p.stats.damage *= 1.15;
        if (upgrade.name.includes('Velocidade')) p.stats.speed *= 1.1;
        if (upgrade.name.includes('Vida')) { p.stats.maxHp += 50; p.stats.hp += 50; }
        if (upgrade.name.includes('Tempo')) p.stats.cooldownReduction = Math.min(0.7, p.stats.cooldownReduction + 0.08);
        if (upgrade.name.includes('Expansão')) p.stats.areaSize *= 1.2;
      }
      setLastUpgrade(upgrade);
      setShowUpgrade(false);
      gameStateRef.current = GameState.TOWER;
      if (waveTimerRef.current >= WAVE_CONFIGS[0].duration) {
         waveRef.current++;
         waveTimerRef.current = 0;
      }
  };

  // --- RENDERIZAÇÃO ---
  const drawIsoSprite = (ctx: CanvasRenderingContext2D, entity: any, type: string) => {
      let bounce = 0;
      if ((type === 'PLAYER' || type === 'GOBLIN' || type === 'DEMON') && entity.animFrame) {
          bounce = Math.abs(Math.sin(entity.animFrame)) * 5;
      }

      const { x, y } = toIso(entity.x, entity.y, entity.z + bounce);

      // Otimização: Culling Simples (Se estiver muito longe da câmera, não desenha)
      // CameraX é negativo da posição do jogador.
      // ScreenX = IsoX + CameraX + HalfWidth
      const screenX = x + cameraRef.current.x + CANVAS_WIDTH/2;
      const screenY = y + cameraRef.current.y + CANVAS_HEIGHT/2;

      // Margem de segurança de 200px
      if (screenX < -200 || screenX > CANVAS_WIDTH + 200 || screenY < -200 || screenY > CANVAS_HEIGHT + 200) {
          return; 
      }

      // Hit Flash (Branco Puro se tomou dano recentemente)
      if (entity.hitFlash && entity.hitFlash > 0) {
          ctx.save();
          const shadow = toIso(entity.x, entity.y, 0);
          ctx.fillStyle = 'rgba(0,0,0,0.4)';
          ctx.beginPath(); ctx.ellipse(shadow.x, shadow.y, 15, 8, 0, 0, Math.PI*2); ctx.fill();

          ctx.fillStyle = '#ffffff';
          const h = type === 'BOSS' ? 60 : 20;
          const w = type === 'BOSS' ? 60 : 20;
          ctx.fillRect(x - w/2, y - h, w, h);
          ctx.restore();
          return; 
      }

      // Sombra
      if (entity.z < 10) {
          const shadow = toIso(entity.x, entity.y, 0);
          ctx.fillStyle = 'rgba(0,0,0,0.4)';
          ctx.beginPath();
          ctx.ellipse(shadow.x, shadow.y, type === 'BOSS' ? 40 : 12, type === 'BOSS' ? 20 : 6, 0, 0, Math.PI*2);
          ctx.fill();
      }

      const layers = type === 'BOSS' ? 12 : 6;
      const scale = 2;

      for(let i=0; i<layers; i++) {
          const ly = y - (i * scale * 2);
          let w = 20; let h = 20;
          let color = entity.color || '#fff';

          if (type === 'PLAYER') {
             if (i === 0) { color = '#1e293b'; w = 14; } 
             else if (i < 3) { w = 18; }
             else if (i === 4) { color = '#fca5a5'; w = 14; }
             else if (i === 5) { 
                 color = entity.archetype === Archetype.MAGE ? '#6b21a8' : 
                        (entity.archetype === Archetype.ARCHER ? '#166534' : '#991b1b');
                 w = 16;
             }
             ctx.fillStyle = color;
             ctx.fillRect(x - w/2, ly - w/2, w, w);
             if (i === 2) { ctx.fillStyle = '#94a3b8'; ctx.fillRect(x + 10, ly - 5, 4, 15); }
          } 
          else if (type === 'BOSS') {
             w = 60 - i*2; h = 60 - i*2;
             ctx.fillStyle = i % 2 === 0 ? '#7f1d1d' : '#991b1b';
             ctx.shadowBlur = 10; ctx.shadowColor = 'red';
             ctx.fillRect(x - w/2, ly - h/2, w, h);
             ctx.shadowBlur = 0;
          }
          else if (type === 'SLIME') {
             w = 24 - i*3; 
             ctx.fillStyle = i > 3 ? '#86efac' : '#22c55e';
             ctx.beginPath(); ctx.arc(x, ly, w/2, 0, Math.PI*2); ctx.fill();
          } 
          else if (type === 'TREE') {
              w = entity.size * (1 - i/10); h = w;
              ctx.fillStyle = i === 0 ? '#451a03' : '#14532d';
              if (i > 2) ctx.fillStyle = '#166534';
              if (i === 0) w = w / 3;
              ctx.fillRect(x - w/2, ly - h/2, w, h);
          }
          else if (type === 'HOUSE') {
              w = entity.size; h = entity.size;
              ctx.fillStyle = i < 4 ? '#78350f' : '#dc2626';
              if (i >= 4) { w = w * (1 - (i-4)/6); h = h * (1 - (i-4)/6); }
              ctx.fillRect(x - w/2, ly - h/2, w, h);
              if (i===2) { ctx.fillStyle = '#000'; ctx.fillRect(x - 10, ly - 10, 20, 30); }
          }
          else if (type === 'LAMP') {
             w = 6;
             if (i < 8) ctx.fillStyle = '#333';
             else { ctx.fillStyle = '#fbbf24'; ctx.shadowBlur = 20; ctx.shadowColor = 'orange'; }
             ctx.fillRect(x - w/2, ly - w*2, w, w*2);
             ctx.shadowBlur = 0;
          }
          else { 
             w = 24;
             ctx.fillStyle = type === 'DEMON' ? '#b91c1c' : '#65a30d';
             ctx.fillRect(x - w/2, ly - w/2, w, w);
          }
      }
  };

  const draw = (dt: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Garante que o canvas sempre ocupe a janela correta
    if(canvas.width !== CANVAS_WIDTH || canvas.height !== CANVAS_HEIGHT) {
        canvas.width = CANVAS_WIDTH;
        canvas.height = CANVAS_HEIGHT;
    }

    ctx.fillStyle = gameStateRef.current === GameState.ISLAND ? COLORS.background : '#020617'; 
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    const shakeX = (Math.random() - 0.5) * shakeRef.current;
    const shakeY = (Math.random() - 0.5) * shakeRef.current;

    ctx.save();
    // 1. Centraliza a tela (0,0 vira Centro)
    ctx.translate(CANVAS_WIDTH/2, CANVAS_HEIGHT/2);
    // 2. Aplica Câmera (Pixel Perfect: Math.floor)
    // Se camera.x = -100 (moveu pra esquerda), queremos desenhar tudo +100 pra direita.
    // Como a camera segue -PlayerIso, se PlayerIso é 100, camera é -100.
    // translate(-100) move tudo pra esquerda. Correto.
    ctx.translate(Math.floor(cameraRef.current.x + shakeX), Math.floor(cameraRef.current.y + shakeY));

    // Desenhar Terreno
    const tileSize = 100;
    // Otimização: Calcular range baseado apenas na visão da câmera
    // playerRef (aprox camera center) em coordenadas de mundo dividido por tileSize
    const px = Math.floor(playerRef.current.x / tileSize);
    const py = Math.floor(playerRef.current.y / tileSize);
    const range = 14; 

    for (let i = px - range; i <= px + range; i++) {
        for (let j = py - range; j <= py + range; j++) {
            const wx = i * tileSize;
            const wy = j * tileSize;

            // Culling Básico de Terreno
            // Se o tile está muito longe do jogador, pula
            if (Math.abs(wx - playerRef.current.x) > 1200 || Math.abs(wy - playerRef.current.y) > 1200) continue;

            let color = COLORS.grass;
            let topColor = COLORS.grassHighlight;
            let h = 0;

            if (gameStateRef.current === GameState.ISLAND) {
                 const dist = Math.hypot(wx, wy);
                 if (dist > 1400) { color = COLORS.water; topColor = COLORS.waterHighlight; h = -20; }
                 else if (Math.abs(wx) < 150 && Math.abs(wy - (-600)) < 150) { color = COLORS.stone; topColor = COLORS.stoneHighlight; h = 10; }
            } else {
                 const noise = (Math.sin(i*0.5) + Math.cos(j*0.5)) * 10; 
                 const isFloor = (i+j)%2===0;
                 color = '#1e293b'; 
                 topColor = isFloor ? adjustColor('#334155', noise) : adjustColor('#1e293b', noise);
                 if (Math.abs(wx) > 900 || Math.abs(wy) > 900) { h = 100; color = '#020617'; topColor = '#0f172a'; }
            }

            const iso = toIso(wx, wy, 0);

            ctx.beginPath();
            ctx.moveTo(iso.x, iso.y - h);
            ctx.lineTo(iso.x + tileSize, iso.y - h + tileSize/2);
            ctx.lineTo(iso.x, iso.y - h + tileSize);
            ctx.lineTo(iso.x - tileSize, iso.y - h + tileSize/2);
            ctx.fillStyle = topColor;
            ctx.fill();

            if (h !== 0 && h > -10) {
                 ctx.fillStyle = adjustColor(color, -40);
                 ctx.beginPath();
                 ctx.moveTo(iso.x + tileSize, iso.y - h + tileSize/2);
                 ctx.lineTo(iso.x + tileSize, iso.y + tileSize/2);
                 ctx.lineTo(iso.x, iso.y + tileSize);
                 ctx.lineTo(iso.x, iso.y - h + tileSize);
                 ctx.fill();

                 ctx.fillStyle = adjustColor(color, -20);
                 ctx.beginPath();
                 ctx.moveTo(iso.x - tileSize, iso.y - h + tileSize/2);
                 ctx.lineTo(iso.x - tileSize, iso.y + tileSize/2);
                 ctx.lineTo(iso.x, iso.y + tileSize);
                 ctx.lineTo(iso.x, iso.y - h + tileSize);
                 ctx.fill();
            }
        }
    }

    // Efeito de Chão Molhado
    if (isRainingRef.current) {
        ctx.globalAlpha = 0.1;
        ctx.fillStyle = '#fff';
        // Renderizar apenas ao redor do player para performance
        const pIso = toIso(playerRef.current.x, playerRef.current.y);
        ctx.fillRect(pIso.x - 1000, pIso.y - 600, 2000, 1200); 
        ctx.globalAlpha = 1.0;
    }

    // Depth Sorting
    const renderList: any[] = [
        { type: 'PLAYER', obj: playerRef.current, y: toIso(playerRef.current.x, playerRef.current.y).y },
        ...enemiesRef.current.map(e => ({ type: e.isBoss ? 'BOSS' : e.type, obj: e, y: toIso(e.x, e.y).y })),
        ...particlesRef.current.map(p => ({ type: p.type || 'PARTICLE', obj: p, y: toIso(p.x, p.y).y })),
    ];

    if (gameStateRef.current === GameState.ISLAND) {
        staticObjectsRef.current.forEach(obj => {
            renderList.push({ type: obj.type, obj, y: toIso(obj.x, obj.y).y });
        });
    }

    renderList.sort((a, b) => a.y - b.y);

    renderList.forEach(item => {
        if (item.type === 'PARTICLE' || item.type === 'RAIN' || item.type === 'BLOOD' || item.type === 'SPARK') {
             const { x, y } = toIso(item.obj.x, item.obj.y, item.obj.z);
             ctx.fillStyle = item.obj.color;

             if (item.type === 'RAIN') {
                 ctx.strokeStyle = item.obj.color;
                 ctx.lineWidth = 1;
                 ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x-2, y+10); ctx.stroke();
             } else if (item.type === 'BLOOD') {
                 ctx.globalAlpha = 0.7;
                 ctx.beginPath(); ctx.ellipse(x, y, item.obj.size*2, item.obj.size, 0, 0, Math.PI*2); ctx.fill();
                 ctx.globalAlpha = 1.0;
             } else {
                 ctx.shadowBlur = 5; ctx.shadowColor = item.obj.color;
                 ctx.beginPath(); ctx.arc(x, y, item.obj.size, 0, Math.PI*2); ctx.fill();
                 ctx.shadowBlur = 0;
             }
        } else {
             drawIsoSprite(ctx, item.obj, item.type);

             // HP Bars Globais
             if (item.obj.hp < item.obj.maxHp && item.obj.hp > 0 && item.type !== 'PARTICLE') {
                 const isBoss = item.type === 'BOSS';
                 const offsetZ = isBoss ? 80 : 30;
                 const { x, y } = toIso(item.obj.x, item.obj.y, item.obj.z + offsetZ);
                 const w = isBoss ? 80 : 20;
                 const h = 4;

                 ctx.fillStyle = '#000'; 
                 ctx.fillRect(x - w/2 - 1, y - 5 - 1, w + 2, h + 2); // Borda

                 ctx.fillStyle = '#1e293b'; 
                 ctx.fillRect(x - w/2, y - 5, w, h); // Fundo

                 ctx.fillStyle = isBoss ? '#dc2626' : '#ef4444'; 
                 ctx.fillRect(x - w/2, y - 5, w * (item.obj.hp/item.obj.maxHp), h); // Vida
             }
        }
    });

    // Projéteis
    projectilesRef.current.forEach(p => {
        const { x, y } = toIso(p.x, p.y, p.z);
        ctx.fillStyle = p.color;
        ctx.shadowBlur = 10; ctx.shadowColor = p.color;

        if (p.type === 'SWORD_SLASH') {
             ctx.strokeStyle = 'white'; ctx.lineWidth = 2;
             ctx.beginPath(); ctx.ellipse(x, y, p.radius, p.radius*0.5, 0, 0, Math.PI*2); ctx.stroke();
        } else if (p.type === 'FIRE_ZONE') {
             ctx.fillStyle = 'rgba(239, 68, 68, 0.4)';
             ctx.beginPath(); ctx.ellipse(x, y, p.radius, p.radius*0.5, 0, 0, Math.PI*2); ctx.fill();
        } else {
             ctx.beginPath(); ctx.arc(x, y, 5, 0, Math.PI*2); ctx.fill();
        }
        ctx.shadowBlur = 0;
    });

    // Mira Corrigida (Projeção no chão)
    const aimIso = toIso(mouseWorldRef.current.x, mouseWorldRef.current.y, 0);
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.2)';
    ctx.setLineDash([5, 5]);
    ctx.lineWidth = 1;

    // Linha do Jogador até a Mira
    const pIso = toIso(playerRef.current.x, playerRef.current.y);
    ctx.beginPath(); ctx.moveTo(pIso.x, pIso.y); ctx.lineTo(aimIso.x, aimIso.y); ctx.stroke();
    ctx.setLineDash([]);

    // Cursor Visual
    ctx.shadowBlur = 5; ctx.shadowColor = 'white';
    ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.ellipse(aimIso.x, aimIso.y, 10, 5, 0, 0, Math.PI*2); ctx.stroke();
    ctx.shadowBlur = 0;

    ctx.restore();

    // --- POS-PROCESSAMENTO (Screen Space) ---
    // Renderizado diretamente na tela sem translate
    if (gameStateRef.current === GameState.TOWER) {
        const cx = CANVAS_WIDTH / 2;
        const cy = CANVAS_HEIGHT / 2;
        const gradient = ctx.createRadialGradient(cx, cy, 150, cx, cy, 900);
        gradient.addColorStop(0, 'rgba(0,0,0,0)'); 
        gradient.addColorStop(0.5, 'rgba(0,0,0,0.3)');
        gradient.addColorStop(1, 'rgba(0,0,0,0.95)'); 
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    }

    // Damage Numbers (Screen Space Calculation for stability)
    ctx.font = 'bold 20px "Cinzel", serif';
    damageNumbersRef.current.forEach(dn => {
        const pos = toIso(dn.x, dn.y, dn.z);
        // Aplica manualment a projeção de câmera + centro
        const sx = pos.x + cameraRef.current.x + CANVAS_WIDTH/2;
        const sy = pos.y + cameraRef.current.y + CANVAS_HEIGHT/2;

        ctx.fillStyle = dn.isCrit ? '#facc15' : 'white';
        ctx.strokeStyle = 'black'; ctx.lineWidth = 3;
        const offset = (1 - dn.life) * 60;

        ctx.save();
        ctx.translate(sx, sy - offset);
        if (dn.isCrit) ctx.scale(1.2, 1.2);
        ctx.strokeText(Math.floor(dn.value).toString(), 0, 0);
        ctx.fillText(Math.floor(dn.value).toString(), 0, 0);
        ctx.restore();
    });
  };

  const formatTime = (s: number) => `${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;

  return (
    <div className="relative w-full h-full bg-[#0f172a] cursor-none select-none overflow-hidden font-mono">
      <canvas ref={canvasRef} className="block w-full h-full cursor-none" />

      {/* --- HUD CENTRALIZADA --- */}
      <div className="absolute inset-x-0 bottom-4 flex flex-col items-center pointer-events-none">

          {/* Boss Bar */}
          {hudData.bossHp > 0 && (
              <div className="mb-8 w-[600px] bg-slate-900 border-2 border-red-900 p-1 rounded-lg shadow-[0_0_20px_rgba(220,38,38,0.5)]">
                  <div className="flex justify-between text-red-500 font-bold mb-1 px-2 uppercase tracking-widest font-serif">
                      <span>Terror da Torre</span>
                      <span>{Math.ceil(hudData.bossHp)}/{Math.ceil(hudData.bossMaxHp)}</span>
                  </div>
                  <div className="h-4 w-full bg-slate-800 rounded overflow-hidden">
