  vx: number;
  vy: number;
  damage: number;
  duration: number;
  radius: number;
  type: 'ARROW' | 'MAGIC_ORB' | 'SWORD_SLASH' | 'BOSS_SMASH' | 'FIRE_ZONE' | 'ENEMY_BOLT';
