                  <div className="flex justify-between items-end text-red-500 font-bold mb-2 px-4 uppercase tracking-widest font-serif drop-shadow-md">
                      <span className="text-2xl">Terror da Torre</span>
                      <span className="text-sm opacity-80">{Math.ceil(hudData.bossHp)}/{Math.ceil(hudData.bossMaxHp)}</span>
