import React, { useEffect, useRef, useState } from 'react';
import { Player, Enemy, Projectile, GameState, Archetype, Particle, DamageNumber, Upgrade, Item, StaticObject } from '../types';
import { CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, BASE_STATS, WAVE_CONFIGS, UPGRADES_LIST, SKILL_CONFIG } from '../constants';
import { UpgradeModal } from './UpgradeModal';
import { Heart, Skull, Sword, Box, Crosshair, Wind } from 'lucide-react';

interface GameCanvasProps {
  archetype: Archetype;
  onGameOver: () => void;
}

// --- MATH UTILS ---
const toIso = (x: number, y: number, z: number = 0) => {
  return { x: (x - y), y: (x + y) / 2 - z };
};

const toWorldFromIso = (isoX: number, isoY: number) => {
    return { x: isoY + isoX / 2, y: isoY - isoX / 2 };
};

const lerp = (start: number, end: number, t: number) => {
  return start * (1 - t) + end * t;
};

// Helper de cor (Darken/Lighten)
const adjustColor = (color: string, amount: number) => {
    const num = parseInt(color.replace('#', ''), 16);
    let r = (num >> 16) + amount;
    let b = ((num >> 8) & 0x00FF) + amount;
    let g = (num & 0x0000FF) + amount;
    r = r > 255 ? 255 : r < 0 ? 0 : r;
    b = b > 255 ? 255 : b < 0 ? 0 : b;
    g = g > 255 ? 255 : g < 0 ? 0 : g;
    return "#" + (g | (b << 8) | (r << 16)).toString(16).padStart(6, '0');
};

export const GameCanvas: React.FC<GameCanvasProps> = ({ archetype, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Game State Refs
  const gameStateRef = useRef<GameState>(GameState.ISLAND);
  const playerRef = useRef<Player>({
    x: 0, y: 0, z: 0,
    archetype,
    stats: JSON.parse(JSON.stringify(BASE_STATS[archetype])),
    level: 1, xp: 0, xpToNextLevel: 100,
    weaponTimer: 0, skill1Timer: 0, skill1MaxCooldown: SKILL_CONFIG[archetype].skill1Cd,
    dashTimer: 0, 
    dashMaxCooldown: SKILL_CONFIG[archetype].dashCd,
    dashCharges: BASE_STATS[archetype].dashChargesMax,
    activeItem: null, itemTimer: 0, itemMaxCooldown: 0,
    facing: 0, isMoving: false, color: COLORS[archetype], animFrame: 0,
    slowTimer: 0
  });

  const enemiesRef = useRef<Enemy[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const damageNumbersRef = useRef<DamageNumber[]>([]);
  const staticObjectsRef = useRef<StaticObject[]>([]);
  const keysRef = useRef<{ [key: string]: boolean }>({});

  // System Refs
  const cameraRef = useRef({ x: 0, y: 0 }); 
  const shakeRef = useRef(0); 
  const timeRef = useRef<number>(0); 
  const waveRef = useRef<number>(0);
  const waveTimerRef = useRef<number>(0);
  const lastSpawnTimeRef = useRef<number>(0);

  // Weather System
  const weatherTimeRef = useRef<number>(0); 
  const isRainingRef = useRef<boolean>(false);
  const rainIntensityRef = useRef<number>(0);
  const rainParticlesTimer = useRef<number>(0);

  // UI State
  const [showUpgrade, setShowUpgrade] = useState(false);
  const [upgradeOptions, setUpgradeOptions] = useState<Upgrade[]>([]);
  const [lastUpgrade, setLastUpgrade] = useState<Upgrade | null>(null);
  const [hudData, setHudData] = useState({ 
      hp: 100, maxHp: 100, xp: 0, xpNext: 100, time: 0, wave: 1, level: 1, 
      state: GameState.ISLAND, skill1Cd: 0, dashCd: 0, itemCd: 0, dashCharges: 0, dashMax: 0,
      activeItem: null as Item | null, bossHp: 0, bossMaxHp: 0
  });

  const mouseScreenRef = useRef({ x: 0, y: 0 }); 
  const mouseWorldRef = useRef({ x: 0, y: 0 });
  const reticleAngleRef = useRef(0);

  // --- INIT ---
  useEffect(() => {
    // Generate Island (Optimized & Beautiful)
    if (gameStateRef.current === GameState.ISLAND) {
        const objects: StaticObject[] = [];

        // 1. Portal (Distinct Landmark)
        objects.push({ id: 'portal', x: -400, y: -400, type: 'PORTAL', size: 140 });

        // 2. Village Houses (Structured Placement)
        // Main Plaza Houses
        objects.push({ id: 'h1', x: -150, y: -150, type: 'HOUSE', size: 110, variant: 0 }); // Red Roof
        objects.push({ id: 'h2', x: 250, y: -250, type: 'HOUSE', size: 130, variant: 1 }); // Blue Roof
        objects.push({ id: 'h3', x: -350, y: 100, type: 'HOUSE', size: 100, variant: 0 });
        objects.push({ id: 'h4', x: 150, y: 200, type: 'HOUSE', size: 120, variant: 1 });
        objects.push({ id: 'h5', x: -50, y: 350, type: 'HOUSE', size: 90, variant: 0 }); // Outskirt house

        // 3. Lamps (Path Guiding)
        const lampPositions = [
            {x: 0, y: -300}, {x: -250, y: -300}, {x: -300, y: -250}, {x: -100, y: -100},
            {x: 100, y: -200}, {x: -200, y: 50}
        ];
        lampPositions.forEach((p, i) => objects.push({ id: `lamp${i}`, x: p.x, y: p.y, type: 'LAMP', size: 20 }));

        // 4. Vegetation (Trees, Rocks, Bushes)
        // We create a density function to avoid the "path" to the portal
        const isPath = (x: number, y: number) => {
            // Path from Center (0,0) to Portal (-400, -400)
            const distToLine = Math.abs((y - (-400))*0 - (x - (-400)) * (-400) + 0) / Math.hypot(-400, -400); // Distance to line segment logic simplified below
            // Simple approach: Check distance to segments
            const dCenter = Math.hypot(x, y);
            const dPortal = Math.hypot(x - (-400), y - (-400));
            // Corridor check
            const crossProduct = Math.abs(x * -400 - y * -400);
            const distToCorridor = crossProduct / Math.hypot(-400, -400);

            // If near center, near portal, or on the line between them
            if (dCenter < 250) return true;
            if (dPortal < 200) return true;
            if (distToCorridor < 100 && x < 50 && y < 50 && x > -450 && y > -450) return true;

            return false;
        };

        // Forest Generation
        for(let i=0; i<150; i++) {
            const angle = Math.random() * Math.PI * 2;
            const dist = 300 + Math.random() * 900;
            const x = Math.cos(angle) * dist;
            const y = Math.sin(angle) * dist;

            // Collision check with houses
            let collides = false;
            for(const obj of objects) {
                if (Math.hypot(x - obj.x, y - obj.y) < obj.size * 0.8) collides = true;
            }

            if (!collides && !isPath(x, y)) {
                // Determine type based on distance/random
                const r = Math.random();
                if (r < 0.6) {
                    objects.push({ 
                        id: `t${i}`, x, y, 
                        type: 'TREE', size: 50 + Math.random() * 70, 
                        variant: Math.random() > 0.5 ? 1 : 0 
                    });
                } else if (r < 0.85) {
                    objects.push({ 
                        id: `b${i}`, x, y, 
                        type: 'BUSH', size: 20 + Math.random() * 15,
                        variant: Math.random() > 0.5 ? 1 : 0
                    });
                } else {
                     objects.push({ 
                        id: `r${i}`, x, y, 
                        type: 'ROCK', size: 15 + Math.random() * 25 
                    });
                }
            }
        }

        staticObjectsRef.current = objects;
    }
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { if (e.code === 'Space') e.preventDefault(); keysRef.current[e.code] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keysRef.current[e.code] = false; };
    const handleMouseMove = (e: MouseEvent) => {
      const rect = canvasRef.current?.getBoundingClientRect();
      if(rect) {
          // Centraliza as coordenadas do mouse relativas ao centro da tela
          mouseScreenRef.current = { 
            x: e.clientX - rect.left - rect.width / 2, 
            y: e.clientY - rect.top - rect.height / 2 
          };
      }
    };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) keysRef.current['MouseLeft'] = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) keysRef.current['MouseLeft'] = false; };
    const handleContextMenu = (e: MouseEvent) => e.preventDefault();

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    window.addEventListener('contextmenu', handleContextMenu);

    let animationFrameId: number;
    let lastTime = performance.now();

    const loop = (timestamp: number) => {
      const dtRaw = (timestamp - lastTime) / 1000;
      const dt = Math.min(dtRaw, 0.1); 
      lastTime = timestamp;

      if (gameStateRef.current === GameState.TOWER || gameStateRef.current === GameState.ISLAND) {
        update(dt);
      }
      draw(dt);
      animationFrameId = requestAnimationFrame(loop);
    };

    animationFrameId = requestAnimationFrame(loop);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
      window.removeEventListener('contextmenu', handleContextMenu);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  // --- UPDATE ---
  const update = (dt: number) => {
    const player = playerRef.current;

    // --- CAMERA DINÂMICA (LOOK AHEAD) ---
    const playerIso = toIso(player.x, player.y, player.z);

    // Fator de Look Ahead
    const lookAheadX = mouseScreenRef.current.x * 0.25;
    const lookAheadY = mouseScreenRef.current.y * 0.25;

    const targetX = -playerIso.x - lookAheadX;
    const targetY = -playerIso.y - lookAheadY;

    cameraRef.current.x = lerp(cameraRef.current.x, targetX, 0.08);
    cameraRef.current.y = lerp(cameraRef.current.y, targetY, 0.08);

    // --- MIRA E CURSOR ---
    const mouseIsoX = mouseScreenRef.current.x - cameraRef.current.x;
    const mouseIsoY = mouseScreenRef.current.y - cameraRef.current.y;
    mouseWorldRef.current = toWorldFromIso(mouseIsoX, mouseIsoY);

    const distMouse = Math.hypot(mouseWorldRef.current.x - player.x, mouseWorldRef.current.y - player.y);
    if (distMouse > 40) {
        player.facing = Math.atan2(mouseWorldRef.current.y - player.y, mouseWorldRef.current.x - player.x);
    }

    reticleAngleRef.current = player.facing; 

    // Input
    let dx = 0;
    let dy = 0;
    if (keysRef.current['KeyW'] || keysRef.current['ArrowUp']) { dx -= 1; dy -= 1; }
    if (keysRef.current['KeyS'] || keysRef.current['ArrowDown']) { dx += 1; dy += 1; }
    if (keysRef.current['KeyA'] || keysRef.current['ArrowLeft']) { dx -= 1; dy += 1; }
    if (keysRef.current['KeyD'] || keysRef.current['ArrowRight']) { dx += 1; dy -= 1; }

    player.isMoving = dx !== 0 || dy !== 0;
    if (player.isMoving) {
      const length = Math.sqrt(dx * dx + dy * dy);
      dx /= length; dy /= length;

      let currentSpeed = player.stats.speed * 60;
      if (player.slowTimer > 0) {
          player.slowTimer -= dt;
          currentSpeed *= 0.6; 
      }
      player.x += dx * currentSpeed * dt;
      player.y += dy * currentSpeed * dt;
      player.animFrame += dt * 10;
    } else {
        player.animFrame = 0;
    }

    if (player.z > 0) {
        player.z -= 200 * dt; 
        if (player.z < 0) player.z = 0;
    }

    // Limits
    const limit = gameStateRef.current === GameState.ISLAND ? 1500 : 900;
    if (Math.abs(player.x) > limit) player.x = Math.sign(player.x) * limit;
    if (Math.abs(player.y) > limit) player.y = Math.sign(player.y) * limit;

    // Transition Lobby -> Tower
    if (gameStateRef.current === GameState.ISLAND) {
        const distToPortal = Math.hypot(player.x - (-400), player.y - (-400)); 
        if (distToPortal < 150) {
            gameStateRef.current = GameState.TOWER;
            player.x = 0; player.y = 0;
            enemiesRef.current = [];
            projectilesRef.current = [];
            waveRef.current = 0;
            timeRef.current = 0;
            weatherTimeRef.current = 0;
            staticObjectsRef.current = [];
        }
        if (player.stats.hp < player.stats.maxHp) player.stats.hp += 100 * dt;
    }

    // Tower Logic
    if (gameStateRef.current === GameState.TOWER) {
        timeRef.current += dt;
        waveTimerRef.current += dt;
        player.skill1Timer -= dt;
        player.itemTimer -= dt;
        player.weaponTimer -= dt;

        // --- CLIMA ---
        weatherTimeRef.current += dt;
        if (weatherTimeRef.current > 30 && weatherTimeRef.current < 90) {
            if (!isRainingRef.current) {
                isRainingRef.current = true;
                shakeRef.current = 10; 
            }
            rainIntensityRef.current = Math.min(1, rainIntensityRef.current + dt * 0.2); 
        } else {
            isRainingRef.current = false;
            rainIntensityRef.current = Math.max(0, rainIntensityRef.current - dt * 0.2); 
        }

        // Spawn de Partículas de Chuva
        if (rainIntensityRef.current > 0.1) {
            rainParticlesTimer.current += dt;
            if(rainParticlesTimer.current > 0.02) { 
                const spawnCount = Math.floor(rainIntensityRef.current * 4); 
                for(let i=0; i<spawnCount; i++) {
                    const angle = Math.random() * Math.PI * 2;
                    const dist = Math.random() * 900; 
                    particlesRef.current.push({
                        id: Math.random().toString(), 
                        x: player.x + Math.cos(angle)*dist - 400, 
                        y: player.y + Math.sin(angle)*dist - 400, 
                        z: 500, vx: 50, vy: 50, vz: -1200, 
                        life: 0.5, maxLife: 0.5, color: '#a5f3fc', size: 1.5, type: 'RAIN'
                    });
                }
                rainParticlesTimer.current = 0;
            }
        }

        // --- DASH ---
        if (player.dashCharges < player.stats.dashChargesMax) {
            player.dashTimer -= dt;
            if (player.dashTimer <= 0) {
                player.dashCharges++;
                player.dashTimer = player.dashMaxCooldown * (1 - player.stats.cooldownReduction);
            }
        }

        // --- SPAWN SYSTEM ---
        const currentConfig = WAVE_CONFIGS[waveRef.current] || WAVE_CONFIGS[WAVE_CONFIGS.length-1];
        const bossAlive = enemiesRef.current.some(e => e.isBoss);

        if (!bossAlive && waveTimerRef.current >= currentConfig.duration) {
             triggerUpgrade();
        } 
        else if (!bossAlive && enemiesRef.current.length < currentConfig.enemyCount) {
             if (Date.now() - lastSpawnTimeRef.current > currentConfig.spawnRate) {
                 if (currentConfig.boss && !enemiesRef.current.some(e => e.isBoss)) {
                     spawnBoss(currentConfig.boss);
                 } else if (!currentConfig.boss) {
                     spawnEnemy();
                 }
                 lastSpawnTimeRef.current = Date.now();
             }
        }

        if (keysRef.current['MouseLeft'] && player.weaponTimer <= 0) useMainAttack();
        if (keysRef.current['KeyQ'] && player.skill1Timer <= 0) {
            useSkill1();
            player.skill1Timer = player.skill1MaxCooldown * (1 - player.stats.cooldownReduction);
        }
        if (keysRef.current['KeyE'] && player.dashCharges > 0) {
            useDash();
            player.dashCharges--;
            if (player.dashTimer <= 0) {
                player.dashTimer = player.dashMaxCooldown * (1 - player.stats.cooldownReduction);
            }
            keysRef.current['KeyE'] = false; 
        }
        if (keysRef.current['KeyR']) activateItem();
    }

    if (shakeRef.current > 0) shakeRef.current -= dt * 30;
    if (shakeRef.current < 0) shakeRef.current = 0;

    updateProjectiles(dt);
    updateEnemies(dt);
    updateParticles(dt);

    const boss = enemiesRef.current.find(e => e.isBoss);
    setHudData({
        hp: player.stats.hp, maxHp: player.stats.maxHp,
        xp: player.xp, xpNext: player.xpToNextLevel,
        time: timeRef.current, wave: waveRef.current + 1, level: player.level,
        state: gameStateRef.current,
        skill1Cd: player.skill1Timer, dashCd: player.dashTimer, 
        dashCharges: player.dashCharges, dashMax: player.stats.dashChargesMax,
        itemCd: player.itemTimer,
        activeItem: player.activeItem,
        bossHp: boss ? boss.hp : 0, bossMaxHp: boss ? boss.maxHp : 0
    });

    if (player.stats.hp <= 0 && gameStateRef.current === GameState.TOWER) {
        gameStateRef.current = GameState.GAME_OVER;
        onGameOver();
    }
  };

  // --- ACTIONS ---
  const spawnEnemy = () => {
    const angle = Math.random() * Math.PI * 2;
    const distance = 850; 

    const ex = playerRef.current.x + Math.cos(angle) * distance;
    const ey = playerRef.current.y + Math.sin(angle) * distance;

    let type: any = 'SLIME';
    const w = waveRef.current;
    const r = Math.random();

    // Wave Progression Logic
    if (w >= 10) { 
        if (r < 0.2) type = 'DEMON';
        else if (r < 0.4) type = 'BAT';
        else if (r < 0.6) type = 'SORCERER';
        else if (r < 0.8) type = 'SNAKE';
        else type = 'GOBLIN';
    } else if (w >= 5) {
        if (r < 0.2) type = 'GOBLIN';
        else if (r < 0.4) type = 'BAT';
        else if (r < 0.6) type = 'SNAKE';
        else if (r < 0.8) type = 'SORCERER';
        else type = 'SLIME';
    } else if (w >= 2) {
         if (r < 0.3) type = 'SNAKE';
         else if (r < 0.6) type = 'GOBLIN';
         else type = 'SLIME';
    } else { 
        type = r < 0.2 ? 'GOBLIN' : 'SLIME';
    }

    const variant = Math.floor(Math.random() * 3);

    let hp = 30 + w * 12;
    let armor = 0;
    let speed = 80 + Math.random()*20;
    let radius = 20;

    if (variant === 1) { hp *= 0.8; speed *= 1.2; }
    else if (variant === 2) { hp *= 1.3; speed *= 0.85; radius *= 1.2; }

    if (w >= 3) armor = 5 + w * 2; 

    let attackRange = 50; 
    let windupTime = 0.5;

    if (type === 'SLIME') { if (variant === 1) speed += 20; }
    if (type === 'GOBLIN') { 
        hp += 30; speed = 90; attackRange = 70; windupTime = 0.4;
        if (variant === 1) { speed = 110; attackRange = 60; }
        if (variant === 2) { hp += 50; speed = 70; }
    }
    if (type === 'SORCERER') { hp += 10; armor = 0; speed = 60; attackRange = 400; windupTime = 0.8; }
    if (type === 'DEMON') { hp += 150; armor += 20; speed = 65; attackRange = 90; windupTime = 0.6; }

    // Novos Inimigos
    if (type === 'SNAKE') {
        hp = 25 + w * 8; speed = 110; attackRange = 300; windupTime = 0.6; radius = 18;
    }
    if (type === 'BAT') {
        hp = 20 + w * 5; speed = 140; attackRange = 60; windupTime = 0.3; radius = 15; armor = 0;
    }

    enemiesRef.current.push({
      id: Math.random().toString(), x: ex, y: ey, z: type === 'BAT' ? 200 : 0, 
      type, isBoss: false,
      hp, maxHp: hp, defense: armor, speed, damage: 10 + w * 2,
      radius, hitboxRadius: radius * 0.8, frame: 0, vx: 0, vy: 0, hitFlash: 0,
      state: type === 'BAT' ? 'SWOOPING' : 'CHASING', 
      stateTimer: 0, attackRange, windupTime, recoverTime: 0.5,
      variant
    });
  };

  const spawnBoss = (type: 'BOSS_GOLEM' | 'BOSS_LICH') => {
      // ... (Mantendo código existente de boss) ...
      const dist = 600;
      const angle = Math.random() * Math.PI * 2;
      const waveMult = 1 + waveRef.current * 0.5;

      let hp = 4000 * waveMult;
      let defense = 30 + waveRef.current * 5;
      let damage = 60 + waveRef.current * 2;
      let speed = 40;
      let radius = 80;
      let attackRange = 180;

      if (type === 'BOSS_GOLEM') {
          hp = 6000 * waveMult;
          defense = 60 + waveRef.current * 5;
          speed = 35;
          damage = 80 + waveRef.current * 3;
          radius = 100;
          attackRange = 150;
      } else if (type === 'BOSS_LICH') {
          hp = 3500 * waveMult;
          defense = 20 + waveRef.current * 5;
          speed = 55;
          damage = 50 + waveRef.current * 2;
          radius = 70;
          attackRange = 450;
      }

      enemiesRef.current.push({
          id: 'boss', x: playerRef.current.x + Math.cos(angle)*dist, y: playerRef.current.y + Math.sin(angle)*dist, z: 0,
          type, isBoss: true,
          hp, maxHp: hp,
          defense, speed, damage, radius, hitboxRadius: radius * 0.8, frame: 0, 
          vx: 0, vy: 0, hitFlash: 0,
          state: 'CHASING', stateTimer: 0, attackRange, windupTime: 1.5, recoverTime: 1.5,
          variant: 0, specialTimer: 5 // Start cooldown for special
      });
      shakeRef.current = 20; 
  };

  const updateEnemies = (dt: number) => {
      const p = playerRef.current;

      const enemiesList = enemiesRef.current;
      const enemyCount = enemiesList.length;

      enemiesRef.current = enemiesList.filter((e, idx) => {
          if (e.hitFlash > 0) e.hitFlash -= dt;
          e.frame += dt; // Animation frame ticker

          // Separation (Bats don't collide with ground units for separation)
          if (e.type !== 'BAT') {
              let sepX = 0, sepY = 0;
              const checkLimit = Math.min(idx + 3, enemyCount);
              for (let i = Math.max(0, idx - 3); i < checkLimit; i++) {
                  if (i === idx) continue;
                  const other = enemiesList[i];
                  if (other.type === 'BAT') continue; // Ignora morcegos na colisão

                  const distSq = (e.x - other.x)**2 + (e.y - other.y)**2;
                  const minDist = (e.radius + other.radius) * 0.8;
                  if (distSq < minDist**2 && distSq > 0.1) {
                      const pushDist = Math.sqrt(distSq);
                      const pushForce = (minDist - pushDist) / pushDist;
                      sepX += (e.x - other.x) * pushForce;
                      sepY += (e.y - other.y) * pushForce;
                  }
              }
              e.vx += sepX * 200 * dt;
              e.vy += sepY * 200 * dt;
          }

          if (Math.abs(e.vx) > 1 || Math.abs(e.vy) > 1) {
              e.x += e.vx * dt; e.y += e.vy * dt;
              e.vx *= 0.9; e.vy *= 0.9;
          }

          const dx = p.x - e.x;
          const dy = p.y - e.y;
          const dist = Math.hypot(dx, dy);

          if (e.isBoss && e.specialTimer !== undefined) {
             e.specialTimer -= dt;
          }

          // --- AI BEHAVIOR ---
          if (e.state === 'CHASING' || e.state === 'SWOOPING') {
              if (e.type === 'SORCERER' && dist < 300) {
                 e.state = 'FLEEING';
                 e.stateTimer = 1.0; 
              }

              // Snake Logic: Tries to stay at range to spit
              if (e.type === 'SNAKE' && dist < 250 && dist > 100) {
                   if (Math.random() < 0.02) { // Random attack chance while in range
                       e.state = 'WINDUP';
                       e.stateTimer = e.windupTime;
                   }
              }

              // Bat Logic: Z-Axis movement
              if (e.type === 'BAT') {
                  const hoverHeight = 60 + Math.sin(e.frame * 5) * 20;
                  if (e.state === 'SWOOPING') {
                      // Mergulha quando perto
                      if (dist < 200) e.z = lerp(e.z, 10, dt * 5);
                      else e.z = lerp(e.z, hoverHeight, dt * 2);
                  }
              }

              // Boss Logic (Simplified for brevity, same as before)
              if (e.isBoss && e.specialTimer !== undefined && e.specialTimer <= 0) {
                  // ... (Boss logic mantida)
                  if (e.type === 'BOSS_GOLEM') {
                       const isEnraged = e.hp < e.maxHp * 0.5;
                       if (dist > 350 && Math.random() < 0.6) {
                           e.state = 'CHANNELING'; e.stateTimer = 0.8; e.specialTimer = isEnraged ? 4 : 7; e.variant = 1; 
                       } else if (Math.random() < 0.4) {
                           e.state = 'CHANNELING'; e.stateTimer = 1.5; e.specialTimer = isEnraged ? 6 : 10; e.variant = 0; 
                       }
                  } else if (e.type === 'BOSS_LICH') {
                       if (dist < 180 && Math.random() < 0.7) {
                           createParticle(e.x, e.y, 10, '#a855f7', 15, 'TELEPORT');
                           const telAngle = Math.atan2(dy, dx) + Math.PI + (Math.random()-0.5);
                           const telDist = 400 + Math.random() * 200;
                           e.x = p.x + Math.cos(telAngle) * telDist;
                           e.y = p.y + Math.sin(telAngle) * telDist;
                           createParticle(e.x, e.y, 10, '#a855f7', 15, 'TELEPORT');
                           e.specialTimer = 4; e.state = 'RECOVERING'; e.stateTimer = 0.5;
                       } else if (Math.random() < 0.5) {
                           e.state = 'CHANNELING'; e.stateTimer = 1.0; e.specialTimer = 8;
                       } else {
                           e.specialTimer = 5;
                       }
                  }
              }

              // Movement Logic
              if (dist > 10) {
                  let mx = dx / dist;
                  let my = dy / dist;

                  // Goblin Flanking
                  if (e.type === 'GOBLIN' && dist > 80 && dist < 300) {
                      const strafeDir = (e.id.charCodeAt(0) % 2 === 0) ? 1 : -1;
                      mx = (mx * 0.5) + (-my * strafeDir * 0.8);
                      my = (my * 0.5) + (mx * strafeDir * 0.8);
                      const len = Math.hypot(mx, my);
                      mx /= len; my /= len;
                  }

                  // Snake Slithering (Visual logic handled in draw, but here we add some wobble)
                  if (e.type === 'SNAKE') {
                      const wobble = Math.sin(e.frame * 8) * 0.5;
                      mx += -my * wobble;
                      my += mx * wobble;
                      // Normalize again
                      const len = Math.hypot(mx, my);
                      mx /= len; my /= len;
                  }

                  // FIX: LICH MOVEMENT LOGIC
                  // Before: e.speed *= -0.5 (permanent flip caused by persistent modification). 
                  // Now: Use temporary speed modifier logic locally.
                  let currentMoveSpeed = e.speed;
                  if (e.type === 'BOSS_LICH' && dist < 350) {
                      currentMoveSpeed *= -0.5; // Back away (Negative speed moves away)
                  }

                  e.x += mx * currentMoveSpeed * dt;
                  e.y += my * currentMoveSpeed * dt;
              }

              if (dist < e.attackRange) {
                  e.state = 'WINDUP';
                  e.stateTimer = e.windupTime;
              }
          }
          else if (e.state === 'FLEEING') {
              e.stateTimer -= dt;
              if (dist > 0) {
                  e.x -= (dx/dist) * e.speed * 1.2 * dt;
                  e.y -= (dy/dist) * e.speed * 1.2 * dt;
              }
              if (e.stateTimer <= 0) e.state = 'CHASING';
          }
          else if (e.state === 'CHANNELING') {
              e.stateTimer -= dt;
              createParticle(e.x + (Math.random()-0.5)*50, e.y + (Math.random()-0.5)*50, Math.random()*100, e.type === 'BOSS_GOLEM' ? '#f59e0b' : '#a855f7', 1, 'SPARK');

              if (e.stateTimer <= 0) {
                  // Boss attacks (Mantido)
                  if (e.type === 'BOSS_GOLEM') {
                      if (e.variant === 1) { 
                          const throwAngle = Math.atan2(dy, dx);
                          projectilesRef.current.push({
                              id: Math.random().toString(), x: e.x, y: e.y, z: 60,
                              vx: Math.cos(throwAngle) * 500, vy: Math.sin(throwAngle) * 500,
                              damage: e.damage * 1.2, duration: 3, radius: 25,
                              type: 'BOSS_ROCK', color: '#78350f', pierce: 999, isEnemy: true
                          });
                      } else { 
                          shakeRef.current = 25;
                          for(let i=0; i<8; i++) {
                              const angle = (i / 8) * Math.PI * 2;
                              projectilesRef.current.push({
                                  id: Math.random().toString(), x: e.x, y: e.y, z: 10,
                                  vx: Math.cos(angle) * 350, vy: Math.sin(angle) * 350,
                                  damage: e.damage * 0.8, duration: 2, radius: 25,
                                  type: 'GOLEM_SHOCKWAVE', color: '#d97706', pierce: 999, isEnemy: true
                              });
                          }
                      }
                  } else if (e.type === 'BOSS_LICH') {
                       for(let i=0; i<12; i++) {
                          const angle = (i / 12) * Math.PI * 2 + (Math.random() * 0.5);
                          projectilesRef.current.push({
                              id: Math.random().toString(), x: e.x, y: e.y, z: 40,
                              vx: Math.cos(angle) * 250, vy: Math.sin(angle) * 250,
                              damage: e.damage * 0.6, duration: 4, radius: 12,
                              type: 'LICH_NOVA', color: '#10b981', pierce: 999, isEnemy: true
                          });
                       }
                  }
                  e.state = 'RECOVERING';
                  e.stateTimer = 1.0;
              }
          }
          else if (e.state === 'WINDUP') {
              e.stateTimer -= dt;
              if (e.stateTimer <= 0) {
                  e.state = 'ATTACKING';

                  if (e.type === 'SORCERER' || e.type === 'BOSS_LICH' || e.type === 'SNAKE') {
                      projectilesRef.current.push({
                          id: Math.random().toString(), x: e.x, y: e.y, z: 40,
                          vx: (dx/dist)*500, vy: (dy/dist)*500,
                          damage: e.damage, duration: 2, radius: 12,
                          type: e.type === 'SNAKE' ? 'POISON_SPIT' : 'ENEMY_BOLT', 
                          color: e.type === 'BOSS_LICH' ? '#10b981' : (e.type === 'SNAKE' ? '#a3e635' : '#9333ea'), 
                          pierce: 0, isEnemy: true
                      });
                  } else if (e.type === 'BOSS_GOLEM') {
                       projectilesRef.current.push({
                          id: Math.random().toString(), x: e.x, y: e.y, z: 0,
                          vx: 0, vy: 0,
                          damage: e.damage * 1.5, duration: 0.5, radius: 140,
                          type: 'BOSS_SMASH', color: '#ef4444', pierce: 999, isEnemy: true
                      });
                      shakeRef.current = 30;
                  } else if (dist < e.attackRange + 30) {
                      takeDamage(p, e.damage);
                  }
                  // CORREÇÃO CRÍTICA 2: Garantindo uso de 'e.type' e não 'type'
                  e.state = e.type === 'BAT' ? 'SWOOPING' : 'RECOVERING';
                  e.stateTimer = e.recoverTime;
                  if (e.type === 'BOSS_GOLEM' && e.hp < e.maxHp * 0.5) e.stateTimer *= 0.5;
              }
          } else if (e.state === 'RECOVERING') {
              e.stateTimer -= dt;
              if (e.stateTimer <= 0) e.state = 'CHASING';
          }

          // Projectile Collision
          for (const proj of projectilesRef.current) {
               if (proj.duration <= 0 || proj.isEnemy) continue;

               // Distância 2D (Ignora Z para facilitar gameplay, exceto se eu quiser ser punitivo com morcegos)
               // Para manter fluido, ataques acertam morcegos mesmo que "visualmente" estejam altos
               const pDist = Math.hypot(proj.x - e.x, proj.y - e.y);

               if(pDist < proj.radius + e.hitboxRadius) {
                   const isAoe = proj.type === 'SWORD_SLASH' || proj.type === 'FIRE_ZONE';
                   let dmg = isAoe ? proj.damage * 5 * dt : proj.damage;
                   const isCrit = Math.random() > 0.8;
                   if (isCrit) dmg *= 1.5;

                   const effectiveDefense = Math.max(0, e.defense - p.stats.armorPenetration);
                   const mitigation = 100 / (100 + effectiveDefense);
                   const finalDmg = dmg * mitigation;

                   e.hitFlash = 0.15; 

                   // Knockback (Morcegos voam mais longe)
                   if (proj.type === 'ARROW' || proj.type === 'MAGIC_ORB') {
                       const kAngle = Math.atan2(e.y - proj.y, e.x - proj.x);
                       const force = e.type === 'BAT' ? 500 : 300;
                       e.vx = Math.cos(kAngle) * force;
                       e.vy = Math.sin(kAngle) * force;
                       if (!isAoe) {
                           proj.pierce--;
                           if (proj.pierce < 0) {
                               proj.duration = 0; 
                           }
                       }
                   }

                   e.hp -= finalDmg;

                   if (!isAoe || Math.random() > 0.8) {
                       createDamageNumber(e.x, e.y, e.z + 40, finalDmg, isCrit, false, mitigation < 0.7);
                   }

                   if(e.hp <= 0 && !e.isBoss) {
                       createParticle(e.x, e.y, e.z, '#ef4444', 12, 'BLOOD'); 
                       if (p.stats.lifeSteal > 0) {
                           const heal = p.stats.maxHp * p.stats.lifeSteal;
                           if (heal > 0) {
                               p.stats.hp = Math.min(p.stats.maxHp, p.stats.hp + heal);
                               createDamageNumber(p.x, p.y, p.z + 80, heal, false, false, false);
                           }
                       }
                       if (!isAoe && proj.pierce < 0) break;
                       break; 
                   }
               }
          }

          if(e.hp <= 0) {
              p.xp += e.isBoss ? 500 : 15;
              shakeRef.current += e.isBoss ? 20 : 2; 

              if(p.xp >= p.xpToNextLevel) {
                  p.level++;
                  p.xp -= p.xpToNextLevel;
                  p.xpToNextLevel *= 1.2;
                  p.stats.damage *= 1.1;
                  p.stats.maxHp *= 1.1;
                  p.stats.hp = p.stats.maxHp;
                  createDamageNumber(p.x, p.y, p.z+60, 0, true); 
                  shakeRef.current += 10; 
              }
              return false;
          }
          return true;
      });
  };

  const takeDamage = (p: Player, amount: number) => {
      const reducedByPercent = amount * (1 - Math.min(0.8, p.stats.damageReduction)); 
      const finalDmg = Math.max(1, reducedByPercent - p.stats.defense);
      p.stats.hp -= finalDmg;
      shakeRef.current = 10;
      p.slowTimer = 0.5;
      createDamageNumber(p.x, p.y, p.z + 50, finalDmg, false, true);
  };

  const updateProjectiles = (dt: number) => {
      const p = playerRef.current;
      projectilesRef.current = projectilesRef.current.filter(proj => {
          proj.duration -= dt;

          if(proj.type === 'SWORD_SLASH') {
              proj.x = playerRef.current.x; proj.y = playerRef.current.y;
          } else {
              proj.x += proj.vx * dt; proj.y += proj.vy * dt;
          }

          if (Math.abs(proj.x - p.x) > 1500 || Math.abs(proj.y - p.y) > 1500) {
              return false;
          }

          if (proj.isEnemy) {
              const dist = Math.hypot(proj.x - p.x, proj.y - p.y);
              if (proj.type === 'LICH_DRAIN_ZONE') {
                  if (dist < proj.radius) {
                      takeDamage(p, proj.damage * dt); 
                      const lich = enemiesRef.current.find(e => e.type === 'BOSS_LICH');
                      if (lich && lich.hp < lich.maxHp) {
                          lich.hp += proj.damage * dt * 0.5;
                      }
                  }
              } else if (dist < (proj.type === 'BOSS_SMASH' ? proj.radius : 20)) {
                  takeDamage(p, proj.damage);
                  return false; 
              } else if (dist < proj.radius) {
                  takeDamage(p, proj.damage);
                  if (proj.type === 'POISON_SPIT') {
                      p.slowTimer = 1.0; // Veneno deixa lento por mais tempo
                  }
                  return false;
              }
          }
          return proj.duration > 0;
      });
  };

  const createDamageNumber = (x: number, y: number, z: number, val: number, crit: boolean, isPlayerDamage = false, isBlocked = false) => {
      if (val < 1 && !isBlocked) return;
      damageNumbersRef.current.push({
          id: Math.random().toString(), x: x + (Math.random()-0.5)*20, y, z, value: val, life: 0.8, isCrit: crit, isPlayerDamage
      });
  };

  const useMainAttack = () => {
     const p = playerRef.current;
     const angle = p.facing;

     const vx = Math.cos(angle) * 800;
     const vy = Math.sin(angle) * 800;
     const atkSpdMultiplier = Math.max(0.1, p.stats.attackSpeed);

     if (p.archetype === Archetype.WARRIOR) {
         projectilesRef.current.push({
             id: Math.random().toString(), x: p.x, y: p.y, z: 20, vx: 0, vy: 0,
             damage: p.stats.damage, duration: 0.3, radius: 100 * p.stats.areaSize,
             type: 'SWORD_SLASH', color: '#60a5fa', pierce: 999
         });
         p.weaponTimer = (0.6 / atkSpdMultiplier) * (1 - p.stats.cooldownReduction);
     } else {
         projectilesRef.current.push({
             id: Math.random().toString(), x: p.x, y: p.y, z: 30, vx, vy,
             damage: p.stats.damage, duration: 1.5, radius: 15,
             type: p.archetype === Archetype.ARCHER ? 'ARROW' : 'MAGIC_ORB', 
             color: p.color, pierce: p.archetype === Archetype.MAGE ? 2 : 0
         });
         const baseCd = p.archetype === Archetype.ARCHER ? 0.4 : 0.5;
         p.weaponTimer = (baseCd / atkSpdMultiplier) * (1 - p.stats.cooldownReduction);
     }
  };

  const useSkill1 = () => {
      const p = playerRef.current;
      createParticle(p.x, p.y, 20, '#fff', 10);
      shakeRef.current = 5; 

      if(p.archetype === Archetype.WARRIOR) {
          projectilesRef.current.push({
             id: Math.random().toString(), x: p.x, y: p.y, z: 20, vx: 0, vy: 0,
             damage: p.stats.damage * 2.5, duration: 0.5, radius: 160 * p.stats.areaSize,
             type: 'SWORD_SLASH', color: '#ef4444', pierce: 999
         });
      } else {
          projectilesRef.current.push({
             id: Math.random().toString(), x: mouseWorldRef.current.x, y: mouseWorldRef.current.y, z: 0, vx: 0, vy: 0,
             damage: p.stats.damage * 3, duration: 1.2, radius: 120 * p.stats.areaSize,
             type: 'FIRE_ZONE', color: p.archetype === Archetype.MAGE ? '#9333ea' : '#ef4444', pierce: 999
         });
      }
  };

  const useDash = () => {
      const p = playerRef.current;
      const angle = Math.atan2(mouseWorldRef.current.y - p.y, mouseWorldRef.current.x - p.x);
      const vx = Math.cos(angle) * 1200;
      const vy = Math.sin(angle) * 1200;
      p.x += vx * 0.2; 
      p.y += vy * 0.2;
      p.z = 40; 
      createParticle(p.x, p.y, 10, '#fff', 5);
  };

  const activateItem = () => {
     const p = playerRef.current;
     if (p.activeItem && p.itemTimer <= 0) {
         p.activeItem.effect(p, enemiesRef.current);
         p.itemTimer = p.activeItem.cooldown;
     }
  };

  const triggerUpgrade = () => {
    gameStateRef.current = GameState.PAUSED;
    const options: Upgrade[] = [];
    const rollItem = !playerRef.current.activeItem && Math.random() > 0.8; 
    for(let i=0; i<4; i++) {
        let pool = UPGRADES_LIST;
        if (rollItem && i === 0) pool = UPGRADES_LIST.filter(u => u.type === 'ITEM');
        const rand = pool[Math.floor(Math.random() * pool.length)];
        options.push({...rand, id: rand.id}); 
    }
    setUpgradeOptions(options);
    setShowUpgrade(true);
  };

  const applyUpgrade = (upgrade: Upgrade) => {
      const p = playerRef.current;
      if (upgrade.type === 'ITEM' && upgrade.itemRef) {
          p.activeItem = upgrade.itemRef;
      } else {
        if (upgrade.id.startsWith('dmg_')) p.stats.damage *= (upgrade.id.includes('rare') ? 1.25 : 1.12);
        if (upgrade.id.startsWith('atk_spd')) p.stats.attackSpeed += (upgrade.id.includes('rare') ? 0.20 : 0.10);
        if (upgrade.id.startsWith('pen_')) p.stats.armorPenetration += 8;

        if (upgrade.id.startsWith('hp_')) {
            const val = upgrade.id.includes('rare') ? 100 : 40;
            p.stats.maxHp += val; 
            p.stats.hp += val;
        }
        if (upgrade.id.startsWith('def_')) p.stats.defense += (upgrade.id.includes('rare') ? 12 : 5);
        if (upgrade.id.startsWith('dmg_red')) p.stats.damageReduction += (upgrade.id.includes('epic') ? 0.10 : 0.05);

        if (upgrade.id.startsWith('ls_')) {
             let val = 0.005; 
             if (upgrade.id.includes('rare')) val = 0.015;
             if (upgrade.id.includes('epic')) val = 0.03;
             p.stats.lifeSteal += val;
        }

        if (upgrade.id.startsWith('spd_')) p.stats.speed *= 1.1;
        if (upgrade.id.startsWith('cdr_')) p.stats.cooldownReduction = Math.min(0.7, p.stats.cooldownReduction + 0.08);
        if (upgrade.id.startsWith('area_')) p.stats.areaSize *= 1.2;
        if (upgrade.id.startsWith('dash_')) {
            const val = upgrade.id.includes('epic') ? 2 : 1;
            p.stats.dashChargesMax += val; 
            p.dashCharges += val; 
        }
      }
      setLastUpgrade(upgrade);
      setShowUpgrade(false);
      gameStateRef.current = GameState.TOWER;
      if (waveTimerRef.current >= WAVE_CONFIGS[0].duration) {
         waveRef.current++;
         waveTimerRef.current = 0;
      }
  };

  const updateParticles = (dt: number) => {
      particlesRef.current = particlesRef.current.filter(p => {
          p.life -= dt;
          p.x += p.vx * dt;
          p.y += p.vy * dt;
          p.z += p.vz * dt;
          if (p.type !== 'RAIN') p.vz -= 300 * dt; 

          if(p.z < 0) {
              p.z = 0;
              if (p.type === 'RAIN') {
                  createParticle(p.x, p.y, 0, '#fff', 1, 'SPARK');
                  return false; 
              }
              if (p.type === 'BLOOD') {
                  p.vx = 0; p.vy = 0; 
              }
          }
          return p.life > 0;
      });
      damageNumbersRef.current = damageNumbersRef.current.filter(d => { d.life -= dt; d.z += 40 * dt; return d.life > 0; });
  };

  const createParticle = (x: number, y: number, z: number, color: string, count: number, type: 'SPARK'|'BLOOD'|'RAIN'|'POISON'|'TELEPORT' = 'SPARK') => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({
              id: Math.random().toString(), x, y, z,
              vx: (Math.random()-0.5)*150, vy: (Math.random()-0.5)*150, vz: Math.random()*150 + 50,
              life: type === 'BLOOD' ? 3 : 0.5, maxLife: 0.5, color, size: Math.random()*3+2, type
          });
      }
  };

  // --- RENDER ---
  const drawIsoSprite = (ctx: CanvasRenderingContext2D, entity: any, type: string) => {
      // 1. Telegraph
      if (['SLIME','GOBLIN','DEMON','BOSS','SORCERER', 'BOSS_GOLEM', 'BOSS_LICH', 'SNAKE'].includes(type) && entity.state === 'WINDUP') {
          const iso = toIso(entity.x, entity.y, 0);
          const progress = Math.max(0, 1 - (entity.stateTimer / entity.windupTime)); // SAFETY: Max(0)
          const radius = Math.max(1, entity.attackRange * (type === 'BOSS_LICH' ? 0.3 : 1.5)); // SAFETY: Max(1)
          ctx.save();
          ctx.strokeStyle = type === 'BOSS_LICH' ? 'rgba(16, 185, 129, 0.6)' : 'rgba(239, 68, 68, 0.6)';
          ctx.lineWidth = 3;
          ctx.beginPath();
          ctx.ellipse(iso.x, iso.y, radius, radius * 0.5, 0, 0, Math.PI * 2);
          ctx.stroke();
          ctx.fillStyle = type === 'BOSS_LICH' ? 'rgba(16, 185, 129, 0.3)' : 'rgba(239, 68, 68, 0.3)';
          ctx.beginPath();
          ctx.ellipse(iso.x, iso.y, radius * progress, (radius * 0.5) * progress, 0, 0, Math.PI * 2);
          ctx.fill();
          ctx.restore();
      }

      // 2. Hit Flash
      if (entity.hitFlash && entity.hitFlash > 0) {
          const { x, y } = toIso(entity.x, entity.y, entity.z);
          const h = (type.includes('BOSS')) ? 80 : 25;
          const w = (type.includes('BOSS')) ? 80 : 25;
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(x - w/2, y - h, w, h);
          return; 
      }

      // 3. Voxel Sprite Drawing
      const idOffset = parseFloat(entity.id || '0') || 0;
      let bounce = 0;
      let stretch = 1;

      // Entities bounce/squash
      if (['PLAYER', 'GOBLIN', 'DEMON', 'SORCERER', 'SLIME', 'SNAKE'].includes(type)) {
          // CORREÇÃO CRÍTICA 1: Usar 'frame' para inimigos se 'animFrame' não existir
          const currentF = entity.animFrame || entity.frame || 0;
          const animVal = Math.sin(currentF + idOffset);
          bounce = Math.abs(animVal) * 3;
          stretch = 1 + (Math.cos(currentF + idOffset) * 0.05);
      }
      if (type === 'BOSS_LICH') {
          const floatVal = Math.sin(performance.now()/500);
          bounce = 20 + floatVal * 10;
      }

      const { x, y } = toIso(entity.x, entity.y, entity.z + bounce);

      // Shadow (Bats have distant shadows)
      if (entity.z < 200 || type === 'BOSS_LICH' || type === 'BAT') {
          const shadow = toIso(entity.x, entity.y, 0); // Shadow always at z=0
          ctx.fillStyle = 'rgba(0,0,0,0.4)';
          ctx.beginPath();
          let wS = 14; let hS = 7;
          if (type.includes('BOSS')) { wS = 50; hS = 25; }
          else if (type === 'TREE') { wS = 25; hS = 12; }
          else if (type === 'BAT') { wS = 10; hS = 5; } // Small shadow for flyer

          ctx.ellipse(shadow.x, shadow.y, wS * stretch, hS * stretch, 0, 0, Math.PI*2);
          ctx.fill();
      }

      const layers = type.includes('BOSS') ? 14 : 7;
      const scale = 2;

      for(let i=0; i<layers; i++) {
          const ly = y - (i * scale * 2);
          let w = 20; 

          if (type === 'PLAYER') {
             // ... existing player logic ...
             if (entity.archetype === Archetype.WARRIOR) {
                 w = 20; let color = '#334155'; if (i >= 5) { color = '#1d4ed8'; w = 16; } if (i === 4) { color = '#94a3b8'; w = 22; } ctx.fillStyle = color; ctx.fillRect(x - w/2, ly - w/2, w, w);
             } else if (entity.archetype === Archetype.MAGE) {
                 w = 18; let color = '#581c87'; if (i >= 5) { color = '#a855f7'; w = 12; } if (i === 6) { w = 8; } ctx.fillStyle = color; ctx.fillRect(x - w/2, ly - w/2, w, w);
             } else {
                 w = 16; let color = '#15803d'; if (i >= 5) { color = '#86efac'; w = 14; } ctx.fillStyle = color; ctx.fillRect(x - w/2, ly - w/2, w, w);
             }
          } 
          // --- STATIC OBJECTS VISUAL OVERHAUL ---
          else if (type === 'TREE') {
              const sway = Math.sin(performance.now()/1500 + entity.x/100) * (i * 0.8);
              if (i < 3) { w = entity.size * 0.15; ctx.fillStyle = '#271306'; ctx.fillRect(x - w/2 + sway*0.2, ly - w, w, w*1.5); } 
              else {
                  let level = 0; if (i > 6) level = 1; if (i > 10) level = 2;
                  let baseC = entity.variant === 1 ? 0x14532d : 0x166534; 
                  if (level === 1) baseC += 0x111111; if (level === 2) baseC += 0x222222;
                  ctx.fillStyle = '#' + baseC.toString(16).padStart(6,'0');
                  const taper = 1 - ((i-3) / (layers)); w = entity.size * 0.8 * taper; const fh = 8; 
                  ctx.fillRect(x - w/2 + sway, ly - fh, w, fh);
              }
          }
          else if (type === 'HOUSE') {
              if (i < 6) {
                  w = entity.size * 0.6; let h = entity.size * 0.5; ctx.fillStyle = i < 2 ? '#44403c' : '#f5f5f4'; ctx.fillRect(x - w/2, ly - h/2, w, h);
                  if (i === 1) { ctx.fillStyle = '#292524'; ctx.fillRect(x - 8, ly - 5, 16, 20); }
                  if (i === 4) { ctx.fillStyle = '#38bdf8'; ctx.fillRect(x - w/3, ly - 5, 10, 10); ctx.fillRect(x + w/3 - 10, ly - 5, 10, 10); }
              } else {
                  const roofProgress = (i - 6); w = (entity.size * 0.7) - (roofProgress * 6); if (w < 0) w = 0;
                  ctx.fillStyle = entity.variant === 1 ? '#1e3a8a' : '#7f1d1d'; if (i % 2 === 0) ctx.fillStyle = adjustColor(ctx.fillStyle as string, 20);
                  ctx.fillRect(x - w/2, ly - 10, w, 14);
              }
          }
          else if (type === 'ROCK') {
              if (i < 3) { w = entity.size * (1 - i*0.2); ctx.fillStyle = '#57534e'; ctx.fillRect(x - w/2, ly - w/2, w, w); }
          }
          else if (type === 'BUSH') {
              if (i < 3) { const sway = Math.sin(performance.now()/800 + entity.x) * 2; w = entity.size * (1 - i*0.1); ctx.fillStyle = entity.variant === 1 ? '#4d7c0f' : '#15803d'; ctx.beginPath(); ctx.arc(x + sway, ly, w/2, 0, Math.PI*2); ctx.fill(); }
          }
          else if (type === 'LAMP') {
             w = 4; if (i < 8) ctx.fillStyle = '#1c1917'; else { ctx.fillStyle = '#f59e0b'; ctx.shadowBlur = 20; ctx.shadowColor = '#d97706'; w = 8; } 
             ctx.fillRect(x - w/2, ly - w*2, w, w*2); ctx.shadowBlur = 0;
          }
          else if (type === 'PORTAL') {
              const t = performance.now() / 1000;
              if (i < 2) { w = entity.size; ctx.fillStyle = '#312e81'; ctx.beginPath(); ctx.ellipse(x, ly, w/2, w/4, 0, 0, Math.PI*2); ctx.fill(); }
              if (i === 2) {
                  ctx.save(); ctx.translate(x, ly - 50);
                  for(let r=0; r<3; r++) {
                      ctx.rotate(t * (r%2 === 0 ? 1 : -1)); ctx.strokeStyle = r === 0 ? '#4f46e5' : (r === 1 ? '#818cf8' : '#c7d2fe'); ctx.lineWidth = 3; ctx.beginPath(); ctx.ellipse(0, 0, entity.size/3 - r*10, entity.size/1.5 - r*20, t + r, 0, Math.PI*2); ctx.stroke();
                  }
                  ctx.restore();
                  const glowSize = 20 + Math.sin(t*3)*5; ctx.fillStyle = 'rgba(99, 102, 241, 0.4)'; ctx.beginPath(); ctx.arc(x, ly - 50, glowSize, 0, Math.PI*2); ctx.fill();
              }
          }
          // --- ENEMIES & BOSSES ---
          else if (type === 'BAT') {
              // Only draw a few layers for bat to keep it small
              if (i < 4) {
                 w = 12;
                 ctx.fillStyle = '#1e293b'; // Dark body
                 ctx.fillRect(x - w/2, ly - w/2, w, w);

                 // Wings (Flapping logic)
                 const flap = Math.sin(entity.frame * 20) * 10;
                 ctx.fillStyle = '#334155';
                 ctx.beginPath();
                 ctx.moveTo(x - w/2, ly);
                 ctx.lineTo(x - w/2 - 15, ly - flap); // Left Wing
                 ctx.lineTo(x - w/2 - 5, ly + 5);
                 ctx.fill();

                 ctx.beginPath();
                 ctx.moveTo(x + w/2, ly);
                 ctx.lineTo(x + w/2 + 15, ly - flap); // Right Wing
                 ctx.lineTo(x + w/2 + 5, ly + 5);
                 ctx.fill();
              }
          }
          else if (type === 'SNAKE') {
              // Slithering Body Segment Logic
              const segmentCount = 6;
              const segIndex = i; // Reuse layer loop as segment loop roughly
              if (i < segmentCount) {
                  const wobble = Math.sin((entity.frame * 10) + (i * 0.5)) * 10;
                  const bx = x + wobble; // Offset X for wobble
                  const by = ly + (i * 4); // Trail behind on Y (isometric-ish)
                  w = 14 - i; // Taper tail
                  ctx.fillStyle = i === 0 ? '#4ade80' : '#3f6212'; // Head green, body dark
                  if (i === 0) { // Head
                       ctx.fillStyle = '#84cc16';
                       ctx.fillRect(bx - w/2, ly, w, w);
                       // Eyes
                       ctx.fillStyle = 'red';
                       ctx.fillRect(bx - 3, ly + 2, 2, 2);
                       ctx.fillRect(bx + 1, ly + 2, 2, 2);
                  } else {
                       ctx.beginPath(); ctx.arc(bx, by, w/2, 0, Math.PI*2); ctx.fill();
                  }
              }
          }
          else if (type === 'BOSS_GOLEM') {
             w = 80 - i*2; let h = 80 - i*2;
             const isEnraged = entity.hp < entity.maxHp * 0.5;
             ctx.fillStyle = i % 3 === 0 ? '#44403c' : '#57534e'; 
             if (isEnraged) ctx.fillStyle = i % 3 === 0 ? '#7f1d1d' : '#991b1b'; 
             if (i === 8 || i === 9) ctx.fillStyle = '#f59e0b'; 
             ctx.fillRect(x - w/2, ly - h/2, w, h);
             if (i === 6) { ctx.fillStyle = isEnraged ? '#450a0a' : '#292524'; ctx.fillRect(x - w - 20, ly, 40, 40); ctx.fillRect(x + w - 20, ly, 40, 40); }
          }
          else if (type === 'BOSS_LICH') {
              w = 40; ctx.fillStyle = '#3b0764'; 
              if (i === 12) { w = 20; ctx.fillStyle = '#f0abfc'; } 
              if (i > 8 && i < 12) { w = 30; ctx.fillStyle = '#581c87'; }
              ctx.fillRect(x - w/2, ly - w/2, w, w);
              if (i < 10) { ctx.fillStyle = '#a16207'; ctx.fillRect(x + 30, ly, 5, 20); } 
              else if (i === 13) { ctx.fillStyle = '#10b981'; ctx.shadowColor = '#10b981'; ctx.shadowBlur = 10; ctx.fillRect(x + 28, ly, 10, 10); ctx.shadowBlur = 0; }
          }
          else if (type === 'SLIME') {
             w = Math.max(1, (24 - i*3) * stretch); // SAFETY: Ensure w > 0
             let c = entity.variant === 1 ? '#4ade80' : (entity.variant === 2 ? '#166534' : '#22c55e'); ctx.fillStyle = c; ctx.globalAlpha = 0.8; ctx.beginPath(); ctx.arc(x, ly, w/2, 0, Math.PI*2); ctx.fill(); ctx.globalAlpha = 1.0;
          } 
          else if (type === 'SORCERER') {
              w = 20; ctx.fillStyle = '#6b21a8'; if (i === 3) w = 24; if (i > 4) { ctx.fillStyle = '#d8b4fe'; w = 16; } ctx.fillRect(x - w/2, ly - w/2, w, w);
          }
          else if (type === 'DEMON') { 
             w = 28; ctx.fillStyle = '#7f1d1d'; ctx.fillRect(x - w/2, ly - w/2, w, w); if (i===3 && entity.defense > 0) { ctx.fillStyle = '#475569'; ctx.fillRect(x - w/2 - 2, ly - 5, w + 4, 10); } if (i >= 5) { ctx.fillStyle = '#000'; ctx.fillRect(x - w/2, ly - 8, 4, 12); ctx.fillRect(x + w/2 - 4, ly - 8, 4, 12); }
          }
          else if (type === 'GOBLIN') { 
             w = 22; let c = '#3f6212'; if (i < 2) c = '#78350f'; if (entity.variant === 1) c = '#854d0e'; ctx.fillStyle = c; ctx.fillRect(x - w/2, ly - w/2, w, w);
          }
      }
  };

  const draw = (dt: number) => {
    // ... (Mantendo draw) ...
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    if(canvas.width !== CANVAS_WIDTH || canvas.height !== CANVAS_HEIGHT) {
        canvas.width = CANVAS_WIDTH;
        canvas.height = CANVAS_HEIGHT;
    }

    // Clear Background
    ctx.fillStyle = COLORS.background;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    const shakeX = (Math.random() - 0.5) * shakeRef.current;
    const shakeY = (Math.random() - 0.5) * shakeRef.current;

    ctx.save();
    ctx.translate(CANVAS_WIDTH/2, CANVAS_HEIGHT/2);
    ctx.translate(Math.floor(cameraRef.current.x + shakeX), Math.floor(cameraRef.current.y + shakeY));

    // --- TERRAIN ---
    const tileSize = 100;
    const pX = playerRef.current.x;
    const pY = playerRef.current.y;
    const range = 14; 

    const px = Math.floor(pX / tileSize);
    const py = Math.floor(pY / tileSize);

    for (let i = px - range; i <= px + range; i++) {
        for (let j = py - range; j <= py + range; j++) {
            const wx = i * tileSize;
            const wy = j * tileSize;

            // Circular render distance
            if (Math.hypot(wx - pX, wy - pY) > 1400) continue;

            // Screen Culling
            const iso = toIso(wx, wy, 0);
            const screenX = iso.x + cameraRef.current.x + CANVAS_WIDTH/2;
            const screenY = iso.y + cameraRef.current.y + CANVAS_HEIGHT/2;
            if (screenX < -200 || screenX > CANVAS_WIDTH + 200 || screenY < -200 || screenY > CANVAS_HEIGHT + 200) continue;

            let color = COLORS.grass;
            let topColor = COLORS.grassHighlight;
            let h = 0;

            if (gameStateRef.current === GameState.ISLAND) {
                 // Village Path
                 const distToCenter = Math.hypot(wx, wy + 200);
                 if (distToCenter < 1200) { // Island Base
                    color = COLORS.grass;
                    topColor = COLORS.grassHighlight;
                    if (Math.abs(wx) < 100 || Math.abs(wy + 200) < 100) { // Stone Paths
                        color = COLORS.stone;
                        topColor = COLORS.stoneHighlight;
                    }
                 } else { // Ocean
                     color = COLORS.water;
                     topColor = COLORS.waterHighlight;
                     h = -20;
                 }
                 // Portal Area
                 if (Math.hypot(wx - (-400), wy - (-400)) < 180) { 
                     color = '#312e81'; topColor = '#4338ca'; h = 5; 
                 }
            } else {
                 // TOWER: Dungeon Floor with Grass cracks
                 const noise = Math.sin(i * 12.9898 + j * 78.233) * 43758.5453;
                 const isGrassCrack = (noise - Math.floor(noise)) > 0.8;

                 color = COLORS.dungeonFloor; 
                 topColor = isGrassCrack ? COLORS.dungeonGrass : COLORS.dungeonFloorHighlight;

                 // Void edges
                 if (Math.abs(wx) > 900 || Math.abs(wy) > 900) { h = -100; color = '#000'; topColor = '#000'; }
            }

            ctx.beginPath();
            ctx.moveTo(iso.x, iso.y - h);
            ctx.lineTo(iso.x + tileSize, iso.y - h + tileSize/2);
            ctx.lineTo(iso.x, iso.y - h + tileSize);
            ctx.lineTo(iso.x - tileSize, iso.y - h + tileSize/2);
            ctx.fillStyle = topColor;
            ctx.fill();

            if (h > -50 && h !== 0) {
                 ctx.fillStyle = adjustColor(color, -20);
                 ctx.beginPath();
                 ctx.moveTo(iso.x + tileSize, iso.y - h + tileSize/2);
                 ctx.lineTo(iso.x + tileSize, iso.y + tileSize/2);
                 ctx.lineTo(iso.x, iso.y + tileSize);
                 ctx.lineTo(iso.x, iso.y - h + tileSize);
                 ctx.fill();

                 ctx.fillStyle = adjustColor(color, -10);
                 ctx.beginPath();
                 ctx.moveTo(iso.x - tileSize, iso.y - h + tileSize/2);
                 ctx.lineTo(iso.x - tileSize, iso.y + tileSize/2);
                 ctx.lineTo(iso.x, iso.y + tileSize);
                 ctx.lineTo(iso.x, iso.y - h + tileSize);
                 ctx.fill();
            }
        }
    }

    // --- SORTING ---
    const renderList: any[] = [];
    renderList.push({ type: 'PLAYER', obj: playerRef.current, y: toIso(playerRef.current.x, playerRef.current.y).y });

    const cullingDist = 1600; 
    for(const e of enemiesRef.current) {
        if (Math.abs(e.x - pX) < cullingDist && Math.abs(e.y - pY) < cullingDist) {
            renderList.push({ type: e.type, obj: e, y: toIso(e.x, e.y).y });
        }
    }
    for(const p of particlesRef.current) {
         renderList.push({ type: p.type || 'PARTICLE', obj: p, y: toIso(p.x, p.y).y });
    }
    if (gameStateRef.current === GameState.ISLAND) {
        staticObjectsRef.current.forEach(obj => { 
             // Simple culling for static objects
             if (Math.abs(obj.x - pX) < cullingDist && Math.abs(obj.y - pY) < cullingDist) {
                renderList.push({ type: obj.type, obj, y: toIso(obj.x, obj.y).y }); 
             }
        });
    }
    renderList.sort((a, b) => a.y - b.y);

    // --- DRAW ENTITIES ---
    for (const item of renderList) {
        if (item.type === 'PARTICLE' || item.type === 'RAIN' || item.type === 'BLOOD' || item.type === 'SPARK' || item.type === 'POISON' || item.type === 'TELEPORT') {
             const { x, y } = toIso(item.obj.x, item.obj.y, item.obj.z);
             ctx.fillStyle = item.obj.color;
             if (item.type === 'RAIN') {
                 ctx.strokeStyle = item.obj.color; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x-2, y+15); ctx.stroke();
             } else if (item.type === 'BLOOD') {
                 ctx.globalAlpha = 0.6; ctx.beginPath(); ctx.ellipse(x, y, item.obj.size*2, item.obj.size, 0, 0, Math.PI*2); ctx.fill(); ctx.globalAlpha = 1.0;
             } else {
                 ctx.shadowBlur = 5; ctx.shadowColor = item.obj.color; ctx.beginPath(); ctx.arc(x, y, item.obj.size, 0, Math.PI*2); ctx.fill(); ctx.shadowBlur = 0;
             }
        } else {
             drawIsoSprite(ctx, item.obj, item.type);

             // HP Bars Minimalistas
             if (item.obj.hp < item.obj.maxHp && item.obj.hp > 0 && item.type !== 'PARTICLE') {
                 const isBoss = item.type.includes('BOSS');
                 const offsetZ = isBoss ? 150 : (item.type === 'BAT' ? 80 : 40);
                 const { x, y } = toIso(item.obj.x, item.obj.y, item.obj.z + offsetZ);
                 const w = isBoss ? 120 : 20;
                 const h = isBoss ? 6 : 3;

                 ctx.fillStyle = '#0f172a'; ctx.fillRect(x - w/2, y - 5, w, h);
                 ctx.fillStyle = '#b91c1c'; ctx.fillRect(x - w/2, y - 5, w * (item.obj.hp/item.obj.maxHp), h); 
             }
        }
    }

    // --- DRAW PROJECTILES ---
    for(const p of projectilesRef.current) {
        const { x, y } = toIso(p.x, p.y, p.z);
        ctx.fillStyle = p.color;
        ctx.shadowBlur = 10; ctx.shadowColor = p.color;

        if (p.type === 'SWORD_SLASH') {
             ctx.strokeStyle = '#fff'; ctx.lineWidth = 2; ctx.beginPath(); ctx.ellipse(x, y, p.radius, p.radius*0.5, 0, 0, Math.PI*2); ctx.stroke();
        } else if (p.type === 'FIRE_ZONE') {
             ctx.fillStyle = 'rgba(127, 29, 29, 0.3)'; ctx.beginPath(); ctx.ellipse(x, y, p.radius, p.radius*0.5, 0, 0, Math.PI*2); ctx.fill();
        } else if (p.type === 'LICH_DRAIN_ZONE') {
             ctx.fillStyle = 'rgba(16, 185, 129, 0.2)'; 
             ctx.beginPath(); ctx.ellipse(x, y, p.radius, p.radius*0.5, 0, 0, Math.PI*2); ctx.fill();
             ctx.strokeStyle = '#10b981'; ctx.lineWidth = 1; ctx.stroke();
             // Bubbles
             if (Math.random() > 0.8) {
                  ctx.fillStyle = '#10b981';
                  const rx = (Math.random()-0.5) * p.radius;
                  const ry = (Math.random()-0.5) * p.radius * 0.5;
                  ctx.beginPath(); ctx.arc(x+rx, y+ry, 2, 0, Math.PI*2); ctx.fill();
             }
        } else if (p.type === 'ENEMY_BOLT' || p.type === 'GOLEM_SHOCKWAVE' || p.type === 'BOSS_ROCK' || p.type === 'LICH_NOVA' || p.type === 'POISON_SPIT') {
             const size = p.type === 'BOSS_ROCK' ? 12 : (p.type === 'GOLEM_SHOCKWAVE' ? 8 : 6);
             ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
             ctx.strokeStyle = '#fff'; ctx.stroke();
        } else if (p.type === 'BOSS_SMASH') {
            ctx.fillStyle = 'rgba(255,255,255,0.8)';
            ctx.beginPath(); ctx.ellipse(x, y, p.radius, p.radius*0.5, 0, 0, Math.PI*2); ctx.fill();
        } else {
             ctx.beginPath(); ctx.arc(x, y, 4, 0, Math.PI*2); ctx.fill();
             // Trail
             ctx.fillStyle = 'rgba(255,255,255,0.4)';
             ctx.beginPath(); ctx.arc(x - p.vx*0.02, y - p.vy*0.02, 2, 0, Math.PI*2); ctx.fill();
        }
        ctx.shadowBlur = 0;
    }

    // --- ATMOSPHERE LAYERS ---
    const cx = CANVAS_WIDTH / 2;
    const cy = CANVAS_HEIGHT / 2;

    // 1. Fog (Procedural Cloud Overlay)
    if (gameStateRef.current === GameState.TOWER) {
        ctx.save();
        ctx.globalAlpha = 0.15;
        // Simulating cloud shadows
        const t = performance.now() / 5000;
        const offset1 = Math.sin(t) * 100;
        const gradientFog = ctx.createRadialGradient(cx + offset1, cy, 100, cx, cy, 1200);
        gradientFog.addColorStop(0, 'rgba(255,255,255,0)');
        gradientFog.addColorStop(0.5, 'rgba(255,255,255,0.1)');
        gradientFog.addColorStop(1, 'rgba(255,255,255,0.3)');
        ctx.fillStyle = gradientFog;
        ctx.fillRect(-1000, -1000, 4000, 4000);
        ctx.restore();
    }

    // 2. Vignette (Dark edges)
    const vignette = ctx.createRadialGradient(cx, cy, 300, cx, cy, 1000);
    vignette.addColorStop(0, 'rgba(0,0,0,0)'); 
    vignette.addColorStop(1, 'rgba(0,0,0,0.8)'); 
    ctx.fillStyle = vignette;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // 3. Rain Overlay (Blue Tint)
    if (isRainingRef.current) {
        ctx.fillStyle = `rgba(30, 58, 138, ${rainIntensityRef.current * 0.15})`;
        ctx.fillRect(0,0,CANVAS_WIDTH, CANVAS_HEIGHT);
    }

    // 4. Slow (Red Tint)
    if (playerRef.current.slowTimer > 0) {
        ctx.fillStyle = 'rgba(69, 10, 10, 0.2)';
        ctx.fillRect(0,0,CANVAS_WIDTH, CANVAS_HEIGHT);
    }

    // --- AIM ASSIST & RETICLE ---
    const aimIso = toIso(mouseWorldRef.current.x, mouseWorldRef.current.y, 0);

    // Check if aiming at enemy
    let isAimingAtEnemy = false;
    for(const e of enemiesRef.current) {
        const dist = Math.hypot(e.x - mouseWorldRef.current.x, e.y - mouseWorldRef.current.y);
        if (dist < 40) { isAimingAtEnemy = true; break; }
    }

    ctx.restore(); // Restore camera transform

    // Draw Aim in World Space (Moved to UI Layer basically)
    // --- SCREEN SPACE RETICLE DRAWING (UI LAYER) ---
    // Calculates exact screen coordinates to decouple from camera shake/matrix
    const screenCx = CANVAS_WIDTH / 2;
    const screenCy = CANVAS_HEIGHT / 2;

    // Player Screen Pos (includes shake for line origin)
    const pIso = toIso(playerRef.current.x, playerRef.current.y);
    const playerScreenX = screenCx + cameraRef.current.x + shakeX + pIso.x;
    const playerScreenY = screenCy + cameraRef.current.y + shakeY + pIso.y - (playerRef.current.z || 0);

    // Mouse Screen Pos (mouseScreenRef is relative to center)
    const mouseScreenX = screenCx + mouseScreenRef.current.x;
    const mouseScreenY = screenCy + mouseScreenRef.current.y;

    ctx.save();

    // Dashed Line from Player to Cursor
    ctx.strokeStyle = isAimingAtEnemy ? 'rgba(239, 68, 68, 0.5)' : 'rgba(255, 255, 255, 0.2)'; 
    ctx.setLineDash([4, 4]); 
    ctx.lineWidth = 2;
    ctx.beginPath(); 
    ctx.moveTo(playerScreenX, playerScreenY - 20); // Start from chest height
    ctx.lineTo(mouseScreenX, mouseScreenY); 
    ctx.stroke();
    ctx.setLineDash([]);

    // Custom Reticle
    ctx.translate(mouseScreenX, mouseScreenY);
    ctx.rotate(reticleAngleRef.current); // Use smoothed/deadzoned angle
    ctx.strokeStyle = isAimingAtEnemy ? '#ef4444' : '#fff';
    ctx.lineWidth = 2;
    const rSize = 12;

    // Directional Arrow / Crosshair
    ctx.beginPath();
    ctx.moveTo(rSize, 0); ctx.lineTo(rSize/2, -rSize/2);
    ctx.moveTo(rSize, 0); ctx.lineTo(rSize/2, rSize/2);
    ctx.moveTo(-rSize, -rSize/2); ctx.lineTo(-rSize/2, 0); ctx.lineTo(-rSize, rSize/2);
    ctx.stroke();

    // Center Dot
    ctx.fillStyle = isAimingAtEnemy ? '#ef4444' : '#fff';
    ctx.beginPath(); ctx.arc(0, 0, 2, 0, Math.PI*2); ctx.fill();

    ctx.restore();


    // --- DAMAGE NUMBERS (UI Space) ---
    // Improved legibility and satisfaction
    for(const dn of damageNumbersRef.current) {
        const pos = toIso(dn.x, dn.y, dn.z);
        const sx = pos.x + cameraRef.current.x + CANVAS_WIDTH/2;
        const sy = pos.y + cameraRef.current.y + CANVAS_HEIGHT/2;

        ctx.fillStyle = dn.isPlayerDamage ? '#ef4444' : (dn.isCrit ? '#fbbf24' : 'white');
        ctx.strokeStyle = '#020617'; 
        ctx.lineWidth = 4; // Borda mais grossa para leitura
        ctx.lineJoin = 'round';

        const offset = (1 - dn.life) * 80; // Sobem mais
        const alpha = Math.min(1, dn.life * 3); // Fade out no final

        ctx.save();
        ctx.globalAlpha = alpha;
        ctx.translate(sx, sy - offset);

        // Crit Pop Animation
        if (dn.isCrit) {
             const scale = 1.5 + Math.sin((1-dn.life)*10)*0.2;
             ctx.scale(scale, scale);
             ctx.font = '900 28px "Cinzel", serif'; // Fonte maior para critico
        } else {
             ctx.font = 'bold 20px "Cinzel", serif';
        }

        const text = Math.floor(dn.value).toString();
        ctx.strokeText(text, 0, 0);
        ctx.fillText(text, 0, 0);

        if (dn.isCrit) {
             // Brilho extra no crítico
             ctx.shadowColor = '#fbbf24';
             ctx.shadowBlur = 10;
             ctx.fillText(text, 0, 0);
             ctx.shadowBlur = 0;
        }

        ctx.restore();
    }
  };

  const formatTime = (s: number) => `${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;

  return (
    <div className="relative w-full h-full bg-[#020617] cursor-none select-none overflow-hidden font-mono">
      <canvas ref={canvasRef} className="block w-full h-full cursor-none" />

      {/* --- HUD CENTRALIZADA --- */}
      <div className="absolute inset-x-0 bottom-6 flex flex-col items-center pointer-events-none z-10">

          {hudData.bossHp > 0 && (
              <div className="mb-10 w-[700px] pointer-events-none animate-in fade-in slide-in-from-top-10 duration-700">
                  <div className="flex justify-between items-end text-red-500 font-bold mb-2 px-4 uppercase tracking-widest font-serif drop-shadow-md">
                      <span className="text-2xl">Terror da Torre</span>
                      <span className="text-sm opacity-80">{Math.ceil(hudData.bossHp)}/{Math.ceil(hudData.bossMaxHp)}</span>
                  </div>
                  <div className="relative h-6 w-full bg-slate-900 border-2 border-slate-700 rounded-sm shadow-[0_0_30px_rgba(220,38,38,0.3)] overflow-hidden">
                      <div className="absolute inset-0 bg-red-950/50"></div>
                      <div className="h-full bg-gradient-to-r from-red-900 via-red-600 to-red-500 transition-all duration-200" style={{width: `${(hudData.bossHp/hudData.bossMaxHp)*100}%`}}></div>
                      {/* Grid overlay pattern */}
                      <div className="absolute inset-0 bg-[url('data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAQAAAAECAYAAACp8Z5+AAAAIklEQVQIW2NkQAKrVq36zwjjgzj//v37zwjjgzhhYWGMYAIAI8YOAj+51n4AAAAASUVORK5CYII=')] opacity-30"></div>
                  </div>
              </div>
          )}

          <div className="flex items-end gap-6 pb-2">
              {/* HP & Info */}
              <div className="bg-slate-900/95 border border-slate-700 rounded-2xl p-5 backdrop-blur-md shadow-2xl w-72 transform transition-transform">
                   <div className="flex items-center justify-between gap-2 text-white font-bold text-2xl mb-3 font-serif">
                       <span className="flex items-center gap-2 text-red-400"><Heart fill="currentColor" /> {Math.ceil(hudData.hp)}</span>
                       <span className="text-sm font-mono text-slate-500">LVL {hudData.level}</span>
                   </div>
                   <div className="relative h-4 bg-slate-950 rounded-full overflow-hidden border border-slate-800 mb-2 shadow-inner">
                       <div className="h-full bg-gradient-to-r from-red-800 to-red-500 transition-all duration-300" style={{width: `${(hudData.hp/hudData.maxHp)*100}%`}}></div>
                   </div>
                   <div className="flex justify-between text-[10px] text-slate-400 font-mono tracking-wide uppercase">
                       <span>XP Progresso</span>
                       <span className="text-amber-500">{Math.floor(hudData.xp)} / {Math.floor(hudData.xpNext)}</span>
                   </div>
                   <div className="mt-1 h-1 w-full bg-slate-800 rounded-full overflow-hidden">
                       <div className="h-full bg-amber-500 shadow-[0_0_10px_#f59e0b]" style={{width: `${(hudData.xp/hudData.xpNext)*100}%`}}></div>
                   </div>
              </div>

              {/* Skills Bar */}
              <div className="flex gap-3 p-4 bg-slate-900/95 border border-slate-700 rounded-2xl backdrop-blur-md shadow-2xl">
                  {/* Basic Attack */}
                  <div className="w-20 h-20 bg-slate-800 rounded-xl border border-slate-600 flex flex-col items-center justify-center grayscale opacity-60">
                      <Sword size={32} />
                  </div>

                  {/* Skill 1 (Q) */}
                  <div className={`relative w-20 h-20 rounded-xl border-2 flex flex-col items-center justify-center overflow-hidden transition-all duration-200
                      ${hudData.skill1Cd <= 0 
                        ? 'bg-blue-950/80 border-blue-400 shadow-[0_0_15px_rgba(59,130,246,0.3)]' 
                        : 'bg-slate-800 border-slate-700 grayscale'}`}>
                      <Crosshair size={32} className={hudData.skill1Cd <= 0 ? "text-blue-400" : "text-slate-500"} />
                      <span className="absolute bottom-1 right-2 text-[10px] font-bold text-slate-400">Q</span>

                      {hudData.skill1Cd > 0 && (
                          <div className="absolute inset-0 bg-black/70 flex items-center justify-center font-bold text-white text-2xl font-mono animate-in fade-in">
                              {Math.ceil(hudData.skill1Cd)}
                          </div>
                      )}
                  </div>

                  {/* Dash (E) */}
                  <div className={`relative w-20 h-20 rounded-xl border-2 flex flex-col items-center justify-center overflow-hidden transition-all duration-200
                      ${hudData.dashCharges > 0 
                        ? 'bg-emerald-950/80 border-emerald-400 shadow-[0_0_15px_rgba(52,211,153,0.3)]' 
                        : 'bg-slate-800 border-slate-700 grayscale'}`}>
                      <Wind size={32} className={hudData.dashCharges > 0 ? "text-emerald-400" : "text-slate-500"} />
                      <span className="absolute bottom-1 right-2 text-[10px] font-bold text-slate-400">E</span>

                      {/* Charges Counter - Improved Visibility */}
                      <div className="absolute top-2 left-0 right-0 flex justify-center gap-1">
                          {Array.from({length: Math.max(hudData.dashMax, 2)}).map((_, i) => (
                             <div key={i} className={`w-2 h-2 rounded-full shadow-sm transition-colors duration-300
                               ${i < hudData.dashCharges ? 'bg-emerald-400 shadow-[0_0_8px_#34d399]' : 'bg-slate-700 border border-slate-600'}`}>
                             </div>
                          ))}
                      </div>

                      {hudData.dashCd > 0 && hudData.dashCharges < hudData.dashMax && (
                          <div className="absolute inset-0 bg-black/70 flex items-center justify-center font-bold text-white text-2xl font-mono">
                              {Math.ceil(hudData.dashCd)}
                          </div>
                      )}
                  </div>

                  {/* Item Ativo (R) */}
                  <div className={`relative w-20 h-20 rounded-xl border-2 flex flex-col items-center justify-center overflow-hidden transition-all duration-200
                      ${hudData.activeItem ? 'bg-amber-950/60 border-amber-500' : 'bg-slate-900 border-slate-800 opacity-40 border-dashed'}`}>
                      {hudData.activeItem ? (
                          <>
                            <span className="text-3xl filter drop-shadow-lg">{hudData.activeItem.icon}</span>
                            <span className="absolute bottom-1 right-2 text-[10px] font-bold text-amber-200">R</span>
                          </>
                      ) : <Box size={24} className="text-slate-600" />}

                      {hudData.itemCd > 0 && (
                          <div className="absolute inset-0 bg-black/70 flex items-center justify-center font-bold text-white text-2xl font-mono">
                              {Math.ceil(hudData.itemCd)}
                          </div>
                      )}
                  </div>
              </div>

              {hudData.state === GameState.TOWER && (
                  <div className="bg-slate-900/95 border border-slate-700 rounded-2xl p-5 backdrop-blur-md shadow-2xl w-40 text-center flex flex-col justify-center h-[124px]">
                      <div className="text-3xl font-mono font-bold text-white mb-2 tracking-widest">{formatTime(hudData.time)}</div>
                      <div className="text-xs text-slate-400 flex items-center justify-center gap-2 font-serif uppercase tracking-wider border-t border-slate-800 pt-2">
                          <Skull size={14} className="text-red-500" /> WAVE {hudData.wave}
                      </div>
                      {isRainingRef.current && (
                          <div className="text-[10px] text-blue-300 animate-pulse mt-1 font-serif font-bold">TEMPESTADE</div>
                      )}
                  </div>
              )}
          </div>
      </div>

      {hudData.state === GameState.ISLAND && (
          <div className="absolute top-20 w-full text-center pointer-events-none animate-bounce">
              <span className="bg-slate-900/90 px-8 py-4 rounded-full text-slate-100 border border-blue-500/50 shadow-[0_0_20px_rgba(59,130,246,0.4)] font-serif tracking-widest text-lg">
                  Siga para o Portal Azul
              </span>
          </div>
      )}

      {showUpgrade && (
        <UpgradeModal 
          options={upgradeOptions} 
          memoryOption={lastUpgrade} 
          onSelect={applyUpgrade} 
        />
      )}
    </div>
  );
};

export enum GameState {
  CHAR_SELECT = 'CHAR_SELECT',
  ISLAND = 'ISLAND',
  TOWER = 'TOWER',
  PAUSED = 'PAUSED',
  GAME_OVER = 'GAME_OVER',
  VICTORY = 'VICTORY'
}

export enum Archetype {
  WARRIOR = 'WARRIOR',
  ARCHER = 'ARCHER',
  MAGE = 'MAGE'
}

export interface Stats {
  maxHp: number;
  hp: number;
  damage: number;
  speed: number;
  defense: number;
  cooldownReduction: number;
  pickupRange: number;
  areaSize: number;
  // Novos Atributos
  armorPenetration: number;
  lifeSteal: number; // Porcentagem curada ao matar (0.0 a 1.0)
  dashChargesMax: number;
  attackSpeed: number; // Multiplicador de velocidade de ataque (ex: 1.0, 1.5)
  damageReduction: number; // Porcentagem de redução (ex: 0.1 = 10%)
}

export interface Item {
  id: string;
  name: string;
  icon: string;
  cooldown: number;
  duration?: number;
  effect: (player: Player, enemies: Enemy[]) => void;
  description: string;
}

export interface AutoItem {
  id: string;
  name: string;
  icon: string;
  cooldown: number;
  timer: number;
  effect: (player: Player, enemies: Enemy[]) => Projectile | null; // Retorna projétil para adicionar ou null
  description: string;
}

export interface Player {
  x: number;
  y: number;
  z: number;
  archetype: Archetype;
  stats: Stats;
  level: number;
  xp: number;
  xpToNextLevel: number;

  // Cooldowns
  weaponTimer: number;
  skill1Timer: number;
  skill1MaxCooldown: number;

  // Dash System
  dashTimer: number;      // Tempo para recarregar a próxima carga
  dashMaxCooldown: number; // Tempo base de recarga
  dashCharges: number;    // Cargas atuais

  // Item Slot (Manual - R)
  activeItem: Item | null;
  itemTimer: number;
  itemMaxCooldown: number;

  // Auto Skills Slots (Automático)
  autoItems: AutoItem[];

  // Status Effects
  slowTimer: number; // Tempo que o jogador fica lento ao tomar dano

  facing: number;
  isMoving: boolean;
  color: string;

  // Animation
  animFrame: number;
}

export type EnemyState = 'CHASING' | 'WINDUP' | 'ATTACKING' | 'RECOVERING' | 'CHANNELING' | 'FLEEING' | 'SWOOPING';

export interface Enemy {
  id: string;
  x: number;
  y: number;
  z: number;
  type: 'SLIME' | 'GOBLIN' | 'SORCERER' | 'DEMON' | 'BOSS_GOLEM' | 'BOSS_LICH' | 'SNAKE' | 'BAT';
  isBoss: boolean;
  hp: number;
  maxHp: number;
  defense: number; // Nova defesa
  speed: number;
  damage: number;
  radius: number;
  hitboxRadius: number;
