  };

  const spawnBoss = (type: EnemyType) => {
      const dist = 600; const angle = Math.random() * Math.PI * 2; const waveFactor = 1 + waveRef.current * 0.5;
      let hp = 5000 * waveFactor; let defense = 20 + waveRef.current * 2; let damage = 50 * waveFactor; let speed = 50; let radius = 80;

      enemiesRef.current.push({
          id: 'boss', x: playerRef.current.x + Math.cos(angle)*dist, y: playerRef.current.y + Math.sin(angle)*dist, z: 0,
          type, isBoss: true, hp, maxHp: hp, defense, speed, damage, radius, hitboxRadius: radius * 0.8, frame: 0, vx: 0, vy: 0, hitFlash: 0,
          state: 'CHASING', stateTimer: 0, attackRange: 200, windupTime: 1.5, recoverTime: 1.0, variant: 0, specialTimer: 5 
      });
      shakeRef.current = 30; 
  };

  const updateEnemies = (dt: number, stats: any) => {
      const p = playerRef.current;
      enemiesRef.current = enemiesRef.current.filter((e, idx) => {
          if (e.hitFlash > 0) e.hitFlash -= dt;
          if (e.frozenTimer && e.frozenTimer > 0) { e.frozenTimer -= dt; return true; }
          e.frame += dt; 

          const isFlying = e.type.includes('BAT') || e.type.includes('SHADOW') || e.type === 'ANGEL';
          const isTrap = e.type.includes('TRAP');

          if (!isTrap && !isFlying) {
              let sepX = 0, sepY = 0; const checkLimit = Math.min(idx + 3, enemiesRef.current.length);
              for (let i = Math.max(0, idx - 3); i < checkLimit; i++) {
                  if (i === idx) continue;
                  const other = enemiesRef.current[i]; if (other.type.includes('BAT')) continue; 
                  const distSq = (e.x - other.x)**2 + (e.y - other.y)**2; const minDist = (e.radius + other.radius) * 0.8;
                  if (distSq < minDist**2 && distSq > 0.1) {
                      const pushDist = Math.sqrt(distSq); const pushForce = (minDist - pushDist) / pushDist;
                      sepX += (e.x - other.x) * pushForce; sepY += (e.y - other.y) * pushForce;
                  }
              }
              e.vx += sepX * 200 * dt; e.vy += sepY * 200 * dt;
          }
          if (Math.abs(e.vx) > 1 || Math.abs(e.vy) > 1) { e.x += e.vx * dt; e.y += e.vy * dt; e.vx *= 0.9; e.vy *= 0.9; }

          const dx = p.x - e.x; const dy = p.y - e.y; const dist = Math.hypot(dx, dy);
          if (e.isBoss && e.specialTimer !== undefined) { e.specialTimer -= dt; }

          if (e.state === 'CHASING' && !isTrap) {
              if (dist > 10) {
                  const mx = dx / dist; const my = dy / dist;
                  e.x += mx * e.speed * dt; e.y += my * e.speed * dt;
              }
              if (dist < e.attackRange) { e.state = 'WINDUP'; e.stateTimer = e.windupTime; }
          }
          else if (e.state === 'WINDUP') {
              e.stateTimer -= dt;
              if (e.stateTimer <= 0) {
                  e.state = 'ATTACKING';
                  if (e.isBoss) {
                      projectilesRef.current.push({
                          id: Math.random().toString(), x: e.x, y: e.y, z: 0, vx: 0, vy: 0,
                          damage: e.damage * 1.5, duration: 0.5, radius: 150, type: 'BOSS_SMASH', color: '#ef4444', pierce: 999, isEnemy: true
                      });
                      shakeRef.current = 20;
                  } else {
                      if (dist < e.attackRange + 50) {
                          takeDamage(p, e.damage);
                          if (e.type.includes('BAT')) { p.stunTimer = 0.5; } 
                      }
                  }
                  e.state = 'RECOVERING'; e.stateTimer = e.recoverTime;
              }
          }
          else if (e.state === 'RECOVERING') {
              e.stateTimer -= dt; if (e.stateTimer <= 0) e.state = 'CHASING';
          }

          for (const proj of projectilesRef.current) {
               if (proj.duration <= 0 || proj.isEnemy) continue;
               if (proj.delayedDamage && proj.duration > 0.1) continue;

               const pDist = Math.hypot(proj.x - e.x, proj.y - e.y);
               if(pDist < proj.radius + e.hitboxRadius) {
                   if (proj.type === 'TIME_PRISON') { e.frozenTimer = 3.0; continue; }
                   if (proj.knockbackForce && !e.isBoss) {
                        const kAngle = Math.atan2(e.y - proj.y, e.x - proj.x);
                        e.vx += Math.cos(kAngle) * proj.knockbackForce; e.vy += Math.sin(kAngle) * proj.knockbackForce;
                   }
                   const isAoe = ['SWORD_SLASH','FIRE_ZONE','OCEAN_WAVE','GODDESS_SEAL'].includes(proj.type);
                   let dmg = isAoe ? proj.damage * 5 * dt : proj.damage;
                   const isCrit = Math.random() < stats.critChance; if (isCrit) dmg *= stats.critDamage;
                   if (stats.executionerThreshold > 0 && (e.hp / e.maxHp) < 0.3) dmg *= (1 + stats.executionerThreshold);

                   const mitigation = 100 / (100 + Math.max(0, e.defense - stats.armorPenetration));
                   const finalDmg = dmg * mitigation;

                   e.hitFlash = 0.15; e.hp -= finalDmg;

                   if (!isAoe) {
                        if (['ARROW', 'MAGIC_ORB'].includes(proj.type)) {
                           proj.pierce--; if (proj.pierce < 0) proj.duration = 0;
                        }
                   }

                   if (!isAoe || Math.random() > 0.8) {
                       createDamageNumber(e.x, e.y, e.z + 40, finalDmg, isCrit);
                       createParticle(e.x, e.y, e.z + 20, proj.color, 2, 'IMPACT');
                   }

                   if(e.hp <= 0 && !e.isBoss) {
                       createParticle(e.x, e.y, e.z, '#ef4444', 8, 'BLOOD'); 
                       if (stats.lifeSteal > 0) { const heal = stats.maxHp * stats.lifeSteal; p.stats.hp = Math.min(stats.maxHp, p.stats.hp + heal); }
                       if (!isAoe && proj.pierce < 0) break; break; 
                   }
               }
          }

          if(e.hp <= 0) {
              p.xp += e.isBoss ? 2000 : 25;
              if(p.xp >= p.xpToNextLevel) {
                  p.level++; p.xp -= p.xpToNextLevel; p.xpToNextLevel *= 1.2;
                  p.stats.damage *= 1.1; p.stats.maxHp *= 1.1; p.stats.hp = p.stats.maxHp;
                  createDamageNumber(p.x, p.y, p.z+60, 0, true); 
              }
              return false;
          }
          return true;
      });
  };

  const takeDamage = (p: Player, amount: number) => {
      const reducedByPercent = amount * (1 - Math.min(0.8, p.stats.damageReduction)); 
      const finalDmg = Math.max(1, reducedByPercent - p.stats.defense);
      p.stats.hp -= finalDmg; shakeRef.current = 10; p.slowTimer = 0.5; p.lastHitTime = 0; 
