  const createDamageNumber = (x: number, y: number, z: number, val: number, crit: boolean, isPlayerDamage = false) => {
      if (val < 1) return;
      damageNumbersRef.current.push({ id: Math.random().toString(), x: x + (Math.random()-0.5)*20, y, z, value: val, life: 0.8, isCrit: crit, isPlayerDamage });
  };

  const useMainAttack = (stats: any) => {
     const p = playerRef.current; const angle = p.facing;
     if (p.archetype === Archetype.WARRIOR) {
