         p.weaponTimer = (0.6 / stats.attackSpeed) * (1 - stats.cooldownReduction);
     } else {
         const vx = Math.cos(angle) * 800; const vy = Math.sin(angle) * 800;
         projectilesRef.current.push({ id: Math.random().toString(), x: p.x, y: p.y, z: 30, vx, vy, damage: stats.damage, duration: 1.5, radius: 15, type: p.archetype === Archetype.ARCHER ? 'ARROW' : 'MAGIC_ORB', color: p.color, pierce: p.archetype === Archetype.MAGE ? 2 : 0 });
         p.weaponTimer = (0.4 / stats.attackSpeed) * (1 - stats.cooldownReduction);
     }
  };
  const useSkill1 = (stats: any) => {
      const p = playerRef.current; createParticle(p.x, p.y, 20, '#fff', 10); shakeRef.current = 5; 
