          projectilesRef.current.push({ id: Math.random().toString(), x: p.x, y: p.y, z: 20, vx: 0, vy: 0, damage: stats.damage * 2.5, duration: 0.5, radius: 160 * stats.areaSize, type: 'SWORD_SLASH', color: '#ef4444', pierce: 999 });
      } else {
          projectilesRef.current.push({ id: Math.random().toString(), x: mouseWorldRef.current.x, y: mouseWorldRef.current.y, z: 0, vx: 0, vy: 0, damage: stats.damage * 3, duration: 1.2, radius: 120 * stats.areaSize, type: 'FIRE_ZONE', color: p.archetype === Archetype.MAGE ? '#9333ea' : '#ef4444', pierce: 999 });
      }
  };
  const useDash = () => {
      const p = playerRef.current; const angle = Math.atan2(mouseWorldRef.current.y - p.y, mouseWorldRef.current.x - p.x);
      const vx = Math.cos(angle) * 1200; const vy = Math.sin(angle) * 1200; p.x += vx * 0.2; p.y += vy * 0.2; p.z = 40; createParticle(p.x, p.y, 10, '#fff', 5);
  };
  const activateItem = () => { if (playerRef.current.activeItem && playerRef.current.itemTimer <= 0) { playerRef.current.activeItem.effect(playerRef.current, enemiesRef.current); playerRef.current.itemTimer = playerRef.current.activeItem.cooldown; } };

  // --- FIXED TRIGGER UPGRADE (NO INFINITE LOOP) ---
  const triggerUpgrade = () => {
    gameStateRef.current = GameState.PAUSED;
    const options: Upgrade[] = [];
    const rollItem = !playerRef.current.activeItem && Math.random() > 0.8; 
    const selectedIds = new Set<string>();

    let safetyCounter = 0;
    while (options.length < 4 && safetyCounter < 50) {
        safetyCounter++;
        let pool = UPGRADES_LIST;
        if (rollItem && options.length === 0) { 
            const itemPool = UPGRADES_LIST.filter(u => u.type === 'ITEM');
            if (itemPool.length > 0) pool = itemPool; 
        } else { 
            pool = UPGRADES_LIST.filter(u => { 
                if (u.type === 'ITEM' && playerRef.current.activeItem) return false; 
                if (u.type === 'AUTO_ITEM' && playerRef.current.autoItems.some(ai => ai.id === u.autoItemRef?.id)) return false; 
                return true; 
            }); 
        }

        if (pool.length === 0) break; // Break if no upgrades available

        const rand = pool[Math.floor(Math.random() * pool.length)];
        if (!selectedIds.has(rand.id)) { 
            options.push({...rand, id: rand.id}); 
            selectedIds.add(rand.id); 
        }
    }
    setUpgradeOptions(options); setShowUpgrade(true);
  };

  const applyUpgrade = (upgrade: Upgrade) => {
      const p = playerRef.current;
      if (upgrade.type === 'ITEM' && upgrade.itemRef) { p.activeItem = upgrade.itemRef; } 
      else if (upgrade.type === 'AUTO_ITEM' && upgrade.autoItemRef) { p.autoItems.push({ ...upgrade.autoItemRef }); } 
      else {
        if (upgrade.id.startsWith('dmg_')) p.stats.damage *= 1.1; 
        if (upgrade.id.startsWith('hp_')) { p.stats.maxHp += 50; p.stats.hp += 50; }
        if (upgrade.id.startsWith('spd_')) p.stats.speed *= 1.05;
        if (upgrade.id.startsWith('def_')) p.stats.defense += 2;
      }
      setLastUpgrade(upgrade); setShowUpgrade(false); gameStateRef.current = GameState.TOWER;

      const waveConfig = getWaveConfig(waveRef.current);
      if ((!waveConfig.boss && waveTimerRef.current >= waveConfig.duration) || waveConfig.boss) {
         if (p.stats.towerEchoStacks > 0) { p.stats.damage *= 1.01; p.stats.defense *= 1.01; } 
         waveRef.current++; waveTimerRef.current = 0; bossSpawnedRef.current = false;
      }
  };

  const updateParticles = (dt: number) => {
      particlesRef.current = particlesRef.current.filter(p => {
          p.life -= dt;
          if (p.type === 'RAIN' || p.type === 'ASH' || p.type === 'FROST' || p.type === 'SAND') { p.z -= 1000 * dt; if(p.z <= 0) { p.z = 0; return false; } }
          else { p.x += p.vx * dt; p.y += p.vy * dt; p.z += p.vz * dt; p.vz -= 300 * dt; if (p.z < 0) p.z = 0; }
          return p.life > 0;
      });
      damageNumbersRef.current = damageNumbersRef.current.filter(d => { d.life -= dt; d.z += 40 * dt; return d.life > 0; });
  };

  const createParticle = (x: number, y: number, z: number, color: string, count: number, type: any = 'SPARK') => {
      for(let i=0; i<count; i++) {
          particlesRef.current.push({ id: Math.random().toString(), x, y, z, vx: (Math.random()-0.5)*150, vy: (Math.random()-0.5)*150, vz: Math.random()*150+50, life: 0.5, maxLife: 0.5, color, size: Math.random()*3+2, type });
      }
  };

  const drawIsoSprite = (ctx: CanvasRenderingContext2D, entity: any, type: string) => {
      if (entity.state === 'WINDUP') {
          const iso = toIso(entity.x, entity.y, 0); const progress = Math.max(0, 1 - (entity.stateTimer / entity.windupTime)); const radius = Math.max(1, entity.attackRange || 50);
          ctx.save(); ctx.strokeStyle = 'rgba(239, 68, 68, 0.6)'; ctx.lineWidth = 3; ctx.beginPath(); ctx.ellipse(iso.x, iso.y, radius, radius * 0.5, 0, 0, Math.PI * 2); ctx.stroke();
          ctx.fillStyle = 'rgba(239, 68, 68, 0.3)'; ctx.beginPath(); ctx.ellipse(iso.x, iso.y, radius * progress, (radius * 0.5) * progress, 0, 0, Math.PI * 2); ctx.fill(); ctx.restore();
      }

      if (['HOUSE', 'TREE', 'PORTAL', 'ROCK', 'LAMP'].includes(type) || type.includes('BOSS')) {
          const shadowBase = toIso(entity.x, entity.y, 0);
          ctx.save();
          ctx.translate(shadowBase.x, shadowBase.y);
          ctx.transform(1, 0, -0.5, 0.5, 0, 0); 
          ctx.fillStyle = 'rgba(0,0,0,0.25)';

          if (type === 'HOUSE') {
              const size = entity.size * 0.6; ctx.fillRect(-size/2, -size, size, size * 2.2);
          } else if (type === 'TREE') {
              const w = entity.size * 0.2; ctx.fillRect(-w/2, 0, w, -entity.size * 1.5); ctx.beginPath(); ctx.arc(0, -entity.size * 1.2, entity.size * 0.5, 0, Math.PI*2); ctx.fill();
          } else if (type === 'PORTAL') {
               ctx.beginPath(); ctx.ellipse(0, -20, entity.size/2, entity.size/3, 0, 0, Math.PI*2); ctx.fill();
          } else if (type.includes('BOSS')) {
               ctx.beginPath(); ctx.ellipse(0, 0, 50, 80, 0, 0, Math.PI*2); ctx.fill();
          }
          ctx.restore();
      } else if (entity.z < 200 && !type.includes('TRAP')) {
          const s = toIso(entity.x, entity.y, 0);
          ctx.fillStyle = 'rgba(0,0,0,0.3)';
          ctx.beginPath(); ctx.ellipse(s.x, s.y, 14, 7, 0, 0, Math.PI*2); ctx.fill();
      }

      const { x, y } = toIso(entity.x, entity.y, entity.z);

      if (type === 'PLAYER') {
          const w = 20; const h = 20;
          ctx.fillStyle = entity.color; ctx.fillRect(x - w/2, y - h, w, h);
          ctx.fillStyle = adjustColor(entity.color, 40); ctx.fillRect(x - w/2, y - h - 5, w, 5); 
      } else if (type === 'TREE') {
          const layers = 5;
          for(let i=0; i<layers; i++) {
              const w = entity.size * (1 - i*0.15); const ly = y - (i * 15);
              ctx.fillStyle = i===0 ? '#271306' : (entity.variant === 1 ? '#14532d' : '#166534');
              if (i > 0 && i%2 === 0) ctx.fillStyle = adjustColor(ctx.fillStyle as string, 10);
              if(i === 0) ctx.fillRect(x - w/4, y - 20, w/2, 20); else { ctx.beginPath(); ctx.arc(x, ly, w/2, 0, Math.PI*2); ctx.fill(); }
          }
      } else if (type === 'HOUSE') {
          const s = entity.size * 0.6;
          ctx.fillStyle = '#f5f5f4'; ctx.fillRect(x - s/2, y - s, s, s); 
          ctx.fillStyle = entity.variant === 1 ? '#1e3a8a' : '#7f1d1d'; 
          ctx.beginPath(); ctx.moveTo(x - s/2 - 5, y - s); ctx.lineTo(x + s/2 + 5, y - s); ctx.lineTo(x, y - s*1.5); ctx.fill();
      } else if (type === 'PORTAL') {
          ctx.strokeStyle = '#4f46e5'; ctx.lineWidth = 4;
          ctx.beginPath(); ctx.ellipse(x, y-40, entity.size/3, entity.size/2, 0, 0, Math.PI*2); ctx.stroke();
          ctx.fillStyle = 'rgba(79, 70, 229, 0.3)'; ctx.fill();
      } else if (type.includes('TRAP')) {
          ctx.fillStyle = '#ef4444'; ctx.fillRect(x-15, y-5, 30, 5);
      } else {
          if (type.includes('BOSS')) {
              ctx.fillStyle = '#b91c1c'; ctx.fillRect(x-40, y-80, 80, 80);
              ctx.fillStyle = '#450a0a'; ctx.fillRect(x-30, y-70, 60, 20); 
          } else if (type.includes('BAT') || type.includes('SHADOW') || type === 'ANGEL') {
              ctx.fillStyle = '#1e293b'; ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x-10, y-10); ctx.lineTo(x+10, y-10); ctx.fill();
          } else if (type.includes('SLIME') || type === 'INSECT') {
              ctx.fillStyle = '#4ade80'; ctx.beginPath(); ctx.arc(x, y-10, 15, 0, Math.PI*2); ctx.fill();
          } else {
              ctx.fillStyle = '#991b1b'; ctx.fillRect(x-15, y-30, 30, 30);
          }
      }
  };

  const draw = (dt: number) => {
    const canvas = canvasRef.current; if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false }); if (!ctx) return;
    const cx = CANVAS_WIDTH / 2; const cy = CANVAS_HEIGHT / 2;
    if(canvas.width !== CANVAS_WIDTH || canvas.height !== CANVAS_HEIGHT) { canvas.width = CANVAS_WIDTH; canvas.height = CANVAS_HEIGHT; }

    const shakeX = (Math.random() - 0.5) * shakeRef.current; const shakeY = (Math.random() - 0.5) * shakeRef.current;

    ctx.fillStyle = COLORS.background; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ctx.save();
    ctx.translate(cx, cy); ctx.scale(ZOOM_LEVEL, ZOOM_LEVEL); ctx.translate(Math.floor(cameraRef.current.x + shakeX), Math.floor(cameraRef.current.y + shakeY));

    const tileSize = 100; const pX = playerRef.current.x; const pY = playerRef.current.y; const px = Math.floor(pX / tileSize); const py = Math.floor(pY / tileSize); const range = 20;

    // Correctly accessing the typed BIOME_COLORS
    let biomeColors = BIOME_COLORS[hudData.biome as BiomeType] || BIOME_COLORS.DEFAULT;

    for (let i = px - range; i <= px + range; i++) {
        for (let j = py - range; j <= py + range; j++) {
            const wx = i * tileSize; const wy = j * tileSize;
            const iso = toIso(wx, wy, 0); const screenX = (iso.x + cameraRef.current.x) * ZOOM_LEVEL + cx; const screenY = (iso.y + cameraRef.current.y) * ZOOM_LEVEL + cy;
            if (screenX < -300 || screenX > CANVAS_WIDTH + 300 || screenY < -300 || screenY > CANVAS_HEIGHT + 300) continue;

            const tileNoise = pseudoRandom(i, j);
            let color = biomeColors.grass;
            let topColor = biomeColors.highlight;
            let h = 0;

            if (gameStateRef.current === GameState.ISLAND) {
                 const distToCenter = Math.hypot(wx, wy + 200);
                 if (distToCenter < 1200) { 
                    if (tileNoise > 0.6) topColor = adjustColor(biomeColors.highlight, 10);
                    if (Math.abs(wx) < 100 || Math.abs(wy + 200) < 100) { color = COLORS.stone; topColor = COLORS.stoneHighlight; }
                 } else { 
                     color = COLORS.water; topColor = COLORS.waterHighlight; h = -20;
                     const wave = Math.sin(timeRef.current * 2 + tileNoise * 10);
                     if (wave > 0.5) topColor = adjustColor(COLORS.waterHighlight, 20);
                 }
            } else {
                 if (Math.abs(wx) > 900 || Math.abs(wy) > 900) { h = -100; color = '#000'; topColor = '#000'; }
                 else if (tileNoise > 0.8) { topColor = adjustColor(biomeColors.highlight, -20); } 
            }

            if (h > -50 && h !== 0) {
                 ctx.fillStyle = adjustColor(color, -20); ctx.beginPath(); ctx.moveTo(iso.x + tileSize, iso.y - h + tileSize/2); ctx.lineTo(iso.x + tileSize, iso.y + tileSize/2); ctx.lineTo(iso.x, iso.y + tileSize); ctx.lineTo(iso.x, iso.y - h + tileSize); ctx.fill();
                 ctx.fillStyle = adjustColor(color, -10); ctx.beginPath(); ctx.moveTo(iso.x - tileSize, iso.y - h + tileSize/2); ctx.lineTo(iso.x - tileSize, iso.y + tileSize/2); ctx.lineTo(iso.x, iso.y + tileSize); ctx.lineTo(iso.x, iso.y - h + tileSize); ctx.fill();
            }
            ctx.beginPath(); ctx.moveTo(iso.x, iso.y - h); ctx.lineTo(iso.x + tileSize, iso.y - h + tileSize/2); ctx.lineTo(iso.x, iso.y - h + tileSize); ctx.lineTo(iso.x - tileSize, iso.y - h + tileSize/2); ctx.fillStyle = topColor; ctx.fill();

            if (h === 0 && topColor !== '#000' && gameStateRef.current === GameState.ISLAND) {
                 if (tileNoise > 0.88 && topColor !== COLORS.stoneHighlight) {
                     const fx = iso.x + (tileNoise * 100) % tileSize - tileSize/2; const fy = iso.y - h + (tileNoise * 50) % (tileSize/2);
                     ctx.fillStyle = tileNoise > 0.94 ? '#f472b6' : (tileNoise > 0.91 ? '#fbbf24' : '#fff');
                     ctx.beginPath(); ctx.arc(fx, fy, 2, 0, Math.PI*2); ctx.fill();
                 }
                 if (tileNoise < 0.08) {
                     const px = iso.x - (tileNoise * 200) % tileSize + tileSize/2; const py = iso.y - h + (tileNoise * 100) % (tileSize/2);
                     ctx.fillStyle = adjustColor(color, -30); ctx.fillRect(px, py, 4, 3);
                 }
            }
        }
    }

    const renderList: any[] = [];
    renderList.push({ type: 'PLAYER', obj: playerRef.current, y: toIso(playerRef.current.x, playerRef.current.y).y });
    for(const e of enemiesRef.current) renderList.push({ type: e.type, obj: e, y: toIso(e.x, e.y).y });
    for(const p of particlesRef.current) renderList.push({ type: p.type || 'PARTICLE', obj: p, y: toIso(p.x, p.y).y });
    if (gameStateRef.current === GameState.ISLAND) { staticObjectsRef.current.forEach(obj => { if (Math.abs(obj.x - pX) < 2000 && Math.abs(obj.y - pY) < 2000) renderList.push({ type: obj.type, obj, y: toIso(obj.x, obj.y).y }); }); }

    renderList.sort((a, b) => a.y - b.y);

    for (const item of renderList) {
        if (['PARTICLE','RAIN','FROST','ASH','SAND','POISON'].some(t => item.type === t)) {
             const { x, y } = toIso(item.obj.x, item.obj.y, item.obj.z); 
             ctx.fillStyle = item.obj.color; 
             if (item.type === 'RAIN') ctx.fillRect(x, y, 1, 10);
             else ctx.fillRect(x, y, item.obj.size, item.obj.size);
        } else {
             drawIsoSprite(ctx, item.obj, item.type);
             if (item.obj.hp < item.obj.maxHp && item.obj.hp > 0 && item.type !== 'PARTICLE') {
                 const { x, y } = toIso(item.obj.x, item.obj.y, item.obj.z + 50);
                 ctx.fillStyle = '#0f172a'; ctx.fillRect(x - 15, y - 5, 30, 4); ctx.fillStyle = '#b91c1c'; ctx.fillRect(x - 15, y - 5, 30 * (item.obj.hp/item.obj.maxHp), 4); 
             }
        }
    }

    for(const p of projectilesRef.current) {
        const { x, y } = toIso(p.x, p.y, p.z); ctx.fillStyle = p.color; ctx.shadowBlur = 10; ctx.shadowColor = p.color;
        ctx.beginPath(); ctx.arc(x, y, p.radius, 0, Math.PI*2); ctx.fill(); ctx.shadowBlur = 0;
    }

    ctx.restore(); 

    if (gameStateRef.current === GameState.TOWER) {
        const cycle = Math.sin((dayCycleTimeRef.current / 120) * Math.PI * 2); 
        const darkness = Math.max(0, -cycle * 0.6); 
        if (darkness > 0) { ctx.fillStyle = `rgba(2, 6, 23, ${darkness})`; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT); }
        const vAlpha = 0.3 + darkness * 0.5;
        const vignette = ctx.createRadialGradient(cx, cy, 300, cx, cy, 1000); vignette.addColorStop(0, 'rgba(0,0,0,0)'); vignette.addColorStop(1, `rgba(0,0,0,${vAlpha})`);
        ctx.fillStyle = vignette; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    }
  };

  const formatTime = (s: number) => `${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;

  return (
    <div className="relative w-full h-full bg-[#020617] cursor-none select-none overflow-hidden font-mono">
      <canvas ref={canvasRef} className="block w-full h-full cursor-none" />

      {/* --- HUD --- */}
      <div className="absolute inset-x-0 bottom-6 flex flex-col items-center pointer-events-none z-10 scale-[0.80] origin-bottom transition-transform">
          {hudData.bossHp > 0 && (
              <div className="mb-10 w-[700px] pointer-events-none animate-in fade-in slide-in-from-top-10 duration-700">
                  <div className="flex justify-between items-end text-red-500 font-bold mb-2 px-4 uppercase tracking-widest font-serif drop-shadow-md">
                      <span className="text-2xl">{hudData.bossName}</span>
                      <span className="text-sm opacity-80">{Math.ceil(hudData.bossHp)}/{Math.ceil(hudData.bossMaxHp)}</span>
                  </div>
                  <div className="relative h-6 w-full bg-slate-900 border-2 border-slate-700 rounded-sm shadow-[0_0_30px_rgba(220,38,38,0.3)] overflow-hidden">
                      <div className="absolute inset-0 bg-red-950/50"></div>
                      <div className="h-full bg-gradient-to-r from-red-900 via-red-600 to-red-500 transition-all duration-200" style={{width: `${(hudData.bossHp/hudData.bossMaxHp)*100}%`}}></div>
                  </div>
              </div>
          )}

          <div className="flex items-end gap-6 pb-2">
              <div className="bg-slate-900/95 border border-slate-700 rounded-2xl p-5 backdrop-blur-md shadow-2xl w-72">
                   <div className="flex items-center justify-between gap-2 text-white font-bold text-2xl mb-3 font-serif">
                       <span className="flex items-center gap-2 text-red-400"><Heart fill="currentColor" /> {Math.ceil(hudData.hp)}</span>
                       <span className="text-sm font-mono text-slate-500">LVL {hudData.level}</span>
                   </div>
                   <div className="relative h-4 bg-slate-950 rounded-full overflow-hidden border border-slate-800 mb-2">
                       <div className="h-full bg-gradient-to-r from-red-800 to-red-500" style={{width: `${(hudData.hp/hudData.maxHp)*100}%`}}></div>
                   </div>
                   <div className="mt-1 h-1 w-full bg-slate-800 rounded-full overflow-hidden">
                       <div className="h-full bg-amber-500" style={{width: `${(hudData.xp/hudData.xpNext)*100}%`}}></div>
                   </div>
              </div>

              <div className="flex gap-3 p-4 bg-slate-900/95 border border-slate-700 rounded-2xl backdrop-blur-md shadow-2xl">
                  <div className="w-16 h-16 bg-slate-800 rounded-xl flex items-center justify-center border border-slate-600"><Sword /></div>
                  <div className="w-16 h-16 bg-slate-800 rounded-xl flex items-center justify-center border border-slate-600"><Crosshair /></div>
                  <div className="w-16 h-16 bg-slate-800 rounded-xl flex items-center justify-center border border-slate-600"><Wind /></div>
                  <div className="w-16 h-16 bg-slate-800 rounded-xl flex items-center justify-center border border-slate-600"><Box /></div>
              </div>

              {hudData.state === GameState.TOWER && (
                  <div className="bg-slate-900/95 border border-slate-700 rounded-2xl p-5 backdrop-blur-md shadow-2xl w-48 text-center flex flex-col justify-center h-[124px]">
                      <div className="text-3xl font-mono font-bold text-white mb-1 tracking-widest">{formatTime(hudData.time)}</div>
                      <div className="text-xs text-slate-400 font-serif uppercase tracking-wider border-t border-slate-800 pt-2 mb-1">
                          ANDAR {hudData.floor}
                      </div>
                      <div className="text-[10px] text-amber-500 font-bold uppercase">{hudData.biome.replace('_', ' ')}</div>
                  </div>
              )}
          </div>
      </div>

      {showUpgrade && <UpgradeModal options={upgradeOptions} memoryOption={lastUpgrade} onSelect={applyUpgrade} />}
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { Player, Enemy, Projectile, GameState, Archetype, Particle, DamageNumber, Upgrade, Item, StaticObject, AutoItem } from '../types';
import { CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, BASE_STATS, WAVE_CONFIGS, UPGRADES_LIST, SKILL_CONFIG, ZOOM_LEVEL } from '../constants';
import { UpgradeModal } from './UpgradeModal';
import { Heart, Skull, Sword, Box, Crosshair, Wind, Zap } from 'lucide-react';

interface GameCanvasProps {
  archetype: Archetype;
  onGameOver: () => void;
}

// --- MATH UTILS ---
const toIso = (x: number, y: number, z: number = 0) => {
  return { x: (x - y), y: (x + y) / 2 - z };
};

const toWorldFromIso = (isoX: number, isoY: number) => {
    return { x: isoY + isoX / 2, y: isoY - isoX / 2 };
};

const lerp = (start: number, end: number, t: number) => {
  return start * (1 - t) + end * t;
};

// Deterministic pseudo-random for terrain consistency
const pseudoRandom = (x: number, y: number) => {
    return Math.abs(Math.sin(x * 12.9898 + y * 78.233) * 43758.5453) % 1;
};

// Helper de cor (Darken/Lighten)
const adjustColor = (color: string, amount: number) => {
    const num = parseInt(color.replace('#', ''), 16);
    let r = (num >> 16) + amount;
    let b = ((num >> 8) & 0x00FF) + amount;
    let g = (num & 0x0000FF) + amount;
    r = r > 255 ? 255 : r < 0 ? 0 : r;
    b = b > 255 ? 255 : b < 0 ? 0 : b;
    g = g > 255 ? 255 : g < 0 ? 0 : g;
    return "#" + (g | (b << 8) | (r << 16)).toString(16).padStart(6, '0');
};

const PORTAL_POS = { x: -400, y: -400 };

export const GameCanvas: React.FC<GameCanvasProps> = ({ archetype, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Game State Refs
  const gameStateRef = useRef<GameState>(GameState.ISLAND);
  const playerRef = useRef<Player>({
    x: 0, y: 0, z: 0,
    archetype,
    stats: JSON.parse(JSON.stringify(BASE_STATS[archetype])),
    level: 1, xp: 0, xpToNextLevel: 100,
    weaponTimer: 0, skill1Timer: 0, skill1MaxCooldown: SKILL_CONFIG[archetype].skill1Cd,
    dashTimer: 0, 
    dashMaxCooldown: SKILL_CONFIG[archetype].dashCd,
    dashCharges: BASE_STATS[archetype].dashChargesMax,
    activeItem: null, itemTimer: 0, itemMaxCooldown: 0,
    autoItems: [], // Habilidades Automáticas
    facing: 0, isMoving: false, color: COLORS[archetype], animFrame: 0,
    slowTimer: 0, lastHitTime: 0, avatarBuffTimer: 0
  });

  const enemiesRef = useRef<Enemy[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const damageNumbersRef = useRef<DamageNumber[]>([]);
  const staticObjectsRef = useRef<StaticObject[]>([]);
  const keysRef = useRef<{ [key: string]: boolean }>({});

  // System Refs
  const cameraRef = useRef({ x: 0, y: 0 }); 
  const shakeRef = useRef(0); 
  const timeRef = useRef<number>(0); 
  const waveRef = useRef<number>(0);
  const waveTimerRef = useRef<number>(0);
  const lastSpawnTimeRef = useRef<number>(0);
  const bossSpawnedRef = useRef<boolean>(false); // Para controlar o spawn único do boss

  // Weather System
  const weatherTimeRef = useRef<number>(0); 
  const isRainingRef = useRef<boolean>(false);
  const rainIntensityRef = useRef<number>(0);
  const rainParticlesTimer = useRef<number>(0);

  // UI State
  const [showUpgrade, setShowUpgrade] = useState(false);
  const [upgradeOptions, setUpgradeOptions] = useState<Upgrade[]>([]);
  const [lastUpgrade, setLastUpgrade] = useState<Upgrade | null>(null);
  const [hudData, setHudData] = useState({ 
      hp: 100, maxHp: 100, xp: 0, xpNext: 100, time: 0, wave: 1, level: 1, 
      state: GameState.ISLAND, skill1Cd: 0, dashCd: 0, itemCd: 0, dashCharges: 0, dashMax: 0,
      activeItem: null as Item | null, bossHp: 0, bossMaxHp: 0,
      autoItems: [] as AutoItem[],
      buffTime: 0
  });

  const mouseScreenRef = useRef({ x: 0, y: 0 }); 
  const mouseWorldRef = useRef({ x: 0, y: 0 });
  const reticleAngleRef = useRef(0);

  // --- INIT ---
  useEffect(() => {
    // Generate Island (Optimized & Beautiful)
    if (gameStateRef.current === GameState.ISLAND) {
        const objects: StaticObject[] = [];
        objects.push({ id: 'portal', x: PORTAL_POS.x, y: PORTAL_POS.y, type: 'PORTAL', size: 140 });
        objects.push({ id: 'h1', x: -150, y: -150, type: 'HOUSE', size: 110, variant: 0 });
        objects.push({ id: 'h2', x: 250, y: -250, type: 'HOUSE', size: 130, variant: 1 });
        objects.push({ id: 'h3', x: -350, y: 100, type: 'HOUSE', size: 100, variant: 0 });
        objects.push({ id: 'h4', x: 150, y: 200, type: 'HOUSE', size: 120, variant: 1 });
        objects.push({ id: 'h5', x: -50, y: 350, type: 'HOUSE', size: 90, variant: 0 });
        const lampPositions = [{x: 0, y: -300}, {x: -250, y: -300}, {x: -300, y: -250}, {x: -100, y: -100}, {x: 100, y: -200}, {x: -200, y: 50}];
        lampPositions.forEach((p, i) => objects.push({ id: `lamp${i}`, x: p.x, y: p.y, type: 'LAMP', size: 20 }));

        const isPath = (x: number, y: number) => {
            const dCenter = Math.hypot(x, y);
            const dPortal = Math.hypot(x - PORTAL_POS.x, y - PORTAL_POS.y);
            const crossProduct = Math.abs(x * PORTAL_POS.y - y * PORTAL_POS.x);
            const distToCorridor = crossProduct / Math.hypot(PORTAL_POS.x, PORTAL_POS.y);

            if (dCenter < 250) return true;
            if (dPortal < 250) return true; // Keep portal area clear
            if (distToCorridor < 100 && x < 50 && y < 50 && x > -450 && y > -450) return true;
            return false;
        };

        for(let i=0; i<150; i++) {
            const angle = Math.random() * Math.PI * 2;
            const dist = 300 + Math.random() * 900;
            const x = Math.cos(angle) * dist;
            const y = Math.sin(angle) * dist;
            let collides = false;
            for(const obj of objects) { if (Math.hypot(x - obj.x, y - obj.y) < obj.size * 0.8) collides = true; }

            if (!collides && !isPath(x, y)) {
                const r = Math.random();
                if (r < 0.6) { objects.push({ id: `t${i}`, x, y, type: 'TREE', size: 50 + Math.random() * 70, variant: Math.random() > 0.5 ? 1 : 0 }); } 
                else if (r < 0.85) { objects.push({ id: `b${i}`, x, y, type: 'BUSH', size: 20 + Math.random() * 15, variant: Math.random() > 0.5 ? 1 : 0 }); } 
                else { objects.push({ id: `r${i}`, x, y, type: 'ROCK', size: 15 + Math.random() * 25 }); }
            }
        }
        staticObjectsRef.current = objects;
    }
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { if (e.code === 'Space') e.preventDefault(); keysRef.current[e.code] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keysRef.current[e.code] = false; };
    const handleMouseMove = (e: MouseEvent) => {
      const rect = canvasRef.current?.getBoundingClientRect();
      if(rect) {
          mouseScreenRef.current = { x: e.clientX - rect.left - rect.width / 2, y: e.clientY - rect.top - rect.height / 2 };
      }
    };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) keysRef.current['MouseLeft'] = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) keysRef.current['MouseLeft'] = false; };
    const handleContextMenu = (e: MouseEvent) => e.preventDefault();

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    window.addEventListener('contextmenu', handleContextMenu);

    let animationFrameId: number;
    let lastTime = performance.now();

    const loop = (timestamp: number) => {
      const dtRaw = (timestamp - lastTime) / 1000;
      const dt = Math.min(dtRaw, 0.1); 
      lastTime = timestamp;

      if (gameStateRef.current === GameState.TOWER || gameStateRef.current === GameState.ISLAND) {
        update(dt);
      }
      draw(dt);
      animationFrameId = requestAnimationFrame(loop);
    };

    animationFrameId = requestAnimationFrame(loop);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
      window.removeEventListener('contextmenu', handleContextMenu);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  // --- UPDATE ---
  const update = (dt: number) => {
    const player = playerRef.current;

    // Calculate effective stats (with buffs)
    const activeStats = { ...player.stats };
    if (player.avatarBuffTimer > 0) {
        player.avatarBuffTimer -= dt;
        activeStats.damage *= 1.3;
        activeStats.speed *= 1.3;
        activeStats.cooldownReduction += 0.2;
        if (player.avatarBuffTimer <= 0) player.avatarBuffTimer = 0;
    }

    // --- CAMERA DINÂMICA ---
    const playerIso = toIso(player.x, player.y, player.z);
    const lookAheadX = (mouseScreenRef.current.x / ZOOM_LEVEL) * 0.25;
    const lookAheadY = (mouseScreenRef.current.y / ZOOM_LEVEL) * 0.25;
    const targetX = -playerIso.x - lookAheadX;
    const targetY = -playerIso.y - lookAheadY;

    cameraRef.current.x = lerp(cameraRef.current.x, targetX, 0.08);
    cameraRef.current.y = lerp(cameraRef.current.y, targetY, 0.08);

    // --- MIRA E CURSOR ---
    const mouseIsoX = (mouseScreenRef.current.x / ZOOM_LEVEL) - cameraRef.current.x;
    const mouseIsoY = (mouseScreenRef.current.y / ZOOM_LEVEL) - cameraRef.current.y;
    mouseWorldRef.current = toWorldFromIso(mouseIsoX, mouseIsoY);

    const distMouse = Math.hypot(mouseWorldRef.current.x - player.x, mouseWorldRef.current.y - player.y);
    if (distMouse > 40) {
        player.facing = Math.atan2(mouseWorldRef.current.y - player.y, mouseWorldRef.current.x - player.x);
    }
    reticleAngleRef.current = player.facing; 

    // Input & Movement
    let dx = 0; let dy = 0;
    if (keysRef.current['KeyW'] || keysRef.current['ArrowUp']) { dx -= 1; dy -= 1; }
    if (keysRef.current['KeyS'] || keysRef.current['ArrowDown']) { dx += 1; dy += 1; }
    if (keysRef.current['KeyA'] || keysRef.current['ArrowLeft']) { dx -= 1; dy += 1; }
    if (keysRef.current['KeyD'] || keysRef.current['ArrowRight']) { dx += 1; dy -= 1; }

    player.isMoving = dx !== 0 || dy !== 0;
    if (player.isMoving) {
      const length = Math.sqrt(dx * dx + dy * dy);
      dx /= length; dy /= length;

      let currentSpeed = activeStats.speed * 60;
      if (player.slowTimer > 0) { player.slowTimer -= dt; currentSpeed *= 0.6; }

      const newX = player.x + dx * currentSpeed * dt;
      const newY = player.y + dy * currentSpeed * dt;

      // Basic Collision for Island (prevent walking through houses/trees)
      let canMoveX = true;
      let canMoveY = true;

      if (gameStateRef.current === GameState.ISLAND) {
          const playerRadius = 15;
          staticObjectsRef.current.forEach(obj => {
              if (obj.type === 'PORTAL' || obj.type === 'BUSH') return; // Pass through portal/bushes

              const dist = Math.hypot(newX - obj.x, player.y - obj.y);
              if (dist < obj.size * 0.4 + playerRadius) canMoveX = false;

              const distY = Math.hypot(player.x - obj.x, newY - obj.y);
              if (distY < obj.size * 0.4 + playerRadius) canMoveY = false;
          });
      }

      if (canMoveX) player.x = newX;
      if (canMoveY) player.y = newY;

      player.animFrame += dt * 10;
    } else { player.animFrame = 0; }

    if (player.z > 0) { player.z -= 200 * dt; if (player.z < 0) player.z = 0; }

    // PASSIVE: Regen
    player.lastHitTime += dt;
    if (activeStats.regen > 0 && player.lastHitTime > 3) { 
        const heal = activeStats.maxHp * (activeStats.regen / 100) * dt;
        player.stats.hp = Math.min(activeStats.maxHp, player.stats.hp + heal);
    }

    // PASSIVE: Shield Logic
    if (activeStats.shieldOnLowHp) {
        if (activeStats.shieldCooldown > 0) activeStats.shieldCooldown -= dt;
        else if (player.stats.hp < activeStats.maxHp * 0.2) {
             activeStats.shieldCooldown = 60; 
             player.stats.hp += activeStats.maxHp * 0.3; 
             createParticle(player.x, player.y, 10, '#3b82f6', 20, 'MAGIC');
        }
        player.stats.shieldCooldown = activeStats.shieldCooldown; 
    }

    // Limits & Transition
    const limit = gameStateRef.current === GameState.ISLAND ? 1500 : 900;
    if (Math.abs(player.x) > limit) player.x = Math.sign(player.x) * limit;
    if (Math.abs(player.y) > limit) player.y = Math.sign(player.y) * limit;

    // PORTAL LOGIC
    if (gameStateRef.current === GameState.ISLAND) {
        const distToPortal = Math.hypot(player.x - PORTAL_POS.x, player.y - PORTAL_POS.y); 
        // Increased radius to 200 for easier entry
        if (distToPortal < 200) {
            gameStateRef.current = GameState.TOWER;
            player.x = 0; player.y = 0; player.z = 0; // Reset player pos
            enemiesRef.current = []; projectilesRef.current = [];
            waveRef.current = 0; timeRef.current = 0; weatherTimeRef.current = 0;
            staticObjectsRef.current = []; // Clear island objects
            bossSpawnedRef.current = false;
        }
        // Heal at lobby
        if (player.stats.hp < activeStats.maxHp) player.stats.hp += 100 * dt;
    }

    // Tower Logic
    if (gameStateRef.current === GameState.TOWER) {
        timeRef.current += dt; waveTimerRef.current += dt;
        player.skill1Timer -= dt; player.itemTimer -= dt; player.weaponTimer -= dt;

        // --- CLIMA ---
        weatherTimeRef.current += dt;
        if (weatherTimeRef.current > 30 && weatherTimeRef.current < 90) {
            if (!isRainingRef.current) { isRainingRef.current = true; shakeRef.current = 10; }
            rainIntensityRef.current = Math.min(1, rainIntensityRef.current + dt * 0.2); 
        } else {
            isRainingRef.current = false; rainIntensityRef.current = Math.max(0, rainIntensityRef.current - dt * 0.2); 
        }
        if (rainIntensityRef.current > 0.1) {
            rainParticlesTimer.current += dt;
            if(rainParticlesTimer.current > 0.02) { 
                const spawnCount = Math.floor(rainIntensityRef.current * 4); 
                for(let i=0; i<spawnCount; i++) {
                    const angle = Math.random() * Math.PI * 2; const dist = Math.random() * 900; 
                    particlesRef.current.push({ id: Math.random().toString(), x: player.x + Math.cos(angle)*dist - 400, y: player.y + Math.sin(angle)*dist - 400, z: 500, vx: 50, vy: 50, vz: -1200, life: 0.5, maxLife: 0.5, color: '#a5f3fc', size: 1.5, type: 'RAIN' });
                }
                rainParticlesTimer.current = 0;
            }
        }

        // --- DASH ---
        if (player.dashCharges < activeStats.dashChargesMax) {
            player.dashTimer -= dt;
            if (player.dashTimer <= 0) {
                player.dashCharges++;
                player.dashTimer = player.dashMaxCooldown * (1 - activeStats.cooldownReduction);
            }
        }

        // --- AUTO ITEMS LOGIC ---
        player.autoItems.forEach(item => {
            item.timer -= dt;
            if (item.timer <= 0) {
                const result = item.effect(player, enemiesRef.current);
                if (result) {
                    if (Array.isArray(result)) projectilesRef.current.push(...result);
                    else projectilesRef.current.push(result);
                    item.timer = item.cooldown * (1 - activeStats.cooldownReduction);
                    if (player.avatarBuffTimer > 0) item.timer *= 0.5; // Avatar buff reduces cooldowns drastically
                } else { item.timer = 0.5; }
            }
        });

        // --- SPAWN SYSTEM ---
        const currentConfig = WAVE_CONFIGS[waveRef.current] || WAVE_CONFIGS[WAVE_CONFIGS.length-1];
        const bossAlive = enemiesRef.current.some(e => e.isBoss);
        if ((!currentConfig.boss && waveTimerRef.current >= currentConfig.duration) || (currentConfig.boss && bossSpawnedRef.current && !bossAlive)) {
             triggerUpgrade();
        } else if (enemiesRef.current.length < currentConfig.enemyCount || currentConfig.boss) { 
             if (Date.now() - lastSpawnTimeRef.current > currentConfig.spawnRate) {
                 if (currentConfig.boss && !bossSpawnedRef.current) { spawnBoss(currentConfig.boss); bossSpawnedRef.current = true; } 
                 else if (enemiesRef.current.length < currentConfig.enemyCount) { spawnEnemy(); }
                 lastSpawnTimeRef.current = Date.now();
             }
        }

        if (keysRef.current['MouseLeft'] && player.weaponTimer <= 0) useMainAttack(activeStats);
        if (keysRef.current['KeyQ'] && player.skill1Timer <= 0) {
            useSkill1(activeStats);
            player.skill1Timer = player.skill1MaxCooldown * (1 - activeStats.cooldownReduction);
        }
        if (keysRef.current['KeyE'] && player.dashCharges > 0) {
            useDash(); player.dashCharges--;
            if (player.dashTimer <= 0) player.dashTimer = player.dashMaxCooldown * (1 - activeStats.cooldownReduction);
            keysRef.current['KeyE'] = false; 
        }
        if (keysRef.current['KeyR']) activateItem();
    }

    if (shakeRef.current > 0) shakeRef.current -= dt * 30; if (shakeRef.current < 0) shakeRef.current = 0;
    updateProjectiles(dt, activeStats);
    updateEnemies(dt, activeStats);
    updateParticles(dt);

    const boss = enemiesRef.current.find(e => e.isBoss);
    setHudData({
        hp: player.stats.hp, maxHp: activeStats.maxHp, xp: player.xp, xpNext: player.xpToNextLevel,
        time: timeRef.current, wave: waveRef.current + 1, level: player.level,
        state: gameStateRef.current, skill1Cd: player.skill1Timer, dashCd: player.dashTimer, 
        dashCharges: player.dashCharges, dashMax: activeStats.dashChargesMax, itemCd: player.itemTimer,
        activeItem: player.activeItem, bossHp: boss ? boss.hp : 0, bossMaxHp: boss ? boss.maxHp : 0,
        autoItems: player.autoItems, buffTime: player.avatarBuffTimer
    });

    if (player.stats.hp <= 0 && gameStateRef.current === GameState.TOWER) {
        gameStateRef.current = GameState.GAME_OVER;
        onGameOver();
    }
  };

  // --- ACTIONS ---
  const spawnEnemy = () => {
    const angle = Math.random() * Math.PI * 2; const distance = 850; 
    const ex = playerRef.current.x + Math.cos(angle) * distance; const ey = playerRef.current.y + Math.sin(angle) * distance;
    let type: any = 'SLIME'; const w = waveRef.current; const r = Math.random();

    if (w >= 10) { if (r < 0.2) type = 'DEMON'; else if (r < 0.4) type = 'BAT'; else if (r < 0.6) type = 'SORCERER'; else if (r < 0.8) type = 'SNAKE'; else type = 'GOBLIN'; } 
    else if (w >= 5) { if (r < 0.2) type = 'GOBLIN'; else if (r < 0.4) type = 'BAT'; else if (r < 0.6) type = 'SNAKE'; else if (r < 0.8) type = 'SORCERER'; else type = 'SLIME'; } 
    else if (w >= 2) { if (r < 0.3) type = 'SNAKE'; else if (r < 0.6) type = 'GOBLIN'; else type = 'SLIME'; } 
    else { type = r < 0.2 ? 'GOBLIN' : 'SLIME'; }

    const variant = Math.floor(Math.random() * 3);
    let hp = 30 + w * 12; let armor = 0; let speed = 80 + Math.random()*20; let radius = 20;

    if (variant === 1) { hp *= 0.8; speed *= 1.2; } else if (variant === 2) { hp *= 1.3; speed *= 0.85; radius *= 1.2; }
    if (w >= 3) armor = 5 + w * 2; 

    let attackRange = 50; let windupTime = 0.5;
    if (type === 'SLIME') { if (variant === 1) speed += 20; }
    if (type === 'GOBLIN') { hp += 30; speed = 90; attackRange = 70; windupTime = 0.4; if (variant === 1) { speed = 110; attackRange = 60; } if (variant === 2) { hp += 50; speed = 70; } }
    if (type === 'SORCERER') { hp += 10; armor = 0; speed = 60; attackRange = 400; windupTime = 0.8; }
    if (type === 'DEMON') { hp += 150; armor += 20; speed = 65; attackRange = 90; windupTime = 0.6; }
    if (type === 'SNAKE') { hp = 25 + w * 8; speed = 110; attackRange = 300; windupTime = 0.6; radius = 18; }
    if (type === 'BAT') { hp = 20 + w * 5; speed = 140; attackRange = 60; windupTime = 0.3; radius = 15; armor = 0; }

    enemiesRef.current.push({
      id: Math.random().toString(), x: ex, y: ey, z: type === 'BAT' ? 200 : 0, 
      type, isBoss: false, hp, maxHp: hp, defense: armor, speed, damage: 10 + w * 2,
      radius, hitboxRadius: radius * 0.8, frame: 0, vx: 0, vy: 0, hitFlash: 0,
      state: type === 'BAT' ? 'SWOOPING' : 'CHASING', stateTimer: 0, attackRange, windupTime, recoverTime: 0.5, variant
    });
  };

  const spawnBoss = (type: 'BOSS_GOLEM' | 'BOSS_LICH') => {
      const dist = 600; const angle = Math.random() * Math.PI * 2; const waveMult = 1 + waveRef.current * 0.5;
      let hp = 4000 * waveMult; let defense = 30 + waveRef.current * 5; let damage = 60 + waveRef.current * 2; let speed = 40; let radius = 80; let attackRange = 180;

      if (type === 'BOSS_GOLEM') { hp = 6000 * waveMult; defense = 60 + waveRef.current * 5; speed = 35; damage = 80 + waveRef.current * 3; radius = 100; attackRange = 150; } 
      else if (type === 'BOSS_LICH') { hp = 3500 * waveMult; defense = 20 + waveRef.current * 5; speed = 55; damage = 50 + waveRef.current * 2; radius = 70; attackRange = 450; }

      enemiesRef.current.push({
          id: 'boss', x: playerRef.current.x + Math.cos(angle)*dist, y: playerRef.current.y + Math.sin(angle)*dist, z: 0,
          type, isBoss: true, hp, maxHp: hp, defense, speed, damage, radius, hitboxRadius: radius * 0.8, frame: 0, vx: 0, vy: 0, hitFlash: 0,
          state: 'CHASING', stateTimer: 0, attackRange, windupTime: 1.5, recoverTime: 1.5, variant: 0, specialTimer: 5 
      });
      shakeRef.current = 20; 
  };

  const updateEnemies = (dt: number, stats: any) => {
      const p = playerRef.current;
      const enemiesList = enemiesRef.current;
      const enemyCount = enemiesList.length;

      enemiesRef.current = enemiesList.filter((e, idx) => {
          if (e.hitFlash > 0) e.hitFlash -= dt;

          // FROZEN LOGIC
          if (e.frozenTimer && e.frozenTimer > 0) {
              e.frozenTimer -= dt;
              return true; // Skip logic but keep enemy
          }

          e.frame += dt; 

          // Separation
          if (e.type !== 'BAT') {
              let sepX = 0, sepY = 0; const checkLimit = Math.min(idx + 3, enemyCount);
              for (let i = Math.max(0, idx - 3); i < checkLimit; i++) {
                  if (i === idx) continue;
                  const other = enemiesList[i]; if (other.type === 'BAT') continue; 
                  const distSq = (e.x - other.x)**2 + (e.y - other.y)**2; const minDist = (e.radius + other.radius) * 0.8;
                  if (distSq < minDist**2 && distSq > 0.1) {
                      const pushDist = Math.sqrt(distSq); const pushForce = (minDist - pushDist) / pushDist;
                      sepX += (e.x - other.x) * pushForce; sepY += (e.y - other.y) * pushForce;
                  }
              }
              e.vx += sepX * 200 * dt; e.vy += sepY * 200 * dt;
          }
          if (Math.abs(e.vx) > 1 || Math.abs(e.vy) > 1) { e.x += e.vx * dt; e.y += e.vy * dt; e.vx *= 0.9; e.vy *= 0.9; }

          const dx = p.x - e.x; const dy = p.y - e.y; const dist = Math.hypot(dx, dy);
          if (e.isBoss && e.specialTimer !== undefined) { e.specialTimer -= dt; }

          // AI BEHAVIOR
          if (e.state === 'CHASING' || e.state === 'SWOOPING') {
              if (e.type === 'SORCERER' && dist < 300) { e.state = 'FLEEING'; e.stateTimer = 1.0; }
              if (e.type === 'SNAKE' && dist < 250 && dist > 100) { if (Math.random() < 0.02) { e.state = 'WINDUP'; e.stateTimer = e.windupTime; } }
              if (e.type === 'BAT') {
                  const hoverHeight = 60 + Math.sin(e.frame * 5) * 20;
                  if (e.state === 'SWOOPING') { if (dist < 200) e.z = lerp(e.z, 10, dt * 5); else e.z = lerp(e.z, hoverHeight, dt * 2); }
              }

              if (e.isBoss && e.specialTimer !== undefined && e.specialTimer <= 0) {
                  if (e.type === 'BOSS_GOLEM') {
                       const isEnraged = e.hp < e.maxHp * 0.5;
                       if (dist > 350 && Math.random() < 0.6) { e.state = 'CHANNELING'; e.stateTimer = 0.8; e.specialTimer = isEnraged ? 4 : 7; e.variant = 1; } 
                       else if (Math.random() < 0.4) { e.state = 'CHANNELING'; e.stateTimer = 1.5; e.specialTimer = isEnraged ? 6 : 10; e.variant = 0; }
                  } else if (e.type === 'BOSS_LICH') {
                       if (dist < 180 && Math.random() < 0.7) {
                           createParticle(e.x, e.y, 10, '#a855f7', 15, 'TELEPORT');
                           const telAngle = Math.atan2(dy, dx) + Math.PI + (Math.random()-0.5); const telDist = 400 + Math.random() * 200;
                           e.x = p.x + Math.cos(telAngle) * telDist; e.y = p.y + Math.sin(telAngle) * telDist;
                           createParticle(e.x, e.y, 10, '#a855f7', 15, 'TELEPORT');
                           e.specialTimer = 4; e.state = 'RECOVERING'; e.stateTimer = 0.5;
                       } else if (Math.random() < 0.5) { e.state = 'CHANNELING'; e.stateTimer = 1.0; e.specialTimer = 8; } 
                       else { e.specialTimer = 5; }
                  }
              }

              if (dist > 10) {
                  let mx = dx / dist; let my = dy / dist;
                  if (e.type === 'GOBLIN' && dist > 80 && dist < 300) {
                      const strafeDir = (e.id.charCodeAt(0) % 2 === 0) ? 1 : -1;
                      mx = (mx * 0.5) + (-my * strafeDir * 0.8); my = (my * 0.5) + (mx * strafeDir * 0.8);
                      const len = Math.hypot(mx, my); mx /= len; my /= len;
                  }
                  if (e.type === 'SNAKE') {
                      const wobble = Math.sin(e.frame * 8) * 0.5; mx += -my * wobble; my += mx * wobble; const len = Math.hypot(mx, my); mx /= len; my /= len;
                  }
                  let currentMoveSpeed = e.speed;
                  if (e.type === 'BOSS_LICH' && dist < 350) { currentMoveSpeed *= -0.5; }
                  e.x += mx * currentMoveSpeed * dt; e.y += my * currentMoveSpeed * dt;
              }
              if (dist < e.attackRange) { e.state = 'WINDUP'; e.stateTimer = e.windupTime; }
          }
          else if (e.state === 'FLEEING') {
              e.stateTimer -= dt; if (dist > 0) { e.x -= (dx/dist) * e.speed * 1.2 * dt; e.y -= (dy/dist) * e.speed * 1.2 * dt; }
              if (e.stateTimer <= 0) e.state = 'CHASING';
          }
          else if (e.state === 'CHANNELING') {
              e.stateTimer -= dt; createParticle(e.x + (Math.random()-0.5)*50, e.y + (Math.random()-0.5)*50, Math.random()*100, e.type === 'BOSS_GOLEM' ? '#f59e0b' : '#a855f7', 1, 'SPARK');
              if (e.stateTimer <= 0) {
                  if (e.type === 'BOSS_GOLEM') {
                      if (e.variant === 1) { 
                          const throwAngle = Math.atan2(dy, dx);
                          projectilesRef.current.push({
                              id: Math.random().toString(), x: e.x, y: e.y, z: 60, vx: Math.cos(throwAngle) * 500, vy: Math.sin(throwAngle) * 500,
                              damage: e.damage * 1.2, duration: 3, radius: 25, type: 'BOSS_ROCK', color: '#78350f', pierce: 999, isEnemy: true
                          });
                      } else { 
                          shakeRef.current = 25;
                          for(let i=0; i<8; i++) {
                              const angle = (i / 8) * Math.PI * 2;
                              projectilesRef.current.push({
                                  id: Math.random().toString(), x: e.x, y: e.y, z: 10, vx: Math.cos(angle) * 350, vy: Math.sin(angle) * 350,
                                  damage: e.damage * 0.8, duration: 2, radius: 25, type: 'GOLEM_SHOCKWAVE', color: '#d97706', pierce: 999, isEnemy: true
                              });
                          }
                      }
                  } else if (e.type === 'BOSS_LICH') {
                       for(let i=0; i<12; i++) {
                          const angle = (i / 12) * Math.PI * 2 + (Math.random() * 0.5);
                          projectilesRef.current.push({
                              id: Math.random().toString(), x: e.x, y: e.y, z: 40, vx: Math.cos(angle) * 250, vy: Math.sin(angle) * 250,
                              damage: e.damage * 0.6, duration: 4, radius: 12, type: 'LICH_NOVA', color: '#10b981', pierce: 999, isEnemy: true
                          });
                       }
                  }
                  e.state = 'RECOVERING'; e.stateTimer = 1.0;
              }
          }
          else if (e.state === 'WINDUP') {
              e.stateTimer -= dt;
              if (e.stateTimer <= 0) {
                  e.state = 'ATTACKING';
                  if (e.type === 'SORCERER' || e.type === 'BOSS_LICH' || e.type === 'SNAKE') {
                      projectilesRef.current.push({
                          id: Math.random().toString(), x: e.x, y: e.y, z: 40, vx: (dx/dist)*500, vy: (dy/dist)*500,
                          damage: e.damage, duration: 2, radius: 12, type: e.type === 'SNAKE' ? 'POISON_SPIT' : 'ENEMY_BOLT', 
                          color: e.type === 'BOSS_LICH' ? '#10b981' : (e.type === 'SNAKE' ? '#a3e635' : '#9333ea'), pierce: 0, isEnemy: true
                      });
                  } else if (e.type === 'BOSS_GOLEM') {
                       projectilesRef.current.push({
                          id: Math.random().toString(), x: e.x, y: e.y, z: 0, vx: 0, vy: 0, damage: e.damage * 1.5, duration: 0.5, radius: 140,
                          type: 'BOSS_SMASH', color: '#ef4444', pierce: 999, isEnemy: true
                      });
                      shakeRef.current = 30;
                  } else if (dist < e.attackRange + 30) { takeDamage(p, e.damage); }
                  e.state = e.type === 'BAT' ? 'SWOOPING' : 'RECOVERING'; e.stateTimer = e.recoverTime;
                  if (e.type === 'BOSS_GOLEM' && e.hp < e.maxHp * 0.5) e.stateTimer *= 0.5;
              }
          } else if (e.state === 'RECOVERING') {
              e.stateTimer -= dt; if (e.stateTimer <= 0) e.state = 'CHASING';
          }

          // Projectile Collision
          for (const proj of projectilesRef.current) {
               if (proj.duration <= 0 || proj.isEnemy) continue;

               // DELAYED DAMAGE (Like Earth Spike / Seal)
               if (proj.delayedDamage) {
                   if (proj.duration > 0.1) continue; // Only damage at end
               }

               const pDist = Math.hypot(proj.x - e.x, proj.y - e.y);
               if(pDist < proj.radius + e.hitboxRadius) {

                   // EFFECTS
                   if (proj.type === 'TIME_PRISON') { e.frozenTimer = 3.0; continue; }
                   if (proj.knockbackForce) {
                        const kAngle = Math.atan2(e.y - proj.y, e.x - proj.x);
                        e.vx += Math.cos(kAngle) * proj.knockbackForce;
                        e.vy += Math.sin(kAngle) * proj.knockbackForce;
                   }

                   // DAMAGE CALCULATION
                   const isAoe = proj.type === 'SWORD_SLASH' || proj.type === 'FIRE_ZONE' || proj.type === 'OCEAN_WAVE';
                   let dmg = isAoe ? proj.damage * 5 * dt : proj.damage;

                   // CRIT SYSTEM
                   const isCrit = Math.random() < stats.critChance;
                   if (isCrit) dmg *= stats.critDamage;

                   // EXECUTIONER SYSTEM
                   if (stats.executionerThreshold > 0 && (e.hp / e.maxHp) < 0.3) {
                       dmg *= (1 + stats.executionerThreshold);
                   }

                   // Defense
                   const effectiveDefense = Math.max(0, e.defense - stats.armorPenetration);
                   const mitigation = 100 / (100 + effectiveDefense);
                   const finalDmg = dmg * mitigation;

                   e.hitFlash = 0.15; 

                   if (!isAoe) {
                       if (proj.type === 'ARROW' || proj.type === 'MAGIC_ORB') {
                           const kAngle = Math.atan2(e.y - proj.y, e.x - proj.x); const force = e.type === 'BAT' ? 500 : 300;
                           e.vx = Math.cos(kAngle) * force; e.vy = Math.sin(kAngle) * force;
                           proj.pierce--; if (proj.pierce < 0) proj.duration = 0; 
                       }
                   }

                   e.hp -= finalDmg;
                   if (!isAoe || Math.random() > 0.8) {
                       createDamageNumber(e.x, e.y, e.z + 40, finalDmg, isCrit, false, mitigation < 0.7);
                       const color = proj.color;
                       if (proj.type === 'MAGIC_ORB' || proj.type === 'AUTO_FIREBALL' || proj.type === 'SWORD_SLASH') { createParticle(e.x, e.y, e.z + 20, color, 3, 'MAGIC'); } 
                       else { createParticle(e.x, e.y, e.z + 20, color, 2, 'IMPACT'); }
                   }

                   if(e.hp <= 0 && !e.isBoss) {
                       createParticle(e.x, e.y, e.z, '#ef4444', 12, 'BLOOD'); 
                       if (stats.lifeSteal > 0) {
                           const heal = stats.maxHp * stats.lifeSteal;
                           if (heal > 0) { p.stats.hp = Math.min(stats.maxHp, p.stats.hp + heal); createDamageNumber(p.x, p.y, p.z + 80, heal, false, false, false); }
                       }
                       if (!isAoe && proj.pierce < 0) break;
                       break; 
                   }
               }
          }

          if(e.hp <= 0) {
              p.xp += e.isBoss ? 500 : 15;
              shakeRef.current += e.isBoss ? 20 : 2; 
              if(p.xp >= p.xpToNextLevel) {
                  p.level++; p.xp -= p.xpToNextLevel; p.xpToNextLevel *= 1.2;
                  p.stats.damage *= 1.1; p.stats.maxHp *= 1.1; p.stats.hp = p.stats.maxHp;
                  createDamageNumber(p.x, p.y, p.z+60, 0, true); shakeRef.current += 10; 
              }
              return false;
          }
          return true;
      });
  };

  const takeDamage = (p: Player, amount: number) => {
      const reducedByPercent = amount * (1 - Math.min(0.8, p.stats.damageReduction)); 
      const finalDmg = Math.max(1, reducedByPercent - p.stats.defense);
      p.stats.hp -= finalDmg;
      shakeRef.current = 10;
      p.slowTimer = 0.5;
      p.lastHitTime = 0; // Resets regen
      createDamageNumber(p.x, p.y, p.z + 50, finalDmg, false, true);
  };

  const updateProjectiles = (dt: number, stats: any) => {
      const p = playerRef.current;
      projectilesRef.current = projectilesRef.current.filter(proj => {
          proj.duration -= dt;

          if(proj.type === 'SWORD_SLASH' || proj.type === 'OCEAN_WAVE' || proj.type === 'TIME_PRISON') {
              // Habilidades que seguem o player ou expandem a partir dele
              if (proj.type === 'OCEAN_WAVE') proj.radius += dt * 100;
              else { proj.x = p.x; proj.y = p.y; }
          } else {
              if (proj.type === 'ARCANE_COLOSSUS') {
                  // Seeker logic for Colossus
                   let closest = null; let minD = Infinity;
                   for(const e of enemiesRef.current) { const d = Math.hypot(e.x - proj.x, e.y - proj.y); if (d < minD) { minD = d; closest = e; } }
                   if (closest) {
                       const angle = Math.atan2(closest.y - proj.y, closest.x - proj.x);
                       proj.vx += Math.cos(angle) * 1000 * dt; proj.vy += Math.sin(angle) * 1000 * dt;
                       // Drag
                       proj.vx *= 0.95; proj.vy *= 0.95;
                   }
              }
              proj.x += proj.vx * dt; proj.y += proj.vy * dt;
          }

          // --- VISUAL TRAILS ---
          if (!proj.isEnemy && proj.duration > 0) {
             if (proj.type === 'ARROW') { if (Math.random() > 0.5) createParticle(proj.x, proj.y, proj.z, 'rgba(255,255,255,0.3)', 1, 'TRAIL'); }
             else if (proj.type === 'MAGIC_ORB' || proj.type === 'ENEMY_BOLT' || proj.type === 'ARCANE_COLOSSUS') { if (Math.random() > 0.2) createParticle(proj.x + (Math.random()-0.5)*10, proj.y + (Math.random()-0.5)*10, proj.z, proj.color, 1, 'MAGIC'); }
             else if (proj.type === 'AUTO_FIREBALL' || proj.type === 'FIRE_ZONE' || proj.type === 'HELL_FLAME') { if (Math.random() > 0.3) createParticle(proj.x + (Math.random()-0.5)*proj.radius, proj.y + (Math.random()-0.5)*proj.radius, proj.z, proj.color, 1, 'FIRE'); }
             else if (proj.type === 'SPIRIT_WAVE') { createParticle(proj.x, proj.y, proj.z, proj.color, 1, 'MAGIC'); }
          }
          if (Math.abs(proj.x - p.x) > 1500 || Math.abs(proj.y - p.y) > 1500) return false;

          if (proj.isEnemy) {
              const dist = Math.hypot(proj.x - p.x, proj.y - p.y);
              if (proj.type === 'LICH_DRAIN_ZONE') {
                  if (dist < proj.radius) { takeDamage(p, proj.damage * dt); const lich = enemiesRef.current.find(e => e.type === 'BOSS_LICH'); if (lich && lich.hp < lich.maxHp) { lich.hp += proj.damage * dt * 0.5; } }
              } else if (dist < (proj.type === 'BOSS_SMASH' ? proj.radius : 20)) { takeDamage(p, proj.damage); return false; 
              } else if (dist < proj.radius) { takeDamage(p, proj.damage); if (proj.type === 'POISON_SPIT') { p.slowTimer = 1.0; } return false; }
          }
          return proj.duration > 0;
      });
  };

  const createDamageNumber = (x: number, y: number, z: number, val: number, crit: boolean, isPlayerDamage = false, isBlocked = false) => {
      if (val < 1 && !isBlocked) return;
      damageNumbersRef.current.push({
          id: Math.random().toString(), x: x + (Math.random()-0.5)*20, y, z, value: val, life: 0.8, isCrit: crit, isPlayerDamage
      });
  };

  const useMainAttack = (stats: any) => {
     const p = playerRef.current;
     const angle = p.facing;
     const vx = Math.cos(angle) * 800; const vy = Math.sin(angle) * 800;
     const atkSpdMultiplier = Math.max(0.1, stats.attackSpeed);

     if (p.archetype === Archetype.WARRIOR) {
         projectilesRef.current.push({
             id: Math.random().toString(), x: p.x, y: p.y, z: 20, vx: 0, vy: 0,
             damage: stats.damage, duration: 0.3, radius: 100 * stats.areaSize,
             type: 'SWORD_SLASH', color: '#60a5fa', pierce: 999
         });
         p.weaponTimer = (0.6 / atkSpdMultiplier) * (1 - stats.cooldownReduction);
     } else {
         projectilesRef.current.push({
             id: Math.random().toString(), x: p.x, y: p.y, z: 30, vx, vy,
             damage: stats.damage, duration: 1.5, radius: 15,
             type: p.archetype === Archetype.ARCHER ? 'ARROW' : 'MAGIC_ORB', 
             color: p.color, pierce: p.archetype === Archetype.MAGE ? 2 : 0
         });
         const baseCd = p.archetype === Archetype.ARCHER ? 0.4 : 0.5;
         p.weaponTimer = (baseCd / atkSpdMultiplier) * (1 - stats.cooldownReduction);
     }
  };

  const useSkill1 = (stats: any) => {
      const p = playerRef.current;
      createParticle(p.x, p.y, 20, '#fff', 10); shakeRef.current = 5; 
      if(p.archetype === Archetype.WARRIOR) {
          projectilesRef.current.push({
             id: Math.random().toString(), x: p.x, y: p.y, z: 20, vx: 0, vy: 0,
             damage: stats.damage * 2.5, duration: 0.5, radius: 160 * stats.areaSize, type: 'SWORD_SLASH', color: '#ef4444', pierce: 999
         });
      } else {
          projectilesRef.current.push({
             id: Math.random().toString(), x: mouseWorldRef.current.x, y: mouseWorldRef.current.y, z: 0, vx: 0, vy: 0,
