                      {hudData.dashCd > 0 && hudData.dashCharges < hudData.dashMax && <div className="absolute inset-0 bg-black/70 flex items-center justify-center font-bold text-white text-2xl font-mono">{Math.ceil(hudData.dashCd)}</div>}
                  </div>
                  <div className={`relative w-20 h-20 rounded-xl border-2 flex flex-col items-center justify-center overflow-hidden transition-all duration-200
                      ${hudData.activeItem ? 'bg-amber-950/60 border-amber-500' : 'bg-slate-900 border-slate-800 opacity-40 border-dashed'}`}>
                      {hudData.activeItem ? (<> <span className="text-3xl filter drop-shadow-lg">{hudData.activeItem.icon}</span> <span className="absolute bottom-1 right-2 text-[10px] font-bold text-amber-200">R</span> </>) : <Box size={24} className="text-slate-600" />}
                      {hudData.itemCd > 0 && <div className="absolute inset-0 bg-black/70 flex items-center justify-center font-bold text-white text-2xl font-mono">{Math.ceil(hudData.itemCd)}</div>}
                  </div>
              </div>

              <div className="flex flex-col gap-2">
                 {hudData.autoItems.map((item, idx) => (
                    <div key={idx} className={`w-12 h-12 border rounded-lg flex items-center justify-center relative overflow-hidden
                       ${item.id.includes('leg_') ? 'bg-amber-950/60 border-amber-500/50 shadow-amber-500/20 shadow-lg' : 'bg-purple-950/60 border-purple-500/50'}
                    `}>
                        <span className="text-xl z-10">{item.icon}</span>
                        <div className={`absolute bottom-0 left-0 h-1 transition-all duration-100 ${item.id.includes('leg_') ? 'bg-amber-400' : 'bg-purple-400'}`} style={{width: `${(1 - (item.timer / item.cooldown)) * 100}%`}}></div>
                    </div>
                 ))}
                 {hudData.autoItems.length === 0 && <div className="w-12 h-12 border border-slate-800 border-dashed rounded-lg flex items-center justify-center opacity-30"><Zap size={16} /></div>}
              </div>

              {hudData.state === GameState.TOWER && (
                  <div className="bg-slate-900/95 border border-slate-700 rounded-2xl p-5 backdrop-blur-md shadow-2xl w-40 text-center flex flex-col justify-center h-[124px]">
                      <div className="text-3xl font-mono font-bold text-white mb-2 tracking-widest">{formatTime(hudData.time)}</div>
                      <div className="text-xs text-slate-400 flex items-center justify-center gap-2 font-serif uppercase tracking-wider border-t border-slate-800 pt-2">
                          <Skull size={14} className="text-red-500" /> WAVE {hudData.wave}
                      </div>
                      {hudData.weather !== 'NONE' && (
                          <div className={`text-[10px] animate-pulse mt-1 font-serif font-bold uppercase
                              ${hudData.weather === 'RAIN' ? 'text-blue-300' : ''}
                              ${hudData.weather === 'STORM' ? 'text-purple-300' : ''}
                              ${hudData.weather === 'SANDSTORM' ? 'text-amber-500' : ''}
                              ${hudData.weather === 'FOG' ? 'text-emerald-200' : ''}
                              ${hudData.weather === 'WIND' ? 'text-slate-300' : ''}
                          `}>
                              {hudData.weather === 'SANDSTORM' ? 'Tempestade de Areia' : 
                               hudData.weather === 'FOG' ? 'Neblina Densa' :
                               hudData.weather === 'WIND' ? 'Vendaval' :
                               hudData.weather === 'STORM' ? 'Tempestade' : 'Chuva'}
                          </div>
                      )}
                  </div>
              )}
          </div>
      </div>

      {hudData.buffTime > 0 && (
          <div className="absolute top-20 w-full flex justify-center pointer-events-none">
               <div className="bg-amber-500/20 border border-amber-400/50 px-6 py-2 rounded-full backdrop-blur-sm text-amber-200 font-bold animate-pulse shadow-[0_0_20px_rgba(251,191,36,0.4)]">
                   AVATAR DA DEUSA: {Math.ceil(hudData.buffTime)}s
               </div>
          </div>
      )}

      {hudData.state === GameState.ISLAND && (
          <div className="absolute top-20 w-full text-center pointer-events-none animate-bounce">
              <span className="bg-slate-900/90 px-8 py-4 rounded-full text-slate-100 border border-blue-500/50 shadow-[0_0_20px_rgba(59,130,246,0.4)] font-serif tracking-widest text-lg">
                  Siga para o Portal Azul
              </span>
          </div>
      )}

      {showUpgrade && (
        <UpgradeModal options={upgradeOptions} memoryOption={lastUpgrade} onSelect={applyUpgrade} />
      )}
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { Player, Enemy, Projectile, GameState, Archetype, Particle, DamageNumber, Upgrade, Item, StaticObject, AutoItem, WeatherType, BiomeType } from '../types';
import { CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, BASE_STATS, WAVE_CONFIGS, UPGRADES_LIST, SKILL_CONFIG, ZOOM_LEVEL, LEVEL_CONFIGS, BIOME_COLORS } from '../constants';
import { UpgradeModal } from './UpgradeModal';
import { Heart, Skull, Sword, Box, Crosshair, Wind, Zap } from 'lucide-react';

interface GameCanvasProps {
  archetype: Archetype;
  onGameOver: () => void;
}

// --- MATH UTILS ---
const toIso = (x: number, y: number, z: number = 0) => {
  return { x: (x - y), y: (x + y) / 2 - z };
};

const toWorldFromIso = (isoX: number, isoY: number) => {
    return { x: isoY + isoX / 2, y: isoY - isoX / 2 };
};

const lerp = (start: number, end: number, t: number) => {
  return start * (1 - t) + end * t;
};

const pseudoRandom = (x: number, y: number) => {
    return Math.abs(Math.sin(x * 12.9898 + y * 78.233) * 43758.5453) % 1;
};

// Optimized Color Adjust
const adjustColor = (color: string, amount: number) => {
    const num = parseInt(color.replace('#', ''), 16);
    let r = (num >> 16) + amount;
    let b = ((num >> 8) & 0x00FF) + amount;
    let g = (num & 0x0000FF) + amount;
    r = r > 255 ? 255 : r < 0 ? 0 : r;
    b = b > 255 ? 255 : b < 0 ? 0 : b;
    g = g > 255 ? 255 : g < 0 ? 0 : g;
    return "#" + (g | (b << 8) | (r << 16)).toString(16).padStart(6, '0');
};

const PORTAL_POS = { x: -400, y: -400 };

export const GameCanvas: React.FC<GameCanvasProps> = ({ archetype, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Game State Refs
  const gameStateRef = useRef<GameState>(GameState.ISLAND);
  const playerRef = useRef<Player>({
    x: 0, y: 0, z: 0,
    archetype,
    stats: JSON.parse(JSON.stringify(BASE_STATS[archetype])),
    level: 1, xp: 0, xpToNextLevel: 100,
    weaponTimer: 0, skill1Timer: 0, skill1MaxCooldown: SKILL_CONFIG[archetype].skill1Cd,
    dashTimer: 0, 
    dashMaxCooldown: SKILL_CONFIG[archetype].dashCd,
    dashCharges: BASE_STATS[archetype].dashChargesMax,
    activeItem: null, itemTimer: 0, itemMaxCooldown: 0,
    autoItems: [], 
    facing: 0, isMoving: false, color: COLORS[archetype], animFrame: 0,
    slowTimer: 0, lastHitTime: 0, avatarBuffTimer: 0
  });

  const enemiesRef = useRef<Enemy[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const damageNumbersRef = useRef<DamageNumber[]>([]);
  const staticObjectsRef = useRef<StaticObject[]>([]);
  const keysRef = useRef<{ [key: string]: boolean }>({});

  // System Refs
  const cameraRef = useRef({ x: 0, y: 0 }); 
  const shakeRef = useRef(0); 
  const timeRef = useRef<number>(0); 
  const waveRef = useRef<number>(0);
  const waveTimerRef = useRef<number>(0);
  const lastSpawnTimeRef = useRef<number>(0);
  const bossSpawnedRef = useRef<boolean>(false); 

  // Dynamic Weather System
  const weatherTypeRef = useRef<WeatherType>('NONE');
  const weatherIntensityRef = useRef<number>(0); 
  const particleTimerRef = useRef<number>(0);
  const windForceRef = useRef({ x: 0, y: 0 }); 

  // UI State
  const [showUpgrade, setShowUpgrade] = useState(false);
  const [upgradeOptions, setUpgradeOptions] = useState<Upgrade[]>([]);
  const [lastUpgrade, setLastUpgrade] = useState<Upgrade | null>(null);
  const [hudData, setHudData] = useState({ 
      hp: 100, maxHp: 100, xp: 0, xpNext: 100, time: 0, wave: 1, level: 1, 
      state: GameState.ISLAND, skill1Cd: 0, dashCd: 0, itemCd: 0, dashCharges: 0, dashMax: 0,
      activeItem: null as Item | null, bossHp: 0, bossMaxHp: 0,
      autoItems: [] as AutoItem[],
      buffTime: 0,
      weather: 'NONE' as WeatherType,
      biome: 'FOREST' as BiomeType
  });

  const mouseScreenRef = useRef({ x: 0, y: 0 }); 
  const mouseWorldRef = useRef({ x: 0, y: 0 });
  const reticleAngleRef = useRef(0);

  const createParticle = (x: number, y: number, z: number, color: string, size: number, type: any = 'PARTICLE') => {
      let vx = (Math.random() - 0.5) * 100;
      let vy = (Math.random() - 0.5) * 100;
      let vz = (Math.random() * 150) + 50;
      let life = 1.0;

      if (type === 'BLOOD') { life = 0.5; }
      if (type === 'SPARK') { vz = 100; life = 0.5; }
      if (type === 'TRAIL') { vx=0; vy=0; vz=0; life=0.3; }

      particlesRef.current.push({
          id: Math.random().toString(),
          x, y, z,
          vx, vy, vz,
          life, maxLife: life,
          color, size, type
      });
  };

  // --- INIT ---
  useEffect(() => {
    if (gameStateRef.current === GameState.ISLAND) {
        const objects: StaticObject[] = [];
        objects.push({ id: 'portal', x: PORTAL_POS.x, y: PORTAL_POS.y, type: 'PORTAL', size: 140 });
        objects.push({ id: 'h1', x: -150, y: -150, type: 'HOUSE', size: 110, variant: 0 });
        objects.push({ id: 'h2', x: 250, y: -250, type: 'HOUSE', size: 130, variant: 1 });
        objects.push({ id: 'h3', x: -350, y: 100, type: 'HOUSE', size: 100, variant: 0 });
        objects.push({ id: 'h4', x: 150, y: 200, type: 'HOUSE', size: 120, variant: 1 });
        objects.push({ id: 'h5', x: -50, y: 350, type: 'HOUSE', size: 90, variant: 0 });
        const lampPositions = [{x: 0, y: -300}, {x: -250, y: -300}, {x: -300, y: -250}, {x: -100, y: -100}, {x: 100, y: -200}, {x: -200, y: 50}];
        lampPositions.forEach((p, i) => objects.push({ id: `lamp${i}`, x: p.x, y: p.y, type: 'LAMP', size: 20 }));

        for(let i=0; i<150; i++) {
            const angle = Math.random() * Math.PI * 2;
            const dist = 300 + Math.random() * 900;
            const x = Math.cos(angle) * dist;
            const y = Math.sin(angle) * dist;
            let collides = false;
            for(const obj of objects) { if (Math.hypot(x - obj.x, y - obj.y) < obj.size * 0.8) collides = true; }
            if (Math.hypot(x - PORTAL_POS.x, y - PORTAL_POS.y) < 250) collides = true;

            if (!collides) {
                const r = Math.random();
                if (r < 0.6) { objects.push({ id: `t${i}`, x, y, type: 'TREE', size: 50 + Math.random() * 70, variant: Math.random() > 0.5 ? 1 : 0 }); } 
                else if (r < 0.85) { objects.push({ id: `b${i}`, x, y, type: 'BUSH', size: 20 + Math.random() * 15, variant: Math.random() > 0.5 ? 1 : 0 }); } 
                else { objects.push({ id: `r${i}`, x, y, type: 'ROCK', size: 15 + Math.random() * 25 }); }
            }
        }
        staticObjectsRef.current = objects;
    }
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { if (e.code === 'Space') e.preventDefault(); keysRef.current[e.code] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keysRef.current[e.code] = false; };
    const handleMouseMove = (e: MouseEvent) => {
      const rect = canvasRef.current?.getBoundingClientRect();
      if(rect) { mouseScreenRef.current = { x: e.clientX - rect.left - rect.width / 2, y: e.clientY - rect.top - rect.height / 2 }; }
    };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) keysRef.current['MouseLeft'] = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) keysRef.current['MouseLeft'] = false; };
    const handleContextMenu = (e: MouseEvent) => e.preventDefault();

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    window.addEventListener('contextmenu', handleContextMenu);

    let animationFrameId: number;
    let lastTime = performance.now();

    const loop = (timestamp: number) => {
      const dtRaw = (timestamp - lastTime) / 1000;
      const dt = Math.min(dtRaw, 0.1); 
      lastTime = timestamp;

      if (gameStateRef.current === GameState.TOWER || gameStateRef.current === GameState.ISLAND) {
        update(dt);
      }
      draw(dt);
      animationFrameId = requestAnimationFrame(loop);
    };

    animationFrameId = requestAnimationFrame(loop);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
      window.removeEventListener('contextmenu', handleContextMenu);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  // --- UPDATE ---
  const update = (dt: number) => {
    const player = playerRef.current;

    // Effective Stats
    const activeStats = { ...player.stats };
    if (player.avatarBuffTimer > 0) {
        player.avatarBuffTimer -= dt;
        activeStats.damage *= 1.3;
        activeStats.speed *= 1.3;
        activeStats.cooldownReduction += 0.2;
        if (player.avatarBuffTimer <= 0) player.avatarBuffTimer = 0;
    }

    // Camera
    const playerIso = toIso(player.x, player.y, player.z);
    const targetX = (-playerIso.x) - (mouseScreenRef.current.x / ZOOM_LEVEL) * 0.25;
    const targetY = (-playerIso.y) - (mouseScreenRef.current.y / ZOOM_LEVEL) * 0.25;
    cameraRef.current.x = lerp(cameraRef.current.x, targetX, 0.08);
    cameraRef.current.y = lerp(cameraRef.current.y, targetY, 0.08);

    // Mouse World
    const mouseIsoX = (mouseScreenRef.current.x / ZOOM_LEVEL) - cameraRef.current.x;
    const mouseIsoY = (mouseScreenRef.current.y / ZOOM_LEVEL) - cameraRef.current.y;
    mouseWorldRef.current = toWorldFromIso(mouseIsoX, mouseIsoY);

    const distMouse = Math.hypot(mouseWorldRef.current.x - player.x, mouseWorldRef.current.y - player.y);
    if (distMouse > 40) player.facing = Math.atan2(mouseWorldRef.current.y - player.y, mouseWorldRef.current.x - player.x);
    reticleAngleRef.current = player.facing; 

    // --- MOVEMENT & WIND PHYSICS ---
    let dx = 0; let dy = 0;
    if (keysRef.current['KeyW'] || keysRef.current['ArrowUp']) { dx -= 1; dy -= 1; }
    if (keysRef.current['KeyS'] || keysRef.current['ArrowDown']) { dx += 1; dy += 1; }
    if (keysRef.current['KeyA'] || keysRef.current['ArrowLeft']) { dx -= 1; dy += 1; }
    if (keysRef.current['KeyD'] || keysRef.current['ArrowRight']) { dx += 1; dy -= 1; }

    // Apply Wind Force
    let windDx = 0; let windDy = 0;
    if (gameStateRef.current === GameState.TOWER && (weatherTypeRef.current === 'WIND' || weatherTypeRef.current === 'STORM' || weatherTypeRef.current === 'SANDSTORM')) {
        windDx = windForceRef.current.x * weatherIntensityRef.current;
        windDy = windForceRef.current.y * weatherIntensityRef.current;
    }

    player.isMoving = dx !== 0 || dy !== 0;
    if (player.isMoving || Math.abs(windDx) > 0.1) {
      const length = Math.sqrt(dx * dx + dy * dy);
      if (length > 0) { dx /= length; dy /= length; }

      let currentSpeed = activeStats.speed * 60;
      if (player.slowTimer > 0) { player.slowTimer -= dt; currentSpeed *= 0.6; }

      const newX = player.x + (dx * currentSpeed + windDx * 30) * dt; 
      const newY = player.y + (dy * currentSpeed + windDy * 30) * dt;

      // Collision
      let canMoveX = true; let canMoveY = true;
      if (gameStateRef.current === GameState.ISLAND) {
          const playerRadius = 15;
          staticObjectsRef.current.forEach(obj => {
              if (obj.type === 'PORTAL' || obj.type === 'BUSH') return;
