import React, { useState } from 'react';
import { MainMenu } from './components/MainMenu';
import { CharacterSelection } from './components/CharacterSelection';
import { GameCanvas } from './components/GameCanvas';
import { GameState, Archetype } from './types';
import { Skull, RotateCcw, Home } from 'lucide-react';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [selectedArchetype, setSelectedArchetype] = useState<Archetype>(Archetype.WARRIOR);

  const handlePlayClick = () => {
    setGameState(GameState.CHAR_SELECT);
  };

  const handleStartGame = (archetype: Archetype) => {
    setSelectedArchetype(archetype);
    setGameState(GameState.ISLAND); // Starts at the Island Lobby
  };

  const handleGameOver = () => {
    setGameState(GameState.GAME_OVER);
  };

  const handleReturnToLobby = () => {
    setGameState(GameState.MENU);
  };

  return (
    <div className="w-screen h-screen overflow-hidden bg-slate-950 font-sans select-none text-white">

      {gameState === GameState.MENU && (
        <MainMenu onPlay={handlePlayClick} />
      )}

      {gameState === GameState.CHAR_SELECT && (
        <CharacterSelection onStart={handleStartGame} onBack={() => setGameState(GameState.MENU)} />
      )}

      {(gameState === GameState.ISLAND || gameState === GameState.TOWER || gameState === GameState.PAUSED) && (
        <GameCanvas 
          archetype={selectedArchetype} 
          onGameOver={handleGameOver} 
        />
      )}

      {gameState === GameState.GAME_OVER && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/90 animate-in fade-in zoom-in duration-500">
          <div className="text-center p-8 bg-slate-900 border border-red-900 rounded-2xl shadow-2xl shadow-red-900/20 max-w-md w-full">
            <Skull size={80} className="mx-auto text-red-500 mb-6 animate-bounce" />
            <h2 className="text-5xl font-bold text-red-500 mb-2 font-serif">FIM DE JOGO</h2>
            <p className="text-slate-400 mb-8">A Torre rejeitou sua alma... por enquanto.</p>

            <div className="space-y-4">
                <button
                onClick={() => setGameState(GameState.ISLAND)}
                className="w-full py-4 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg flex items-center justify-center gap-2 transition-all hover:scale-105"
                >
                <RotateCcw /> Tentar Novamente
                </button>
                <button
                onClick={handleReturnToLobby}
                className="w-full py-4 bg-slate-800 hover:bg-slate-700 text-slate-300 font-bold rounded-lg flex items-center justify-center gap-2 transition-all hover:scale-105"
                >
                <Home /> Voltar ao Menu
                </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

