  const drawIsoSprite = (ctx: CanvasRenderingContext2D, entity: any, type: string) => {
      // 1. Telegraph
      if (['SLIME','GOBLIN','DEMON','BOSS','SORCERER', 'BOSS_GOLEM', 'BOSS_LICH', 'SNAKE'].includes(type) && entity.state === 'WINDUP') {
          const iso = toIso(entity.x, entity.y, 0); const progress = Math.max(0, 1 - (entity.stateTimer / entity.windupTime)); const radius = Math.max(1, entity.attackRange * (type === 'BOSS_LICH' ? 0.3 : 1.5));
          ctx.save(); ctx.strokeStyle = type === 'BOSS_LICH' ? 'rgba(16, 185, 129, 0.6)' : 'rgba(239, 68, 68, 0.6)'; ctx.lineWidth = 3; ctx.beginPath(); ctx.ellipse(iso.x, iso.y, radius, radius * 0.5, 0, 0, Math.PI * 2); ctx.stroke();
          ctx.fillStyle = type === 'BOSS_LICH' ? 'rgba(16, 185, 129, 0.3)' : 'rgba(239, 68, 68, 0.3)'; ctx.beginPath(); ctx.ellipse(iso.x, iso.y, radius * progress, (radius * 0.5) * progress, 0, 0, Math.PI * 2); ctx.fill(); ctx.restore();
      }

      // 2. Hit Flash
      if (entity.hitFlash && entity.hitFlash > 0) {
          const { x, y } = toIso(entity.x, entity.y, entity.z); const h = (type.includes('BOSS')) ? 80 : 25; const w = (type.includes('BOSS')) ? 80 : 25;
          ctx.fillStyle = '#ffffff'; ctx.fillRect(x - w/2, y - h, w, h); return; 
      }

      const idOffset = parseFloat(entity.id || '0') || 0; let bounce = 0; let stretch = 1;
      if (['PLAYER', 'GOBLIN', 'DEMON', 'SORCERER', 'SLIME', 'SNAKE'].includes(type)) {
          const currentF = entity.animFrame || entity.frame || 0; const animVal = Math.sin(currentF + idOffset); bounce = Math.abs(animVal) * 3; stretch = 1 + (Math.cos(currentF + idOffset) * 0.05);
      }
      if (type === 'BOSS_LICH') { const floatVal = Math.sin(performance.now()/500); bounce = 20 + floatVal * 10; }

      // PROJECTED SHADOWS
      if (entity.z < 200 || type === 'BOSS_LICH' || type === 'BAT') {
          const shadowBase = toIso(entity.x, entity.y, 0); 
          ctx.save();
          if (type === 'HOUSE' || type === 'TREE' || type === 'PORTAL') {
              ctx.translate(shadowBase.x, shadowBase.y);
              ctx.transform(1, 0, -0.6, 0.6, 0, 0); 
              ctx.fillStyle = 'rgba(0,0,0,0.3)';

              if (type === 'HOUSE') {
                  const size = entity.size * 0.6; ctx.fillRect(-size/2, -size, size, size*1.5);
              } else if (type === 'TREE') {
                  const trunkW = entity.size * 0.15; ctx.fillRect(-trunkW/2, 0, trunkW, -entity.size * 0.2); ctx.beginPath(); ctx.arc(0, -entity.size*0.8, entity.size * 0.4, 0, Math.PI*2); ctx.fill(); 
              } else if (type === 'PORTAL') {
                  ctx.beginPath(); ctx.ellipse(0, -20, entity.size/2, entity.size/4, 0, 0, Math.PI*2); ctx.fill();
              }
          } else {
              let wS = 14; let hS = 7; if (type.includes('BOSS')) { wS = 50; hS = 25; } else if (type === 'BAT') { wS = 10; hS = 5; }
              ctx.fillStyle = 'rgba(0,0,0,0.4)'; ctx.beginPath(); ctx.ellipse(shadowBase.x, shadowBase.y, wS * stretch, hS * stretch, 0, 0, Math.PI*2); ctx.fill();
          }
          ctx.restore();
      }

      const { x, y } = toIso(entity.x, entity.y, entity.z + bounce);
      const layers = type.includes('BOSS') ? 14 : 7; const scale = 2;

      for(let i=0; i<layers; i++) {
          const ly = y - (i * scale * 2); let w = 20; 
          if (type === 'PLAYER') {
             if (entity.archetype === Archetype.WARRIOR) { w = 20; let color = '#334155'; if (i >= 5) { color = '#1d4ed8'; w = 16; } if (i === 4) { color = '#94a3b8'; w = 22; } ctx.fillStyle = color; ctx.fillRect(x - w/2, ly - w/2, w, w); } 
             else if (entity.archetype === Archetype.MAGE) { w = 18; let color = '#581c87'; if (i >= 5) { color = '#a855f7'; w = 12; } if (i === 6) { w = 8; } ctx.fillStyle = color; ctx.fillRect(x - w/2, ly - w/2, w, w); } 
             else { w = 16; let color = '#15803d'; if (i >= 5) { color = '#86efac'; w = 14; } ctx.fillStyle = color; ctx.fillRect(x - w/2, ly - w/2, w, w); }
          } else if (type === 'TREE') {
              const sway = Math.sin(performance.now()/1500 + entity.x/100) * (i * 0.8);
              if (i < 3) { w = entity.size * 0.15; ctx.fillStyle = '#271306'; ctx.fillRect(x - w/2 + sway*0.2, ly - w, w, w*1.5); } 
              else { let level = 0; if (i > 6) level = 1; if (i > 10) level = 2; let baseC = entity.variant === 1 ? 0x14532d : 0x166534; if (level === 1) baseC += 0x111111; if (level === 2) baseC += 0x222222; ctx.fillStyle = '#' + baseC.toString(16).padStart(6,'0'); const taper = 1 - ((i-3) / (layers)); w = entity.size * 0.8 * taper; const fh = 8; ctx.fillRect(x - w/2 + sway, ly - fh, w, fh); }
          } else if (type === 'HOUSE') {
              if (i < 6) { w = entity.size * 0.6; let h = entity.size * 0.5; ctx.fillStyle = i < 2 ? '#44403c' : '#f5f5f4'; ctx.fillRect(x - w/2, ly - h/2, w, h); if (i === 1) { ctx.fillStyle = '#292524'; ctx.fillRect(x - 8, ly - 5, 16, 20); } if (i === 4) { ctx.fillStyle = '#38bdf8'; ctx.fillRect(x - w/3, ly - 5, 10, 10); ctx.fillRect(x + w/3 - 10, ly - 5, 10, 10); } } else { const roofProgress = (i - 6); w = (entity.size * 0.7) - (roofProgress * 6); if (w < 0) w = 0; ctx.fillStyle = entity.variant === 1 ? '#1e3a8a' : '#7f1d1d'; if (i % 2 === 0) ctx.fillStyle = adjustColor(ctx.fillStyle as string, 20); ctx.fillRect(x - w/2, ly - 10, w, 14); }
          } else if (type === 'ROCK') { if (i < 3) { w = entity.size * (1 - i*0.2); ctx.fillStyle = '#57534e'; ctx.fillRect(x - w/2, ly - w/2, w, w); }
          } else if (type === 'BUSH') { if (i < 3) { const sway = Math.sin(performance.now()/800 + entity.x) * 2; w = entity.size * (1 - i*0.1); ctx.fillStyle = entity.variant === 1 ? '#4d7c0f' : '#15803d'; ctx.beginPath(); ctx.arc(x + sway, ly, w/2, 0, Math.PI*2); ctx.fill(); }
          } else if (type === 'LAMP') { w = 4; if (i < 8) ctx.fillStyle = '#1c1917'; else { ctx.fillStyle = '#f59e0b'; ctx.shadowBlur = 20; ctx.shadowColor = '#d97706'; w = 8; } ctx.fillRect(x - w/2, ly - w*2, w, w*2); ctx.shadowBlur = 0;
          } else if (type === 'PORTAL') { const t = performance.now() / 1000; if (i < 2) { w = entity.size; ctx.fillStyle = '#312e81'; ctx.beginPath(); ctx.ellipse(x, ly, w/2, w/4, 0, 0, Math.PI*2); ctx.fill(); } if (i === 2) { ctx.save(); ctx.translate(x, ly - 50); for(let r=0; r<3; r++) { ctx.rotate(t * (r%2 === 0 ? 1 : -1)); ctx.strokeStyle = r === 0 ? '#4f46e5' : (r === 1 ? '#818cf8' : '#c7d2fe'); ctx.lineWidth = 3; ctx.beginPath(); ctx.ellipse(0, 0, entity.size/3 - r*10, entity.size/1.5 - r*20, t + r, 0, Math.PI*2); ctx.stroke(); } ctx.restore(); const glowSize = 20 + Math.sin(t*3)*5; ctx.fillStyle = 'rgba(99, 102, 241, 0.4)'; ctx.beginPath(); ctx.arc(x, ly - 50, glowSize, 0, Math.PI*2); ctx.fill(); }
          } else if (type === 'BAT') { if (i < 4) { w = 12; ctx.fillStyle = '#1e293b'; ctx.fillRect(x - w/2, ly - w/2, w, w); const flap = Math.sin(entity.frame * 20) * 10; ctx.fillStyle = '#334155'; ctx.beginPath(); ctx.moveTo(x - w/2, ly); ctx.lineTo(x - w/2 - 15, ly - flap); ctx.lineTo(x - w/2 - 5, ly + 5); ctx.fill(); ctx.beginPath(); ctx.moveTo(x + w/2, ly); ctx.lineTo(x + w/2 + 15, ly - flap); ctx.lineTo(x + w/2 + 5, ly + 5); ctx.fill(); }
          } else if (type === 'SNAKE') { if (i < 6) { const wobble = Math.sin((entity.frame * 10) + (i * 0.5)) * 10; const bx = x + wobble; const by = ly + (i * 4); w = 14 - i; ctx.fillStyle = i === 0 ? '#4ade80' : '#3f6212'; if (i === 0) { ctx.fillStyle = '#84cc16'; ctx.fillRect(bx - w/2, ly, w, w); ctx.fillStyle = 'red'; ctx.fillRect(bx - 3, ly + 2, 2, 2); ctx.fillRect(bx + 1, ly + 2, 2, 2); } else { ctx.beginPath(); ctx.arc(bx, by, w/2, 0, Math.PI*2); ctx.fill(); } }
          } else if (type === 'BOSS_GOLEM') { w = 80 - i*2; let h = 80 - i*2; const isEnraged = entity.hp < entity.maxHp * 0.5; ctx.fillStyle = i % 3 === 0 ? '#44403c' : '#57534e'; if (isEnraged) ctx.fillStyle = i % 3 === 0 ? '#7f1d1d' : '#991b1b'; if (i === 8 || i === 9) ctx.fillStyle = '#f59e0b'; ctx.fillRect(x - w/2, ly - h/2, w, h); if (i === 6) { ctx.fillStyle = isEnraged ? '#450a0a' : '#292524'; ctx.fillRect(x - w - 20, ly, 40, 40); ctx.fillRect(x + w - 20, ly, 40, 40); }
          } else if (type === 'BOSS_LICH') { 
              w = 40; ctx.fillStyle = '#3b0764'; 
              if (i === 12) {
                  // Head details
                  ctx.fillStyle = '#e9d5ff'; ctx.fillRect(x - 10, ly - 10, 20, 20); // Skull
                  ctx.fillStyle = '#ef4444'; ctx.fillRect(x - 6, ly - 4, 4, 4); ctx.fillRect(x + 2, ly - 4, 4, 4); // Eyes
              } else {
                  ctx.fillRect(x - w/2, ly - w/2, w, w);
              }
          } else {
              // Generic fallback (Slimes etc)
              w = 25 - i * 2; 
              if (type === 'DEMON') { ctx.fillStyle = '#ef4444'; w = 30 - i*2; }
              else if (type === 'SORCERER') { ctx.fillStyle = '#a855f7'; w = 25 - i*1.5; }
              else if (type === 'GOBLIN') { ctx.fillStyle = '#22c55e'; }
              else { ctx.fillStyle = '#3b82f6'; } // SLIME
              ctx.fillRect(x - w/2, ly - w/2, w, w);
          }
      }
  };

  return (
    <>
      <canvas
        ref={canvasRef}
        className="block fixed inset-0 z-0 bg-slate-950"
      />

      {/* HUD Layer */}
      <div className="absolute inset-0 z-10 pointer-events-none">
           <div className="absolute top-4 left-4 flex flex-col gap-2">
               {/* HP Bar */}
               <div className="w-64 h-6 bg-slate-900 border border-slate-700 rounded-full overflow-hidden relative">
                   <div className="h-full bg-red-600 transition-all duration-200" style={{ width: `${(hudData.hp / hudData.maxHp) * 100}%` }}></div>
                   <div className="absolute inset-0 flex items-center justify-center text-xs font-bold text-white shadow-black drop-shadow-md">
                       {Math.ceil(hudData.hp)} / {Math.ceil(hudData.maxHp)}
                   </div>
               </div>

               {/* XP Bar */}
               <div className="w-64 h-2 bg-slate-900 border border-slate-800 rounded-full overflow-hidden">
                   <div className="h-full bg-amber-400 transition-all duration-200" style={{ width: `${(hudData.xp / hudData.xpNext) * 100}%` }}></div>
               </div>

               <div className="text-white font-mono text-sm drop-shadow-md">
                   LVL {hudData.level} | WAVE {hudData.wave} | {Math.floor(hudData.time / 60)}:{(Math.floor(hudData.time) % 60).toString().padStart(2, '0')}
               </div>
           </div>

           {/* Skills HUD */}
           <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-end gap-4">
               {/* Dash */}
               <div className="flex flex-col items-center gap-1">
                   <div className={`w-12 h-12 rounded border-2 flex items-center justify-center relative bg-slate-900 ${hudData.dashCharges > 0 ? 'border-white' : 'border-slate-600'}`}>
                       <Wind size={20} className={hudData.dashCharges > 0 ? 'text-white' : 'text-slate-500'} />
                       <div className="absolute bottom-0 right-0 bg-slate-700 text-[10px] px-1">{hudData.dashCharges}</div>
                       {hudData.dashCd > 0 && <div className="absolute inset-0 bg-black/50 flex items-center justify-center text-xs font-bold">{hudData.dashCd.toFixed(1)}</div>}
                   </div>
                   <span className="text-[10px] font-bold text-slate-400">SPACE/E</span>
               </div>

               {/* Skill 1 */}
               <div className="flex flex-col items-center gap-1">
                   <div className={`w-14 h-14 rounded border-2 flex items-center justify-center relative bg-slate-900 ${hudData.skill1Cd <= 0 ? 'border-blue-400 shadow-[0_0_10px_rgba(96,165,250,0.5)]' : 'border-slate-600'}`}>
                       <Zap size={24} className={hudData.skill1Cd <= 0 ? 'text-blue-400' : 'text-slate-500'} />
                       {hudData.skill1Cd > 0 && <div className="absolute inset-0 bg-black/50 flex items-center justify-center text-sm font-bold">{hudData.skill1Cd.toFixed(1)}</div>}
                   </div>
                   <span className="text-[10px] font-bold text-slate-400">Q</span>
               </div>

               {/* Item */}
               <div className="flex flex-col items-center gap-1">
                    <div className={`w-12 h-12 rounded border-2 flex items-center justify-center relative bg-slate-900 ${hudData.activeItem && hudData.itemCd <= 0 ? 'border-purple-400' : 'border-slate-600'}`}>
                       {hudData.activeItem ? <span className="text-2xl">{hudData.activeItem.icon}</span> : <Box size={20} className="text-slate-700" />}
                       {hudData.itemCd > 0 && <div className="absolute inset-0 bg-black/50 flex items-center justify-center text-xs font-bold">{hudData.itemCd.toFixed(1)}</div>}
                   </div>
                   <span className="text-[10px] font-bold text-slate-400">R</span>
               </div>
           </div>

           {/* Boss Health */}
           {hudData.bossHp > 0 && (
               <div className="absolute top-20 left-1/2 -translate-x-1/2 w-96 max-w-full px-4">
                   <div className="text-center text-red-500 font-black tracking-widest text-lg mb-1 drop-shadow-md">BOSS</div>
                   <div className="h-6 w-full bg-slate-900 border-2 border-red-900 rounded relative overflow-hidden">
                       <div className="h-full bg-red-700 transition-all duration-100" style={{ width: `${(hudData.bossHp / hudData.bossMaxHp) * 100}%` }}></div>
                   </div>
               </div>
           )}

           {/* Level Title */}
           {levelTitle && (
                <div className="absolute top-1/3 left-0 w-full text-center animate-in zoom-in fade-in duration-1000 fill-mode-forwards">
                    <h1 className="text-6xl font-black text-transparent bg-clip-text bg-gradient-to-b from-amber-100 to-amber-600 drop-shadow-lg font-serif tracking-widest">{levelTitle.title}</h1>
                    <h2 className="text-2xl text-slate-300 font-mono tracking-widest mt-2">{levelTitle.subtitle}</h2>
                </div>
           )}
      </div>

      {showUpgrade && (
          <UpgradeModal 
             options={upgradeOptions} 
             memoryOption={null}
             onSelect={applyUpgrade} 
          />
      )}
    </>
  );
};

export enum GameState {
  MENU = 'MENU',
  CHAR_SELECT = 'CHAR_SELECT',
  ISLAND = 'ISLAND',
  TOWER = 'TOWER',
  PAUSED = 'PAUSED',
  GAME_OVER = 'GAME_OVER',
  VICTORY = 'VICTORY'
}

export enum Archetype {
  WARRIOR = 'WARRIOR',
  ARCHER = 'ARCHER',
  MAGE = 'MAGE'
}

export type WeatherType = 'NONE' | 'RAIN' | 'FOG' | 'WIND' | 'STORM' | 'SANDSTORM';

export type BiomeType = 'FOREST' | 'ICE' | 'DESERT' | 'SWAMP' | 'DEMON' | 'DEFAULT';

export interface Stats {
  maxHp: number;
  hp: number;
  damage: number;
  speed: number;
  defense: number;
  cooldownReduction: number;
  pickupRange: number;
  areaSize: number;
  // Novos Atributos
  armorPenetration: number;
  lifeSteal: number; // Porcentagem curada ao matar (0.0 a 1.0)
  dashChargesMax: number;
  attackSpeed: number; // Multiplicador de velocidade de ataque (ex: 1.0, 1.5)
  damageReduction: number; // Porcentagem de redução (ex: 0.1 = 10%)

  // Novos Atributos (Update)
  critChance: number; // 0.0 a 1.0
  critDamage: number; // Multiplicador (base 1.5)
  regen: number; // HP por segundo
  executionerThreshold: number; // % de HP do inimigo para bônus de dano (0.0 se inativo)
  towerEchoStacks: number; // Stacks de "Eco da Torre"
  shieldOnLowHp: boolean; // Possui passiva de escudo
  shieldCooldown: number; // Cooldown atual do escudo
}

export interface Item {
  id: string;
  name: string;
  icon: string;
  cooldown: number;
  duration?: number;
  effect: (player: Player, enemies: Enemy[]) => void;
  description: string;
}

export interface AutoItem {
  id: string;
  name: string;
  icon: string;
  cooldown: number;
  timer: number;
  effect: (player: Player, enemies: Enemy[]) => Projectile | null | Projectile[]; // Pode retornar array
  description: string;
}

export interface Player {
  x: number;
  y: number;
  z: number;
  archetype: Archetype;
  stats: Stats;
  level: number;
  xp: number;
  xpToNextLevel: number;

  // Cooldowns
  weaponTimer: number;
  skill1Timer: number;
  skill1MaxCooldown: number;

  // Dash System
  dashTimer: number;      // Tempo para recarregar a próxima carga
  dashMaxCooldown: number; // Tempo base de recarga
  dashCharges: number;    // Cargas atuais

  // Item Slot (Manual - R)
  activeItem: Item | null;
  itemTimer: number;
  itemMaxCooldown: number;

  // Auto Skills Slots (Automático)
  autoItems: AutoItem[];

  // Status Effects
  slowTimer: number; // Tempo que o jogador fica lento ao tomar dano
  lastHitTime: number; // Tempo desde o último dano recebido (para passiva de regen)
  avatarBuffTimer: number; // Timer do buff "Avatar da Deusa"

  facing: number;
  isMoving: boolean;
  color: string;

  // Animation
  animFrame: number;
}

export type EnemyState = 'CHASING' | 'WINDUP' | 'ATTACKING' | 'RECOVERING' | 'CHANNELING' | 'FLEEING' | 'SWOOPING' | 'FROZEN';

export interface Enemy {
  id: string;
  x: number;
  y: number;
  z: number;
  type: 'SLIME' | 'GOBLIN' | 'SORCERER' | 'DEMON' | 'BOSS_GOLEM' | 'BOSS_LICH' | 'SNAKE' | 'BAT';
  isBoss: boolean;
  hp: number;
  maxHp: number;
  defense: number; // Nova defesa
  speed: number;
  damage: number;
  radius: number;
  hitboxRadius: number;
  frame: number;
  variant: number; // 0: Normal, 1: Swift/Weak, 2: Tank/Slow

  // AI State Machine
  state: EnemyState;
  stateTimer: number; // Tempo restante no estado atual
  attackRange: number; // Distância para iniciar ataque
  windupTime: number; // Tempo avisando o ataque
  recoverTime: number; // Tempo parado após ataque
  specialTimer?: number; // Timer para habilidades especiais do boss

  // Physics & Visuals
  vx: number; 
  vy: number; 
  hitFlash: number; 
  frozenTimer?: number; // Se > 0, inimigo está congelado
  knockbackResist?: number; // 0 a 1 (1 = imune)
}

export interface StaticObject {
  id: string;
  x: number;
  y: number;
  type: 'TREE' | 'HOUSE' | 'LAMP' | 'PORTAL' | 'ROCK' | 'BUSH';
  size: number;
  variant?: number; // Para cor da casa ou tipo de árvore
}

export interface Projectile {
  id: string;
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  damage: number;
  duration: number;
  radius: number;
  // Novos tipos adicionados
  type: 'ARROW' | 'MAGIC_ORB' | 'SWORD_SLASH' | 'BOSS_SMASH' | 'FIRE_ZONE' | 'ENEMY_BOLT' | 'GOLEM_SHOCKWAVE' | 'LICH_DRAIN_ZONE' | 'BOSS_ROCK' | 'LICH_NOVA' | 'POISON_SPIT' | 'AUTO_LIGHTNING' | 'AUTO_FIREBALL' | 
        'JUDGEMENT_STRIKE' | 'OCEAN_WAVE' | 'GODDESS_SEAL' | 'HELL_FLAME' | 'ARCANE_COLOSSUS' | 'TIME_PRISON' | 'EARTH_SPIKE' | 'MANA_SHARD' | 'SPIRIT_WAVE';
  color: string;
  pierce: number;
  isEnemy?: boolean; // Se true, da dano no player
  delayedDamage?: boolean; // Se true, só dá dano quando duration acaba ou timer específico
  knockbackForce?: number;
}

export interface Particle {
  id: string;
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  life: number;
  maxLife: number;
  color: string;
  size: number;
  type?: 'RAIN' | 'BLOOD' | 'SPARK' | 'POISON' | 'TELEPORT' | 'TRAIL' | 'MAGIC' | 'FIRE' | 'IMPACT' | 'SHOCKWAVE' | 'FROST' | 'FOG' | 'SAND';
}

export interface DamageNumber {
  id: string;
  x: number;
  y: number;
  z: number;
  value: number;
  life: number;
  isCrit: boolean;
  isPlayerDamage?: boolean; // Se true, é dano QUE O JOGADOR TOMOU (vermelho escuro)
}

export interface Upgrade {
  id: string;
  name: string;
  description: string;
  type: 'STAT' | 'WEAPON' | 'PASSIVE' | 'ITEM' | 'AUTO_ITEM';
  rarity: 'COMMON' | 'RARE' | 'EPIC' | 'LEGENDARY';
  itemRef?: Item;
  autoItemRef?: AutoItem; // Referência para auto skill
}

export interface WaveConfig {
  duration: number;
  enemyCount: number;
  spawnRate: number;
  boss?: 'BOSS_GOLEM' | 'BOSS_LICH';
  weather?: WeatherType;
}

