    }
  };

  const spawnEnemy = () => {
    const angle = Math.random() * Math.PI * 2; const distance = 850; 
    const ex = playerRef.current.x + Math.cos(angle) * distance; const ey = playerRef.current.y + Math.sin(angle) * distance;
    let type: any = 'SLIME'; const w = waveRef.current; const r = Math.random();

    if (w >= 10) { if (r < 0.2) type = 'DEMON'; else if (r < 0.4) type = 'BAT'; else if (r < 0.6) type = 'SORCERER'; else if (r < 0.8) type = 'SNAKE'; else type = 'GOBLIN'; } 
    else if (w >= 5) { if (r < 0.2) type = 'GOBLIN'; else if (r < 0.4) type = 'BAT'; else if (r < 0.6) type = 'SNAKE'; else if (r < 0.8) type = 'SORCERER'; else type = 'SLIME'; } 
    else if (w >= 2) { if (r < 0.3) type = 'SNAKE'; else if (r < 0.6) type = 'GOBLIN'; else type = 'SLIME'; } 
