    const variant = Math.floor(Math.random() * 3);
    let hp = 30 + w * 12; let armor = 0; let speed = 80 + Math.random()*20; let radius = 20;

    if (variant === 1) { hp *= 0.8; speed *= 1.2; } else if (variant === 2) { hp *= 1.3; speed *= 0.85; radius *= 1.2; }
    if (w >= 3) armor = 5 + w * 2; 

    let attackRange = 50; let windupTime = 0.5;
    if (type === 'SLIME') { if (variant === 1) speed += 20; }
    if (type === 'GOBLIN') { hp += 30; speed = 90; attackRange = 70; windupTime = 0.4; if (variant === 1) { speed = 110; attackRange = 60; } if (variant === 2) { hp += 50; speed = 70; } }
    if (type === 'SORCERER') { hp += 10; armor = 0; speed = 60; attackRange = 400; windupTime = 0.8; }
    if (type === 'DEMON') { hp += 150; armor += 20; speed = 65; attackRange = 90; windupTime = 0.6; }
    if (type === 'SNAKE') { hp = 25 + w * 8; speed = 110; attackRange = 300; windupTime = 0.6; radius = 18; }
    if (type === 'BAT') { hp = 20 + w * 5; speed = 140; attackRange = 60; windupTime = 0.3; radius = 15; armor = 0; }

    enemiesRef.current.push({
      id: Math.random().toString(), x: ex, y: ey, z: type === 'BAT' ? 200 : 0, 
      type, isBoss: false, hp, maxHp: hp, defense: armor, speed, damage: 10 + w * 2,
      radius, hitboxRadius: radius * 0.8, frame: 0, vx: 0, vy: 0, hitFlash: 0,
      state: type === 'BAT' ? 'SWOOPING' : 'CHASING', stateTimer: 0, attackRange, windupTime, recoverTime: 0.5, variant
    });
  };

  const spawnBoss = (type: any) => {
      const dist = 600; const angle = Math.random() * Math.PI * 2; const waveMult = 1 + waveRef.current * 0.5;
      let hp = 4000 * waveMult; let defense = 30 + waveRef.current * 5; let damage = 60 + waveRef.current * 2; let speed = 40; let radius = 80; let attackRange = 180;

      if (type === 'BOSS_GOLEM') { hp = 6000 * waveMult; defense = 60 + waveRef.current * 5; speed = 35; damage = 80 + waveRef.current * 3; radius = 100; attackRange = 150; } 
      else if (type === 'BOSS_LICH') { hp = 3500 * waveMult; defense = 20 + waveRef.current * 5; speed = 55; damage = 50 + waveRef.current * 2; radius = 70; attackRange = 450; }

      enemiesRef.current.push({
          id: 'boss', x: playerRef.current.x + Math.cos(angle)*dist, y: playerRef.current.y + Math.sin(angle)*dist, z: 0,
          type, isBoss: true, hp, maxHp: hp, defense, speed, damage, radius, hitboxRadius: radius * 0.8, frame: 0, vx: 0, vy: 0, hitFlash: 0,
          state: 'CHASING', stateTimer: 0, attackRange, windupTime: 1.5, recoverTime: 1.5, variant: 0, specialTimer: 5 
      });
      shakeRef.current = 20; 
  };

  const updateEnemies = (dt: number, stats: any) => {
      const p = playerRef.current;
      const enemiesList = enemiesRef.current;
      const enemyCount = enemiesList.length;

      enemiesRef.current = enemiesList.filter((e, idx) => {
          if (e.hitFlash > 0) e.hitFlash -= dt;
          if (e.frozenTimer && e.frozenTimer > 0) { e.frozenTimer -= dt; return true; }
          e.frame += dt; 

          if (e.type !== 'BAT') {
              let sepX = 0, sepY = 0; const checkLimit = Math.min(idx + 3, enemyCount);
              for (let i = Math.max(0, idx - 3); i < checkLimit; i++) {
                  if (i === idx) continue;
                  const other = enemiesList[i]; if (other.type === 'BAT') continue; 
                  const distSq = (e.x - other.x)**2 + (e.y - other.y)**2; const minDist = (e.radius + other.radius) * 0.8;
                  if (distSq < minDist**2 && distSq > 0.1) {
                      const pushDist = Math.sqrt(distSq); const pushForce = (minDist - pushDist) / pushDist;
                      sepX += (e.x - other.x) * pushForce; sepY += (e.y - other.y) * pushForce;
                  }
              }
