          }
          if (Math.abs(e.vx) > 1 || Math.abs(e.vy) > 1) { e.x += e.vx * dt; e.y += e.vy * dt; e.vx *= 0.9; e.vy *= 0.9; }

          const dx = p.x - e.x; const dy = p.y - e.y; const dist = Math.hypot(dx, dy);
          if (e.isBoss && e.specialTimer !== undefined) { e.specialTimer -= dt; }

          if (e.state === 'CHASING' || e.state === 'SWOOPING') {
              if (e.type === 'SORCERER' && dist < 300) { e.state = 'FLEEING'; e.stateTimer = 1.0; }
              if (e.type === 'SNAKE' && dist < 250 && dist > 100) { if (Math.random() < 0.02) { e.state = 'WINDUP'; e.stateTimer = e.windupTime; } }
              if (e.type === 'BAT') {
                  const hoverHeight = 60 + Math.sin(e.frame * 5) * 20;
                  if (e.state === 'SWOOPING') { if (dist < 200) e.z = lerp(e.z, 10, dt * 5); else e.z = lerp(e.z, hoverHeight, dt * 2); }
              }
              if (dist > 10) {
                  let mx = dx / dist; let my = dy / dist;
                  if (e.type === 'GOBLIN' && dist > 80 && dist < 300) {
                      const strafeDir = (e.id.charCodeAt(0) % 2 === 0) ? 1 : -1;
                      mx = (mx * 0.5) + (-my * strafeDir * 0.8); my = (my * 0.5) + (mx * strafeDir * 0.8); const len = Math.hypot(mx, my); mx /= len; my /= len;
                  }
                  if (e.type === 'SNAKE') { const wobble = Math.sin(e.frame * 8) * 0.5; mx += -my * wobble; my += mx * wobble; const len = Math.hypot(mx, my); mx /= len; my /= len; }
                  let currentMoveSpeed = e.speed;
                  if (e.type === 'BOSS_LICH' && dist < 350) { currentMoveSpeed *= -0.5; }
                  e.x += mx * currentMoveSpeed * dt; e.y += my * currentMoveSpeed * dt;
