          }
          else if (e.state === 'FLEEING') { e.stateTimer -= dt; if (dist > 0) { e.x -= (dx/dist) * e.speed * 1.2 * dt; e.y -= (dy/dist) * e.speed * 1.2 * dt; } if (e.stateTimer <= 0) e.state = 'CHASING'; }
          else if (e.state === 'WINDUP') {
