                       projectilesRef.current.push({ id: Math.random().toString(), x: e.x, y: e.y, z: 0, vx: 0, vy: 0, damage: e.damage * 1.5, duration: 0.5, radius: 140, type: 'BOSS_SMASH', color: '#ef4444', pierce: 999, isEnemy: true }); shakeRef.current = 30;
                  } else if (dist < e.attackRange + 30) { takeDamage(p, e.damage); }
                  e.state = e.type === 'BAT' ? 'SWOOPING' : 'RECOVERING'; e.stateTimer = e.recoverTime;
                  if (e.type === 'BOSS_GOLEM' && e.hp < e.maxHp * 0.5) e.stateTimer *= 0.5;
              }
          } else if (e.state === 'RECOVERING') { e.stateTimer -= dt; if (e.stateTimer <= 0) e.state = 'CHASING'; }

          for (const proj of projectilesRef.current) {
               if (proj.duration <= 0 || proj.isEnemy) continue;
               if (proj.delayedDamage && proj.duration > 0.1) continue;
               const pDist = Math.hypot(proj.x - e.x, proj.y - e.y);
               if(pDist < proj.radius + e.hitboxRadius) {
                   if (proj.type === 'TIME_PRISON') { e.frozenTimer = 3.0; continue; }
                   if (proj.knockbackForce) { const kAngle = Math.atan2(e.y - proj.y, e.x - proj.x); e.vx += Math.cos(kAngle) * proj.knockbackForce; e.vy += Math.sin(kAngle) * proj.knockbackForce; }
                   const isAoe = proj.type === 'SWORD_SLASH' || proj.type === 'FIRE_ZONE' || proj.type === 'OCEAN_WAVE';
                   let dmg = isAoe ? proj.damage * 5 * dt : proj.damage;
                   const isCrit = Math.random() < stats.critChance; if (isCrit) dmg *= stats.critDamage;
                   if (stats.executionerThreshold > 0 && (e.hp / e.maxHp) < 0.3) { dmg *= (1 + stats.executionerThreshold); }
                   const mitigation = 100 / (100 + Math.max(0, e.defense - stats.armorPenetration));
