        else if (p.type === 'LICH_DRAIN_ZONE') { ctx.fillStyle = 'rgba(16, 185, 129, 0.2)'; ctx.beginPath(); ctx.ellipse(x, y, p.radius, p.radius*0.5, 0, 0, Math.PI*2); ctx.fill(); ctx.strokeStyle = '#10b981'; ctx.lineWidth = 1; ctx.stroke(); } 
        else if (p.type === 'AUTO_LIGHTNING') { ctx.strokeStyle = '#fef08a'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(x, y - 400); let currY = y - 400; let currX = x; const steps = 5; const stepY = 400 / steps; for(let i=0; i<steps; i++) { currY += stepY; currX += (Math.random() - 0.5) * 40; ctx.lineTo(currX, currY); } ctx.lineTo(x, y); ctx.stroke(); ctx.fillStyle = '#fef08a'; ctx.beginPath(); ctx.arc(x, y, p.radius * (p.duration/0.5), 0, Math.PI*2); ctx.fill(); } 
        else if (p.type === 'ARROW') { const tailX = x - p.vx * 0.04; const tailY = y - p.vy * 0.04; const grad = ctx.createLinearGradient(x, y, tailX, tailY); grad.addColorStop(0, p.color); grad.addColorStop(1, 'rgba(255,255,255,0)'); ctx.strokeStyle = grad; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(tailX, tailY); ctx.stroke(); ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI*2); ctx.fill(); } 
        else if (p.type === 'ARCANE_COLOSSUS') { ctx.beginPath(); ctx.arc(x, y, 10, 0, Math.PI*2); ctx.fillStyle='#fff'; ctx.fill(); ctx.beginPath(); ctx.arc(x, y, 6, 0, Math.PI*2); ctx.fillStyle=p.color; ctx.fill(); } 
        else if (p.type === 'BOSS_SMASH' || p.type === 'JUDGEMENT_STRIKE') { ctx.fillStyle = p.type === 'BOSS_SMASH' ? 'rgba(255,255,255,0.8)' : 'rgba(252, 211, 77, 0.4)'; ctx.beginPath(); ctx.ellipse(x, y, p.radius, p.radius*0.5, 0, 0, Math.PI*2); ctx.fill(); } 
        else { ctx.beginPath(); ctx.arc(x, y, 4, 0, Math.PI*2); ctx.fill(); ctx.fillStyle = 'rgba(255,255,255,0.4)'; ctx.beginPath(); ctx.arc(x - p.vx*0.02, y - p.vy*0.02, 2, 0, Math.PI*2); ctx.fill(); }
        ctx.shadowBlur = 0;
    }

    ctx.restore(); 

    // --- WEATHER OVERLAY (FOG / GRADIENTS) ---
    if (gameStateRef.current === GameState.TOWER && weatherTypeRef.current === 'FOG' && weatherIntensityRef.current > 0.1) {
        // Fog effect: Clear in center, thick at edges
        const grad = ctx.createRadialGradient(cx, cy, 100, cx, cy, 800);
        const intensity = weatherIntensityRef.current * 0.8;
        grad.addColorStop(0, 'rgba(200, 215, 210, 0)');
        grad.addColorStop(0.6, `rgba(180, 200, 190, ${intensity * 0.5})`);
        grad.addColorStop(1, `rgba(150, 170, 160, ${intensity})`);
        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    }

    const vignette = ctx.createRadialGradient(cx, cy, 300, cx, cy, 1000); 
    vignette.addColorStop(0, 'rgba(0,0,0,0)'); 
    vignette.addColorStop(1, 'rgba(0,0,0,0.8)'); 
    ctx.fillStyle = vignette; 
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    if (weatherTypeRef.current === 'RAIN' || weatherTypeRef.current === 'STORM') { 
        ctx.fillStyle = `rgba(30, 58, 138, ${weatherIntensityRef.current * 0.15})`; 
        ctx.fillRect(0,0,CANVAS_WIDTH, CANVAS_HEIGHT); 
    }
    if (weatherTypeRef.current === 'SANDSTORM') {
        ctx.fillStyle = `rgba(217, 119, 6, ${weatherIntensityRef.current * 0.15})`; 
        ctx.fillRect(0,0,CANVAS_WIDTH, CANVAS_HEIGHT);
    }

    if (playerRef.current.slowTimer > 0) { ctx.fillStyle = 'rgba(69, 10, 10, 0.2)'; ctx.fillRect(0,0,CANVAS_WIDTH, CANVAS_HEIGHT); }
    if (playerRef.current.avatarBuffTimer > 0) {
        const pulse = 0.1 + Math.sin(timeRef.current * 10) * 0.05;
        ctx.fillStyle = `rgba(252, 211, 77, ${pulse})`; ctx.fillRect(0,0,CANVAS_WIDTH, CANVAS_HEIGHT);
    }

    // ... (Aim Assist & Damage Numbers)
    const pIso = toIso(playerRef.current.x, playerRef.current.y);
    const playerScreenX = cx + (cameraRef.current.x + shakeX + pIso.x) * ZOOM_LEVEL;
    const playerScreenY = cy + (cameraRef.current.y + shakeY + pIso.y - (playerRef.current.z || 0)) * ZOOM_LEVEL;
    const mouseScreenX = cx + mouseScreenRef.current.x; const mouseScreenY = cy + mouseScreenRef.current.y;
    let isAimingAtEnemy = false; for(const e of enemiesRef.current) { const dist = Math.hypot(e.x - mouseWorldRef.current.x, e.y - mouseWorldRef.current.y); if (dist < 40) { isAimingAtEnemy = true; break; } }
    ctx.save(); ctx.strokeStyle = isAimingAtEnemy ? 'rgba(239, 68, 68, 0.5)' : 'rgba(255, 255, 255, 0.2)'; ctx.setLineDash([4, 4]); ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(playerScreenX, playerScreenY - 20); ctx.lineTo(mouseScreenX, mouseScreenY); ctx.stroke(); ctx.setLineDash([]); ctx.translate(mouseScreenX, mouseScreenY); ctx.rotate(reticleAngleRef.current); ctx.strokeStyle = isAimingAtEnemy ? '#ef4444' : '#fff'; ctx.lineWidth = 2; const rSize = 12; ctx.beginPath(); ctx.moveTo(rSize, 0); ctx.lineTo(rSize/2, -rSize/2); ctx.moveTo(rSize, 0); ctx.lineTo(rSize/2, rSize/2); ctx.moveTo(-rSize, -rSize/2); ctx.lineTo(-rSize/2, 0); ctx.lineTo(-rSize, rSize/2); ctx.stroke(); ctx.fillStyle = isAimingAtEnemy ? '#ef4444' : '#fff'; ctx.beginPath(); ctx.arc(0, 0, 2, 0, Math.PI*2); ctx.fill(); ctx.restore();
    for(const dn of damageNumbersRef.current) { const pos = toIso(dn.x, dn.y, dn.z); const sx = cx + (pos.x + cameraRef.current.x) * ZOOM_LEVEL; const sy = cy + (pos.y + cameraRef.current.y) * ZOOM_LEVEL; ctx.fillStyle = dn.isPlayerDamage ? '#ef4444' : (dn.isCrit ? '#fbbf24' : 'white'); ctx.strokeStyle = '#020617'; ctx.lineWidth = 4; ctx.lineJoin = 'round'; const offset = (1 - dn.life) * 80; const alpha = Math.min(1, dn.life * 3); ctx.save(); ctx.globalAlpha = alpha; ctx.translate(sx, sy - offset); if (dn.isCrit) { const scale = 1.5 + Math.sin((1-dn.life)*10)*0.2; ctx.scale(scale, scale); ctx.font = '900 28px "Cinzel", serif'; } else { ctx.font = 'bold 20px "Cinzel", serif'; } const text = Math.floor(dn.value).toString(); ctx.strokeText(text, 0, 0); ctx.fillText(text, 0, 0); if (dn.isCrit) { ctx.shadowColor = '#fbbf24'; ctx.shadowBlur = 10; ctx.fillText(text, 0, 0); ctx.shadowBlur = 0; } ctx.restore(); }
  };

  const formatTime = (s: number) => `${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;

  return (
    <>
      <canvas ref={canvasRef} className="block w-full h-full cursor-none" />

      {/* --- HUD --- */}
      <div className="absolute inset-x-0 bottom-6 flex flex-col items-center pointer-events-none z-10 scale-[0.80] origin-bottom transition-transform">
          {hudData.bossHp > 0 && (
              <div className="mb-10 w-[700px] pointer-events-none animate-in fade-in slide-in-from-top-10 duration-700">
                  <div className="flex justify-between items-end text-red-500 font-bold mb-2 px-4 uppercase tracking-widest font-serif drop-shadow-md">
                      <span className="text-2xl">Terror da Torre</span>
                      <span className="text-sm opacity-80">{Math.ceil(hudData.bossHp)}/{Math.ceil(hudData.bossMaxHp)}</span>
                  </div>
                  <div className="relative h-6 w-full bg-slate-900 border-2 border-slate-700 rounded-sm shadow-[0_0_30px_rgba(220,38,38,0.3)] overflow-hidden">
                      <div className="absolute inset-0 bg-red-950/50"></div>
                      <div className="h-full bg-gradient-to-r from-red-900 via-red-600 to-red-500 transition-all duration-200" style={{width: `${(hudData.bossHp/hudData.bossMaxHp)*100}%`}}></div>
                  </div>
              </div>
          )}

          <div className="flex items-end gap-6 pb-2">
              <div className="bg-slate-900/95 border border-slate-700 rounded-2xl p-5 backdrop-blur-md shadow-2xl w-72 transform transition-transform">
                   <div className="flex items-center justify-between gap-2 text-white font-bold text-2xl mb-3 font-serif">
                       <span className="flex items-center gap-2 text-red-400"><Heart fill="currentColor" /> {Math.ceil(hudData.hp)}</span>
                       <span className="text-sm font-mono text-slate-500">LVL {hudData.level}</span>
                   </div>
                   <div className="relative h-4 bg-slate-950 rounded-full overflow-hidden border border-slate-800 mb-2 shadow-inner">
                       <div className="h-full bg-gradient-to-r from-red-800 to-red-500 transition-all duration-300" style={{width: `${(hudData.hp/hudData.maxHp)*100}%`}}></div>
                   </div>
                   <div className="flex justify-between text-[10px] text-slate-400 font-mono tracking-wide uppercase">
                       <span>XP Progresso</span>
                       <span className="text-amber-500">{Math.floor(hudData.xp)} / {Math.floor(hudData.xpNext)}</span>
                   </div>
                   <div className="mt-1 h-1 w-full bg-slate-800 rounded-full overflow-hidden">
                       <div className="h-full bg-amber-500 shadow-[0_0_10px_#f59e0b]" style={{width: `${(hudData.xp/hudData.xpNext)*100}%`}}></div>
                   </div>
              </div>

              <div className="flex gap-3 p-4 bg-slate-900/95 border border-slate-700 rounded-2xl backdrop-blur-md shadow-2xl">
                  <div className="w-20 h-20 bg-slate-800 rounded-xl border border-slate-600 flex flex-col items-center justify-center grayscale opacity-60">
                      <Sword size={32} />
                  </div>
                  <div className={`relative w-20 h-20 rounded-xl border-2 flex flex-col items-center justify-center overflow-hidden transition-all duration-200
                      ${hudData.skill1Cd <= 0 ? 'bg-blue-950/80 border-blue-400 shadow-[0_0_15px_rgba(59,130,246,0.3)]' : 'bg-slate-800 border-slate-700 grayscale'}`}>
                      <Crosshair size={32} className={hudData.skill1Cd <= 0 ? "text-blue-400" : "text-slate-500"} />
                      <span className="absolute bottom-1 right-2 text-[10px] font-bold text-slate-400">Q</span>
                      {hudData.skill1Cd > 0 && <div className="absolute inset-0 bg-black/70 flex items-center justify-center font-bold text-white text-2xl font-mono animate-in fade-in">{Math.ceil(hudData.skill1Cd)}</div>}
                  </div>
                  <div className={`relative w-20 h-20 rounded-xl border-2 flex flex-col items-center justify-center overflow-hidden transition-all duration-200
                      ${hudData.dashCharges > 0 ? 'bg-emerald-950/80 border-emerald-400 shadow-[0_0_15px_rgba(52,211,153,0.3)]' : 'bg-slate-800 border-slate-700 grayscale'}`}>
                      <Wind size={32} className={hudData.dashCharges > 0 ? "text-emerald-400" : "text-slate-500"} />
                      <span className="absolute bottom-1 right-2 text-[10px] font-bold text-slate-400">E</span>
                      <div className="absolute top-2 left-0 right-0 flex justify-center gap-1">
                          {Array.from({length: Math.max(hudData.dashMax, 2)}).map((_, i) => (
                             <div key={i} className={`w-2 h-2 rounded-full shadow-sm transition-colors duration-300 ${i < hudData.dashCharges ? 'bg-emerald-400 shadow-[0_0_8px_#34d399]' : 'bg-slate-700 border border-slate-600'}`}></div>
                          ))}
                      </div>
                      {hudData.dashCd > 0 && hudData.dashCharges < hudData.dashMax && <div className="absolute inset-0 bg-black/70 flex items-center justify-center font-bold text-white text-2xl font-mono">{Math.ceil(hudData.dashCd)}</div>}
                  </div>
                  <div className={`relative w-20 h-20 rounded-xl border-2 flex flex-col items-center justify-center overflow-hidden transition-all duration-200
                      ${hudData.activeItem ? 'bg-amber-950/60 border-amber-500' : 'bg-slate-900 border-slate-800 opacity-40 border-dashed'}`}>
                      {hudData.activeItem ? (<> <span className="text-3xl filter drop-shadow-lg">{hudData.activeItem.icon}</span> <span className="absolute bottom-1 right-2 text-[10px] font-bold text-amber-200">R</span> </>) : <Box size={24} className="text-slate-600" />}
                      {hudData.itemCd > 0 && <div className="absolute inset-0 bg-black/70 flex items-center justify-center font-bold text-white text-2xl font-mono">{Math.ceil(hudData.itemCd)}</div>}
                  </div>
              </div>

              <div className="flex flex-col gap-2">
                 {hudData.autoItems.map((item, idx) => (
                    <div key={idx} className={`w-12 h-12 border rounded-lg flex items-center justify-center relative overflow-hidden
                       ${item.id.includes('leg_') ? 'bg-amber-950/60 border-amber-500/50 shadow-amber-500/20 shadow-lg' : 'bg-purple-950/60 border-purple-500/50'}
                    `}>
                        <span className="text-xl z-10">{item.icon}</span>
                        <div className={`absolute bottom-0 left-0 h-1 transition-all duration-100 ${item.id.includes('leg_') ? 'bg-amber-400' : 'bg-purple-400'}`} style={{width: `${(1 - (item.timer / item.cooldown)) * 100}%`}}></div>
                    </div>
                 ))}
                 {hudData.autoItems.length === 0 && <div className="w-12 h-12 border border-slate-800 border-dashed rounded-lg flex items-center justify-center opacity-30"><Zap size={16} /></div>}
              </div>

              {hudData.state === GameState.TOWER && (
                  <div className="bg-slate-900/95 border border-slate-700 rounded-2xl p-5 backdrop-blur-md shadow-2xl w-40 text-center flex flex-col justify-center h-[124px]">
                      <div className="text-3xl font-mono font-bold text-white mb-2 tracking-widest">{formatTime(hudData.time)}</div>
                      <div className="text-xs text-slate-400 flex items-center justify-center gap-2 font-serif uppercase tracking-wider border-t border-slate-800 pt-2">
                          <Skull size={14} className="text-red-500" /> WAVE {hudData.wave}
                      </div>
                      {hudData.weather !== 'NONE' && (
                          <div className={`text-[10px] animate-pulse mt-1 font-serif font-bold uppercase
                              ${hudData.weather === 'RAIN' ? 'text-blue-300' : ''}
                              ${hudData.weather === 'STORM' ? 'text-purple-300' : ''}
                              ${hudData.weather === 'SANDSTORM' ? 'text-amber-500' : ''}
                              ${hudData.weather === 'FOG' ? 'text-emerald-200' : ''}
                              ${hudData.weather === 'WIND' ? 'text-slate-300' : ''}
                          `}>
                              {hudData.weather === 'SANDSTORM' ? 'Tempestade de Areia' : 
                               hudData.weather === 'FOG' ? 'Neblina Densa' :
                               hudData.weather === 'WIND' ? 'Vendaval' :
                               hudData.weather === 'STORM' ? 'Tempestade' : 'Chuva'}
                          </div>
                      )}
                  </div>
              )}
          </div>
      </div>

      {hudData.buffTime > 0 && (
          <div className="absolute top-20 w-full flex justify-center pointer-events-none">
               <div className="bg-amber-500/20 border border-amber-400/50 px-6 py-2 rounded-full backdrop-blur-sm text-amber-200 font-bold animate-pulse shadow-[0_0_20px_rgba(251,191,36,0.4)]">
                   AVATAR DA DEUSA: {Math.ceil(hudData.buffTime)}s
               </div>
          </div>
      )}

      {/* --- LEVEL TRANSITION OVERLAY --- */}
      {levelTitle && (
        <div className="absolute inset-0 flex items-center justify-center bg-black z-50 animate-in fade-in duration-500">
            <div className="text-center">
                <h1 className="text-6xl md:text-8xl font-black text-transparent bg-clip-text bg-gradient-to-b from-amber-100 to-amber-600 drop-shadow-[0_0_30px_rgba(245,158,11,0.5)] font-serif tracking-widest mb-4 animate-in zoom-in slide-in-from-bottom-10 duration-1000 fill-mode-forwards">
                    {levelTitle.title}
                </h1>
                <h2 className="text-xl md:text-3xl text-slate-300 font-mono tracking-[0.5em] uppercase animate-in fade-in slide-in-from-bottom-5 duration-1000 delay-300 fill-mode-forwards">
                    {levelTitle.subtitle}
                </h2>
            </div>
        </div>
      )}

      {hudData.state === GameState.ISLAND && (
          <div className="absolute top-20 w-full text-center pointer-events-none animate-bounce">
              <span className="bg-slate-900/90 px-8 py-4 rounded-full text-slate-100 border border-blue-500/50 shadow-[0_0_20px_rgba(59,130,246,0.4)] font-serif tracking-widest text-lg">
                  Siga para o Portal Azul
              </span>
          </div>
      )}

      {showUpgrade && (
        <UpgradeModal options={upgradeOptions} memoryOption={lastUpgrade} onSelect={applyUpgrade} />
      )}
    </>
  );
};

export enum GameState {
  CHAR_SELECT = 'CHAR_SELECT',
  ISLAND = 'ISLAND',
  TOWER = 'TOWER',
  PAUSED = 'PAUSED',
  GAME_OVER = 'GAME_OVER',
  VICTORY = 'VICTORY'
}

export enum Archetype {
  WARRIOR = 'WARRIOR',
  ARCHER = 'ARCHER',
  MAGE = 'MAGE'
}

export type WeatherType = 'NONE' | 'RAIN' | 'FOG' | 'WIND' | 'STORM' | 'SANDSTORM';

export type BiomeType = 'FOREST' | 'ICE' | 'DESERT' | 'SWAMP' | 'DEMON' | 'DEFAULT';

export interface Stats {
  maxHp: number;
  hp: number;
  damage: number;
  speed: number;
  defense: number;
  cooldownReduction: number;
  pickupRange: number;
  areaSize: number;
  // Novos Atributos
  armorPenetration: number;
  lifeSteal: number; // Porcentagem curada ao matar (0.0 a 1.0)
  dashChargesMax: number;
  attackSpeed: number; // Multiplicador de velocidade de ataque (ex: 1.0, 1.5)
  damageReduction: number; // Porcentagem de redução (ex: 0.1 = 10%)

  // Novos Atributos (Update)
  critChance: number; // 0.0 a 1.0
  critDamage: number; // Multiplicador (base 1.5)
  regen: number; // HP por segundo
  executionerThreshold: number; // % de HP do inimigo para bônus de dano (0.0 se inativo)
  towerEchoStacks: number; // Stacks de "Eco da Torre"
  shieldOnLowHp: boolean; // Possui passiva de escudo
  shieldCooldown: number; // Cooldown atual do escudo
}

export interface Item {
  id: string;
  name: string;
  icon: string;
  cooldown: number;
  duration?: number;
  effect: (player: Player, enemies: Enemy[]) => void;
  description: string;
}

export interface AutoItem {
  id: string;
  name: string;
  icon: string;
  cooldown: number;
  timer: number;
  effect: (player: Player, enemies: Enemy[]) => Projectile | null | Projectile[]; // Pode retornar array
  description: string;
}

export interface Player {
  x: number;
  y: number;
  z: number;
  archetype: Archetype;
  stats: Stats;
  level: number;
  xp: number;
  xpToNextLevel: number;

  // Cooldowns
  weaponTimer: number;
  skill1Timer: number;
  skill1MaxCooldown: number;

  // Dash System
  dashTimer: number;      // Tempo para recarregar a próxima carga
  dashMaxCooldown: number; // Tempo base de recarga
  dashCharges: number;    // Cargas atuais

  // Item Slot (Manual - R)
  activeItem: Item | null;
  itemTimer: number;
  itemMaxCooldown: number;

  // Auto Skills Slots (Automático)
  autoItems: AutoItem[];

  // Status Effects
  slowTimer: number; // Tempo que o jogador fica lento ao tomar dano
  lastHitTime: number; // Tempo desde o último dano recebido (para passiva de regen)
  avatarBuffTimer: number; // Timer do buff "Avatar da Deusa"

  facing: number;
  isMoving: boolean;
  color: string;

  // Animation
  animFrame: number;
}

export type EnemyState = 'CHASING' | 'WINDUP' | 'ATTACKING' | 'RECOVERING' | 'CHANNELING' | 'FLEEING' | 'SWOOPING' | 'FROZEN';

export interface Enemy {
  id: string;
  x: number;
  y: number;
  z: number;
  type: 'SLIME' | 'GOBLIN' | 'SORCERER' | 'DEMON' | 'BOSS_GOLEM' | 'BOSS_LICH' | 'SNAKE' | 'BAT';
  isBoss: boolean;
  hp: number;
  maxHp: number;
  defense: number; // Nova defesa
  speed: number;
  damage: number;
  radius: number;
  hitboxRadius: number;
  frame: number;
  variant: number; // 0: Normal, 1: Swift/Weak, 2: Tank/Slow

  // AI State Machine
  state: EnemyState;
  stateTimer: number; // Tempo restante no estado atual
  attackRange: number; // Distância para iniciar ataque
  windupTime: number; // Tempo avisando o ataque
  recoverTime: number; // Tempo parado após ataque
  specialTimer?: number; // Timer para habilidades especiais do boss

  // Physics & Visuals
  vx: number; 
  vy: number; 
  hitFlash: number; 
  frozenTimer?: number; // Se > 0, inimigo está congelado
  knockbackResist?: number; // 0 a 1 (1 = imune)
}

export interface StaticObject {
  id: string;
  x: number;
  y: number;
  type: 'TREE' | 'HOUSE' | 'LAMP' | 'PORTAL' | 'ROCK' | 'BUSH';
  size: number;
  variant?: number; // Para cor da casa ou tipo de árvore
}

export interface Projectile {
  id: string;
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  damage: number;
  duration: number;
  radius: number;
  // Novos tipos adicionados
  type: 'ARROW' | 'MAGIC_ORB' | 'SWORD_SLASH' | 'BOSS_SMASH' | 'FIRE_ZONE' | 'ENEMY_BOLT' | 'GOLEM_SHOCKWAVE' | 'LICH_DRAIN_ZONE' | 'BOSS_ROCK' | 'LICH_NOVA' | 'POISON_SPIT' | 'AUTO_LIGHTNING' | 'AUTO_FIREBALL' | 
        'JUDGEMENT_STRIKE' | 'OCEAN_WAVE' | 'GODDESS_SEAL' | 'HELL_FLAME' | 'ARCANE_COLOSSUS' | 'TIME_PRISON' | 'EARTH_SPIKE' | 'MANA_SHARD' | 'SPIRIT_WAVE';
  color: string;
  pierce: number;
  isEnemy?: boolean; // Se true, da dano no player
  delayedDamage?: boolean; // Se true, só dá dano quando duration acaba ou timer específico
  knockbackForce?: number;
}

export interface Particle {
  id: string;
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  life: number;
  maxLife: number;
  color: string;
  size: number;
  type?: 'RAIN' | 'BLOOD' | 'SPARK' | 'POISON' | 'TELEPORT' | 'TRAIL' | 'MAGIC' | 'FIRE' | 'IMPACT' | 'SHOCKWAVE' | 'FROST' | 'FOG' | 'SAND';
}

export interface DamageNumber {
  id: string;
  x: number;
  y: number;
  z: number;
  value: number;
  life: number;
  isCrit: boolean;
  isPlayerDamage?: boolean; // Se true, é dano QUE O JOGADOR TOMOU (vermelho escuro)
}

export interface Upgrade {
  id: string;
  name: string;
  description: string;
  type: 'STAT' | 'WEAPON' | 'PASSIVE' | 'ITEM' | 'AUTO_ITEM';
  rarity: 'COMMON' | 'RARE' | 'EPIC' | 'LEGENDARY';
  itemRef?: Item;
  autoItemRef?: AutoItem; // Referência para auto skill
}

export interface WaveConfig {
  duration: number;
  enemyCount: number;
  spawnRate: number;
  boss?: 'BOSS_GOLEM' | 'BOSS_LICH';
  weather?: WeatherType;
}

