    ctx.translate(CANVAS_WIDTH/2, CANVAS_HEIGHT/2); ctx.scale(ZOOM_LEVEL, ZOOM_LEVEL); ctx.translate(Math.floor(cameraRef.current.x + shakeX), Math.floor(cameraRef.current.y + shakeY));

