  vx: number; 
  vy: number; 
  hitFlash: number; 
  frozenTimer?: number;
  knockbackResist?: number;
}

export interface StaticObject {
  id: string;
  x: number;
  y: number;
  type: 'TREE' | 'HOUSE' | 'LAMP' | 'PORTAL' | 'ROCK' | 'BUSH' | 'CRYSTAL' | 'PILLAR' | 'TOMBSTONE';
  size: number;
  variant?: number;
}

export interface Projectile {
  id: string;
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  damage: number;
  duration: number;
  radius: number;
  type: string; // Expanded dynamically
  color: string;
  pierce: number;
  isEnemy?: boolean;
  delayedDamage?: boolean;
  knockbackForce?: number;
}

export interface Particle {
  id: string;
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  life: number;
  maxLife: number;
  color: string;
  size: number;
  type?: 'RAIN' | 'BLOOD' | 'SPARK' | 'POISON' | 'TELEPORT' | 'TRAIL' | 'MAGIC' | 'FIRE' | 'IMPACT' | 'SHOCKWAVE' | 'FROST' | 'FOG' | 'SAND' | 'SNOW' | 'ASH';
}

export interface DamageNumber {
  id: string;
  x: number;
  y: number;
  z: number;
  value: number;
  life: number;
  isCrit: boolean;
  isPlayerDamage?: boolean;
}

export interface Upgrade {
  id: string;
  name: string;
  description: string;
  type: 'STAT' | 'WEAPON' | 'PASSIVE' | 'ITEM' | 'AUTO_ITEM';
  rarity: 'COMMON' | 'RARE' | 'EPIC' | 'LEGENDARY';
