    level: 1, xp: 0, xpToNextLevel: 100,
    weaponTimer: 0, skill1Timer: 0, skill1MaxCooldown: SKILL_CONFIG[archetype].skill1Cd,
    dashTimer: 0, 
    dashMaxCooldown: SKILL_CONFIG[archetype].dashCd,
    dashCharges: BASE_STATS[archetype].dashChargesMax,
    activeItem: null, itemTimer: 0, itemMaxCooldown: 0,
    autoItems: [], 
    facing: 0, isMoving: false, color: COLORS[archetype], animFrame: 0,
    slowTimer: 0, poisonTimer: 0, lastHitTime: 0, avatarBuffTimer: 0
  });

  const enemiesRef = useRef<Enemy[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const damageNumbersRef = useRef<DamageNumber[]>([]);
  const staticObjectsRef = useRef<StaticObject[]>([]);
  const keysRef = useRef<{ [key: string]: boolean }>({});

  // System Refs
  const cameraRef = useRef({ x: 0, y: 0 }); 
  const shakeRef = useRef(0); 
  const timeRef = useRef<number>(0); 
  const waveRef = useRef<number>(0);
  const waveTimerRef = useRef<number>(0);
  const lastSpawnTimeRef = useRef<number>(0);
  const bossSpawnedRef = useRef<boolean>(false); 

  // Dynamic Weather System
  const weatherTypeRef = useRef<WeatherType>('NONE');
  const weatherIntensityRef = useRef<number>(0); 
  const particleTimerRef = useRef<number>(0);
  const windForceRef = useRef({ x: 0, y: 0 }); 

  // UI State
  const [showUpgrade, setShowUpgrade] = useState(false);
  const [upgradeOptions, setUpgradeOptions] = useState<Upgrade[]>([]);
  const [lastUpgrade, setLastUpgrade] = useState<Upgrade | null>(null);
  const [hudData, setHudData] = useState({ 
      hp: 100, maxHp: 100, xp: 0, xpNext: 100, time: 0, wave: 1, level: 1, 
      state: GameState.ISLAND, skill1Cd: 0, dashCd: 0, itemCd: 0, dashCharges: 0, dashMax: 0,
      activeItem: null as Item | null, bossHp: 0, bossMaxHp: 0,
      autoItems: [] as AutoItem[],
      buffTime: 0,
      weather: 'NONE' as WeatherType,
      biome: 'FOREST' as BiomeType
  });

  const mouseScreenRef = useRef({ x: 0, y: 0 }); 
  const mouseWorldRef = useRef({ x: 0, y: 0 });
  const reticleAngleRef = useRef(0);

  const createParticle = (x: number, y: number, z: number, color: string, size: number, type: any = 'PARTICLE') => {
      let vx = (Math.random() - 0.5) * 100;
      let vy = (Math.random() - 0.5) * 100;
      let vz = (Math.random() * 150) + 50;
      let life = 1.0;

      if (type === 'BLOOD') { life = 0.5; }
      if (type === 'POISON') { vz = 50; life = 0.8; }
      if (type === 'SPARK') { vz = 100; life = 0.5; }
      if (type === 'TRAIL') { vx=0; vy=0; vz=0; life=0.3; }

      particlesRef.current.push({
          id: Math.random().toString(),
          x, y, z,
          vx, vy, vz,
          life, maxLife: life,
          color, size, type
      });
  };

  // --- INIT ---
  useEffect(() => {
    if (gameStateRef.current === GameState.ISLAND) {
        const objects: StaticObject[] = [];
        objects.push({ id: 'portal', x: PORTAL_POS.x, y: PORTAL_POS.y, type: 'PORTAL', size: 140 });
        objects.push({ id: 'h1', x: -150, y: -150, type: 'HOUSE', size: 110, variant: 0 });
        objects.push({ id: 'h2', x: 250, y: -250, type: 'HOUSE', size: 130, variant: 1 });
        objects.push({ id: 'h3', x: -350, y: 100, type: 'HOUSE', size: 100, variant: 0 });
        objects.push({ id: 'h4', x: 150, y: 200, type: 'HOUSE', size: 120, variant: 1 });
        objects.push({ id: 'h5', x: -50, y: 350, type: 'HOUSE', size: 90, variant: 0 });
        const lampPositions = [{x: 0, y: -300}, {x: -250, y: -300}, {x: -300, y: -250}, {x: -100, y: -100}, {x: 100, y: -200}, {x: -200, y: 50}];
        lampPositions.forEach((p, i) => objects.push({ id: `lamp${i}`, x: p.x, y: p.y, type: 'LAMP', size: 20 }));

        for(let i=0; i<150; i++) {
            const angle = Math.random() * Math.PI * 2;
            const dist = 300 + Math.random() * 900;
            const x = Math.cos(angle) * dist;
            const y = Math.sin(angle) * dist;
            let collides = false;
            for(const obj of objects) { if (Math.hypot(x - obj.x, y - obj.y) < obj.size * 0.8) collides = true; }
            if (Math.hypot(x - PORTAL_POS.x, y - PORTAL_POS.y) < 250) collides = true;

            if (!collides) {
                const r = Math.random();
                if (r < 0.6) { objects.push({ id: `t${i}`, x, y, type: 'TREE', size: 50 + Math.random() * 70, variant: Math.random() > 0.5 ? 1 : 0 }); } 
                else if (r < 0.85) { objects.push({ id: `b${i}`, x, y, type: 'BUSH', size: 20 + Math.random() * 15, variant: Math.random() > 0.5 ? 1 : 0 }); } 
                else { objects.push({ id: `r${i}`, x, y, type: 'ROCK', size: 15 + Math.random() * 25 }); }
            }
        }
        staticObjectsRef.current = objects;
    }
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { if (e.code === 'Space') e.preventDefault(); keysRef.current[e.code] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keysRef.current[e.code] = false; };
    const handleMouseMove = (e: MouseEvent) => {
      const rect = canvasRef.current?.getBoundingClientRect();
      if(rect) { mouseScreenRef.current = { x: e.clientX - rect.left - rect.width / 2, y: e.clientY - rect.top - rect.height / 2 }; }
    };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) keysRef.current['MouseLeft'] = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) keysRef.current['MouseLeft'] = false; };
    const handleContextMenu = (e: MouseEvent) => e.preventDefault();

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    window.addEventListener('contextmenu', handleContextMenu);

    let animationFrameId: number;
    let lastTime = performance.now();

    const loop = (timestamp: number) => {
      const dtRaw = (timestamp - lastTime) / 1000;
      const dt = Math.min(dtRaw, 0.1); 
      lastTime = timestamp;

      if (gameStateRef.current === GameState.TOWER || gameStateRef.current === GameState.ISLAND) {
        update(dt);
      }
      draw(dt);
      animationFrameId = requestAnimationFrame(loop);
    };

    animationFrameId = requestAnimationFrame(loop);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
      window.removeEventListener('contextmenu', handleContextMenu);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  // --- UPDATE ---
  const update = (dt: number) => {
    const player = playerRef.current;

    // Effective Stats
    const activeStats = { ...player.stats };
    if (player.avatarBuffTimer > 0) {
        player.avatarBuffTimer -= dt;
        activeStats.damage *= 1.3;
        activeStats.speed *= 1.3;
        activeStats.cooldownReduction += 0.2;
        if (player.avatarBuffTimer <= 0) player.avatarBuffTimer = 0;
    }

    // Camera
    const playerIso = toIso(player.x, player.y, player.z);
    const targetX = (-playerIso.x) - (mouseScreenRef.current.x / ZOOM_LEVEL) * 0.25;
    const targetY = (-playerIso.y) - (mouseScreenRef.current.y / ZOOM_LEVEL) * 0.25;
    cameraRef.current.x = lerp(cameraRef.current.x, targetX, 0.08);
    cameraRef.current.y = lerp(cameraRef.current.y, targetY, 0.08);

    // Mouse World
    const mouseIsoX = (mouseScreenRef.current.x / ZOOM_LEVEL) - cameraRef.current.x;
    const mouseIsoY = (mouseScreenRef.current.y / ZOOM_LEVEL) - cameraRef.current.y;
    mouseWorldRef.current = toWorldFromIso(mouseIsoX, mouseIsoY);

    const distMouse = Math.hypot(mouseWorldRef.current.x - player.x, mouseWorldRef.current.y - player.y);
    if (distMouse > 40) player.facing = Math.atan2(mouseWorldRef.current.y - player.y, mouseWorldRef.current.x - player.x);
    reticleAngleRef.current = player.facing; 

    // --- MOVEMENT & WIND PHYSICS ---
    let dx = 0; let dy = 0;
    if (keysRef.current['KeyW'] || keysRef.current['ArrowUp']) { dx -= 1; dy -= 1; }
    if (keysRef.current['KeyS'] || keysRef.current['ArrowDown']) { dx += 1; dy += 1; }
    if (keysRef.current['KeyA'] || keysRef.current['ArrowLeft']) { dx -= 1; dy += 1; }
    if (keysRef.current['KeyD'] || keysRef.current['ArrowRight']) { dx += 1; dy -= 1; }

    // Apply Wind Force
    let windDx = 0; let windDy = 0;
    if (gameStateRef.current === GameState.TOWER && (weatherTypeRef.current === 'WIND' || weatherTypeRef.current === 'STORM' || weatherTypeRef.current === 'SANDSTORM')) {
        windDx = windForceRef.current.x * weatherIntensityRef.current;
        windDy = windForceRef.current.y * weatherIntensityRef.current;
    }

    player.isMoving = dx !== 0 || dy !== 0;
    if (player.isMoving || Math.abs(windDx) > 0.1) {
      const length = Math.sqrt(dx * dx + dy * dy);
      if (length > 0) { dx /= length; dy /= length; }

      let currentSpeed = activeStats.speed * 60;
      if (player.slowTimer > 0) { player.slowTimer -= dt; currentSpeed *= 0.6; }

      // Weather Slow
      if (weatherTypeRef.current === 'SNOW' || weatherTypeRef.current === 'SANDSTORM') {
          currentSpeed *= 0.85; // Natural slow from terrain/weather
      }

      const newX = player.x + (dx * currentSpeed + windDx * 30) * dt; 
      const newY = player.y + (dy * currentSpeed + windDy * 30) * dt;

      // Collision
      let canMoveX = true; let canMoveY = true;
      if (gameStateRef.current === GameState.ISLAND) {
          const playerRadius = 15;
          staticObjectsRef.current.forEach(obj => {
              if (obj.type === 'PORTAL' || obj.type === 'BUSH') return;
              const dist = Math.hypot(newX - obj.x, player.y - obj.y);
              if (dist < obj.size * 0.4 + playerRadius) canMoveX = false;
              const distY = Math.hypot(player.x - obj.x, newY - obj.y);
              if (distY < obj.size * 0.4 + playerRadius) canMoveY = false;
          });
      }

      if (canMoveX) player.x = newX;
      if (canMoveY) player.y = newY;

      player.animFrame += dt * 10;
    } else { player.animFrame = 0; }

    if (player.z > 0) { player.z -= 200 * dt; if (player.z < 0) player.z = 0; }

    // Regen, Poison & Shield
    player.lastHitTime += dt;
    if (player.poisonTimer > 0) {
        player.poisonTimer -= dt;
        if (Math.floor(timeRef.current * 5) % 3 === 0) { // Simple tick check
             player.stats.hp -= 3 * dt; // DoT
             player.lastHitTime = 0;
             if (Math.random() > 0.8) createParticle(player.x, player.y, player.z + 20, '#a3e635', 5, 'POISON');
        }
    }

    if (activeStats.regen > 0 && player.lastHitTime > 3) { 
        const heal = activeStats.maxHp * (activeStats.regen / 100) * dt;
        player.stats.hp = Math.min(activeStats.maxHp, player.stats.hp + heal);
    }
    if (activeStats.shieldOnLowHp) {
        if (activeStats.shieldCooldown > 0) activeStats.shieldCooldown -= dt;
        else if (player.stats.hp < activeStats.maxHp * 0.2) {
             activeStats.shieldCooldown = 60; 
             player.stats.hp += activeStats.maxHp * 0.3; 
             createParticle(player.x, player.y, 10, '#3b82f6', 20, 'MAGIC');
        }
        player.stats.shieldCooldown = activeStats.shieldCooldown; 
    }

    const limit = gameStateRef.current === GameState.ISLAND ? 1500 : 900;
    if (Math.abs(player.x) > limit) player.x = Math.sign(player.x) * limit;
    if (Math.abs(player.y) > limit) player.y = Math.sign(player.y) * limit;

    // Portal Logic
    if (gameStateRef.current === GameState.ISLAND) {
        const distToPortal = Math.hypot(player.x - PORTAL_POS.x, player.y - PORTAL_POS.y); 
        if (distToPortal < 200) {
            gameStateRef.current = GameState.TOWER;
            player.x = 0; player.y = 0; player.z = 0; 
            enemiesRef.current = []; projectilesRef.current = [];
            waveRef.current = 0; timeRef.current = 0; 
            staticObjectsRef.current = []; 
            bossSpawnedRef.current = false;
        }
        if (player.stats.hp < activeStats.maxHp) player.stats.hp += 100 * dt;
    }

    // TOWER LOGIC
    if (gameStateRef.current === GameState.TOWER) {
        timeRef.current += dt; waveTimerRef.current += dt;
        player.skill1Timer -= dt; player.itemTimer -= dt; player.weaponTimer -= dt;

        // --- WEATHER SYSTEM UPDATE ---
        const currentWaveConfig = WAVE_CONFIGS[waveRef.current] || WAVE_CONFIGS[WAVE_CONFIGS.length-1];
        weatherTypeRef.current = currentWaveConfig.weather || 'NONE';

        if (weatherTypeRef.current !== 'NONE') {
            weatherIntensityRef.current = Math.min(1, weatherIntensityRef.current + dt * 0.1);
            if (weatherTypeRef.current === 'WIND' || weatherTypeRef.current === 'STORM' || weatherTypeRef.current === 'SANDSTORM') {
                const windAngle = timeRef.current * 0.1;
                windForceRef.current = { x: Math.cos(windAngle), y: Math.sin(windAngle) };
            }
        } else {
            weatherIntensityRef.current = Math.max(0, weatherIntensityRef.current - dt * 0.2);
            windForceRef.current = { x: 0, y: 0 };
        }

        if (weatherIntensityRef.current > 0.1) {
            particleTimerRef.current += dt;
            const spawnRate = weatherTypeRef.current === 'STORM' ? 0.01 : 0.05;

            if (particleTimerRef.current > spawnRate) {
                const spawnCount = Math.floor(weatherIntensityRef.current * 5); 
                for(let i=0; i<spawnCount; i++) {
                    const angle = Math.random() * Math.PI * 2; const dist = Math.random() * 900; 
                    const px = player.x + Math.cos(angle)*dist - 400; 
                    const py = player.y + Math.sin(angle)*dist - 400;

                    let pType: any = 'RAIN';
                    let pColor = '#a5f3fc';
                    let pVz = -1200;
                    let pLife = 0.5;

                    if (weatherTypeRef.current === 'SANDSTORM') {
                        pType = 'SAND'; pColor = '#d97706'; pVz = -200; pLife = 1.0;
                    } else if (weatherTypeRef.current === 'FOG') {
                        pType = 'FOG'; pColor = 'rgba(200,220,230,0.1)'; pVz = 0; pLife = 2.0;
                    } else if (weatherTypeRef.current === 'SNOW') {
                        pType = 'SNOW'; pColor = '#ffffff'; pVz = -300; pLife = 1.5;
                    } else if (weatherTypeRef.current === 'ASH') {
                        pType = 'ASH'; pColor = '#57534e'; pVz = -150; pLife = 2.0;
                    }

                    const wx = windForceRef.current.x * 500;
                    const wy = windForceRef.current.y * 500;

                    particlesRef.current.push({ 
                        id: Math.random().toString(), 
                        x: px, y: py, z: pType === 'FOG' ? 50 : 500, 
                        vx: 50 + wx, vy: 50 + wy, vz: pVz, 
                        life: pLife, maxLife: pLife, 
                        color: pColor, size: pType === 'FOG' ? 50 : 1.5, type: pType 
                    });
                }
                particleTimerRef.current = 0;
            }
        }

        // Dash & Items
        if (player.dashCharges < activeStats.dashChargesMax) {
            player.dashTimer -= dt;
            if (player.dashTimer <= 0) {
                player.dashCharges++;
                player.dashTimer = player.dashMaxCooldown * (1 - activeStats.cooldownReduction);
            }
        }
        player.autoItems.forEach(item => {
            item.timer -= dt;
            if (item.timer <= 0) {
                const result = item.effect(player, enemiesRef.current);
                if (result) {
                    if (Array.isArray(result)) projectilesRef.current.push(...result); else projectilesRef.current.push(result);
                    item.timer = item.cooldown * (1 - activeStats.cooldownReduction);
                    if (player.avatarBuffTimer > 0) item.timer *= 0.5; 
                } else { item.timer = 0.5; }
            }
        });

        // Spawn & Trigger Upgrade
        const bossAlive = enemiesRef.current.some(e => e.isBoss);
        if ((!currentWaveConfig.boss && waveTimerRef.current >= currentWaveConfig.duration) || (currentWaveConfig.boss && bossSpawnedRef.current && !bossAlive)) {
             triggerUpgrade();
        } else if (enemiesRef.current.length < currentWaveConfig.enemyCount || currentWaveConfig.boss) { 
             if (Date.now() - lastSpawnTimeRef.current > currentWaveConfig.spawnRate) {
                 if (currentWaveConfig.boss && !bossSpawnedRef.current) { spawnBoss(currentWaveConfig.boss); bossSpawnedRef.current = true; } 
                 else if (enemiesRef.current.length < currentWaveConfig.enemyCount) { spawnEnemy(); }
                 lastSpawnTimeRef.current = Date.now();
             }
        }

        if (keysRef.current['MouseLeft'] && player.weaponTimer <= 0) useMainAttack(activeStats);
        if (keysRef.current['KeyQ'] && player.skill1Timer <= 0) { useSkill1(activeStats); player.skill1Timer = player.skill1MaxCooldown * (1 - activeStats.cooldownReduction); }
        if (keysRef.current['KeyE'] && player.dashCharges > 0) { useDash(); player.dashCharges--; if (player.dashTimer <= 0) player.dashTimer = player.dashMaxCooldown * (1 - activeStats.cooldownReduction); keysRef.current['KeyE'] = false; }
        if (keysRef.current['KeyR']) activateItem();
    }

    if (shakeRef.current > 0) shakeRef.current -= dt * 30; if (shakeRef.current < 0) shakeRef.current = 0;
    updateProjectiles(dt, activeStats);
    updateEnemies(dt, activeStats);
    updateParticles(dt);

    const levelIdx = Math.floor(waveRef.current / 5);
    const biome = LEVEL_CONFIGS[Math.min(levelIdx, LEVEL_CONFIGS.length-1)].biome;
    const boss = enemiesRef.current.find(e => e.isBoss);
    setHudData({
        hp: player.stats.hp, maxHp: activeStats.maxHp, xp: player.xp, xpNext: player.xpToNextLevel,
        time: timeRef.current, wave: waveRef.current + 1, level: player.level,
        state: gameStateRef.current, skill1Cd: player.skill1Timer, dashCd: player.dashTimer, 
        dashCharges: player.dashCharges, dashMax: activeStats.dashChargesMax, itemCd: player.itemTimer,
        activeItem: player.activeItem, bossHp: boss ? boss.hp : 0, bossMaxHp: boss ? boss.maxHp : 0,
        autoItems: player.autoItems, buffTime: player.avatarBuffTimer, weather: weatherTypeRef.current, biome
    });

    if (player.stats.hp <= 0 && gameStateRef.current === GameState.TOWER) {
        gameStateRef.current = GameState.GAME_OVER;
        onGameOver();
    }
  };

  const spawnEnemy = () => {
    const angle = Math.random() * Math.PI * 2; const distance = 850; 
    const ex = playerRef.current.x + Math.cos(angle) * distance; const ey = playerRef.current.y + Math.sin(angle) * distance;

    // Select monster based on Level Config
    const currentWave = waveRef.current;
    const levelIdx = Math.min(Math.floor(currentWave / 5), LEVEL_CONFIGS.length - 1);
    const levelConfig = LEVEL_CONFIGS[levelIdx];
    const monsterType = levelConfig.monsters[Math.floor(Math.random() * levelConfig.monsters.length)];

    let hp = 30 + currentWave * 15; let speed = 80 + Math.random()*20;
    let initialZ = 0;

    // Specific Monster Stats (Simplified logic)
    if (monsterType.includes('GOLEM') || monsterType.includes('TROLL')) { hp *= 2; speed *= 0.6; }
    if (monsterType.includes('WOLF') || monsterType.includes('DOG')) { hp *= 0.7; speed *= 1.4; }
    if (monsterType.includes('BAT') || monsterType.includes('HARPY') || monsterType.includes('GHOST')) { 
        hp *= 0.6; 
        speed *= 1.3; 
        initialZ = 100; // Start flying high
    }
    if (monsterType.includes('SNAKE') || monsterType.includes('WORM')) {
        speed *= 1.2;
    }

    const variant = Math.floor(Math.random() * 3);
    if (variant === 1) { hp *= 0.8; speed *= 1.2; } else if (variant === 2) { hp *= 1.3; speed *= 0.85; }

    enemiesRef.current.push({
      id: Math.random().toString(), x: ex, y: ey, z: initialZ, 
      type: monsterType, isBoss: false, hp, maxHp: hp, defense: currentWave * 2, speed, damage: 10 + currentWave * 2,
      radius: 20, hitboxRadius: 16, frame: 0, vx: 0, vy: 0, hitFlash: 0,
      state: 'CHASING', stateTimer: 0, attackRange: 50, windupTime: 0.5, recoverTime: 0.5, variant
    });
  };

  const spawnBoss = (config: any) => {
      if (!config) return;

      const dist = 600; const angle = Math.random() * Math.PI * 2;
      const hp = 5000 * config.hpMult * (1 + waveRef.current * 0.2); 
      const damage = 60 * config.dmgMult + waveRef.current * 2; 

      enemiesRef.current.push({
          id: 'boss', x: playerRef.current.x + Math.cos(angle)*dist, y: playerRef.current.y + Math.sin(angle)*dist, z: 0,
          type: config.type, isBoss: true, hp, maxHp: hp, defense: 50 + waveRef.current * 5, 
          speed: 120, // High Mobility as requested
          damage, radius: 80, hitboxRadius: 60, frame: 0, vx: 0, vy: 0, hitFlash: 0,
          state: 'CHASING', stateTimer: 0, attackRange: 150, windupTime: 1.0, recoverTime: 1.0, variant: 0, 
          skill1Cd: 0, skill2Cd: 5, skill3Cd: 10,
          skill1MaxCd: 6, skill2MaxCd: 12, skill3MaxCd: 18,
          bossColor: config.color
      });
      shakeRef.current = 20; 
  };

  const updateEnemies = (dt: number, stats: any) => {
      const p = playerRef.current;
      const enemiesList = enemiesRef.current;
      const enemyCount = enemiesList.length;

      enemiesRef.current = enemiesList.filter((e, idx) => {
          if (e.hitFlash > 0) e.hitFlash -= dt;
          if (e.frozenTimer && e.frozenTimer > 0) { e.frozenTimer -= dt; return true; }
          e.frame += dt; 

          // --- BOSS AI LOGIC ---
          if (e.isBoss) {
              // Skill Cooldowns
              if (e.skill1Cd && e.skill1Cd > 0) e.skill1Cd -= dt;
              if (e.skill2Cd && e.skill2Cd > 0) e.skill2Cd -= dt;
              if (e.skill3Cd && e.skill3Cd > 0) e.skill3Cd -= dt;

              // Retreat Logic (Low HP)
              if (e.hp < e.maxHp * 0.3 && e.state !== 'RETREATING' && e.state !== 'ATTACKING') {
                  if (Math.random() < 0.05) { // Chance to decide to retreat
                      e.state = 'RETREATING';
                      e.stateTimer = 5.0; // Retreat for 5 seconds
                  }
              }

              // Regen if retreating or idle
              if (e.state === 'RETREATING' || e.state === 'RECOVERING') {
                  e.hp = Math.min(e.maxHp, e.hp + 10 * dt);
              }
          }

          // Separation Flocking
          if (!e.isBoss && !e.type.includes('BAT')) { // Bats fly over enemies
              let sepX = 0, sepY = 0; const checkLimit = Math.min(idx + 3, enemyCount);
              for (let i = Math.max(0, idx - 3); i < checkLimit; i++) {
                  if (i === idx) continue;
                  const other = enemiesList[i];
                  const distSq = (e.x - other.x)**2 + (e.y - other.y)**2; const minDist = (e.radius + other.radius) * 0.8;
                  if (distSq < minDist**2 && distSq > 0.1) {
                      const pushDist = Math.sqrt(distSq); const pushForce = (minDist - pushDist) / pushDist;
                      sepX += (e.x - other.x) * pushForce; sepY += (e.y - other.y) * pushForce;
                  }
              }
              e.vx += sepX * 200 * dt; e.vy += sepY * 200 * dt;
          }

          if (Math.abs(e.vx) > 1 || Math.abs(e.vy) > 1) { e.x += e.vx * dt; e.y += e.vy * dt; e.vx *= 0.9; e.vy *= 0.9; }

          const dx = p.x - e.x; const dy = p.y - e.y; const dist = Math.hypot(dx, dy);

          if (e.state === 'CHASING') {
              if (dist > 10) {
                  let speed = e.speed * (e.isBoss ? 1.5 : 1); // Bosses move faster
                  let mx = dx / dist;
                  let my = dy / dist;

                  // --- SNAKE MOVEMENT ---
                  if (e.type.includes('SNAKE') || e.type.includes('WORM')) {
                      // Winding motion: add vector perpendicular to direction
                      const wobble = Math.sin(e.frame * 8) * 0.6;
                      mx += -my * wobble; // Perpendicular X
                      my += mx * wobble; // Perpendicular Y
                      const len = Math.hypot(mx, my);
                      mx /= len; my /= len;
                  }

                  // --- BAT MOVEMENT ---
                  if (e.type.includes('BAT') || e.type.includes('HARPY') || e.type.includes('GHOST')) {
                      // Hover logic
                      const hoverHeight = 100 + Math.sin(e.frame * 2) * 20;
                      e.z = lerp(e.z, hoverHeight, dt * 2);

                      // Swoop trigger
                      if (dist < 200 && dist > 50 && Math.random() < 0.02) {
                          e.state = 'WINDUP';
                          e.stateTimer = 0.4;
                      }
                  }

                  e.x += mx * speed * dt;
                  e.y += my * speed * dt;
              }

              // Boss Skill Trigger Logic
              if (e.isBoss) {
                  if (e.skill1Cd && e.skill1Cd <= 0 && dist < 300) { e.state = 'WINDUP'; e.stateTimer = 0.5; e.skill1Cd = e.skill1MaxCd; } // Skill 1 (e.g. Smash)
                  else if (e.skill2Cd && e.skill2Cd <= 0) { e.state = 'WINDUP'; e.stateTimer = 0.8; e.skill2Cd = e.skill2MaxCd; } // Skill 2 (e.g. Nova/Range)
                  else if (e.skill3Cd && e.skill3Cd <= 0) { e.state = 'WINDUP'; e.stateTimer = 1.2; e.skill3Cd = e.skill3MaxCd; } // Skill 3 (Ult)
                  else if (dist < e.attackRange) { e.state = 'WINDUP'; e.stateTimer = e.windupTime; } // Normal Attack
              } else {
                  // Normal Enemy Attack Trigger
                  if (!(e.type.includes('BAT') || e.type.includes('HARPY'))) { // Flying enemies trigger via Swoop
                      if (dist < e.attackRange) { e.state = 'WINDUP'; e.stateTimer = e.windupTime; }
                  }
              }
          }
          else if (e.state === 'RETREATING') {
              // Run away from player
              if (dist > 0) {
                  e.x -= (dx / dist) * e.speed * 1.5 * dt;
                  e.y -= (dy / dist) * e.speed * 1.5 * dt;
              }
              e.stateTimer -= dt;
              if (e.stateTimer <= 0 || dist > 600) {
                  e.state = 'CHASING';
              }
          }
          else if (e.state === 'WINDUP') {
              e.stateTimer -= dt;

              // --- BAT SWOOP TELEGRAPH ---
              if (e.type.includes('BAT') || e.type.includes('HARPY')) {
                  e.z = lerp(e.z, 140, dt * 5); // Wind up backwards/upwards
              }

              if (e.stateTimer <= 0) {
                  if (e.type.includes('BAT') || e.type.includes('HARPY')) {
                      e.state = 'SWOOPING'; // Flying enemies swoop instead of just ATTACKING
                  } else {
                      e.state = 'ATTACKING';

                      // Boss Skill Execution
                      if (e.isBoss) {
                          projectilesRef.current.push({ 
                              id: Math.random().toString(), x: e.x, y: e.y, z: 0, vx: 0, vy: 0, 
                              damage: e.damage, duration: 0.5, radius: 150, type: 'BOSS_SMASH', 
                              color: e.bossColor || '#ef4444', pierce: 999, isEnemy: true 
                          });
                          shakeRef.current = 20;
                      } 
                      // Snake Poison Attack
                      else if (e.type.includes('SNAKE') || e.type.includes('WORM')) {
                          if (dist < e.attackRange + 40) {
                              takeDamage(p, e.damage, 'POISON');
                          }
                      }
                      // Normal Melee
                      else if (dist < e.attackRange + 30) { 
                          takeDamage(p, e.damage); 
                      }
                      e.state = 'RECOVERING'; 
                      e.stateTimer = e.recoverTime;
                  }
              }
          } 
          else if (e.state === 'SWOOPING') {
              // --- FLYING ENEMY DIVE ---
              const speed = e.speed * 3.5;
              const diveDx = p.x - e.x;
              const diveDy = p.y - e.y;
              const diveDist = Math.hypot(diveDx, diveDy);

              if (diveDist > 10) {
                  e.x += (diveDx / diveDist) * speed * dt;
                  e.y += (diveDy / diveDist) * speed * dt;
              }
              e.z = lerp(e.z, 0, dt * 10); // Crash down

              if (diveDist < 20 || e.z < 10) {
                  takeDamage(p, e.damage);
                  e.state = 'RECOVERING';
                  e.stateTimer = 1.0;
              }
          }
          else if (e.state === 'RECOVERING') { 
              e.stateTimer -= dt; 

              // Flying recover (Fly back up)
              if (e.type.includes('BAT') || e.type.includes('HARPY')) {
                  e.z = lerp(e.z, 100, dt * 2);
              }

              if (e.stateTimer <= 0) e.state = 'CHASING'; 
          }

          for (const proj of projectilesRef.current) {
               if (proj.duration <= 0 || proj.isEnemy) continue;
               if (proj.delayedDamage && proj.duration > 0.1) continue;

               // --- FLYING ENEMY COLLISION LOGIC ---
               // Ground attacks (Sword Slash, Fire Zone) miss high flying enemies
               if (e.z > 50 && (proj.type === 'SWORD_SLASH' || proj.type === 'FIRE_ZONE' || proj.type === 'EARTH_SPIKE')) {
                   continue;
               }

               const pDist = Math.hypot(proj.x - e.x, proj.y - e.y);
               if(pDist < proj.radius + e.hitboxRadius) {
                   if (proj.type === 'TIME_PRISON') { e.frozenTimer = 3.0; continue; }
                   if (proj.knockbackForce) { const kAngle = Math.atan2(e.y - proj.y, e.x - proj.x); e.vx += Math.cos(kAngle) * proj.knockbackForce; e.vy += Math.sin(kAngle) * proj.knockbackForce; }
                   const isAoe = proj.type === 'SWORD_SLASH' || proj.type === 'FIRE_ZONE' || proj.type === 'OCEAN_WAVE';
                   let dmg = isAoe ? proj.damage * 5 * dt : proj.damage;
                   const isCrit = Math.random() < stats.critChance; if (isCrit) dmg *= stats.critDamage;
                   if (stats.executionerThreshold > 0 && (e.hp / e.maxHp) < 0.3) { dmg *= (1 + stats.executionerThreshold); }
                   const mitigation = 100 / (100 + Math.max(0, e.defense - stats.armorPenetration));
                   const finalDmg = dmg * mitigation;
                   e.hitFlash = 0.15; 
                   if (!isAoe) { if (proj.type === 'ARROW' || proj.type === 'MAGIC_ORB') { const kAngle = Math.atan2(e.y - proj.y, e.x - proj.x); const force = e.type === 'BAT' ? 500 : 300; e.vx = Math.cos(kAngle) * force; e.vy = Math.sin(kAngle) * force; proj.pierce--; if (proj.pierce < 0) proj.duration = 0; } }
                   e.hp -= finalDmg;
                   if (!isAoe || Math.random() > 0.8) { createDamageNumber(e.x, e.y, e.z + 40, finalDmg, isCrit, false, mitigation < 0.7); const color = proj.color; if (proj.type === 'MAGIC_ORB' || proj.type === 'AUTO_FIREBALL' || proj.type === 'SWORD_SLASH') { createParticle(e.x, e.y, e.z + 20, color, 3, 'MAGIC'); } else { createParticle(e.x, e.y, e.z + 20, color, 2, 'IMPACT'); } }
                   if(e.hp <= 0 && !e.isBoss) { createParticle(e.x, e.y, e.z, '#ef4444', 12, 'BLOOD'); if (stats.lifeSteal > 0) { const heal = stats.maxHp * stats.lifeSteal; if (heal > 0) { p.stats.hp = Math.min(stats.maxHp, p.stats.hp + heal); createDamageNumber(p.x, p.y, p.z + 80, heal, false, false, false); } } if (!isAoe && proj.pierce < 0) break; break; }
               }
          }

          if(e.hp <= 0) {
              p.xp += e.isBoss ? 500 : 15; shakeRef.current += e.isBoss ? 20 : 2; 
              if(p.xp >= p.xpToNextLevel) { p.level++; p.xp -= p.xpToNextLevel; p.xpToNextLevel *= 1.2; p.stats.damage *= 1.1; p.stats.maxHp *= 1.1; p.stats.hp = p.stats.maxHp; createDamageNumber(p.x, p.y, p.z+60, 0, true); shakeRef.current += 10; }
              return false;
          }
          return true;
      });
  };

  const takeDamage = (p: Player, amount: number, effectType?: 'POISON' | 'NORMAL') => {
      const reducedByPercent = amount * (1 - Math.min(0.8, p.stats.damageReduction)); 
      const finalDmg = Math.max(1, reducedByPercent - p.stats.defense);
      p.stats.hp -= finalDmg; 
      shakeRef.current = 10; 
      p.slowTimer = 0.5; 
      p.lastHitTime = 0; 

      if (effectType === 'POISON') {
          p.poisonTimer = 5.0; // 5 seconds of poison
          createParticle(p.x, p.y, p.z + 40, '#a3e635', 10, 'POISON');
      }

      createDamageNumber(p.x, p.y, p.z + 50, finalDmg, false, true);
  };

  const updateProjectiles = (dt: number, stats: any) => {
      const p = playerRef.current;
      projectilesRef.current = projectilesRef.current.filter(proj => {
          proj.duration -= dt;
          if(proj.type === 'SWORD_SLASH' || proj.type === 'OCEAN_WAVE' || proj.type === 'TIME_PRISON') { if (proj.type === 'OCEAN_WAVE') proj.radius += dt * 100; else { proj.x = p.x; proj.y = p.y; } } 
          else { if (proj.type === 'ARCANE_COLOSSUS') { let closest = null; let minD = Infinity; for(const e of enemiesRef.current) { const d = Math.hypot(e.x - proj.x, e.y - proj.y); if (d < minD) { minD = d; closest = e; } } if (closest) { const angle = Math.atan2(closest.y - proj.y, closest.x - proj.x); proj.vx += Math.cos(angle) * 1000 * dt; proj.vy += Math.sin(angle) * 1000 * dt; proj.vx *= 0.95; proj.vy *= 0.95; } } proj.x += proj.vx * dt; proj.y += proj.vy * dt; }
          if (!proj.isEnemy && proj.duration > 0) { if (proj.type === 'ARROW') { if (Math.random() > 0.5) createParticle(proj.x, proj.y, proj.z, 'rgba(255,255,255,0.3)', 1, 'TRAIL'); } else if (proj.type === 'MAGIC_ORB' || proj.type === 'ENEMY_BOLT' || proj.type === 'ARCANE_COLOSSUS') { if (Math.random() > 0.2) createParticle(proj.x + (Math.random()-0.5)*10, proj.y + (Math.random()-0.5)*10, proj.z, proj.color, 1, 'MAGIC'); } else if (proj.type === 'AUTO_FIREBALL' || proj.type === 'FIRE_ZONE' || proj.type === 'HELL_FLAME') { if (Math.random() > 0.3) createParticle(proj.x + (Math.random()-0.5)*proj.radius, proj.y + (Math.random()-0.5)*proj.radius, proj.z, proj.color, 1, 'FIRE'); } else if (proj.type === 'SPIRIT_WAVE') { createParticle(proj.x, proj.y, proj.z, proj.color, 1, 'MAGIC'); } }
          if (Math.abs(proj.x - p.x) > 1500 || Math.abs(proj.y - p.y) > 1500) return false;
          if (proj.isEnemy) { const dist = Math.hypot(proj.x - p.x, proj.y - p.y); if (proj.type === 'LICH_DRAIN_ZONE') { if (dist < proj.radius) { takeDamage(p, proj.damage * dt); const lich = enemiesRef.current.find(e => e.type === 'BOSS_LICH'); if (lich && lich.hp < lich.maxHp) { lich.hp += proj.damage * dt * 0.5; } } } else if (dist < (proj.type === 'BOSS_SMASH' ? proj.radius : 20)) { takeDamage(p, proj.damage); return false; } else if (dist < proj.radius) { takeDamage(p, proj.damage); if (proj.type === 'POISON_SPIT') { p.slowTimer = 1.0; } return false; } }
          return proj.duration > 0;
      });
  };

  const createDamageNumber = (x: number, y: number, z: number, val: number, crit: boolean, isPlayerDamage = false, isBlocked = false) => {
      if (val < 1 && !isBlocked) return;
      damageNumbersRef.current.push({ id: Math.random().toString(), x: x + (Math.random()-0.5)*20, y, z, value: val, life: 0.8, isCrit: crit, isPlayerDamage });
  };

  const useMainAttack = (stats: any) => {
     const p = playerRef.current; const angle = p.facing; const vx = Math.cos(angle) * 800; const vy = Math.sin(angle) * 800; const atkSpdMultiplier = Math.max(0.1, stats.attackSpeed);
     if (p.archetype === Archetype.WARRIOR) { projectilesRef.current.push({ id: Math.random().toString(), x: p.x, y: p.y, z: 20, vx: 0, vy: 0, damage: stats.damage, duration: 0.3, radius: 100 * stats.areaSize, type: 'SWORD_SLASH', color: '#60a5fa', pierce: 999 }); p.weaponTimer = (0.6 / atkSpdMultiplier) * (1 - stats.cooldownReduction); } 
     else { projectilesRef.current.push({ id: Math.random().toString(), x: p.x, y: p.y, z: 30, vx, vy, damage: stats.damage, duration: 1.5, radius: 15, type: p.archetype === Archetype.ARCHER ? 'ARROW' : 'MAGIC_ORB', color: p.color, pierce: p.archetype === Archetype.MAGE ? 2 : 0 }); const baseCd = p.archetype === Archetype.ARCHER ? 0.4 : 0.5; p.weaponTimer = (baseCd / atkSpdMultiplier) * (1 - stats.cooldownReduction); }
  };

  const useSkill1 = (stats: any) => {
      const p = playerRef.current; createParticle(p.x, p.y, 20, '#fff', 10); shakeRef.current = 5; 
      if(p.archetype === Archetype.WARRIOR) { 
          projectilesRef.current.push({ id: Math.random().toString(), x: p.x, y: p.y, z: 20, vx: 0, vy: 0, damage: stats.damage * 2.5, duration: 0.5, radius: 160 * stats.areaSize, type: 'SWORD_SLASH', color: '#ef4444', pierce: 999 }); 
      } 
      else if (p.archetype === Archetype.ARCHER) {
          // ARCHER Q: CONE ARROW BURST
          const baseAngle = Math.atan2(mouseWorldRef.current.y - p.y, mouseWorldRef.current.x - p.x);
          const arrowCount = 5;
          const spread = Math.PI / 4; // 45 degrees spread
          const startAngle = baseAngle - spread / 2;
          const stepAngle = spread / (arrowCount - 1);

          for(let i=0; i<arrowCount; i++) {
              const currentAngle = startAngle + (stepAngle * i);
              const vx = Math.cos(currentAngle) * 900;
              const vy = Math.sin(currentAngle) * 900;

              projectilesRef.current.push({ 
                  id: Math.random().toString(), 
                  x: p.x, y: p.y, z: 30, 
                  vx, vy, 
                  damage: stats.damage * 1.5, 
                  duration: 1.0, 
                  radius: 20, 
