              });
          }
      }
      else { 
          projectilesRef.current.push({ id: Math.random().toString(), x: mouseWorldRef.current.x, y: mouseWorldRef.current.y, z: 0, vx: 0, vy: 0, damage: stats.damage * 3, duration: 1.2, radius: 120 * stats.areaSize, type: 'FIRE_ZONE', color: p.archetype === Archetype.MAGE ? '#9333ea' : '#ef4444', pierce: 999 }); 
      }
  };

  const useDash = () => {
      const p = playerRef.current; const angle = Math.atan2(mouseWorldRef.current.y - p.y, mouseWorldRef.current.x - p.x); const vx = Math.cos(angle) * 1200; const vy = Math.sin(angle) * 1200;
      p.x += vx * 0.2; p.y += vy * 0.2; p.z = 40; createParticle(p.x, p.y, 10, '#fff', 5);
  };

  const activateItem = () => { const p = playerRef.current; if (p.activeItem && p.itemTimer <= 0) { p.activeItem.effect(p, enemiesRef.current); p.itemTimer = p.activeItem.cooldown; } };

  // --- FIXED TRIGGER UPGRADE (NO INFINITE LOOP + NO SOFT LOCK) ---
  const triggerUpgrade = () => {
    gameStateRef.current = GameState.PAUSED;
    const options: Upgrade[] = [];
    const rollItem = !playerRef.current.activeItem && Math.random() > 0.8; 
    const selectedIds = new Set<string>();

    let safetyCounter = 0;
    while (options.length < 4 && safetyCounter < 50) {
        safetyCounter++;
        let pool = UPGRADES_LIST;

        if (rollItem && options.length === 0) { 
            // Try to find items specifically
            const itemPool = UPGRADES_LIST.filter(u => u.type === 'ITEM');
            if (itemPool.length > 0) {
                pool = itemPool;
            } else {
                // Fallback to normal pool if no items available (prevents soft lock)
                pool = UPGRADES_LIST.filter(u => u.type !== 'ITEM' && u.type !== 'AUTO_ITEM'); 
            }
        } 
        else {
            pool = UPGRADES_LIST.filter(u => {
                if (u.type === 'ITEM' && playerRef.current.activeItem) return false;
                if (u.type === 'AUTO_ITEM' && playerRef.current.autoItems.some(ai => ai.id === u.autoItemRef?.id)) return false;
                return true;
            });
        }

        // Critical Fallback: If filtered pool is empty (e.g. player has everything), use STAT upgrades which are always stackable
        if (pool.length === 0) {
            pool = UPGRADES_LIST.filter(u => u.type === 'STAT');
        }

        if (pool.length === 0) break; // Should effectively never happen with STAT fallback

        const rand = pool[Math.floor(Math.random() * pool.length)];
        // Allow duplicates if we are forcing STAT fallback, otherwise ensure unique
        if (!selectedIds.has(rand.id) || pool.every(p => selectedIds.has(p.id))) { 
            options.push({...rand, id: rand.id}); 
            selectedIds.add(rand.id); 
        }
    }
    setUpgradeOptions(options);
    setShowUpgrade(true);
  };

  const getLegendaryItems = () => {
      const p = playerRef.current;
      const legendaries: (Item | AutoItem)[] = [];
      if (p.activeItem && p.activeItem.isLegendary) legendaries.push(p.activeItem);
      p.autoItems.forEach(ai => {
          if (ai.isLegendary) legendaries.push(ai);
      });
      return legendaries;
  };

  const applyUpgrade = (upgrade: Upgrade, swapId?: string) => {
      const p = playerRef.current;

      // Handle Swap Logic
      if (swapId) {
          if (p.activeItem && p.activeItem.id === swapId) {
              p.activeItem = null;
          } else {
              p.autoItems = p.autoItems.filter(ai => ai.id !== swapId);
          }
      }

      if (upgrade.type === 'ITEM' && upgrade.itemRef) { p.activeItem = upgrade.itemRef; } 
      else if (upgrade.type === 'AUTO_ITEM' && upgrade.autoItemRef) { p.autoItems.push({ ...upgrade.autoItemRef }); } 
      else {
        if (upgrade.id.startsWith('dmg_')) p.stats.damage *= (upgrade.id.includes('rare') ? 1.25 : 1.12);
        if (upgrade.id.startsWith('atk_spd')) p.stats.attackSpeed += (upgrade.id.includes('rare') ? 0.20 : 0.10);
        if (upgrade.id.startsWith('pen_')) p.stats.armorPenetration += 8;
        if (upgrade.id.startsWith('hp_')) { const val = upgrade.id.includes('rare') ? 100 : 40; p.stats.maxHp += val; p.stats.hp += val; }
        if (upgrade.id.startsWith('def_')) p.stats.defense += (upgrade.id.includes('rare') ? 12 : 5);
        if (upgrade.id.startsWith('dmg_red')) p.stats.damageReduction += (upgrade.id.includes('epic') ? 0.10 : 0.05);
        if (upgrade.id.startsWith('ls_')) { let val = 0.001; if (upgrade.id.includes('rare')) val = 0.002; if (upgrade.id.includes('epic')) val = 0.004; p.stats.lifeSteal += val; }
        if (upgrade.id.startsWith('spd_')) p.stats.speed *= 1.1;
        if (upgrade.id.startsWith('cdr_')) p.stats.cooldownReduction = Math.min(0.7, p.stats.cooldownReduction + 0.08);
        if (upgrade.id.startsWith('area_')) p.stats.areaSize *= 1.2;
        if (upgrade.id.startsWith('dash_')) { const val = upgrade.id.includes('epic') ? 2 : 1; p.stats.dashChargesMax += val; p.dashCharges += val; }

        if (upgrade.id === 'pass_predator') { p.stats.critChance += 0.05; p.stats.critDamage += 0.2; }
        if (upgrade.id === 'pass_colossus') { p.stats.maxHp *= 1.25; p.stats.damageReduction += 0.05; p.stats.hp += 50; }
        if (upgrade.id === 'pass_hourglass') { p.stats.cooldownReduction += 0.15; }
        if (upgrade.id === 'pass_executioner') { p.stats.executionerThreshold = 0.15; }
        if (upgrade.id === 'pass_shadow') { p.stats.speed *= 1.1; p.stats.attackSpeed += 0.1; }
        if (upgrade.id === 'pass_ancient_blood') { p.stats.regen += 1.5; }
        if (upgrade.id === 'pass_living_mana') { p.stats.damage *= 1.1; } 
        if (upgrade.id === 'pass_guardian') { p.stats.shieldOnLowHp = true; }
        if (upgrade.id === 'pass_1000runes') { p.stats.damage *= 1.02; } 
        if (upgrade.id === 'pass_echo') { p.stats.towerEchoStacks++; }
      }
      setLastUpgrade(upgrade); setShowUpgrade(false); gameStateRef.current = GameState.TOWER;

      const currentConfig = WAVE_CONFIGS[waveRef.current] || WAVE_CONFIGS[WAVE_CONFIGS.length-1];
      if ((!currentConfig.boss && waveTimerRef.current >= currentConfig.duration) || (currentConfig.boss)) {
         if (p.stats.towerEchoStacks > 0) { p.stats.damage *= (1 + p.stats.towerEchoStacks * 0.01); p.stats.defense *= (1 + p.stats.towerEchoStacks * 0.01); } 
         waveRef.current++; waveTimerRef.current = 0; bossSpawnedRef.current = false;
      }
  };

  const updateParticles = (dt: number) => {
      particlesRef.current = particlesRef.current.filter(p => {
          p.life -= dt;

          if (p.type === 'FIRE') { 
              p.z += 50 * dt; 
              p.size = Math.max(0, p.size - dt * 5); 
              p.x += Math.sin(timeRef.current * 5 + p.id[0]) * 10 * dt; 
          } 
          else if (p.type === 'TRAIL') { 
              p.size = Math.max(0, p.size - dt * 10); 
          }
          else if (p.type === 'MAGIC') { p.vx += (Math.random()-0.5) * 200 * dt; p.vy += (Math.random()-0.5) * 200 * dt; p.z += 20 * dt; p.x += p.vx * dt; p.y += p.vy * dt; }
          else if (p.type === 'POISON') { p.z += 30 * dt; p.size = Math.max(0, p.size - dt * 5); }
          else if (p.type === 'IMPACT') { p.vx *= 0.9; p.vy *= 0.9; p.x += p.vx * dt; p.y += p.vy * dt; p.z += p.vz * dt; }

          // --- WEATHER PARTICLE PHYSICS ---
          else if (p.type === 'SNOW' || p.type === 'ASH') {
               // Swaying motion
               const sway = Math.sin(timeRef.current * 2 + parseInt(p.id)) * 20;
               p.x += (p.vx + sway + windForceRef.current.x * 200) * dt; 
               p.y += (p.vy + windForceRef.current.y * 200) * dt; 
               p.z += p.vz * dt; // Fall slow
          }
          else if (p.type === 'FOG' || p.type === 'SAND') {
               // Move with wind primarily
               p.x += (p.vx + windForceRef.current.x * 400) * dt;
               p.y += (p.vy + windForceRef.current.y * 400) * dt;
               p.z = 50 + Math.sin(timeRef.current + parseInt(p.id)) * 10; // Bobbing
          }
          else if (p.type === 'RAIN' || p.type === 'STORM') {
