        else if (p.type === 'ARCANE_COLOSSUS') { ctx.beginPath(); ctx.arc(x, y, 10, 0, Math.PI*2); ctx.fillStyle='#fff'; ctx.fill(); ctx.beginPath(); ctx.arc(x, y, 6, 0, Math.PI*2); ctx.fillStyle=p.color; ctx.fill(); } 
        else if (p.type === 'BOSS_SMASH' || p.type === 'JUDGEMENT_STRIKE') { ctx.fillStyle = p.type === 'BOSS_SMASH' ? 'rgba(255,255,255,0.8)' : 'rgba(252, 211, 77, 0.4)'; ctx.beginPath(); ctx.ellipse(x, y, p.radius, p.radius*0.5, 0, 0, Math.PI*2); ctx.fill(); } 
        else { ctx.beginPath(); ctx.arc(x, y, 4, 0, Math.PI*2); ctx.fill(); ctx.fillStyle = 'rgba(255,255,255,0.4)'; ctx.beginPath(); ctx.arc(x - p.vx*0.02, y - p.vy*0.02, 2, 0, Math.PI*2); ctx.fill(); }
        ctx.shadowBlur = 0;
    }

    ctx.restore(); 

    // --- WEATHER OVERLAY (FOG / GRADIENTS / VISION MASK) ---
    const isSandstorm = weatherTypeRef.current === 'SANDSTORM';
    const isSnowStorm = weatherTypeRef.current === 'SNOW';
    const isFog = weatherTypeRef.current === 'FOG';

    if (gameStateRef.current === GameState.TOWER && (isFog || isSandstorm || isSnowStorm) && weatherIntensityRef.current > 0.1) {
        // Vision Restriction Mask
        // Creates a hole in the center (transparent) and gets darker/foggy at edges
        const visionRadius = (isSandstorm || isSnowStorm) ? 250 : 450;
        const grad = ctx.createRadialGradient(cx, cy, 100, cx, cy, visionRadius * 2.5);
        const intensity = weatherIntensityRef.current * 0.95;

        let fogColor = 'rgba(200, 215, 210,'; // Fog (Greyish Cyan)
        if (isSandstorm) fogColor = 'rgba(180, 130, 80,'; // Sand (Brownish)
        if (isSnowStorm) fogColor = 'rgba(220, 240, 255,'; // Snow (Whiteish Blue)

        grad.addColorStop(0, `${fogColor} 0)`);
        grad.addColorStop(0.3, `${fogColor} ${intensity * 0.2})`);
        grad.addColorStop(1, `${fogColor} ${intensity})`);

        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    }

    // Vignette for atmosphere
    const vignette = ctx.createRadialGradient(cx, cy, 300, cx, cy, 1000); 
    vignette.addColorStop(0, 'rgba(0,0,0,0)'); 
    vignette.addColorStop(1, 'rgba(0,0,0,0.8)'); 
    ctx.fillStyle = vignette; 
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    if (weatherTypeRef.current === 'RAIN' || weatherTypeRef.current === 'STORM') { 
        ctx.fillStyle = `rgba(30, 58, 138, ${weatherIntensityRef.current * 0.15})`; 
        ctx.fillRect(0,0,CANVAS_WIDTH, CANVAS_HEIGHT); 
    }

    if (playerRef.current.slowTimer > 0) { ctx.fillStyle = 'rgba(69, 10, 10, 0.2)'; ctx.fillRect(0,0,CANVAS_WIDTH, CANVAS_HEIGHT); }
    if (playerRef.current.avatarBuffTimer > 0) {
        const pulse = 0.1 + Math.sin(timeRef.current * 10) * 0.05;
        ctx.fillStyle = `rgba(252, 211, 77, ${pulse})`; ctx.fillRect(0,0,CANVAS_WIDTH, CANVAS_HEIGHT);
    }

    // Poison Overlay
    if (playerRef.current.poisonTimer > 0) {
        ctx.fillStyle = `rgba(163, 230, 53, ${0.1 + Math.sin(timeRef.current * 5) * 0.05})`;
        ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    }

    // ... (Aim Assist & Damage Numbers)
    const pIso = toIso(playerRef.current.x, playerRef.current.y);
    const playerScreenX = cx + (cameraRef.current.x + shakeX + pIso.x) * ZOOM_LEVEL;
    const playerScreenY = cy + (cameraRef.current.y + shakeY + pIso.y - (playerRef.current.z || 0)) * ZOOM_LEVEL;
    const mouseScreenX = cx + mouseScreenRef.current.x; const mouseScreenY = cy + mouseScreenRef.current.y;
    let isAimingAtEnemy = false; for(const e of enemiesRef.current) { const dist = Math.hypot(e.x - mouseWorldRef.current.x, e.y - mouseWorldRef.current.y); if (dist < 40) { isAimingAtEnemy = true; break; } }
    ctx.save(); ctx.strokeStyle = isAimingAtEnemy ? 'rgba(239, 68, 68, 0.5)' : 'rgba(255, 255, 255, 0.2)'; ctx.setLineDash([4, 4]); ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(playerScreenX, playerScreenY - 20); ctx.lineTo(mouseScreenX, mouseScreenY); ctx.stroke(); ctx.setLineDash([]); ctx.translate(mouseScreenX, mouseScreenY); ctx.rotate(reticleAngleRef.current); ctx.strokeStyle = isAimingAtEnemy ? '#ef4444' : '#fff'; ctx.lineWidth = 2; const rSize = 12; ctx.beginPath(); ctx.moveTo(rSize, 0); ctx.lineTo(rSize/2, -rSize/2); ctx.moveTo(rSize, 0); ctx.lineTo(rSize/2, rSize/2); ctx.moveTo(-rSize, -rSize/2); ctx.lineTo(-rSize/2, 0); ctx.lineTo(-rSize, rSize/2); ctx.stroke(); ctx.fillStyle = isAimingAtEnemy ? '#ef4444' : '#fff'; ctx.beginPath(); ctx.arc(0, 0, 2, 0, Math.PI*2); ctx.fill(); ctx.restore();
    for(const dn of damageNumbersRef.current) { const pos = toIso(dn.x, dn.y, dn.z); const sx = cx + (pos.x + cameraRef.current.x) * ZOOM_LEVEL; const sy = cy + (pos.y + cameraRef.current.y) * ZOOM_LEVEL; ctx.fillStyle = dn.isPlayerDamage ? '#ef4444' : (dn.isCrit ? '#fbbf24' : 'white'); ctx.strokeStyle = '#020617'; ctx.lineWidth = 4; ctx.lineJoin = 'round'; const offset = (1 - dn.life) * 80; const alpha = Math.min(1, dn.life * 3); ctx.save(); ctx.globalAlpha = alpha; ctx.translate(sx, sy - offset); if (dn.isCrit) { const scale = 1.5 + Math.sin((1-dn.life)*10)*0.2; ctx.scale(scale, scale); ctx.font = '900 28px "Cinzel", serif'; } else { ctx.font = 'bold 20px "Cinzel", serif'; } const text = Math.floor(dn.value).toString(); ctx.strokeText(text, 0, 0); ctx.fillText(text, 0, 0); if (dn.isCrit) { ctx.shadowColor = '#fbbf24'; ctx.shadowBlur = 10; ctx.fillText(text, 0, 0); ctx.shadowBlur = 0; } ctx.restore(); }
  };

  const formatTime = (s: number) => `${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;

  return (
    <div className="relative w-full h-full bg-[#020617] cursor-none select-none overflow-hidden font-mono">
      <canvas ref={canvasRef} className="block w-full h-full cursor-none" />

      {/* --- HUD --- */}
      <div className="absolute inset-x-0 bottom-6 flex flex-col items-center pointer-events-none z-10 scale-[0.80] origin-bottom transition-transform">
          {hudData.bossHp > 0 && (
              <div className="mb-10 w-[700px] pointer-events-none animate-in fade-in slide-in-from-top-10 duration-700">
                  <div className="flex justify-between items-end text-red-500 font-bold mb-2 px-4 uppercase tracking-widest font-serif drop-shadow-md">
                      <span className="text-2xl">{enemiesRef.current.find(e => e.isBoss)?.type === 'BOSS_GOBLIN' ? 'Rei Goblin' : 'Terror da Torre'}</span>
                      <span className="text-sm opacity-80">{Math.ceil(hudData.bossHp)}/{Math.ceil(hudData.bossMaxHp)}</span>
                  </div>
                  <div className="relative h-6 w-full bg-slate-900 border-2 border-slate-700 rounded-sm shadow-[0_0_30px_rgba(220,38,38,0.3)] overflow-hidden">
                      <div className="absolute inset-0 bg-red-950/50"></div>
                      <div className="h-full bg-gradient-to-r from-red-900 via-red-600 to-red-500 transition-all duration-200" style={{width: `${(hudData.bossHp/hudData.bossMaxHp)*100}%`}}></div>
                  </div>
              </div>
          )}

          <div className="flex items-end gap-6 pb-2">
              <div className="bg-slate-900/95 border border-slate-700 rounded-2xl p-5 backdrop-blur-md shadow-2xl w-72 transform transition-transform">
                   <div className="flex items-center justify-between gap-2 text-white font-bold text-2xl mb-3 font-serif">
                       <span className="flex items-center gap-2 text-red-400"><Heart fill="currentColor" /> {Math.ceil(hudData.hp)}</span>
                       <span className="text-sm font-mono text-slate-500">LVL {hudData.level}</span>
                   </div>
                   <div className="relative h-4 bg-slate-950 rounded-full overflow-hidden border border-slate-800 mb-2 shadow-inner">
                       <div className="h-full bg-gradient-to-r from-red-800 to-red-500 transition-all duration-300" style={{width: `${(hudData.hp/hudData.maxHp)*100}%`}}></div>
                   </div>
                   <div className="flex justify-between text-[10px] text-slate-400 font-mono tracking-wide uppercase">
                       <span>XP Progresso</span>
                       <span className="text-amber-500">{Math.floor(hudData.xp)} / {Math.floor(hudData.xpNext)}</span>
                   </div>
                   <div className="mt-1 h-1 w-full bg-slate-800 rounded-full overflow-hidden">
                       <div className="h-full bg-amber-500 shadow-[0_0_10px_#f59e0b]" style={{width: `${(hudData.xp/hudData.xpNext)*100}%`}}></div>
                   </div>
              </div>

              <div className="flex gap-3 p-4 bg-slate-900/95 border border-slate-700 rounded-2xl backdrop-blur-md shadow-2xl">
