     if (p.archetype === Archetype.WARRIOR) { projectilesRef.current.push({ id: Math.random().toString(), x: p.x, y: p.y, z: 20, vx: 0, vy: 0, damage: stats.damage, duration: 0.3, radius: 100 * stats.areaSize, type: 'SWORD_SLASH', color: '#60a5fa', pierce: 999 }); p.weaponTimer = (0.6 / atkSpdMultiplier) * (1 - stats.cooldownReduction); } 
     else { projectilesRef.current.push({ id: Math.random().toString(), x: p.x, y: p.y, z: 30, vx, vy, damage: stats.damage, duration: 1.5, radius: 15, type: p.archetype === Archetype.ARCHER ? 'ARROW' : 'MAGIC_ORB', color: p.color, pierce: p.archetype === Archetype.MAGE ? 2 : 0 }); const baseCd = p.archetype === Archetype.ARCHER ? 0.4 : 0.5; p.weaponTimer = (baseCd / atkSpdMultiplier) * (1 - stats.cooldownReduction); }
  };

  const useSkill1 = (stats: any) => {
