  const useDash = () => {
      const p = playerRef.current; const angle = Math.atan2(mouseWorldRef.current.y - p.y, mouseWorldRef.current.x - p.x); const vx = Math.cos(angle) * 1200; const vy = Math.sin(angle) * 1200;
      p.x += vx * 0.2; p.y += vy * 0.2; p.z = 40; createParticle(p.x, p.y, 10, '#fff', 5);
  };

  const activateItem = () => { const p = playerRef.current; if (p.activeItem && p.itemTimer <= 0) { p.activeItem.effect(p, enemiesRef.current); p.itemTimer = p.activeItem.cooldown; } };

  // --- FIXED TRIGGER UPGRADE (NO INFINITE LOOP + NO SOFT LOCK) ---
  const triggerUpgrade = () => {
    gameStateRef.current = GameState.PAUSED;
    const options: Upgrade[] = [];
    const rollItem = !playerRef.current.activeItem && Math.random() > 0.8; 
    const selectedIds = new Set<string>();

    let safetyCounter = 0;
    while (options.length < 4 && safetyCounter < 50) {
        safetyCounter++;
        let pool = UPGRADES_LIST;

        if (rollItem && options.length === 0) { 
            // Try to find items specifically
            const itemPool = UPGRADES_LIST.filter(u => u.type === 'ITEM');
            if (itemPool.length > 0) {
                pool = itemPool;
            } else {
                // Fallback to normal pool if no items available (prevents soft lock)
                pool = UPGRADES_LIST.filter(u => u.type !== 'ITEM' && u.type !== 'AUTO_ITEM'); 
            }
        } 
        else {
            pool = UPGRADES_LIST.filter(u => {
                if (u.type === 'ITEM' && playerRef.current.activeItem) return false;
                if (u.type === 'AUTO_ITEM' && playerRef.current.autoItems.some(ai => ai.id === u.autoItemRef?.id)) return false;
                return true;
            });
        }

        // Critical Fallback: If filtered pool is empty (e.g. player has everything), use STAT upgrades which are always stackable
        if (pool.length === 0) {
            pool = UPGRADES_LIST.filter(u => u.type === 'STAT');
        }

        if (pool.length === 0) break; // Should effectively never happen with STAT fallback

        const rand = pool[Math.floor(Math.random() * pool.length)];
        // Allow duplicates if we are forcing STAT fallback, otherwise ensure unique
        if (!selectedIds.has(rand.id) || pool.every(p => selectedIds.has(p.id))) { 
            options.push({...rand, id: rand.id}); 
            selectedIds.add(rand.id); 
        }
    }
    setUpgradeOptions(options);
    setShowUpgrade(true);
  };

  const getLegendaryItems = () => {
      const p = playerRef.current;
      const legendaries: (Item | AutoItem)[] = [];
      if (p.activeItem && p.activeItem.isLegendary) legendaries.push(p.activeItem);
      p.autoItems.forEach(ai => {
          if (ai.isLegendary) legendaries.push(ai);
      });
      return legendaries;
  };

  const applyUpgrade = (upgrade: Upgrade, swapId?: string) => {
      const p = playerRef.current;

      // Handle Swap Logic
      if (swapId) {
          if (p.activeItem && p.activeItem.id === swapId) {
              p.activeItem = null;
          } else {
              p.autoItems = p.autoItems.filter(ai => ai.id !== swapId);
          }
      }

      if (upgrade.type === 'ITEM' && upgrade.itemRef) { p.activeItem = upgrade.itemRef; } 
      else if (upgrade.type === 'AUTO_ITEM' && upgrade.autoItemRef) { p.autoItems.push({ ...upgrade.autoItemRef }); } 
      else {
        if (upgrade.id.startsWith('dmg_')) p.stats.damage *= (upgrade.id.includes('rare') ? 1.25 : 1.12);
        if (upgrade.id.startsWith('atk_spd')) p.stats.attackSpeed += (upgrade.id.includes('rare') ? 0.20 : 0.10);
        if (upgrade.id.startsWith('pen_')) p.stats.armorPenetration += 8;
        if (upgrade.id.startsWith('hp_')) { const val = upgrade.id.includes('rare') ? 100 : 40; p.stats.maxHp += val; p.stats.hp += val; }
        if (upgrade.id.startsWith('def_')) p.stats.defense += (upgrade.id.includes('rare') ? 12 : 5);
        if (upgrade.id.startsWith('dmg_red')) p.stats.damageReduction += (upgrade.id.includes('epic') ? 0.10 : 0.05);
        if (upgrade.id.startsWith('ls_')) { let val = 0.001; if (upgrade.id.includes('rare')) val = 0.002; if (upgrade.id.includes('epic')) val = 0.004; p.stats.lifeSteal += val; }
        if (upgrade.id.startsWith('spd_')) p.stats.speed *= 1.1;
        if (upgrade.id.startsWith('cdr_')) p.stats.cooldownReduction = Math.min(0.7, p.stats.cooldownReduction + 0.08);
        if (upgrade.id.startsWith('area_')) p.stats.areaSize *= 1.2;
        if (upgrade.id.startsWith('dash_')) { const val = upgrade.id.includes('epic') ? 2 : 1; p.stats.dashChargesMax += val; p.dashCharges += val; }

        if (upgrade.id === 'pass_predator') { p.stats.critChance += 0.05; p.stats.critDamage += 0.2; }
        if (upgrade.id === 'pass_colossus') { p.stats.maxHp *= 1.25; p.stats.damageReduction += 0.05; p.stats.hp += 50; }
        if (upgrade.id === 'pass_hourglass') { p.stats.cooldownReduction += 0.15; }
        if (upgrade.id === 'pass_executioner') { p.stats.executionerThreshold = 0.15; }
        if (upgrade.id === 'pass_shadow') { p.stats.speed *= 1.1; p.stats.attackSpeed += 0.1; }
        if (upgrade.id === 'pass_ancient_blood') { p.stats.regen += 1.5; }
        if (upgrade.id === 'pass_living_mana') { p.stats.damage *= 1.1; } 
        if (upgrade.id === 'pass_guardian') { p.stats.shieldOnLowHp = true; }
        if (upgrade.id === 'pass_1000runes') { p.stats.damage *= 1.02; } 
        if (upgrade.id === 'pass_echo') { p.stats.towerEchoStacks++; }
      }
      setLastUpgrade(upgrade); setShowUpgrade(false); gameStateRef.current = GameState.TOWER;

      const currentConfig = WAVE_CONFIGS[waveRef.current] || WAVE_CONFIGS[WAVE_CONFIGS.length-1];
      if ((!currentConfig.boss && waveTimerRef.current >= currentConfig.duration) || (currentConfig.boss)) {
         if (p.stats.towerEchoStacks > 0) { p.stats.damage *= (1 + p.stats.towerEchoStacks * 0.01); p.stats.defense *= (1 + p.stats.towerEchoStacks * 0.01); } 
         waveRef.current++; waveTimerRef.current = 0; bossSpawnedRef.current = false;

         // Respawn traps on new wave (adds chaos)
         const levelIdx = Math.floor(waveRef.current / 5);
         const biome = LEVEL_CONFIGS[Math.min(levelIdx, LEVEL_CONFIGS.length-1)].biome;
         if (waveRef.current % 2 === 0) spawnTraps(biome); // Spawn more traps every 2 waves
      }
  };

  const updateParticles = (dt: number) => {
      particlesRef.current = particlesRef.current.filter(p => {
          p.life -= dt;

          if (p.type === 'FIRE') { 
              p.z += 50 * dt; 
              p.size = Math.max(0, p.size - dt * 5); 
              p.x += Math.sin(timeRef.current * 5 + p.id[0]) * 10 * dt; 
          } 
          else if (p.type === 'TRAIL') { 
              p.size = Math.max(0, p.size - dt * 10); 
          }
          else if (p.type === 'MAGIC') { p.vx += (Math.random()-0.5) * 200 * dt; p.vy += (Math.random()-0.5) * 200 * dt; p.z += 20 * dt; p.x += p.vx * dt; p.y += p.vy * dt; }
          else if (p.type === 'POISON') { p.z += 30 * dt; p.size = Math.max(0, p.size - dt * 5); }
          else if (p.type === 'IMPACT') { p.vx *= 0.9; p.vy *= 0.9; p.x += p.vx * dt; p.y += p.vy * dt; p.z += p.vz * dt; }

          // --- WEATHER PARTICLE PHYSICS ---
          else if (p.type === 'SNOW' || p.type === 'ASH') {
               // Swaying motion
               const sway = Math.sin(timeRef.current * 2 + parseInt(p.id)) * 20;
               p.x += (p.vx + sway + windForceRef.current.x * 200) * dt; 
               p.y += (p.vy + windForceRef.current.y * 200) * dt; 
               p.z += p.vz * dt; // Fall slow
          }
          else if (p.type === 'FOG' || p.type === 'SAND') {
               // Move with wind primarily
               p.x += (p.vx + windForceRef.current.x * 400) * dt;
               p.y += (p.vy + windForceRef.current.y * 400) * dt;
               p.z = 50 + Math.sin(timeRef.current + parseInt(p.id)) * 10; // Bobbing
          }
          else if (p.type === 'RAIN' || p.type === 'STORM') {
              // Rain falls fast and slants with wind
              p.x += (p.vx + windForceRef.current.x * 600) * dt;
              p.y += (p.vy + windForceRef.current.y * 600) * dt;
              p.z += p.vz * dt;
          }
          else { 
              // Standard particle
              p.x += p.vx * dt; p.y += p.vy * dt; p.z += p.vz * dt; 
          }

          if (p.type !== 'RAIN' && p.type !== 'FIRE' && p.type !== 'MAGIC' && p.type !== 'FOG' && p.type !== 'SNOW' && p.type !== 'ASH' && p.type !== 'POISON' && p.type !== 'SAND') p.vz -= 300 * dt; 

          if(p.z < 0 && p.type !== 'FOG' && p.type !== 'SAND') { p.z = 0; if (p.type === 'RAIN') { createParticle(p.x, p.y, 0, '#fff', 1, 'SPARK'); return false; } if (p.type === 'BLOOD') { p.vx = 0; p.vy = 0; } }
          return p.life > 0;
      });
      damageNumbersRef.current = damageNumbersRef.current.filter(d => { d.life -= dt; d.z += 40 * dt; return d.life > 0; });
  };

  // --- RENDER ---
  const drawIsoSprite = (ctx: CanvasRenderingContext2D, entity: any, type: string) => {
      // TELEGRAPHING (Dash Path or Jump Zone)
      if (entity.state === 'WINDUP') {
          // Dash Telegraph
          if (entity.type.includes('WOLF') || entity.type.includes('DOG') || entity.type.includes('SHARK')) {
              const startIso = toIso(entity.startX || entity.x, entity.startY || entity.y, 0);
              const targetIso = toIso(entity.targetX || entity.x, entity.targetY || entity.y, 0);

              ctx.save();
              ctx.globalAlpha = 0.3;
              ctx.fillStyle = '#ef4444';
              // Draw a quad on floor
              ctx.beginPath();
              ctx.moveTo(startIso.x - 10, startIso.y);
              ctx.lineTo(targetIso.x - 10, targetIso.y);
              ctx.lineTo(targetIso.x + 10, targetIso.y);
              ctx.lineTo(startIso.x + 10, startIso.y);
              ctx.fill();

              // Arrow Tip
              ctx.fillStyle = '#b91c1c';
              ctx.globalAlpha = 0.5;
              ctx.beginPath();
              ctx.arc(targetIso.x, targetIso.y, 15, 0, Math.PI * 2);
              ctx.fill();
              ctx.restore();
          }
          // Jump Telegraph
          else if (entity.type.includes('SLIME') || entity.type.includes('SPIDER') || entity.type.includes('YETI') || entity.type.includes('FROG')) {
              if (entity.targetX) {
                  const targetIso = toIso(entity.targetX, entity.targetY, 0);
                  ctx.save();
                  ctx.fillStyle = '#ef4444';
                  ctx.globalAlpha = 0.3 + Math.sin(timeRef.current * 15) * 0.1;
                  ctx.beginPath();
                  ctx.ellipse(targetIso.x, targetIso.y, 30, 15, 0, 0, Math.PI * 2);
                  ctx.fill();
                  ctx.strokeStyle = '#b91c1c';
                  ctx.lineWidth = 2;
                  ctx.stroke();
                  ctx.restore();
              }
          }
      }

      // Hit Flash
      if (entity.hitFlash && entity.hitFlash > 0) {
          const { x, y } = toIso(entity.x, entity.y, entity.z); 
          const w = 30; const h = 30;
          ctx.fillStyle = '#ffffff'; ctx.fillRect(x - w/2, y - h, w, h); return; 
      }

      const { x, y } = toIso(entity.x, entity.y, entity.z);
      const layers = 5;

      // --- DISTINCT ENEMY SPRITES ---

      // 1. SLIMES (Round, Translucent)
      if (type.includes('SLIME')) {
          const wobble = Math.sin(entity.frame * 5) * 2;
          ctx.fillStyle = type.includes('POISON') ? 'rgba(132, 204, 22, 0.8)' : 'rgba(59, 130, 246, 0.8)';
          for(let i=0; i<3; i++) {
              ctx.beginPath();
              ctx.ellipse(x, y - i*6 + wobble, 15 - i*2, 10 - i, 0, 0, Math.PI*2);
              ctx.fill();
          }
          return;
      }

      // 2. WOLVES/DOGS (Horizontal, Fast)
      if (type.includes('WOLF') || type.includes('DOG')) {
          const color = type.includes('ICE') ? '#cbd5e1' : '#78716c';
          // Body
          ctx.fillStyle = color;
          ctx.fillRect(x - 15, y - 10, 30, 12);
          // Head
          ctx.fillStyle = adjustColor(color, -20);
          ctx.fillRect(x + 10, y - 15, 12, 10);
          // Legs (suggestion)
          if (entity.isMoving) {
              ctx.fillStyle = '#44403c';
              const leg = Math.sin(entity.frame * 20) * 5;
              ctx.fillRect(x - 10 + leg, y, 4, 4);
              ctx.fillRect(x + 5 - leg, y, 4, 4);
          }
          return;
      }

      // 3. SKELETONS (Thin, Bone color)
      if (type.includes('SKELETON')) {
          // Ribs/Spine
          ctx.fillStyle = '#e2e8f0';
          ctx.fillRect(x - 4, y - 18, 8, 14);
          // Skull
          ctx.fillStyle = '#f8fafc';
          ctx.beginPath(); ctx.arc(x, y - 24, 6, 0, Math.PI*2); ctx.fill();
          // Bow
          if (entity.state === 'SHOOTING') {
              ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 2;
              ctx.beginPath(); ctx.arc(x + 8, y - 15, 10, -Math.PI/2, Math.PI/2); ctx.stroke();
          }
          return;
      }

      // 4. GOBLINS (Small, Green, Pointy)
      if (type.includes('GOBLIN')) {
          // Body
          ctx.fillStyle = '#15803d';
          ctx.fillRect(x - 8, y - 12, 16, 12);
          // Head
          ctx.fillStyle = '#22c55e';
          ctx.beginPath(); ctx.arc(x, y - 18, 7, 0, Math.PI*2); ctx.fill();
          // Ears
          ctx.beginPath(); ctx.moveTo(x-6, y-18); ctx.lineTo(x-12, y-22); ctx.lineTo(x-6, y-14); ctx.fill();
          ctx.beginPath(); ctx.moveTo(x+6, y-18); ctx.lineTo(x+12, y-22); ctx.lineTo(x+6, y-14); ctx.fill();
          return;
      }

      // 5. BATS/HARPIES (Flying, Wings)
      if (type.includes('BAT') || type.includes('HARPY')) {
          ctx.fillStyle = '#1e293b'; 
          ctx.beginPath(); ctx.arc(x, y - 10, 6, 0, Math.PI*2); ctx.fill(); // Body
          // Wings Flap
          const flap = Math.sin(entity.frame * 20) * 10;
          ctx.fillStyle = '#334155';
          ctx.beginPath(); ctx.moveTo(x, y-10); ctx.lineTo(x-15, y-15-flap); ctx.lineTo(x-5, y); ctx.fill();
          ctx.beginPath(); ctx.moveTo(x, y-10); ctx.lineTo(x+15, y-15-flap); ctx.lineTo(x+5, y); ctx.fill();
          return;
      }

      // 6. GOLEMS (Big, Blocky)
      if (type.includes('GOLEM')) {
          const color = '#57534e';
          ctx.fillStyle = color;
          // Legs
          ctx.fillRect(x - 10, y - 10, 8, 10); ctx.fillRect(x + 2, y - 10, 8, 10);
          // Chest
          ctx.fillStyle = adjustColor(color, 20);
          ctx.fillRect(x - 15, y - 35, 30, 25);
          // Head
          ctx.fillStyle = adjustColor(color, 40);
          ctx.fillRect(x - 8, y - 45, 16, 10);
          if (entity.state === 'GUARDING') {
              ctx.strokeStyle = '#fff'; ctx.lineWidth = 2; ctx.strokeRect(x-15, y-35, 30, 25);
          }
          return;
      }

      // 7. SNAKES (Long, Winding)
      if (type.includes('SNAKE') || type.includes('WORM')) {
          for(let i=0; i<5; i++) {
              const lag = i * 2;
              const sway = Math.sin(entity.frame * 10 + lag) * 5;
              ctx.fillStyle = i===0 ? '#facc15' : '#a16207'; // Head vs Body
              ctx.beginPath(); ctx.arc(x + sway, y - i*4, 6 - i*0.5, 0, Math.PI*2); ctx.fill();
          }
          return;
      }

      // 8. PLAYER & GENERIC FALLBACK
      if (type === 'PLAYER') {
          const scale = 1;
          for(let i=0; i<layers; i++) {
             const ly = y - (i * scale * 2); let w = 20; 
             if (entity.archetype === Archetype.WARRIOR) { w = 20; let color = '#334155'; if (i >= 5) { color = '#1d4ed8'; w = 16; } if (i === 4) { color = '#94a3b8'; w = 22; } ctx.fillStyle = color; ctx.fillRect(x - w/2, ly - w/2, w, w); } 
             else if (entity.archetype === Archetype.MAGE) { w = 18; let color = '#581c87'; if (i >= 5) { color = '#a855f7'; w = 12; } if (i === 6) { w = 8; } ctx.fillStyle = color; ctx.fillRect(x - w/2, ly - w/2, w, w); } 
             else { w = 16; let color = '#15803d'; if (i >= 5) { color = '#86efac'; w = 14; } ctx.fillStyle = color; ctx.fillRect(x - w/2, ly - w/2, w, w); }
          }
          return;
      }

      // Static Objects & Traps
      if (['TREE', 'HOUSE', 'PORTAL', 'LAMP', 'ROCK', 'BUSH', 'CRYSTAL', 'PILLAR', 'TOMBSTONE'].includes(type)) {
          // Keep existing simple shapes for environment
          if (type === 'TREE') {
              ctx.fillStyle = '#271306'; ctx.fillRect(x - 4, y - 20, 8, 20);
              ctx.fillStyle = entity.variant === 1 ? '#14532d' : '#166534'; 
              ctx.beginPath(); ctx.moveTo(x - 15, y - 15); ctx.lineTo(x, y - 50); ctx.lineTo(x + 15, y - 15); ctx.fill();
          } 
          else if (type === 'PORTAL') {
              ctx.fillStyle = '#312e81'; ctx.beginPath(); ctx.ellipse(x, y, 30, 10, 0, 0, Math.PI*2); ctx.fill();
              ctx.strokeStyle = '#4338ca'; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x, y-60); ctx.stroke();
          }
          else {
              ctx.fillStyle = '#57534e'; ctx.fillRect(x - 10, y - 10, 20, 10);
          }
          return;
      }

      // TRAPS (Already handled in main draw loop but good to have fallback)
      if (type === 'SPIKES' || type === 'LAVA' || type === 'BEAR_TRAP' || type === 'POISON_VENT') return;

      // BOSS FALLBACK
      if (type.includes('BOSS')) {
          const w = 60; const h = 60;
          ctx.fillStyle = entity.bossColor || '#000';
          ctx.fillRect(x - w/2, y - h, w, h);
          // Eyes
          ctx.fillStyle = '#fff';
          ctx.fillRect(x - 15, y - 40, 10, 10);
          ctx.fillRect(x + 5, y - 40, 10, 10);
      } else {
          // Unknown Enemy Fallback
          ctx.fillStyle = '#94a3b8';
          ctx.fillRect(x - 10, y - 20, 20, 20);
      }
  };

  const draw = (dt: number) => {
    const canvas = canvasRef.current; if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false }); if (!ctx) return;

    const cx = CANVAS_WIDTH / 2; const cy = CANVAS_HEIGHT / 2;
    if(canvas.width !== CANVAS_WIDTH || canvas.height !== CANVAS_HEIGHT) { canvas.width = CANVAS_WIDTH; canvas.height = CANVAS_HEIGHT; }

    ctx.fillStyle = COLORS.background; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    const shakeX = (Math.random() - 0.5) * shakeRef.current; const shakeY = (Math.random() - 0.5) * shakeRef.current;

    ctx.save();
    ctx.translate(CANVAS_WIDTH/2, CANVAS_HEIGHT/2); ctx.scale(ZOOM_LEVEL, ZOOM_LEVEL); ctx.translate(Math.floor(cameraRef.current.x + shakeX), Math.floor(cameraRef.current.y + shakeY));

    // --- TERRAIN RENDER ---
    const tileSize = 100; const pX = playerRef.current.x; const pY = playerRef.current.y; const range = 20; const px = Math.floor(pX / tileSize); const py = Math.floor(pY / tileSize);

    // Determine Biome Colors for Tower
    const biome = hudData.biome || 'DEFAULT';
    const biomeSet = BIOME_COLORS[biome] || BIOME_COLORS.DEFAULT;

    for (let i = px - range; i <= px + range; i++) {
        for (let j = py - range; j <= py + range; j++) {
            const wx = i * tileSize; const wy = j * tileSize;
            if (Math.hypot(wx - pX, wy - pY) > 2000) continue;
            const iso = toIso(wx, wy, 0); const screenX = (iso.x + cameraRef.current.x) * ZOOM_LEVEL + CANVAS_WIDTH/2; const screenY = (iso.y + cameraRef.current.y) * ZOOM_LEVEL + CANVAS_HEIGHT/2;
            if (screenX < -300 || screenX > CANVAS_WIDTH + 300 || screenY < -300 || screenY > CANVAS_HEIGHT + 300) continue;

            let color = biomeSet.grass; let topColor = biomeSet.highlight; let h = 0;
            const tileNoise = pseudoRandom(i, j); 

            if (gameStateRef.current === GameState.ISLAND) {
                 const distToCenter = Math.hypot(wx, wy + 200);
                 if (distToCenter < 1200) { 
                    color = COLORS.grass; topColor = COLORS.grassHighlight;
                    if (tileNoise > 0.6) topColor = adjustColor(COLORS.grassHighlight, 10);
                    if (tileNoise < 0.3) topColor = adjustColor(COLORS.grassHighlight, -10);
                    if (Math.abs(wx) < 100 || Math.abs(wy + 200) < 100) { color = COLORS.stone; topColor = COLORS.stoneHighlight; if (tileNoise > 0.5) topColor = adjustColor(COLORS.stoneHighlight, 15); }
                 } else { color = COLORS.water; topColor = COLORS.waterHighlight; const wave = Math.sin(timeRef.current * 2 + tileNoise * 10); if (wave > 0.5) topColor = adjustColor(COLORS.waterHighlight, 20); h = -20; }
                 if (Math.hypot(wx - PORTAL_POS.x, wy - PORTAL_POS.y) < 180) { color = '#312e81'; topColor = '#4338ca'; h = 5; }
            } else {
                 // TOWER BIOME RENDER
                 const isGrassCrack = (tileNoise - Math.floor(tileNoise)) > 0.8;
                 color = biomeSet.water; // Use 'water' slot as dark floor base
                 topColor = isGrassCrack ? biomeSet.grass : biomeSet.highlight;
                 if (Math.abs(wx) > 900 || Math.abs(wy) > 900) { h = -100; color = '#000'; topColor = '#000'; }
            }

            if (h > -50 && h !== 0) {
                 ctx.fillStyle = adjustColor(color, -20); ctx.beginPath(); ctx.moveTo(iso.x + tileSize, iso.y - h + tileSize/2); ctx.lineTo(iso.x + tileSize, iso.y + tileSize/2); ctx.lineTo(iso.x, iso.y + tileSize); ctx.lineTo(iso.x, iso.y - h + tileSize); ctx.fill();
                 ctx.fillStyle = adjustColor(color, -10); ctx.beginPath(); ctx.moveTo(iso.x - tileSize, iso.y - h + tileSize/2); ctx.lineTo(iso.x - tileSize, iso.y + tileSize/2); ctx.lineTo(iso.x, iso.y + tileSize); ctx.lineTo(iso.x, iso.y - h + tileSize); ctx.fill();
            }
            ctx.beginPath(); ctx.moveTo(iso.x, iso.y - h); ctx.lineTo(iso.x + tileSize, iso.y - h + tileSize/2); ctx.lineTo(iso.x, iso.y - h + tileSize); ctx.lineTo(iso.x - tileSize, iso.y - h + tileSize/2); ctx.fillStyle = topColor; ctx.fill();

            if (gameStateRef.current === GameState.ISLAND && h === 0 && topColor !== COLORS.stoneHighlight && topColor !== COLORS.waterHighlight && topColor !== '#4338ca') {
                if (tileNoise > 0.85) {
                    const fx = iso.x + (tileNoise * 100) % tileSize - tileSize/2; const fy = iso.y - h + (tileNoise * 50) % (tileSize/2);
                    ctx.fillStyle = tileNoise > 0.92 ? '#f472b6' : (tileNoise > 0.88 ? '#fbbf24' : '#fff');
                    ctx.beginPath(); ctx.arc(fx, fy, 2, 0, Math.PI*2); ctx.fill();
                } else if (tileNoise < 0.1) {
                    const px = iso.x - (tileNoise * 200) % tileSize + tileSize/2; const py = iso.y - h + (tileNoise * 100) % (tileSize/2);
                    ctx.fillStyle = '#57534e'; ctx.fillRect(px, py, 4, 3);
                }
            }
        }
    }

    // ... (Sorting & Entity Render logic kept same for brevity, full block output ensures it works)
    const renderList: any[] = [];
    renderList.push({ type: 'PLAYER', obj: playerRef.current, y: toIso(playerRef.current.x, playerRef.current.y).y });
    const cullingDist = 2000; 
    for(const e of enemiesRef.current) { if (Math.abs(e.x - pX) < cullingDist && Math.abs(e.y - pY) < cullingDist) renderList.push({ type: e.type, obj: e, y: toIso(e.x, e.y).y }); }
    for(const t of trapsRef.current) { if (Math.abs(t.x - pX) < cullingDist && Math.abs(t.y - pY) < cullingDist) renderList.push({ type: t.type, obj: t, y: toIso(t.x, t.y).y }); }
    for(const p of particlesRef.current) { renderList.push({ type: p.type || 'PARTICLE', obj: p, y: toIso(p.x, p.y).y }); }
    if (gameStateRef.current === GameState.ISLAND) { staticObjectsRef.current.forEach(obj => { if (Math.abs(obj.x - pX) < cullingDist && Math.abs(obj.y - pY) < cullingDist) renderList.push({ type: obj.type, obj, y: toIso(obj.x, obj.y).y }); }); }
    renderList.sort((a, b) => a.y - b.y);

    for (const item of renderList) {
        if (['PARTICLE','RAIN','BLOOD','SPARK','POISON','TELEPORT','TRAIL','MAGIC','FIRE','IMPACT','FOG','SAND','SNOW','ASH'].includes(item.type)) {
             const { x, y } = toIso(item.obj.x, item.obj.y, item.obj.z); 
             ctx.fillStyle = item.obj.color;

             if (item.type === 'RAIN') { 
                 const windX = windForceRef.current.x * 15;
                 ctx.strokeStyle = item.obj.color; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x-2 + windX, y+15); ctx.stroke(); 
             } 
             else if (item.type === 'FOG') { ctx.globalAlpha = 0.15; ctx.beginPath(); ctx.arc(x, y, item.obj.size, 0, Math.PI*2); ctx.fill(); ctx.globalAlpha = 1.0; }
             else if (item.type === 'SAND') { ctx.globalAlpha = 0.4; ctx.beginPath(); ctx.arc(x, y, item.obj.size, 0, Math.PI*2); ctx.fill(); ctx.globalAlpha = 1.0; }
             else if (item.type === 'SNOW') { ctx.globalAlpha = 0.8; ctx.beginPath(); ctx.arc(x, y, item.obj.size, 0, Math.PI*2); ctx.fill(); ctx.globalAlpha = 1.0; }
             else if (item.type === 'ASH') { ctx.globalAlpha = 0.7; ctx.beginPath(); ctx.arc(x, y, item.obj.size, 0, Math.PI*2); ctx.fill(); ctx.globalAlpha = 1.0; }
             else if (item.type === 'BLOOD') { ctx.globalAlpha = 0.6; ctx.beginPath(); ctx.ellipse(x, y, item.obj.size*2, item.obj.size, 0, 0, Math.PI*2); ctx.fill(); ctx.globalAlpha = 1.0; } 
             else if (item.type === 'POISON') { ctx.globalAlpha = 0.6; ctx.beginPath(); ctx.arc(x, y, item.obj.size, 0, Math.PI*2); ctx.fill(); ctx.globalAlpha = 1.0; }
             else if (item.type === 'IMPACT') { ctx.globalAlpha = item.obj.life / item.obj.maxLife; ctx.beginPath(); ctx.arc(x, y, item.obj.size, 0, Math.PI*2); ctx.fill(); ctx.globalAlpha = 1.0; }
             else { ctx.shadowBlur = item.type === 'MAGIC' || item.type === 'FIRE' ? 10 : 5; ctx.shadowColor = item.obj.color; ctx.beginPath(); ctx.arc(x, y, item.obj.size, 0, Math.PI*2); ctx.fill(); ctx.shadowBlur = 0; }
        } else {
             drawIsoSprite(ctx, item.obj, item.type);
             if (item.obj.hp < item.obj.maxHp && item.obj.hp > 0 && !['PARTICLE','SPIKES','LAVA','POISON_VENT','BEAR_TRAP'].includes(item.type)) {
                 const isBoss = item.type.includes('BOSS'); const offsetZ = isBoss ? 150 : (item.type.includes('BAT') ? 80 : 40); const { x, y } = toIso(item.obj.x, item.obj.y, item.obj.z + offsetZ); const w = isBoss ? 120 : 20; const h = isBoss ? 6 : 3;
                 ctx.fillStyle = '#0f172a'; ctx.fillRect(x - w/2, y - 5, w, h); ctx.fillStyle = '#b91c1c'; ctx.fillRect(x - w/2, y - 5, w * (item.obj.hp/item.obj.maxHp), h); 
             }
             if (item.obj.frozenTimer > 0) {
                 const { x, y } = toIso(item.obj.x, item.obj.y, item.obj.z + 20);
                 ctx.fillStyle = 'rgba(200, 240, 255, 0.5)'; ctx.beginPath(); ctx.arc(x, y, item.obj.radius, 0, Math.PI*2); ctx.fill();
             }
        }
    }

    for(const p of projectilesRef.current) {
        const { x, y } = toIso(p.x, p.y, p.z); ctx.fillStyle = p.color; ctx.shadowBlur = 10; ctx.shadowColor = p.color;

        if (p.type === 'SWORD_SLASH') { const progress = 1 - (p.duration / 0.3); const currentRadius = p.radius * (0.5 + progress * 0.5); ctx.strokeStyle = '#fff'; ctx.lineWidth = 4 * (1 - progress); ctx.beginPath(); ctx.ellipse(x, y, currentRadius, currentRadius*0.5, 0, 0, Math.PI*2); ctx.stroke(); ctx.fillStyle = `rgba(96, 165, 250, ${0.5 * (1 - progress)})`; ctx.fill(); } 
        else if (p.type === 'FIRE_ZONE' || p.type === 'GODDESS_SEAL') { const pulse = 1 + Math.sin(timeRef.current * 10) * 0.1; ctx.fillStyle = p.type === 'GODDESS_SEAL' ? 'rgba(216, 180, 254, 0.3)' : 'rgba(220, 38, 38, 0.2)'; ctx.beginPath(); ctx.ellipse(x, y, p.radius * pulse, p.radius * 0.5 * pulse, 0, 0, Math.PI*2); ctx.fill(); ctx.fillStyle = p.type === 'GODDESS_SEAL' ? 'rgba(255, 255, 255, 0.2)' : 'rgba(254, 202, 202, 0.1)'; ctx.beginPath(); ctx.ellipse(x, y, p.radius * 0.7, p.radius * 0.35, 0, 0, Math.PI*2); ctx.fill(); } 
        else if (p.type === 'TIME_PRISON') { ctx.strokeStyle = '#e0f2fe'; ctx.lineWidth = 2; ctx.beginPath(); ctx.ellipse(x, y, p.radius, p.radius*0.5, 0, 0, Math.PI*2); ctx.stroke(); ctx.fillStyle = 'rgba(224, 242, 254, 0.1)'; ctx.fill(); } 
        else if (p.type === 'OCEAN_WAVE') { ctx.strokeStyle = '#0ea5e9'; ctx.lineWidth = 6; ctx.beginPath(); ctx.ellipse(x, y, p.radius, p.radius*0.5, 0, 0, Math.PI*2); ctx.stroke(); } 
        else if (p.type === 'LICH_DRAIN_ZONE') { ctx.fillStyle = 'rgba(16, 185, 129, 0.2)'; ctx.beginPath(); ctx.ellipse(x, y, p.radius, p.radius*0.5, 0, 0, Math.PI*2); ctx.fill(); ctx.strokeStyle = '#10b981'; ctx.lineWidth = 1; ctx.stroke(); } 
        else if (p.type === 'AUTO_LIGHTNING') { ctx.strokeStyle = '#fef08a'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(x, y - 400); let currY = y - 400; let currX = x; const steps = 5; const stepY = 400 / steps; for(let i=0; i<steps; i++) { currY += stepY; currX += (Math.random() - 0.5) * 40; ctx.lineTo(currX, currY); } ctx.lineTo(x, y); ctx.stroke(); ctx.fillStyle = '#fef08a'; ctx.beginPath(); ctx.arc(x, y, p.radius * (p.duration/0.5), 0, Math.PI*2); ctx.fill(); } 
        else if (p.type === 'ARROW' || p.type === 'MAGIC_ORB' || p.type === 'ENEMY_BOLT') {
            if (p.type === 'ARROW') {
                const angle = Math.atan2(p.vy, p.vx);
                ctx.save();
                ctx.translate(x, y);
                ctx.rotate(angle);

                // Glow
                ctx.shadowBlur = 5;
                ctx.shadowColor = p.color;

                // Shaft
                ctx.fillStyle = '#e2e8f0'; 
                ctx.fillRect(-15, -1, 30, 2);

                // Head
                ctx.fillStyle = p.color;
                ctx.beginPath();
                ctx.moveTo(15, 0);
                ctx.lineTo(5, -4);
                ctx.lineTo(5, 4);
                ctx.fill();

                // Fletching (Feathers)
                ctx.fillStyle = '#f8fafc';
                ctx.beginPath();
                ctx.moveTo(-15, 0);
                ctx.lineTo(-20, -4);
                ctx.lineTo(-12, 0);
                ctx.lineTo(-20, 4);
                ctx.fill();

                ctx.restore();
            } else {
                // Orb or Enemy Bolt
                const tailX = x - p.vx * 0.04; 
                const tailY = y - p.vy * 0.04; 
                const grad = ctx.createLinearGradient(x, y, tailX, tailY); 
                grad.addColorStop(0, p.color); 
                grad.addColorStop(1, 'rgba(255,255,255,0)'); 
                ctx.strokeStyle = grad; 
                ctx.lineWidth = 2; 
                ctx.beginPath(); 
                ctx.moveTo(x, y); 
                ctx.lineTo(tailX, tailY); 
                ctx.stroke(); 
                ctx.fillStyle = '#fff'; 
                ctx.beginPath(); 
                ctx.arc(x, y, 3, 0, Math.PI*2); 
                ctx.fill();
            }
        } 
        else if (p.type === 'ARCANE_COLOSSUS') { ctx.beginPath(); ctx.arc(x, y, 10, 0, Math.PI*2); ctx.fillStyle='#fff'; ctx.fill(); ctx.beginPath(); ctx.arc(x, y, 6, 0, Math.PI*2); ctx.fillStyle=p.color; ctx.fill(); } 
        else if (p.type === 'BOSS_SMASH' || p.type === 'JUDGEMENT_STRIKE') { ctx.fillStyle = p.type === 'BOSS_SMASH' ? 'rgba(255,255,255,0.8)' : 'rgba(252, 211, 77, 0.4)'; ctx.beginPath(); ctx.ellipse(x, y, p.radius, p.radius*0.5, 0, 0, Math.PI*2); ctx.fill(); } 
        else { ctx.beginPath(); ctx.arc(x, y, 4, 0, Math.PI*2); ctx.fill(); ctx.fillStyle = 'rgba(255,255,255,0.4)'; ctx.beginPath(); ctx.arc(x - p.vx*0.02, y - p.vy*0.02, 2, 0, Math.PI*2); ctx.fill(); }
        ctx.shadowBlur = 0;
    }

    ctx.restore(); 

    // --- WEATHER OVERLAY (FOG / GRADIENTS / VISION MASK) ---
    const isSandstorm = weatherTypeRef.current === 'SANDSTORM';
    const isSnowStorm = weatherTypeRef.current === 'SNOW';
    const isFog = weatherTypeRef.current === 'FOG';

    if (gameStateRef.current === GameState.TOWER && (isFog || isSandstorm || isSnowStorm) && weatherIntensityRef.current > 0.1) {
        const visionRadius = (isSandstorm || isSnowStorm) ? 250 : 450;
        const grad = ctx.createRadialGradient(cx, cy, 100, cx, cy, visionRadius * 2.5);
        const intensity = weatherIntensityRef.current * 0.95;

        let fogColor = 'rgba(200, 215, 210,'; 
        if (isSandstorm) fogColor = 'rgba(180, 130, 80,'; 
        if (isSnowStorm) fogColor = 'rgba(220, 240, 255,'; 

        grad.addColorStop(0, `${fogColor} 0)`);
        grad.addColorStop(0.3, `${fogColor} ${intensity * 0.2})`);
        grad.addColorStop(1, `${fogColor} ${intensity})`);

        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    }

    const vignette = ctx.createRadialGradient(cx, cy, 300, cx, cy, 1000); 
    vignette.addColorStop(0, 'rgba(0,0,0,0)'); 
    vignette.addColorStop(1, 'rgba(0,0,0,0.8)'); 
    ctx.fillStyle = vignette; 
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    if (weatherTypeRef.current === 'RAIN' || weatherTypeRef.current === 'STORM') { 
        ctx.fillStyle = `rgba(30, 58, 138, ${weatherIntensityRef.current * 0.15})`; 
        ctx.fillRect(0,0,CANVAS_WIDTH, CANVAS_HEIGHT); 
    }

    if (playerRef.current.slowTimer > 0) { ctx.fillStyle = 'rgba(69, 10, 10, 0.2)'; ctx.fillRect(0,0,CANVAS_WIDTH, CANVAS_HEIGHT); }
    if (playerRef.current.avatarBuffTimer > 0) {
        const pulse = 0.1 + Math.sin(timeRef.current * 10) * 0.05;
        ctx.fillStyle = `rgba(252, 211, 77, ${pulse})`; ctx.fillRect(0,0,CANVAS_WIDTH, CANVAS_HEIGHT);
    }

    if (playerRef.current.poisonTimer > 0) {
        ctx.fillStyle = `rgba(163, 230, 53, ${0.1 + Math.sin(timeRef.current * 5) * 0.05})`;
        ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    }

    const pIso = toIso(playerRef.current.x, playerRef.current.y);
    const playerScreenX = cx + (cameraRef.current.x + shakeX + pIso.x) * ZOOM_LEVEL;
    const playerScreenY = cy + (cameraRef.current.y + shakeY + pIso.y - (playerRef.current.z || 0)) * ZOOM_LEVEL;
    const mouseScreenX = cx + mouseScreenRef.current.x; const mouseScreenY = cy + mouseScreenRef.current.y;
    let isAimingAtEnemy = false; for(const e of enemiesRef.current) { const dist = Math.hypot(e.x - mouseWorldRef.current.x, e.y - mouseWorldRef.current.y); if (dist < 40) { isAimingAtEnemy = true; break; } }
    ctx.save(); ctx.strokeStyle = isAimingAtEnemy ? 'rgba(239, 68, 68, 0.5)' : 'rgba(255, 255, 255, 0.2)'; ctx.setLineDash([4, 4]); ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(playerScreenX, playerScreenY - 20); ctx.lineTo(mouseScreenX, mouseScreenY); ctx.stroke(); ctx.setLineDash([]); ctx.translate(mouseScreenX, mouseScreenY); ctx.rotate(reticleAngleRef.current); ctx.strokeStyle = isAimingAtEnemy ? '#ef4444' : '#fff'; ctx.lineWidth = 2; const rSize = 12; ctx.beginPath(); ctx.moveTo(rSize, 0); ctx.lineTo(rSize/2, -rSize/2); ctx.moveTo(rSize, 0); ctx.lineTo(rSize/2, rSize/2); ctx.moveTo(-rSize, -rSize/2); ctx.lineTo(-rSize/2, 0); ctx.lineTo(-rSize, rSize/2); ctx.stroke(); ctx.fillStyle = isAimingAtEnemy ? '#ef4444' : '#fff'; ctx.beginPath(); ctx.arc(0, 0, 2, 0, Math.PI*2); ctx.fill(); ctx.restore();
    for(const dn of damageNumbersRef.current) { const pos = toIso(dn.x, dn.y, dn.z); const sx = cx + (pos.x + cameraRef.current.x) * ZOOM_LEVEL; const sy = cy + (pos.y + cameraRef.current.y) * ZOOM_LEVEL; ctx.fillStyle = dn.isPlayerDamage ? '#ef4444' : (dn.isCrit ? '#fbbf24' : 'white'); ctx.strokeStyle = '#020617'; ctx.lineWidth = 4; ctx.lineJoin = 'round'; const offset = (1 - dn.life) * 80; const alpha = Math.min(1, dn.life * 3); ctx.save(); ctx.globalAlpha = alpha; ctx.translate(sx, sy - offset); if (dn.isCrit) { const scale = 1.5 + Math.sin((1-dn.life)*10)*0.2; ctx.scale(scale, scale); ctx.font = '900 28px "Cinzel", serif'; } else { ctx.font = 'bold 20px "Cinzel", serif'; } const text = Math.floor(dn.value).toString(); ctx.strokeText(text, 0, 0); ctx.fillText(text, 0, 0); if (dn.isCrit) { ctx.shadowColor = '#fbbf24'; ctx.shadowBlur = 10; ctx.fillText(text, 0, 0); ctx.shadowBlur = 0; } ctx.restore(); }
  };

  const formatTime = (s: number) => `${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;

  return (
    <div className="relative w-full h-full bg-[#020617] cursor-none select-none overflow-hidden font-mono">
      <canvas ref={canvasRef} className="block w-full h-full cursor-none" />

      {/* --- HUD --- */}
      <div className="absolute inset-x-0 bottom-6 flex flex-col items-center pointer-events-none z-10 scale-[0.80] origin-bottom transition-transform">
          {hudData.bossHp > 0 && (
              <div className="mb-10 w-[700px] pointer-events-none animate-in fade-in slide-in-from-top-10 duration-700">
                  <div className="flex justify-between items-end text-red-500 font-bold mb-2 px-4 uppercase tracking-widest font-serif drop-shadow-md">
                      <span className="text-2xl">{enemiesRef.current.find(e => e.isBoss)?.type === 'BOSS_GOBLIN' ? 'Rei Goblin' : 'Terror da Torre'}</span>
                      <span className="text-sm opacity-80">{Math.ceil(hudData.bossHp)}/{Math.ceil(hudData.bossMaxHp)}</span>
                  </div>
                  <div className="relative h-6 w-full bg-slate-900 border-2 border-slate-700 rounded-sm shadow-[0_0_30px_rgba(220,38,38,0.3)] overflow-hidden">
                      <div className="absolute inset-0 bg-red-950/50"></div>
                      <div className="h-full bg-gradient-to-r from-red-900 via-red-600 to-red-500 transition-all duration-200" style={{width: `${(hudData.bossHp/hudData.bossMaxHp)*100}%`}}></div>
                  </div>
              </div>
          )}

          <div className="flex items-end gap-6 pb-2">
              <div className="bg-slate-900/95 border border-slate-700 rounded-2xl p-5 backdrop-blur-md shadow-2xl w-72 transform transition-transform">
                   <div className="flex items-center justify-between gap-2 text-white font-bold text-2xl mb-3 font-serif">
                       <span className="flex items-center gap-2 text-red-400"><Heart fill="currentColor" /> {Math.ceil(hudData.hp)}</span>
                       <span className="text-sm font-mono text-slate-500">LVL {hudData.level}</span>
                   </div>
                   <div className="relative h-4 bg-slate-950 rounded-full overflow-hidden border border-slate-800 mb-2 shadow-inner">
                       <div className="h-full bg-gradient-to-r from-red-800 to-red-500 transition-all duration-300" style={{width: `${(hudData.hp/hudData.maxHp)*100}%`}}></div>
                   </div>
                   <div className="flex justify-between text-[10px] text-slate-400 font-mono tracking-wide uppercase">
                       <span>XP Progresso</span>
                       <span className="text-amber-500">{Math.floor(hudData.xp)} / {Math.floor(hudData.xpNext)}</span>
                   </div>
                   <div className="mt-1 h-1 w-full bg-slate-800 rounded-full overflow-hidden">
                       <div className="h-full bg-amber-500 shadow-[0_0_10px_#f59e0b]" style={{width: `${(hudData.xp/hudData.xpNext)*100}%`}}></div>
                   </div>
              </div>

              <div className="flex gap-3 p-4 bg-slate-900/95 border border-slate-700 rounded-2xl backdrop-blur-md shadow-2xl">
