      if (type.includes('GOLEM')) {
          const color = '#57534e'; ctx.fillStyle = color; ctx.fillRect(x - 10, y - 10, 8, 10); ctx.fillRect(x + 2, y - 10, 8, 10); ctx.fillStyle = adjustColor(color, 20); ctx.fillRect(x - 15, y - 35, 30, 25); ctx.fillStyle = adjustColor(color, 40); ctx.fillRect(x - 8, y - 45, 16, 10);
          return;
      }
      // 7. SNAKES
      if (type.includes('SNAKE') || type.includes('WORM')) {
          for(let i=0; i<5; i++) { const sway = Math.sin(entity.frame * 10 + i * 2) * 5; ctx.fillStyle = i===0 ? '#facc15' : '#a16207'; ctx.beginPath(); ctx.arc(x + sway, y - i*4, 6 - i*0.5, 0, Math.PI*2); ctx.fill(); }
          return;
      }
      // 8. PLAYER
      if (type === 'PLAYER') {
          const scale = 1;
          for(let i=0; i<layers; i++) {
             const ly = y - (i * scale * 2); let w = 20; 
             if (entity.archetype === Archetype.WARRIOR) { w = 20; let color = '#334155'; if (i >= 5) { color = '#1d4ed8'; w = 16; } if (i === 4) { color = '#94a3b8'; w = 22; } ctx.fillStyle = color; ctx.fillRect(x - w/2, ly - w/2, w, w); } 
             else if (entity.archetype === Archetype.MAGE) { w = 18; let color = '#581c87'; if (i >= 5) { color = '#a855f7'; w = 12; } if (i === 6) { w = 8; } ctx.fillStyle = color; ctx.fillRect(x - w/2, ly - w/2, w, w); } 
             else { w = 16; let color = '#15803d'; if (i >= 5) { color = '#86efac'; w = 14; } ctx.fillStyle = color; ctx.fillRect(x - w/2, ly - w/2, w, w); }
          }
