             if (item.obj.frozenTimer > 0) { const { x, y } = toIso(item.obj.x, item.obj.y, item.obj.z + 20); ctx.fillStyle = 'rgba(200, 240, 255, 0.5)'; ctx.beginPath(); ctx.arc(x, y, item.obj.radius, 0, Math.PI*2); ctx.fill(); }
        }
    }

