        if (p.type === 'SWORD_SLASH') { const progress = 1 - (p.duration / 0.3); ctx.strokeStyle = '#fff'; ctx.lineWidth = 4 * (1 - progress); ctx.beginPath(); ctx.ellipse(x, y, p.radius, p.radius*0.5, 0, 0, Math.PI*2); ctx.stroke(); } 
        else if (p.type === 'FIRE_ZONE' || p.type === 'GODDESS_SEAL') { const pulse = 1 + Math.sin(timeRef.current * 10) * 0.1; ctx.fillStyle = p.type === 'GODDESS_SEAL' ? 'rgba(216, 180, 254, 0.3)' : 'rgba(220, 38, 38, 0.2)'; ctx.beginPath(); ctx.ellipse(x, y, p.radius * pulse, p.radius * 0.5 * pulse, 0, 0, Math.PI*2); ctx.fill(); } 
        else if (p.type === 'ARROW' || p.type === 'MAGIC_ORB' || p.type === 'ENEMY_BOLT') { const tailX = x - p.vx * 0.04; const tailY = y - p.vy * 0.04; ctx.strokeStyle = p.color; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(tailX, tailY); ctx.stroke(); ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI*2); ctx.fill(); } 
