import React, { useRef, useEffect, useState, useCallback, useMemo } from 'react';
import { useGameContext } from '../context/GameContext';
import { createParticle } from '../utils/particle';
import { calculateDistance, clamp } from '../utils/helpers';
import { COLORS } from '../constants/colors';
import { CANVAS_WIDTH, CANVAS_HEIGHT, TOUCH_RADIUS } from '../constants/dimensions';
import { MAX_PROJECTILES } from '../constants/limits';
import { calculateAngle } from '../utils/math';

interface GameCanvasProps {
    draw: (ctx: CanvasRenderingContext2D, dt: number) => void;
    update: (dt: number) => void;
    handleJoystickStart: (e: React.TouchEvent) => void;
    handleJoystickMove: (e: React.TouchEvent) => void;
    handleJoystickEnd: (e: React.TouchEvent) => void;
    clear: () => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ draw, update, handleJoystickStart, handleJoystickMove, handleJoystickEnd, clear }) => {
