    const [isGameStarted, setIsGameStarted] = useState(false);
    const [lastTime, setLastTime] = useState(0);

    const { player, projectiles, enemies, traps, particles, dispatch } = useGameContext();
    const projectilesRef = useRef(projectiles);
    const enemiesRef = useRef(enemies);
    const trapsRef = useRef(traps);
    const particlesRef = useRef(particles);

    const handleResize = useCallback(() => {
        if (canvasRef.current) {
            canvasRef.current.width = CANVAS_WIDTH;
            canvasRef.current.height = CANVAS_HEIGHT;
        }
    }, []);

    useEffect(() => {
        handleResize();
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, [handleResize]);

    const updateProjectiles = (dt: number) => {
        dispatch({ type: 'UPDATE_PROJECTILES', payload: { dt } });
        projectilesRef.current = projectiles;
    };

    const updateEnemies = (dt: number) => {
        dispatch({ type: 'UPDATE_ENEMIES', payload: { dt } });
        enemiesRef.current = enemies;
    };

    const updateTraps = (dt: number) => {
        dispatch({ type: 'UPDATE_TRAPS', payload: { dt } });
        trapsRef.current = traps;
    };

    const updateParticles = (dt: number) => {
        dispatch({ type: 'UPDATE_PARTICLES', payload: { dt } });
        particlesRef.current = particles;
    };

    const update = (currentTime: number) => {
        if (!isGameStarted) return;

        const deltaTime = (currentTime - lastTime) / 1000;
        setLastTime(currentTime);

        updateProjectiles(deltaTime);
        updateEnemies(deltaTime);
        updateTraps(deltaTime);
        updateParticles(deltaTime);
        requestAnimationFrame(update);
