        let animationFrameId: number;

        const start = () => {
            setIsGameStarted(true);
            setLastTime(performance.now());
            animationFrameId = requestAnimationFrame(gameLoop);
        };

        const stop = () => {
            setIsGameStarted(false);
            if (animationFrameId) {
                cancelAnimationFrame(animationFrameId);
            }
        };

        start();

        return () => {
