import React, { useEffect, useRef, useState } from 'react';
import { Player, Enemy, Projectile, GameState, Archetype, Particle, DamageNumber, Upgrade, Item, AutoItem, StaticObject, WeatherType, BiomeType, Trap } from '../types';
import { CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, BASE_STATS, WAVE_CONFIGS, UPGRADES_LIST, SKILL_CONFIG, ZOOM_LEVEL, LEVEL_CONFIGS, BIOME_COLORS } from '../constants';
import { UpgradeModal } from './UpgradeModal';
import { Heart, Skull, Sword, Box, Crosshair, Wind, Zap, Move } from 'lucide-react';

interface GameCanvasProps {
  archetype: Archetype;
  onGameOver: () => void;
  isMobile: boolean;
}

// --- MATH UTILS ---
const toIso = (x: number, y: number, z: number = 0) => {
  return { x: (x - y), y: (x + y) / 2 - z };
};

const toWorldFromIso = (isoX: number, isoY: number) => {
    return { x: isoY + isoX / 2, y: isoY - isoX / 2 };
};

const lerp = (start: number, end: number, t: number) => {
  return start * (1 - t) + end * t;
};

const pseudoRandom = (x: number, y: number) => {
    return Math.abs(Math.sin(x * 12.9898 + y * 78.233) * 43758.5453) % 1;
};

// Optimized Color Adjust
const adjustColor = (color: string, amount: number) => {
    const num = parseInt(color.replace('#', ''), 16);
    let r = (num >> 16) + amount;
    let b = ((num >> 8) & 0x00FF) + amount;
    let g = (num & 0x0000FF) + amount;
    r = r > 255 ? 255 : r < 0 ? 0 : r;
    b = b > 255 ? 255 : b < 0 ? 0 : b;
    g = g > 255 ? 255 : g < 0 ? 0 : g;
    return "#" + (g | (b << 8) | (r << 16)).toString(16).padStart(6, '0');
};

const PORTAL_POS = { x: -400, y: -400 };

export const GameCanvas: React.FC<GameCanvasProps> = ({ archetype, onGameOver, isMobile }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Game State Refs
  const gameStateRef = useRef<GameState>(GameState.ISLAND);
  const playerRef = useRef<Player>({
    x: 0, y: 0, z: 0,
    archetype,
    stats: JSON.parse(JSON.stringify(BASE_STATS[archetype])),
    level: 1, xp: 0, xpToNextLevel: 100,
    weaponTimer: 0, skill1Timer: 0, skill1MaxCooldown: SKILL_CONFIG[archetype].skill1Cd,
    dashTimer: 0, 
    dashMaxCooldown: SKILL_CONFIG[archetype].dashCd,
    dashCharges: BASE_STATS[archetype].dashChargesMax,
    activeItem: null, itemTimer: 0, itemMaxCooldown: 0,
    autoItems: [], 
    facing: 0, isMoving: false, color: COLORS[archetype], animFrame: 0,
    slowTimer: 0, poisonTimer: 0, lastHitTime: 0, avatarBuffTimer: 0
  });

  const enemiesRef = useRef<Enemy[]>([]);
  const trapsRef = useRef<Trap[]>([]); 
  const projectilesRef = useRef<Projectile[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const damageNumbersRef = useRef<DamageNumber[]>([]);
  const staticObjectsRef = useRef<StaticObject[]>([]);
  const keysRef = useRef<{ [key: string]: boolean }>({});

  // Mobile Controls Refs
  const joystickRef = useRef({ active: false, startX: 0, startY: 0, currentX: 0, currentY: 0, vectorX: 0, vectorY: 0, id: -1 });

  // System Refs
  const cameraRef = useRef({ x: 0, y: 0 }); 
  const shakeRef = useRef(0); 
  const timeRef = useRef<number>(0); 
  const waveRef = useRef<number>(0);
  const waveTimerRef = useRef<number>(0);
  const lastSpawnTimeRef = useRef<number>(0);
  const bossSpawnedRef = useRef<boolean>(false); 

  // Dynamic Weather System
  const weatherTypeRef = useRef<WeatherType>('NONE');
  const weatherIntensityRef = useRef<number>(0); 
  const particleTimerRef = useRef<number>(0);
  const windForceRef = useRef({ x: 0, y: 0 }); 

  // UI State
  const [showUpgrade, setShowUpgrade] = useState(false);
  const [upgradeOptions, setUpgradeOptions] = useState<Upgrade[]>([]);
  const [lastUpgrade, setLastUpgrade] = useState<Upgrade | null>(null);
  const [hudData, setHudData] = useState({ 
      hp: 100, maxHp: 100, xp: 0, xpNext: 100, time: 0, wave: 1, level: 1, 
      state: GameState.ISLAND, skill1Cd: 0, dashCd: 0, itemCd: 0, dashCharges: 0, dashMax: 0,
      activeItem: null as Item | null, bossHp: 0, bossMaxHp: 0,
      autoItems: [] as AutoItem[],
      buffTime: 0,
      weather: 'NONE' as WeatherType,
      biome: 'FOREST' as BiomeType
  });

  const mouseScreenRef = useRef({ x: 0, y: 0 }); 
  const mouseWorldRef = useRef({ x: 0, y: 0 });
  const reticleAngleRef = useRef(0);

  const createParticle = (x: number, y: number, z: number, color: string, size: number, type: any = 'PARTICLE') => {
      let vx = (Math.random() - 0.5) * 100;
      let vy = (Math.random() - 0.5) * 100;
      let vz = (Math.random() * 150) + 50;
      let life = 1.0;

      if (type === 'BLOOD') { life = 0.5; }
      if (type === 'POISON') { vz = 50; life = 0.8; }
      if (type === 'SPARK') { vz = 100; life = 0.5; }
      if (type === 'TRAIL') { vx=0; vy=0; vz=0; life=0.3; }

      particlesRef.current.push({
          id: Math.random().toString(),
          x, y, z,
          vx, vy, vz,
          life, maxLife: life,
          color, size, type
      });
  };

  // --- INIT ---
  useEffect(() => {
    if (gameStateRef.current === GameState.ISLAND) {
        const objects: StaticObject[] = [];
        objects.push({ id: 'portal', x: PORTAL_POS.x, y: PORTAL_POS.y, type: 'PORTAL', size: 140 });
        objects.push({ id: 'h1', x: -150, y: -150, type: 'HOUSE', size: 110, variant: 0 });
        objects.push({ id: 'h2', x: 250, y: -250, type: 'HOUSE', size: 130, variant: 1 });
        objects.push({ id: 'h3', x: -350, y: 100, type: 'HOUSE', size: 100, variant: 0 });
        objects.push({ id: 'h4', x: 150, y: 200, type: 'HOUSE', size: 120, variant: 1 });
        objects.push({ id: 'h5', x: -50, y: 350, type: 'HOUSE', size: 90, variant: 0 });
        const lampPositions = [{x: 0, y: -300}, {x: -250, y: -300}, {x: -300, y: -250}, {x: -100, y: -100}, {x: 100, y: -200}, {x: -200, y: 50}];
        lampPositions.forEach((p, i) => objects.push({ id: `lamp${i}`, x: p.x, y: p.y, type: 'LAMP', size: 20 }));

        for(let i=0; i<150; i++) {
            const angle = Math.random() * Math.PI * 2;
            const dist = 300 + Math.random() * 900;
            const x = Math.cos(angle) * dist;
            const y = Math.sin(angle) * dist;
            let collides = false;
            for(const obj of objects) { if (Math.hypot(x - obj.x, y - obj.y) < obj.size * 0.8) collides = true; }
            if (Math.hypot(x - PORTAL_POS.x, y - PORTAL_POS.y) < 250) collides = true;

            if (!collides) {
                const r = Math.random();
                if (r < 0.6) { objects.push({ id: `t${i}`, x, y, type: 'TREE', size: 50 + Math.random() * 70, variant: Math.random() > 0.5 ? 1 : 0 }); } 
                else if (r < 0.85) { objects.push({ id: `b${i}`, x, y, type: 'BUSH', size: 20 + Math.random() * 15, variant: Math.random() > 0.5 ? 1 : 0 }); } 
                else { objects.push({ id: `r${i}`, x, y, type: 'ROCK', size: 15 + Math.random() * 25 }); }
            }
        }
        staticObjectsRef.current = objects;
    }
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { if (e.code === 'Space') e.preventDefault(); keysRef.current[e.code] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keysRef.current[e.code] = false; };
    const handleMouseMove = (e: MouseEvent) => {
      const rect = canvasRef.current?.getBoundingClientRect();
      if(rect) { mouseScreenRef.current = { x: e.clientX - rect.left - rect.width / 2, y: e.clientY - rect.top - rect.height / 2 }; }
    };
    const handleMouseDown = (e: MouseEvent) => { if (e.button === 0) keysRef.current['MouseLeft'] = true; };
    const handleMouseUp = (e: MouseEvent) => { if (e.button === 0) keysRef.current['MouseLeft'] = false; };
    const handleContextMenu = (e: MouseEvent) => e.preventDefault();

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    if (!isMobile) {
        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mousedown', handleMouseDown);
        window.addEventListener('mouseup', handleMouseUp);
    }
    window.addEventListener('contextmenu', handleContextMenu);

    let animationFrameId: number;
    let lastTime = performance.now();

    const loop = (timestamp: number) => {
      const dtRaw = (timestamp - lastTime) / 1000;
      const dt = Math.min(dtRaw, 0.1); 
      lastTime = timestamp;

      if (gameStateRef.current === GameState.TOWER || gameStateRef.current === GameState.ISLAND) {
        update(dt);
      }
      draw(dt);
      animationFrameId = requestAnimationFrame(loop);
    };

    animationFrameId = requestAnimationFrame(loop);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
      window.removeEventListener('contextmenu', handleContextMenu);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  // --- MOBILE JOYSTICK HANDLERS ---
  const handleJoystickStart = (e: React.TouchEvent) => {
    const touch = e.changedTouches[0];
    joystickRef.current = {
        active: true,
        startX: touch.clientX,
        startY: touch.clientY,
        currentX: touch.clientX,
        currentY: touch.clientY,
        vectorX: 0,
        vectorY: 0,
        id: touch.identifier
    };
  };

  const handleJoystickMove = (e: React.TouchEvent) => {
      if (!joystickRef.current.active) return;
      const touch = Array.from(e.changedTouches).find((t: React.Touch) => t.identifier === joystickRef.current.id);
      if (touch) {
          joystickRef.current.currentX = touch.clientX;
          joystickRef.current.currentY = touch.clientY;

          const dx = touch.clientX - joystickRef.current.startX;
          const dy = touch.clientY - joystickRef.current.startY;
          const dist = Math.sqrt(dx*dx + dy*dy);
          const maxDist = 50;

          const normDist = Math.min(dist, maxDist);
          const angle = Math.atan2(dy, dx);

          joystickRef.current.vectorX = Math.cos(angle) * (normDist / maxDist);
          joystickRef.current.vectorY = Math.sin(angle) * (normDist / maxDist);
      }
  };

  const handleJoystickEnd = (e: React.TouchEvent) => {
      const touch = Array.from(e.changedTouches).find((t: React.Touch) => t.identifier === joystickRef.current.id);
      if (touch) {
          joystickRef.current.active = false;
          joystickRef.current.vectorX = 0;
          joystickRef.current.vectorY = 0;
      }
  };

  // --- MOBILE ACTIONS ---
  const handleMobileSkill = (skill: 'Q' | 'E' | 'R') => {
      const p = playerRef.current;
      const stats = p.stats;

      // Effective Stats (recalc briefly for instant input)
      if (p.avatarBuffTimer > 0) { stats.damage *= 1.3; stats.speed *= 1.3; stats.cooldownReduction += 0.2; }

      if (skill === 'Q' && p.skill1Timer <= 0) { 
          useSkill1(stats); 
          p.skill1Timer = p.skill1MaxCooldown * (1 - stats.cooldownReduction); 
      }
      if (skill === 'E' && p.dashCharges > 0) { 
          useDash(); 
          p.dashCharges--; 
          if (p.dashTimer <= 0) p.dashTimer = p.dashMaxCooldown * (1 - stats.cooldownReduction); 
      }
      if (skill === 'R') {
          activateItem();
      }
  };

  // --- UPDATE ---
  const update = (dt: number) => {
    const player = playerRef.current;

    // Effective Stats
    const activeStats = { ...player.stats };
    if (player.avatarBuffTimer > 0) {
        player.avatarBuffTimer -= dt;
        activeStats.damage *= 1.3;
        activeStats.speed *= 1.3;
        activeStats.cooldownReduction += 0.2;
        if (player.avatarBuffTimer <= 0) player.avatarBuffTimer = 0;
    }

    // Camera
    const playerIso = toIso(player.x, player.y, player.z);

    // Mobile Viewport Centering is slightly different (no mouse peek)
    let targetX = -playerIso.x;
    let targetY = -playerIso.y;

    if (!isMobile) {
        targetX -= (mouseScreenRef.current.x / ZOOM_LEVEL) * 0.25;
        targetY -= (mouseScreenRef.current.y / ZOOM_LEVEL) * 0.25;
    }

    cameraRef.current.x = lerp(cameraRef.current.x, targetX, 0.08);
    cameraRef.current.y = lerp(cameraRef.current.y, targetY, 0.08);

    // Mouse World Calculation
    if (!isMobile) {
        const mouseIsoX = (mouseScreenRef.current.x / ZOOM_LEVEL) - cameraRef.current.x;
        const mouseIsoY = (mouseScreenRef.current.y / ZOOM_LEVEL) - cameraRef.current.y;
        mouseWorldRef.current = toWorldFromIso(mouseIsoX, mouseIsoY);
    }

    // --- MOVEMENT & WIND PHYSICS ---
    let dx = 0; let dy = 0;

    if (isMobile) {
        // Mobile Joystick
        dx = joystickRef.current.vectorX;
        dy = joystickRef.current.vectorY;

        // AUTO AIM FOR MOBILE
        // Find closest enemy
        let closestDist = 700;
        let closestEnemy = null;
        for (const e of enemiesRef.current) {
            const d = Math.hypot(e.x - player.x, e.y - player.y);
            if (d < closestDist) {
                closestDist = d;
                closestEnemy = e;
            }
        }

        if (closestEnemy) {
            player.facing = Math.atan2(closestEnemy.y - player.y, closestEnemy.x - player.x);
            // Update "Virtual Mouse" for skills that use mouse position (like Mage Q)
            mouseWorldRef.current = { x: closestEnemy.x, y: closestEnemy.y };
        } else if (dx !== 0 || dy !== 0) {
            // Face movement direction if no enemy
            player.facing = Math.atan2(dy, dx);
            mouseWorldRef.current = { 
                x: player.x + Math.cos(player.facing) * 200, 
                y: player.y + Math.sin(player.facing) * 200 
            };
        }

    } else {
        // Desktop Keys
        if (keysRef.current['KeyW'] || keysRef.current['ArrowUp']) { dx -= 1; dy -= 1; }
        if (keysRef.current['KeyS'] || keysRef.current['ArrowDown']) { dx += 1; dy += 1; }
        if (keysRef.current['KeyA'] || keysRef.current['ArrowLeft']) { dx -= 1; dy += 1; }
        if (keysRef.current['KeyD'] || keysRef.current['ArrowRight']) { dx += 1; dy -= 1; }

        const distMouse = Math.hypot(mouseWorldRef.current.x - player.x, mouseWorldRef.current.y - player.y);
        if (distMouse > 40) player.facing = Math.atan2(mouseWorldRef.current.y - player.y, mouseWorldRef.current.x - player.x);
    }

    reticleAngleRef.current = player.facing; 

    // Apply Wind Force
    let windDx = 0; let windDy = 0;
    if (gameStateRef.current === GameState.TOWER && (weatherTypeRef.current === 'WIND' || weatherTypeRef.current === 'STORM' || weatherTypeRef.current === 'SANDSTORM')) {
        windDx = windForceRef.current.x * weatherIntensityRef.current;
        windDy = windForceRef.current.y * weatherIntensityRef.current;
    }

    player.isMoving = Math.abs(dx) > 0.1 || Math.abs(dy) > 0.1;

    if (player.isMoving || Math.abs(windDx) > 0.1) {
      if (!isMobile) {
          // Normalize Keyboard input (Joystick is already normalized)
          const length = Math.sqrt(dx * dx + dy * dy);
          if (length > 0) { dx /= length; dy /= length; }
      }

      let currentSpeed = activeStats.speed * 60;
      if (player.slowTimer > 0) { player.slowTimer -= dt; currentSpeed *= 0.6; }

      // Weather Slow
      if (weatherTypeRef.current === 'SNOW' || weatherTypeRef.current === 'SANDSTORM') {
          currentSpeed *= 0.85; // Natural slow from terrain/weather
      }

      const newX = player.x + (dx * currentSpeed + windDx * 30) * dt; 
      const newY = player.y + (dy * currentSpeed + windDy * 30) * dt;

      // Collision
      let canMoveX = true; let canMoveY = true;
      if (gameStateRef.current === GameState.ISLAND) {
          const playerRadius = 15;
          staticObjectsRef.current.forEach(obj => {
              if (obj.type === 'PORTAL' || obj.type === 'BUSH') return;
              const dist = Math.hypot(newX - obj.x, player.y - obj.y);
              if (dist < obj.size * 0.4 + playerRadius) canMoveX = false;
              const distY = Math.hypot(player.x - obj.x, newY - obj.y);
              if (distY < obj.size * 0.4 + playerRadius) canMoveY = false;
          });
      }

      if (canMoveX) player.x = newX;
      if (canMoveY) player.y = newY;

      player.animFrame += dt * 10;
    } else { player.animFrame = 0; }

    if (player.z > 0) { player.z -= 200 * dt; if (player.z < 0) player.z = 0; }

    // Regen, Poison & Shield
    player.lastHitTime += dt;
    if (player.poisonTimer > 0) {
        player.poisonTimer -= dt;
        if (Math.floor(timeRef.current * 5) % 3 === 0) { // Simple tick check
             player.stats.hp -= 3 * dt; // DoT
             player.lastHitTime = 0;
             if (Math.random() > 0.8) createParticle(player.x, player.y, player.z + 20, '#a3e635', 5, 'POISON');
        }
    }

    if (activeStats.regen > 0 && player.lastHitTime > 3) { 
        const heal = activeStats.maxHp * (activeStats.regen / 100) * dt;
        player.stats.hp = Math.min(activeStats.maxHp, player.stats.hp + heal);
    }
    if (activeStats.shieldOnLowHp) {
        if (activeStats.shieldCooldown > 0) activeStats.shieldCooldown -= dt;
        else if (player.stats.hp < activeStats.maxHp * 0.2) {
             activeStats.shieldCooldown = 60; 
             player.stats.hp += activeStats.maxHp * 0.3; 
             createParticle(player.x, player.y, 10, '#3b82f6', 20, 'MAGIC');
        }
        player.stats.shieldCooldown = activeStats.shieldCooldown; 
    }

    const limit = gameStateRef.current === GameState.ISLAND ? 1500 : 900;
    if (Math.abs(player.x) > limit) player.x = Math.sign(player.x) * limit;
    if (Math.abs(player.y) > limit) player.y = Math.sign(player.y) * limit;

    // Portal Logic
    if (gameStateRef.current === GameState.ISLAND) {
        const distToPortal = Math.hypot(player.x - PORTAL_POS.x, player.y - PORTAL_POS.y); 
        if (distToPortal < 200) {
            gameStateRef.current = GameState.TOWER;
            player.x = 0; player.y = 0; player.z = 0; 
            enemiesRef.current = []; projectilesRef.current = []; trapsRef.current = [];
            waveRef.current = 0; timeRef.current = 0; 
            staticObjectsRef.current = []; 
            bossSpawnedRef.current = false;

            spawnTraps('FOREST'); // Initial Spawn
        }
        if (player.stats.hp < activeStats.maxHp) player.stats.hp += 100 * dt;
    }

    // TOWER LOGIC
    if (gameStateRef.current === GameState.TOWER) {
        timeRef.current += dt; waveTimerRef.current += dt;
        player.skill1Timer -= dt; player.itemTimer -= dt; player.weaponTimer -= dt;

        // --- WEATHER SYSTEM UPDATE ---
        const currentWaveConfig = WAVE_CONFIGS[waveRef.current] || WAVE_CONFIGS[WAVE_CONFIGS.length-1];
        weatherTypeRef.current = currentWaveConfig.weather || 'NONE';

        if (weatherTypeRef.current !== 'NONE') {
            weatherIntensityRef.current = Math.min(1, weatherIntensityRef.current + dt * 0.1);
            if (weatherTypeRef.current === 'WIND' || weatherTypeRef.current === 'STORM' || weatherTypeRef.current === 'SANDSTORM') {
                const windAngle = timeRef.current * 0.1;
                windForceRef.current = { x: Math.cos(windAngle), y: Math.sin(windAngle) };
            }
        } else {
            weatherIntensityRef.current = Math.max(0, weatherIntensityRef.current - dt * 0.2);
            windForceRef.current = { x: 0, y: 0 };
        }

        if (weatherIntensityRef.current > 0.1) {
            particleTimerRef.current += dt;
            const spawnRate = weatherTypeRef.current === 'STORM' ? 0.01 : 0.05;

            if (particleTimerRef.current > spawnRate) {
                const spawnCount = Math.floor(weatherIntensityRef.current * 5); 
                for(let i=0; i<spawnCount; i++) {
                    const angle = Math.random() * Math.PI * 2; const dist = Math.random() * 900; 
                    const px = player.x + Math.cos(angle)*dist - 400; 
                    const py = player.y + Math.sin(angle)*dist - 400;

                    let pType: any = 'RAIN';
                    let pColor = '#a5f3fc';
                    let pVz = -1200;
                    let pLife = 0.5;

                    if (weatherTypeRef.current === 'SANDSTORM') {
                        pType = 'SAND'; pColor = '#d97706'; pVz = -200; pLife = 1.0;
                    } else if (weatherTypeRef.current === 'FOG') {
                        pType = 'FOG'; pColor = 'rgba(200,220,230,0.1)'; pVz = 0; pLife = 2.0;
                    } else if (weatherTypeRef.current === 'SNOW') {
                        pType = 'SNOW'; pColor = '#ffffff'; pVz = -300; pLife = 1.5;
                    } else if (weatherTypeRef.current === 'ASH') {
                        pType = 'ASH'; pColor = '#57534e'; pVz = -150; pLife = 2.0;
                    }

                    const wx = windForceRef.current.x * 500;
                    const wy = windForceRef.current.y * 500;

                    particlesRef.current.push({ 
                        id: Math.random().toString(), 
                        x: px, y: py, z: pType === 'FOG' ? 50 : 500, 
                        vx: 50 + wx, vy: 50 + wy, vz: pVz, 
                        life: pLife, maxLife: pLife, 
                        color: pColor, size: pType === 'FOG' ? 50 : 1.5, type: pType 
                    });
                }
                particleTimerRef.current = 0;
            }
        }

        // Dash & Items
        if (player.dashCharges < activeStats.dashChargesMax) {
            player.dashTimer -= dt;
            if (player.dashTimer <= 0) {
                player.dashCharges++;
                player.dashTimer = player.dashMaxCooldown * (1 - activeStats.cooldownReduction);
            }
        }
        player.autoItems.forEach(item => {
            item.timer -= dt;
            if (item.timer <= 0) {
                const result = item.effect(player, enemiesRef.current);
                if (result) {
                    if (Array.isArray(result)) projectilesRef.current.push(...result); else projectilesRef.current.push(result);
                    item.timer = item.cooldown * (1 - activeStats.cooldownReduction);
                    if (player.avatarBuffTimer > 0) item.timer *= 0.5; 
                } else { item.timer = 0.5; }
            }
        });

        // Spawn & Trigger Upgrade
        const bossAlive = enemiesRef.current.some(e => e.isBoss);
        if ((!currentWaveConfig.boss && waveTimerRef.current >= currentWaveConfig.duration) || (currentWaveConfig.boss && bossSpawnedRef.current && !bossAlive)) {
             triggerUpgrade();
        } else if (enemiesRef.current.length < currentWaveConfig.enemyCount || currentWaveConfig.boss) { 
             if (Date.now() - lastSpawnTimeRef.current > currentWaveConfig.spawnRate) {
                 if (currentWaveConfig.boss && !bossSpawnedRef.current) { spawnBoss(currentWaveConfig.boss); bossSpawnedRef.current = true; } 
                 else if (enemiesRef.current.length < currentWaveConfig.enemyCount) { spawnEnemy(); }
                 lastSpawnTimeRef.current = Date.now();
             }
        }

        // Auto Attack for Mobile (or click for desktop)
        if ((isMobile || keysRef.current['MouseLeft']) && player.weaponTimer <= 0) {
            useMainAttack(activeStats);
        }

        // Desktop Skills
        if (!isMobile) {
            if (keysRef.current['KeyQ'] && player.skill1Timer <= 0) { useSkill1(activeStats); player.skill1Timer = player.skill1MaxCooldown * (1 - activeStats.cooldownReduction); }
            if (keysRef.current['KeyE'] && player.dashCharges > 0) { useDash(); player.dashCharges--; if (player.dashTimer <= 0) player.dashTimer = player.dashMaxCooldown * (1 - activeStats.cooldownReduction); keysRef.current['KeyE'] = false; }
            if (keysRef.current['KeyR']) activateItem();
        }
    }

    if (shakeRef.current > 0) shakeRef.current -= dt * 30; if (shakeRef.current < 0) shakeRef.current = 0;
    updateProjectiles(dt, activeStats);
    updateEnemies(dt, activeStats);
    updateParticles(dt);
    updateTraps(dt);

    const levelIdx = Math.floor(waveRef.current / 5);
    const biome = LEVEL_CONFIGS[Math.min(levelIdx, LEVEL_CONFIGS.length-1)].biome;
    const boss = enemiesRef.current.find(e => e.isBoss);
    setHudData({
        hp: player.stats.hp, maxHp: activeStats.maxHp, xp: player.xp, xpNext: player.xpToNextLevel,
        time: timeRef.current, wave: waveRef.current + 1, level: player.level,
        state: gameStateRef.current, skill1Cd: player.skill1Timer, dashCd: player.dashTimer, 
        dashCharges: player.dashCharges, dashMax: activeStats.dashChargesMax, itemCd: player.itemTimer,
        activeItem: player.activeItem, bossHp: boss ? boss.hp : 0, bossMaxHp: boss ? boss.maxHp : 0,
        autoItems: player.autoItems, buffTime: player.avatarBuffTimer, weather: weatherTypeRef.current, biome
    });

    if (player.stats.hp <= 0 && gameStateRef.current === GameState.TOWER) {
        gameStateRef.current = GameState.GAME_OVER;
        onGameOver();
    }
  };

  // --- SPAWN LOGIC ---
  const spawnTraps = (biome: BiomeType) => {
      const traps: Trap[] = [];
      const trapCount = 10 + waveRef.current * 2;

      for(let i=0; i<trapCount; i++) {
          const angle = Math.random() * Math.PI * 2;
          const dist = 300 + Math.random() * 800;
          const x = Math.cos(angle) * dist;
          const y = Math.sin(angle) * dist;

          let type: any = 'SPIKES';
          if (biome === 'VOLCANO') type = 'LAVA';
          if (biome === 'SWAMP') type = 'POISON_VENT';
          if (biome === 'FOREST' && Math.random() > 0.5) type = 'BEAR_TRAP';
          if (biome === 'ICE') type = 'SPIKES'; // Ice Spikes

          traps.push({
              id: Math.random().toString(),
              x, y, type,
              damage: 10 + waveRef.current * 2,
              radius: type === 'LAVA' ? 50 : 30,
              state: 'IDLE',
              timer: Math.random() * 2,
              triggerRange: 60
          });
      }
      trapsRef.current = traps;
  };

  const spawnEnemy = () => {
    const angle = Math.random() * Math.PI * 2; const distance = 850; 
    const ex = playerRef.current.x + Math.cos(angle) * distance; const ey = playerRef.current.y + Math.sin(angle) * distance;

    // Select monster based on Level Config
    const currentWave = waveRef.current;
    const levelIdx = Math.min(Math.floor(currentWave / 5), LEVEL_CONFIGS.length - 1);
    const levelConfig = LEVEL_CONFIGS[levelIdx];
    const monsterType = levelConfig.monsters[Math.floor(Math.random() * levelConfig.monsters.length)];

    let hp = 40 + currentWave * 20; let speed = 80 + Math.random()*20; // Increased base Stats
    let initialZ = 0;

    // Specific Monster Stats & AI Setup
    if (monsterType.includes('GOLEM') || monsterType.includes('TROLL')) { hp *= 2.5; speed *= 0.6; }
    if (monsterType.includes('WOLF') || monsterType.includes('DOG')) { hp *= 0.8; speed *= 1.5; }
    if (monsterType.includes('BAT') || monsterType.includes('HARPY') || monsterType.includes('GHOST')) { 
        hp *= 0.7; 
        speed *= 1.3; 
        initialZ = 100; 
    }
    if (monsterType.includes('SNAKE') || monsterType.includes('WORM')) {
        speed *= 1.2;
    }

    const variant = Math.floor(Math.random() * 3);
    if (variant === 1) { hp *= 0.8; speed *= 1.2; } else if (variant === 2) { hp *= 1.3; speed *= 0.85; }

    enemiesRef.current.push({
      id: Math.random().toString(), x: ex, y: ey, z: initialZ, 
      type: monsterType, isBoss: false, hp, maxHp: hp, defense: currentWave * 3, speed, damage: 15 + currentWave * 3,
      radius: 20, hitboxRadius: 16, frame: 0, vx: 0, vy: 0, hitFlash: 0,
      state: 'CHASING', stateTimer: 0, attackRange: 50, windupTime: 0.5, recoverTime: 0.5, variant,
      specialCooldown: 2 + Math.random() * 3, specialMaxCooldown: 5, // Init Cooldowns for AI
      targetX: undefined, targetY: undefined
    });
  };

  const spawnBoss = (config: any) => {
      if (!config) return;

      const dist = 600; const angle = Math.random() * Math.PI * 2;
      const hp = 6000 * config.hpMult * (1 + waveRef.current * 0.25); 
      const damage = 70 * config.dmgMult + waveRef.current * 3; 

      enemiesRef.current.push({
          id: 'boss', x: playerRef.current.x + Math.cos(angle)*dist, y: playerRef.current.y + Math.sin(angle)*dist, z: 0,
          type: config.type, isBoss: true, hp, maxHp: hp, defense: 60 + waveRef.current * 6, 
          speed: 130, // High Mobility as requested
          damage, radius: 80, hitboxRadius: 60, frame: 0, vx: 0, vy: 0, hitFlash: 0,
          state: 'CHASING', stateTimer: 0, attackRange: 150, windupTime: 1.0, recoverTime: 1.0, variant: 0, 
          skill1Cd: 0, skill2Cd: 5, skill3Cd: 10,
          skill1MaxCd: 6, skill2MaxCd: 12, skill3MaxCd: 18,
          bossColor: config.color,
          specialCooldown: 0, specialMaxCooldown: 0,
          targetX: undefined, targetY: undefined
      });
      shakeRef.current = 20; 
  };

  const updateEnemies = (dt: number, stats: any) => {
      const p = playerRef.current;
      const enemiesList = enemiesRef.current;
      const enemyCount = enemiesList.length;

      enemiesRef.current = enemiesList.filter((e, idx) => {
          if (e.hitFlash > 0) e.hitFlash -= dt;
          if (e.frozenTimer && e.frozenTimer > 0) { e.frozenTimer -= dt; return true; }
          e.frame += dt; 
          if (e.specialCooldown > 0) e.specialCooldown -= dt;

          // --- BOSS AI LOGIC ---
          if (e.isBoss) {
              // Skill Cooldowns
              if (e.skill1Cd && e.skill1Cd > 0) e.skill1Cd -= dt;
              if (e.skill2Cd && e.skill2Cd > 0) e.skill2Cd -= dt;
              if (e.skill3Cd && e.skill3Cd > 0) e.skill3Cd -= dt;

              // Retreat Logic (Low HP)
              if (e.hp < e.maxHp * 0.3 && e.state !== 'RETREATING' && e.state !== 'ATTACKING') {
                  if (Math.random() < 0.05) { // Chance to decide to retreat
                      e.state = 'RETREATING';
                      e.stateTimer = 5.0; // Retreat for 5 seconds
                  }
              }

              // Regen if retreating or idle
              if (e.state === 'RETREATING' || e.state === 'RECOVERING') {
                  e.hp = Math.min(e.maxHp, e.hp + 10 * dt);
              }
          }

          // Separation Flocking
          if (!e.isBoss && !e.type.includes('BAT') && e.state !== 'DASHING' && e.state !== 'JUMPING') { 
              let sepX = 0, sepY = 0; const checkLimit = Math.min(idx + 3, enemyCount);
              for (let i = Math.max(0, idx - 3); i < checkLimit; i++) {
                  if (i === idx) continue;
                  const other = enemiesList[i];
                  const distSq = (e.x - other.x)**2 + (e.y - other.y)**2; const minDist = (e.radius + other.radius) * 0.8;
                  if (distSq < minDist**2 && distSq > 0.1) {
                      const pushDist = Math.sqrt(distSq); const pushForce = (minDist - pushDist) / pushDist;
                      sepX += (e.x - other.x) * pushForce; sepY += (e.y - other.y) * pushForce;
                  }
              }
              e.vx += sepX * 200 * dt; e.vy += sepY * 200 * dt;
          }

          if (e.state !== 'DASHING' && e.state !== 'JUMPING' && (Math.abs(e.vx) > 1 || Math.abs(e.vy) > 1)) { e.x += e.vx * dt; e.y += e.vy * dt; e.vx *= 0.9; e.vy *= 0.9; }

          const dx = p.x - e.x; const dy = p.y - e.y; const dist = Math.hypot(dx, dy);

          if (e.state === 'CHASING') {
              // Ensure targets are cleared
              if (e.targetX !== undefined) { e.targetX = undefined; e.targetY = undefined; }

              if (dist > 10) {
                  let speed = e.speed * (e.isBoss ? 1.5 : 1); // Bosses move faster
                  let mx = dx / dist;
                  let my = dy / dist;

                  // --- SNAKE MOVEMENT ---
                  if (e.type.includes('SNAKE') || e.type.includes('WORM')) {
                      const wobble = Math.sin(e.frame * 8) * 0.6;
                      mx += -my * wobble; 
                      my += mx * wobble;
                      const len = Math.hypot(mx, my);
                      mx /= len; my /= len;
                  }

                  // --- BAT MOVEMENT ---
                  if (e.type.includes('BAT') || e.type.includes('HARPY') || e.type.includes('GHOST')) {
                      const hoverHeight = 100 + Math.sin(e.frame * 2) * 20;
                      e.z = lerp(e.z, hoverHeight, dt * 2);
                      if (dist < 200 && dist > 50 && Math.random() < 0.02) {
                          e.state = 'WINDUP';
                          e.stateTimer = 0.4;
                      }
                  }

                  // --- NEW AI: DASHING (Wolves, Dogs) ---
                  if ((e.type.includes('WOLF') || e.type.includes('DOG') || e.type.includes('SHARK')) && e.specialCooldown <= 0 && dist < 350 && dist > 100) {
                      e.state = 'WINDUP';
                      e.stateTimer = 0.6; // Telegraph time
                      e.specialCooldown = e.specialMaxCooldown;
                      e.vx = 0; e.vy = 0; 

                      // Calculate Dash Target for Telegraphing
                      const dashAngle = Math.atan2(p.y - e.y, p.x - e.x);
                      const dashDist = 300;
                      e.startX = e.x; e.startY = e.y;
                      e.targetX = e.x + Math.cos(dashAngle) * dashDist;
                      e.targetY = e.y + Math.sin(dashAngle) * dashDist;
                  }
                  // --- NEW AI: JUMPING (Slimes, Spiders, Yetis) ---
                  else if ((e.type.includes('SLIME') || e.type.includes('SPIDER') || e.type.includes('YETI') || e.type.includes('FROG')) && e.specialCooldown <= 0 && dist < 300) {
                      e.state = 'WINDUP';
                      e.stateTimer = 0.8; // Telegraph jump
                      e.specialCooldown = e.specialMaxCooldown;
                      e.vx = 0; e.vy = 0;
                      e.targetX = p.x; e.targetY = p.y; // Jump to player pos
                      e.startX = e.x; e.startY = e.y;
                  }
                  // --- NEW AI: SHOOTING (Skeletons, Sorcerers, Witches) ---
                  else if ((e.type.includes('SKELETON') || e.type.includes('SORCERER') || e.type.includes('WITCH') || e.type.includes('NECRO')) && e.specialCooldown <= 0 && dist < 500) {
                      e.state = 'SHOOTING';
                      e.stateTimer = 1.0; // Aiming time
                      e.specialCooldown = e.specialMaxCooldown;
                      e.vx = 0; e.vy = 0;
                  }
                  // --- NEW AI: GUARDING (Golems) ---
                  else if (e.type.includes('GOLEM') && e.specialCooldown <= 0 && dist < 200) {
                      e.state = 'GUARDING';
                      e.stateTimer = 3.0;
                      e.specialCooldown = e.specialMaxCooldown * 1.5;
                  }
                  else {
                      // Normal Movement
                      e.x += mx * speed * dt;
                      e.y += my * speed * dt;
                  }
              }

              // Boss/Normal Attack Triggers
              if (e.isBoss) {
                  if (e.skill1Cd && e.skill1Cd <= 0 && dist < 300) { e.state = 'WINDUP'; e.stateTimer = 0.5; e.skill1Cd = e.skill1MaxCd; } 
                  else if (e.skill2Cd && e.skill2Cd <= 0) { e.state = 'WINDUP'; e.stateTimer = 0.8; e.skill2Cd = e.skill2MaxCd; } 
                  else if (e.skill3Cd && e.skill3Cd <= 0) { e.state = 'WINDUP'; e.stateTimer = 1.2; e.skill3Cd = e.skill3MaxCd; } 
                  else if (dist < e.attackRange) { e.state = 'WINDUP'; e.stateTimer = e.windupTime; } 
              } else {
                  if (!(e.type.includes('BAT') || e.type.includes('HARPY')) && e.state !== 'SHOOTING' && e.state !== 'GUARDING') { 
                      if (dist < e.attackRange) { e.state = 'WINDUP'; e.stateTimer = e.windupTime; e.targetX = undefined; } // Ensure normal attack has no targetX
                  }
              }
          }
          else if (e.state === 'RETREATING') {
              if (dist > 0) { e.x -= (dx / dist) * e.speed * 1.5 * dt; e.y -= (dy / dist) * e.speed * 1.5 * dt; }
              e.stateTimer -= dt;
              if (e.stateTimer <= 0 || dist > 600) { e.state = 'CHASING'; }
          }
          else if (e.state === 'GUARDING') {
              e.stateTimer -= dt;
              e.hp = Math.min(e.maxHp, e.hp + (e.maxHp * 0.05 * dt));
              if (e.stateTimer <= 0) e.state = 'CHASING';
          }
          else if (e.state === 'SHOOTING') {
              e.stateTimer -= dt;
              if (e.stateTimer <= 0) {
                  const angle = Math.atan2(p.y - e.y, p.x - e.x);
                  projectilesRef.current.push({
                      id: Math.random().toString(),
                      x: e.x, y: e.y, z: 30,
                      vx: Math.cos(angle) * 400, vy: Math.sin(angle) * 400,
                      damage: e.damage,
                      duration: 2.0,
                      radius: 10,
                      type: 'ENEMY_BOLT',
                      color: e.type.includes('SKELETON') ? '#e2e8f0' : '#a855f7',
                      pierce: 0,
                      isEnemy: true
                  });
                  e.state = 'RECOVERING';
                  e.stateTimer = 1.0;
              }
          }
          else if (e.state === 'WINDUP') {
              e.stateTimer -= dt;

              if (e.type.includes('BAT') || e.type.includes('HARPY')) {
                  e.z = lerp(e.z, 140, dt * 5); 
              }

              if (e.stateTimer <= 0) {
                  // Check if it was a Special Move (Target is defined)
                  const hasTarget = e.targetX !== undefined;

                  // DASH EXECUTION
                  if (hasTarget && (e.type.includes('WOLF') || e.type.includes('DOG') || e.type.includes('SHARK'))) {
                      e.state = 'DASHING';
                      e.stateTimer = 0.4; // Dash duration
                      const dashAngle = Math.atan2((e.targetY || p.y) - e.y, (e.targetX || p.x) - e.x);
                      e.vx = Math.cos(dashAngle) * 1200;
                      e.vy = Math.sin(dashAngle) * 1200;
                  }
                  // JUMP EXECUTION
                  else if (hasTarget && (e.type.includes('SLIME') || e.type.includes('SPIDER') || e.type.includes('YETI') || e.type.includes('FROG'))) {
                      e.state = 'JUMPING';
                      e.stateTimer = 0.8; // Air time
                      e.vx = (e.targetX! - e.x) / 0.8;
                      e.vy = (e.targetY! - e.y) / 0.8;
                  }
                  else if (e.type.includes('BAT') || e.type.includes('HARPY')) {
                      e.state = 'SWOOPING'; 
                  } else {
                      // Normal Attack Fallback (even for Slimes/Wolves if on cooldown/close range)
                      e.state = 'ATTACKING';
                      if (e.isBoss) {
                          projectilesRef.current.push({ id: Math.random().toString(), x: e.x, y: e.y, z: 0, vx: 0, vy: 0, damage: e.damage, duration: 0.5, radius: 150, type: 'BOSS_SMASH', color: e.bossColor || '#ef4444', pierce: 999, isEnemy: true });
                          shakeRef.current = 20;
                      } 
                      else if (e.type.includes('SNAKE') || e.type.includes('WORM')) {
                          if (dist < e.attackRange + 40) { takeDamage(p, e.damage, 'POISON'); }
                      }
                      else if (dist < e.attackRange + 30) { takeDamage(p, e.damage); }
                      e.state = 'RECOVERING'; e.stateTimer = e.recoverTime;
                  }
              }
          }
          else if (e.state === 'DASHING') {
              e.stateTimer -= dt;
              e.x += e.vx * dt;
              e.y += e.vy * dt;
              createParticle(e.x, e.y, e.z, '#fff', 2, 'TRAIL');
              if (dist < 40) { takeDamage(p, e.damage * 1.2); e.state = 'RECOVERING'; e.stateTimer = 1.0; }
              if (e.stateTimer <= 0) { e.state = 'RECOVERING'; e.stateTimer = 0.5; e.vx = 0; e.vy = 0; }
          }
          else if (e.state === 'JUMPING') {
              e.stateTimer -= dt;
              e.x += e.vx * dt;
              e.y += e.vy * dt;
              // Parabolic Arc
              const totalTime = 0.8;
              const progress = 1 - (e.stateTimer / totalTime);
              e.z = Math.sin(progress * Math.PI) * 200;

              if (e.stateTimer <= 0) {
                  e.z = 0;
                  e.state = 'RECOVERING';
                  e.stateTimer = 1.0;
                  e.vx = 0; e.vy = 0;
                  createParticle(e.x, e.y, 0, '#fff', 10, 'IMPACT');

                  // Area Damage on Land
                  const landDist = Math.hypot(p.x - e.x, p.y - e.y);
                  if (landDist < 60) {
                      takeDamage(p, e.damage * 1.5);
                      p.slowTimer = 1.0;
                  }
              }
          }
          else if (e.state === 'SWOOPING') {
              const speed = e.speed * 3.5;
              const diveDx = p.x - e.x;
              const diveDy = p.y - e.y;
              const diveDist = Math.hypot(diveDx, diveDy);
              if (diveDist > 10) { e.x += (diveDx / diveDist) * speed * dt; e.y += (diveDy / diveDist) * speed * dt; }
              e.z = lerp(e.z, 0, dt * 10); 
              if (diveDist < 20 || e.z < 10) { takeDamage(p, e.damage); e.state = 'RECOVERING'; e.stateTimer = 1.0; }
          }
          else if (e.state === 'RECOVERING') { 
              e.targetX = undefined; // Reset Target
              e.stateTimer -= dt; 
              if (e.type.includes('BAT') || e.type.includes('HARPY')) { e.z = lerp(e.z, 100, dt * 2); }
              if (e.stateTimer <= 0) e.state = 'CHASING'; 
          }

          for (const proj of projectilesRef.current) {
               if (proj.duration <= 0 || proj.isEnemy) continue;
               if (proj.delayedDamage && proj.duration > 0.1) continue;
               if (e.z > 50 && (proj.type === 'SWORD_SLASH' || proj.type === 'FIRE_ZONE' || proj.type === 'EARTH_SPIKE')) continue;

               const pDist = Math.hypot(proj.x - e.x, proj.y - e.y);
               if(pDist < proj.radius + e.hitboxRadius) {
                   if (proj.type === 'TIME_PRISON') { e.frozenTimer = 3.0; continue; }
                   if (proj.knockbackForce && e.state !== 'GUARDING') { const kAngle = Math.atan2(e.y - proj.y, e.x - proj.x); e.vx += Math.cos(kAngle) * proj.knockbackForce; e.vy += Math.sin(kAngle) * proj.knockbackForce; }

                   const isAoe = proj.type === 'SWORD_SLASH' || proj.type === 'FIRE_ZONE' || proj.type === 'OCEAN_WAVE';
                   let dmg = isAoe ? proj.damage * 5 * dt : proj.damage;
                   const isCrit = Math.random() < stats.critChance; if (isCrit) dmg *= stats.critDamage;
                   if (stats.executionerThreshold > 0 && (e.hp / e.maxHp) < 0.3) { dmg *= (1 + stats.executionerThreshold); }

                   let mitigation = 100 / (100 + Math.max(0, e.defense - stats.armorPenetration));
                   if (e.state === 'GUARDING') mitigation *= 0.2; 

                   const finalDmg = dmg * mitigation;
                   e.hitFlash = 0.15; 

                   if (!isAoe) { if (proj.type === 'ARROW' || proj.type === 'MAGIC_ORB') { const kAngle = Math.atan2(e.y - proj.y, e.x - proj.x); const force = e.type === 'BAT' ? 500 : 300; e.vx = Math.cos(kAngle) * force; e.vy = Math.sin(kAngle) * force; proj.pierce--; if (proj.pierce < 0) proj.duration = 0; } }
                   e.hp -= finalDmg;

                   const isBlocked = e.state === 'GUARDING';
                   if (!isAoe || Math.random() > 0.8) { 
                       createDamageNumber(e.x, e.y, e.z + 40, finalDmg, isCrit, false, isBlocked); 
                       const color = proj.color; 
                       if (isBlocked) createParticle(e.x, e.y, e.z + 40, '#94a3b8', 5, 'SPARK');
                       else if (proj.type === 'MAGIC_ORB' || proj.type === 'AUTO_FIREBALL' || proj.type === 'SWORD_SLASH') { createParticle(e.x, e.y, e.z + 20, color, 3, 'MAGIC'); } else { createParticle(e.x, e.y, e.z + 20, color, 2, 'IMPACT'); } 
                   }
                   if(e.hp <= 0 && !e.isBoss) { createParticle(e.x, e.y, e.z, '#ef4444', 12, 'BLOOD'); if (stats.lifeSteal > 0) { const heal = stats.maxHp * stats.lifeSteal; if (heal > 0) { p.stats.hp = Math.min(stats.maxHp, p.stats.hp + heal); createDamageNumber(p.x, p.y, p.z + 80, heal, false, false, false); } } if (!isAoe && proj.pierce < 0) break; break; }
               }
          }

          if(e.hp <= 0) {
              p.xp += e.isBoss ? 500 : 15; shakeRef.current += e.isBoss ? 20 : 2; 
              if(p.xp >= p.xpToNextLevel) { p.level++; p.xp -= p.xpToNextLevel; p.xpToNextLevel *= 1.2; p.stats.damage *= 1.1; p.stats.maxHp *= 1.1; p.stats.hp = p.stats.maxHp; createDamageNumber(p.x, p.y, p.z+60, 0, true); shakeRef.current += 10; }
              return false;
          }
          return true;
      });
  };

  const updateTraps = (dt: number) => {
      const p = playerRef.current;
      trapsRef.current.forEach(trap => {
          trap.timer += dt;

          if (trap.type === 'SPIKES') {
              if (trap.state === 'IDLE' && trap.timer > 2.0) { trap.state = 'ACTIVE'; trap.timer = 0; }
              if (trap.state === 'ACTIVE' && trap.timer > 1.0) { trap.state = 'IDLE'; trap.timer = 0; }
              if (trap.state === 'ACTIVE') {
                   const dist = Math.hypot(p.x - trap.x, p.y - trap.y);
                   if (dist < trap.radius) takeDamage(p, trap.damage * dt * 2); 
              }
          }
          else if (trap.type === 'BEAR_TRAP') {
              if (trap.state === 'IDLE') {
                  const dist = Math.hypot(p.x - trap.x, p.y - trap.y);
                  if (dist < trap.radius) {
                      takeDamage(p, trap.damage);
                      p.slowTimer = 2.0;
                      trap.state = 'COOLDOWN';
                      createParticle(p.x, p.y, 10, '#475569', 10, 'IMPACT');
                  }
              }
          }
          else if (trap.type === 'LAVA' || trap.type === 'POISON_VENT') {
              const dist = Math.hypot(p.x - trap.x, p.y - trap.y);
              if (dist < trap.radius) {
                  takeDamage(p, trap.damage * dt, trap.type === 'POISON_VENT' ? 'POISON' : 'NORMAL');
              }
          }
      });
  };

  const takeDamage = (p: Player, amount: number, effectType?: 'POISON' | 'NORMAL') => {
      const reducedByPercent = amount * (1 - Math.min(0.8, p.stats.damageReduction)); 
      const finalDmg = Math.max(1, reducedByPercent - p.stats.defense);
      p.stats.hp -= finalDmg; 
      shakeRef.current = 10; 
      p.slowTimer = 0.5; 
      p.lastHitTime = 0; 

      if (effectType === 'POISON') {
          p.poisonTimer = 5.0; 
          createParticle(p.x, p.y, p.z + 40, '#a3e635', 10, 'POISON');
      }

      createDamageNumber(p.x, p.y, p.z + 50, finalDmg, false, true);
  };

  const updateProjectiles = (dt: number, stats: any) => {
      const p = playerRef.current;
      projectilesRef.current = projectilesRef.current.filter(proj => {
          proj.duration -= dt;
          if(proj.type === 'SWORD_SLASH' || proj.type === 'OCEAN_WAVE' || proj.type === 'TIME_PRISON') { if (proj.type === 'OCEAN_WAVE') proj.radius += dt * 100; else { proj.x = p.x; proj.y = p.y; } } 
          else { if (proj.type === 'ARCANE_COLOSSUS') { let closest = null; let minD = Infinity; for(const e of enemiesRef.current) { const d = Math.hypot(e.x - proj.x, e.y - proj.y); if (d < minD) { minD = d; closest = e; } } if (closest) { const angle = Math.atan2(closest.y - proj.y, closest.x - proj.x); proj.vx += Math.cos(angle) * 1000 * dt; proj.vy += Math.sin(angle) * 1000 * dt; proj.vx *= 0.95; proj.vy *= 0.95; } } proj.x += proj.vx * dt; proj.y += proj.vy * dt; }
          if (!proj.isEnemy && proj.duration > 0) { if (proj.type === 'ARROW') { if (Math.random() > 0.5) createParticle(proj.x, proj.y, proj.z, 'rgba(255,255,255,0.3)', 1, 'TRAIL'); } else if (proj.type === 'MAGIC_ORB' || proj.type === 'ENEMY_BOLT' || proj.type === 'ARCANE_COLOSSUS') { if (Math.random() > 0.2) createParticle(proj.x + (Math.random()-0.5)*10, proj.y + (Math.random()-0.5)*10, proj.z, proj.color, 1, 'MAGIC'); } else if (proj.type === 'AUTO_FIREBALL' || proj.type === 'FIRE_ZONE' || proj.type === 'HELL_FLAME') { if (Math.random() > 0.3) createParticle(proj.x + (Math.random()-0.5)*proj.radius, proj.y + (Math.random()-0.5)*proj.radius, proj.z, proj.color, 1, 'FIRE'); } else if (proj.type === 'SPIRIT_WAVE') { createParticle(proj.x, proj.y, proj.z, proj.color, 1, 'MAGIC'); } }
          if (Math.abs(proj.x - p.x) > 1500 || Math.abs(proj.y - p.y) > 1500) return false;
          if (proj.isEnemy) { const dist = Math.hypot(proj.x - p.x, proj.y - p.y); if (proj.type === 'LICH_DRAIN_ZONE') { if (dist < proj.radius) { takeDamage(p, proj.damage * dt); const lich = enemiesRef.current.find(e => e.type === 'BOSS_LICH'); if (lich && lich.hp < lich.maxHp) { lich.hp += proj.damage * dt * 0.5; } } } else if (dist < (proj.type === 'BOSS_SMASH' ? proj.radius : 20)) { takeDamage(p, proj.damage); return false; } else if (dist < proj.radius) { takeDamage(p, proj.damage); if (proj.type === 'POISON_SPIT') { p.slowTimer = 1.0; } return false; } }
          return proj.duration > 0;
      });
  };

  const updateParticles = (dt: number) => {
      particlesRef.current = particlesRef.current.filter(p => {
          p.life -= dt;
          p.x += p.vx * dt;
          p.y += p.vy * dt;
          p.z += p.vz * dt;
          if (['RAIN', 'SNOW', 'ASH', 'SAND'].includes(p.type || '')) {
              if (p.z <= 0) return false;
          } else if (p.type !== 'FOG' && p.type !== 'TRAIL') {
               p.vz -= 1000 * dt; 
               if (p.z <= 0) {
                   p.z = 0;
                   p.vx *= 0.5;
                   p.vy *= 0.5;
                   p.vz *= -0.5;
                   if (Math.abs(p.vz) < 50) p.vz = 0;
               }
          }
          return p.life > 0;
      });
  };

  const createDamageNumber = (x: number, y: number, z: number, val: number, crit: boolean, isPlayerDamage = false, isBlocked = false) => {
      if (val < 1 && !isBlocked) return;
      damageNumbersRef.current.push({ id: Math.random().toString(), x: x + (Math.random()-0.5)*20, y, z, value: val, life: 0.8, isCrit: crit, isPlayerDamage });
  };

  const useMainAttack = (stats: any) => {
     const p = playerRef.current; const angle = p.facing; const vx = Math.cos(angle) * 800; const vy = Math.sin(angle) * 800; const atkSpdMultiplier = Math.max(0.1, stats.attackSpeed);
     if (p.archetype === Archetype.WARRIOR) { projectilesRef.current.push({ id: Math.random().toString(), x: p.x, y: p.y, z: 20, vx: 0, vy: 0, damage: stats.damage, duration: 0.3, radius: 100 * stats.areaSize, type: 'SWORD_SLASH', color: '#60a5fa', pierce: 999 }); p.weaponTimer = (0.6 / atkSpdMultiplier) * (1 - stats.cooldownReduction); } 
     else { projectilesRef.current.push({ id: Math.random().toString(), x: p.x, y: p.y, z: 30, vx, vy, damage: stats.damage, duration: 1.5, radius: 15, type: p.archetype === Archetype.ARCHER ? 'ARROW' : 'MAGIC_ORB', color: p.color, pierce: p.archetype === Archetype.MAGE ? 2 : 0 }); const baseCd = p.archetype === Archetype.ARCHER ? 0.4 : 0.5; p.weaponTimer = (baseCd / atkSpdMultiplier) * (1 - stats.cooldownReduction); }
  };

  const useSkill1 = (stats: any) => {
      const p = playerRef.current; createParticle(p.x, p.y, 20, '#fff', 10); shakeRef.current = 5; 
      if(p.archetype === Archetype.WARRIOR) { 
          projectilesRef.current.push({ id: Math.random().toString(), x: p.x, y: p.y, z: 20, vx: 0, vy: 0, damage: stats.damage * 2.5, duration: 0.5, radius: 160 * stats.areaSize, type: 'SWORD_SLASH', color: '#ef4444', pierce: 999 }); 
      } 
      else if (p.archetype === Archetype.ARCHER) {
          // ARCHER Q: CONE ARROW BURST
          const baseAngle = reticleAngleRef.current;
          const arrowCount = 5;
          const spread = Math.PI / 4; // 45 degrees spread
          const startAngle = baseAngle - spread / 2;
          const stepAngle = spread / (arrowCount - 1);

          for(let i=0; i<arrowCount; i++) {
              const currentAngle = startAngle + (stepAngle * i);
              const vx = Math.cos(currentAngle) * 900;
              const vy = Math.sin(currentAngle) * 900;

              projectilesRef.current.push({ 
                  id: Math.random().toString(), 
                  x: p.x, y: p.y, z: 30, 
                  vx, vy, 
                  damage: stats.damage * 1.5, 
                  duration: 1.0, 
                  radius: 20, 
                  type: 'ARROW', 
                  color: '#86efac', 
                  pierce: 3 // Burst arrows penetrate multiple targets
              });
          }
      }
      else { 
          projectilesRef.current.push({ id: Math.random().toString(), x: mouseWorldRef.current.x, y: mouseWorldRef.current.y, z: 0, vx: 0, vy: 0, damage: stats.damage * 3, duration: 1.2, radius: 120 * stats.areaSize, type: 'FIRE_ZONE', color: p.archetype === Archetype.MAGE ? '#9333ea' : '#ef4444', pierce: 999 }); 
      }
  };

  const useDash = () => {
      const p = playerRef.current; 
      const angle = p.isMoving ? Math.atan2(joystickRef.current.vectorY, joystickRef.current.vectorX) : reticleAngleRef.current; 
      // Fallback for keyboard dash if joystick is inactive but isMobile (unlikely case but good for hybrid)
      const moveAngle = Math.atan2(p.y - mouseWorldRef.current.y, p.x - mouseWorldRef.current.x) + Math.PI;

      const finalAngle = joystickRef.current.active ? angle : (isMobile ? reticleAngleRef.current : moveAngle);

      const vx = Math.cos(finalAngle) * 1200; const vy = Math.sin(finalAngle) * 1200;
      p.x += vx * 0.2; p.y += vy * 0.2; p.z = 40; createParticle(p.x, p.y, 10, '#fff', 5);
  };

  const activateItem = () => { const p = playerRef.current; if (p.activeItem && p.itemTimer <= 0) { p.activeItem.effect(p, enemiesRef.current); p.itemTimer = p.activeItem.cooldown; } };

  // --- TRIGGER UPGRADE LOGIC ---
  const triggerUpgrade = () => {
    gameStateRef.current = GameState.PAUSED;
    const options: Upgrade[] = [];
    const rollItem = !playerRef.current.activeItem && Math.random() > 0.8; 
    const selectedIds = new Set<string>();

    let safetyCounter = 0;
    while (options.length < 4 && safetyCounter < 50) {
        safetyCounter++;
        let pool = UPGRADES_LIST;

        if (rollItem && options.length === 0) { 
            const itemPool = UPGRADES_LIST.filter(u => u.type === 'ITEM');
            if (itemPool.length > 0) {
                pool = itemPool;
            } else {
                pool = UPGRADES_LIST.filter(u => u.type !== 'ITEM' && u.type !== 'AUTO_ITEM'); 
            }
        } 
        else {
            pool = UPGRADES_LIST.filter(u => {
                if (u.type === 'ITEM' && playerRef.current.activeItem) return false;
                if (u.type === 'AUTO_ITEM' && playerRef.current.autoItems.some(ai => ai.id === u.autoItemRef?.id)) return false;
                return true;
            });
        }

        if (pool.length === 0) {
            pool = UPGRADES_LIST.filter(u => u.type === 'STAT');
        }

        if (pool.length === 0) break;

        const rand = pool[Math.floor(Math.random() * pool.length)];
        if (!selectedIds.has(rand.id) || pool.every(p => selectedIds.has(p.id))) { 
            options.push({...rand, id: rand.id}); 
            selectedIds.add(rand.id); 
        }
    }
    setUpgradeOptions(options);
    setShowUpgrade(true);
  };

  const getLegendaryItems = () => {
      const p = playerRef.current;
      const legendaries: (Item | AutoItem)[] = [];
      if (p.activeItem && p.activeItem.isLegendary) legendaries.push(p.activeItem);
      p.autoItems.forEach(ai => {
          if (ai.isLegendary) legendaries.push(ai);
      });
      return legendaries;
  };

  const applyUpgrade = (upgrade: Upgrade, swapId?: string) => {
      const p = playerRef.current;

      if (swapId) {
          if (p.activeItem && p.activeItem.id === swapId) {
              p.activeItem = null;
          } else {
              p.autoItems = p.autoItems.filter(ai => ai.id !== swapId);
          }
      }

      if (upgrade.type === 'ITEM' && upgrade.itemRef) { p.activeItem = upgrade.itemRef; } 
      else if (upgrade.type === 'AUTO_ITEM' && upgrade.autoItemRef) { p.autoItems.push({ ...upgrade.autoItemRef }); } 
      else {
        if (upgrade.id.startsWith('dmg_')) p.stats.damage *= (upgrade.id.includes('rare') ? 1.25 : 1.12);
        if (upgrade.id.startsWith('atk_spd')) p.stats.attackSpeed += (upgrade.id.includes('rare') ? 0.20 : 0.10);
        if (upgrade.id.startsWith('pen_')) p.stats.armorPenetration += 8;
        if (upgrade.id.startsWith('hp_')) { const val = upgrade.id.includes('rare') ? 100 : 40; p.stats.maxHp += val; p.stats.hp += val; }
        if (upgrade.id.startsWith('def_')) p.stats.defense += (upgrade.id.includes('rare') ? 12 : 5);
        if (upgrade.id.startsWith('dmg_red')) p.stats.damageReduction += (upgrade.id.includes('epic') ? 0.10 : 0.05);
        if (upgrade.id.startsWith('ls_')) { let val = 0.001; if (upgrade.id.includes('rare')) val = 0.002; if (upgrade.id.includes('epic')) val = 0.004; p.stats.lifeSteal += val; }
        if (upgrade.id.startsWith('spd_')) p.stats.speed *= 1.1;
        if (upgrade.id.startsWith('cdr_')) p.stats.cooldownReduction = Math.min(0.7, p.stats.cooldownReduction + 0.08);
        if (upgrade.id.startsWith('area_')) p.stats.areaSize *= 1.2;
        if (upgrade.id.startsWith('dash_')) { const val = upgrade.id.includes('epic') ? 2 : 1; p.stats.dashChargesMax += val; p.dashCharges += val; }

        if (upgrade.id === 'pass_predator') { p.stats.critChance += 0.05; p.stats.critDamage += 0.2; }
        if (upgrade.id === 'pass_colossus') { p.stats.maxHp *= 1.25; p.stats.damageReduction += 0.05; p.stats.hp += 50; }
        if (upgrade.id === 'pass_hourglass') { p.stats.cooldownReduction += 0.15; }
        if (upgrade.id === 'pass_executioner') { p.stats.executionerThreshold = 0.15; }
        if (upgrade.id === 'pass_shadow') { p.stats.speed *= 1.1; p.stats.attackSpeed += 0.1; }
        if (upgrade.id === 'pass_ancient_blood') { p.stats.regen += 1.5; }
        if (upgrade.id === 'pass_living_mana') { p.stats.damage *= 1.1; } 
        if (upgrade.id === 'pass_guardian') { p.stats.shieldOnLowHp = true; }
        if (upgrade.id === 'pass_1000runes') { p.stats.damage *= 1.02; } 
        if (upgrade.id === 'pass_echo') { p.stats.towerEchoStacks++; }
      }
      setLastUpgrade(upgrade); setShowUpgrade(false); gameStateRef.current = GameState.TOWER;

      const currentConfig = WAVE_CONFIGS[waveRef.current] || WAVE_CONFIGS[WAVE_CONFIGS.length-1];
      if ((!currentConfig.boss && waveTimerRef.current >= currentConfig.duration) || (currentConfig.boss)) {
         if (p.stats.towerEchoStacks > 0) { p.stats.damage *= (1 + p.stats.towerEchoStacks * 0.01); p.stats.defense *= (1 + p.stats.towerEchoStacks * 0.01); } 
         waveRef.current++; waveTimerRef.current = 0; bossSpawnedRef.current = false;

         const levelIdx = Math.floor(waveRef.current / 5);
         const biome = LEVEL_CONFIGS[Math.min(levelIdx, LEVEL_CONFIGS.length-1)].biome;
         if (waveRef.current % 2 === 0) spawnTraps(biome); 
      }
  };

  // --- RENDER HELPERS ---
  const drawIsoSprite = (ctx: CanvasRenderingContext2D, entity: any, type: string) => {
      // TELEGRAPHING (Dash Path or Jump Zone)
      if (entity.state === 'WINDUP') {
          // Dash Telegraph
          if (entity.type.includes('WOLF') || entity.type.includes('DOG') || entity.type.includes('SHARK')) {
              const startIso = toIso(entity.startX || entity.x, entity.startY || entity.y, 0);
              const targetIso = toIso(entity.targetX || entity.x, entity.targetY || entity.y, 0);

              ctx.save();
              ctx.globalAlpha = 0.3;
              ctx.fillStyle = '#ef4444';
              // Draw a quad on floor
              ctx.beginPath();
              ctx.moveTo(startIso.x - 10, startIso.y);
              ctx.lineTo(targetIso.x - 10, targetIso.y);
              ctx.lineTo(targetIso.x + 10, targetIso.y);
              ctx.lineTo(startIso.x + 10, startIso.y);
              ctx.fill();
              ctx.restore();
          }
          // Jump Telegraph
          else if (entity.type.includes('SLIME') || entity.type.includes('SPIDER') || entity.type.includes('YETI') || entity.type.includes('FROG')) {
              if (entity.targetX) {
                  const targetIso = toIso(entity.targetX, entity.targetY, 0);
                  ctx.save();
                  ctx.fillStyle = '#ef4444';
                  ctx.globalAlpha = 0.3 + Math.sin(timeRef.current * 15) * 0.1;
                  ctx.beginPath();
                  ctx.ellipse(targetIso.x, targetIso.y, 30, 15, 0, 0, Math.PI * 2);
                  ctx.fill();
                  ctx.restore();
              }
          }
      }

      // Hit Flash
      if (entity.hitFlash && entity.hitFlash > 0) {
          const { x, y } = toIso(entity.x, entity.y, entity.z); 
          const w = 30; const h = 30;
          ctx.fillStyle = '#ffffff'; ctx.fillRect(x - w/2, y - h, w, h); return; 
      }

      const { x, y } = toIso(entity.x, entity.y, entity.z);
      const layers = 5;

      // 1. SLIMES (Round, Translucent)
      if (type.includes('SLIME')) {
          const wobble = Math.sin(entity.frame * 5) * 2;
          ctx.fillStyle = type.includes('POISON') ? 'rgba(132, 204, 22, 0.8)' : 'rgba(59, 130, 246, 0.8)';
          for(let i=0; i<3; i++) {
              ctx.beginPath();
              ctx.ellipse(x, y - i*6 + wobble, 15 - i*2, 10 - i, 0, 0, Math.PI*2);
              ctx.fill();
          }
          return;
      }
      // 2. WOLVES/DOGS
      if (type.includes('WOLF') || type.includes('DOG')) {
          const color = type.includes('ICE') ? '#cbd5e1' : '#78716c';
          ctx.fillStyle = color; ctx.fillRect(x - 15, y - 10, 30, 12);
          ctx.fillStyle = adjustColor(color, -20); ctx.fillRect(x + 10, y - 15, 12, 10);
          return;
      }
      // 3. SKELETONS
      if (type.includes('SKELETON')) {
          ctx.fillStyle = '#e2e8f0'; ctx.fillRect(x - 4, y - 18, 8, 14);
          ctx.fillStyle = '#f8fafc'; ctx.beginPath(); ctx.arc(x, y - 24, 6, 0, Math.PI*2); ctx.fill();
          return;
      }
      // 4. GOBLINS
      if (type.includes('GOBLIN')) {
          ctx.fillStyle = '#15803d'; ctx.fillRect(x - 8, y - 12, 16, 12);
          ctx.fillStyle = '#22c55e'; ctx.beginPath(); ctx.arc(x, y - 18, 7, 0, Math.PI*2); ctx.fill();
          return;
      }
      // 5. BATS/HARPIES
      if (type.includes('BAT') || type.includes('HARPY')) {
          ctx.fillStyle = '#1e293b'; ctx.beginPath(); ctx.arc(x, y - 10, 6, 0, Math.PI*2); ctx.fill(); 
          const flap = Math.sin(entity.frame * 20) * 10;
          ctx.fillStyle = '#334155'; ctx.beginPath(); ctx.moveTo(x, y-10); ctx.lineTo(x-15, y-15-flap); ctx.lineTo(x-5, y); ctx.fill(); ctx.beginPath(); ctx.moveTo(x, y-10); ctx.lineTo(x+15, y-15-flap); ctx.lineTo(x+5, y); ctx.fill();
          return;
      }
      // 6. GOLEMS
      if (type.includes('GOLEM')) {
          const color = '#57534e'; ctx.fillStyle = color; ctx.fillRect(x - 10, y - 10, 8, 10); ctx.fillRect(x + 2, y - 10, 8, 10); ctx.fillStyle = adjustColor(color, 20); ctx.fillRect(x - 15, y - 35, 30, 25); ctx.fillStyle = adjustColor(color, 40); ctx.fillRect(x - 8, y - 45, 16, 10);
          return;
      }
      // 7. SNAKES
      if (type.includes('SNAKE') || type.includes('WORM')) {
          for(let i=0; i<5; i++) { const sway = Math.sin(entity.frame * 10 + i * 2) * 5; ctx.fillStyle = i===0 ? '#facc15' : '#a16207'; ctx.beginPath(); ctx.arc(x + sway, y - i*4, 6 - i*0.5, 0, Math.PI*2); ctx.fill(); }
          return;
      }
      // 8. PLAYER
      if (type === 'PLAYER') {
          const scale = 1;
          for(let i=0; i<layers; i++) {
             const ly = y - (i * scale * 2); let w = 20; 
             if (entity.archetype === Archetype.WARRIOR) { w = 20; let color = '#334155'; if (i >= 5) { color = '#1d4ed8'; w = 16; } if (i === 4) { color = '#94a3b8'; w = 22; } ctx.fillStyle = color; ctx.fillRect(x - w/2, ly - w/2, w, w); } 
             else if (entity.archetype === Archetype.MAGE) { w = 18; let color = '#581c87'; if (i >= 5) { color = '#a855f7'; w = 12; } if (i === 6) { w = 8; } ctx.fillStyle = color; ctx.fillRect(x - w/2, ly - w/2, w, w); } 
             else { w = 16; let color = '#15803d'; if (i >= 5) { color = '#86efac'; w = 14; } ctx.fillStyle = color; ctx.fillRect(x - w/2, ly - w/2, w, w); }
          }
          return;
      }
      // Static
      if (['TREE', 'HOUSE', 'PORTAL', 'LAMP', 'ROCK', 'BUSH'].includes(type)) {
          if (type === 'TREE') { ctx.fillStyle = '#271306'; ctx.fillRect(x - 4, y - 20, 8, 20); ctx.fillStyle = entity.variant === 1 ? '#14532d' : '#166534'; ctx.beginPath(); ctx.moveTo(x - 15, y - 15); ctx.lineTo(x, y - 50); ctx.lineTo(x + 15, y - 15); ctx.fill(); } 
          else if (type === 'PORTAL') { ctx.fillStyle = '#312e81'; ctx.beginPath(); ctx.ellipse(x, y, 30, 10, 0, 0, Math.PI*2); ctx.fill(); }
          else { ctx.fillStyle = '#57534e'; ctx.fillRect(x - 10, y - 10, 20, 10); }
          return;
      }
      if (type.includes('BOSS')) {
          const w = 60; const h = 60; ctx.fillStyle = entity.bossColor || '#000'; ctx.fillRect(x - w/2, y - h, w, h); ctx.fillStyle = '#fff'; ctx.fillRect(x - 15, y - 40, 10, 10); ctx.fillRect(x + 5, y - 40, 10, 10);
      } else { ctx.fillStyle = '#94a3b8'; ctx.fillRect(x - 10, y - 20, 20, 20); }
  };

  const draw = (dt: number) => {
    const canvas = canvasRef.current; if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false }); if (!ctx) return;
    if(canvas.width !== CANVAS_WIDTH || canvas.height !== CANVAS_HEIGHT) { canvas.width = CANVAS_WIDTH; canvas.height = CANVAS_HEIGHT; }

    const cx = CANVAS_WIDTH / 2;
    const cy = CANVAS_HEIGHT / 2;

    ctx.fillStyle = COLORS.background; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    const shakeX = (Math.random() - 0.5) * shakeRef.current; const shakeY = (Math.random() - 0.5) * shakeRef.current;

    ctx.save();
    ctx.translate(CANVAS_WIDTH/2, CANVAS_HEIGHT/2); ctx.scale(ZOOM_LEVEL, ZOOM_LEVEL); ctx.translate(Math.floor(cameraRef.current.x + shakeX), Math.floor(cameraRef.current.y + shakeY));

    // --- TERRAIN RENDER ---
    const tileSize = 100; const pX = playerRef.current.x; const pY = playerRef.current.y; const range = 18; const px = Math.floor(pX / tileSize); const py = Math.floor(pY / tileSize);
    const biome = hudData.biome || 'DEFAULT'; const biomeSet = BIOME_COLORS[biome] || BIOME_COLORS.DEFAULT;

    for (let i = px - range; i <= px + range; i++) {
        for (let j = py - range; j <= py + range; j++) {
            const wx = i * tileSize; const wy = j * tileSize;
            if (Math.hypot(wx - pX, wy - pY) > 1500) continue;
            const iso = toIso(wx, wy, 0); const screenX = (iso.x + cameraRef.current.x) * ZOOM_LEVEL + CANVAS_WIDTH/2; const screenY = (iso.y + cameraRef.current.y) * ZOOM_LEVEL + CANVAS_HEIGHT/2;
            if (screenX < -200 || screenX > CANVAS_WIDTH + 200 || screenY < -200 || screenY > CANVAS_HEIGHT + 200) continue;

            let color = biomeSet.grass; let topColor = biomeSet.highlight; let h = 0; const tileNoise = pseudoRandom(i, j); 
            if (gameStateRef.current === GameState.ISLAND) {
                 if (Math.hypot(wx, wy + 200) < 1200) { color = COLORS.grass; topColor = COLORS.grassHighlight; if (Math.abs(wx) < 100 || Math.abs(wy + 200) < 100) { color = COLORS.stone; topColor = COLORS.stoneHighlight; } } 
                 else { color = COLORS.water; topColor = COLORS.waterHighlight; h = -20; }
                 if (Math.hypot(wx - PORTAL_POS.x, wy - PORTAL_POS.y) < 180) { color = '#312e81'; topColor = '#4338ca'; h = 5; }
            } else { color = biomeSet.water; topColor = (tileNoise - Math.floor(tileNoise)) > 0.8 ? biomeSet.grass : biomeSet.highlight; if (Math.abs(wx) > 900 || Math.abs(wy) > 900) { h = -100; color = '#000'; topColor = '#000'; } }

            if (h > -50 && h !== 0) { ctx.fillStyle = adjustColor(color, -20); ctx.beginPath(); ctx.moveTo(iso.x + tileSize, iso.y - h + tileSize/2); ctx.lineTo(iso.x + tileSize, iso.y + tileSize/2); ctx.lineTo(iso.x, iso.y + tileSize); ctx.lineTo(iso.x, iso.y - h + tileSize); ctx.fill(); }
            ctx.beginPath(); ctx.moveTo(iso.x, iso.y - h); ctx.lineTo(iso.x + tileSize, iso.y - h + tileSize/2); ctx.lineTo(iso.x, iso.y - h + tileSize); ctx.lineTo(iso.x - tileSize, iso.y - h + tileSize/2); ctx.fillStyle = topColor; ctx.fill();
        }
    }

    // Entities Render
    const renderList: any[] = [];
    renderList.push({ type: 'PLAYER', obj: playerRef.current, y: toIso(playerRef.current.x, playerRef.current.y).y });
    const cullingDist = 1800; 
    for(const e of enemiesRef.current) { if (Math.abs(e.x - pX) < cullingDist && Math.abs(e.y - pY) < cullingDist) renderList.push({ type: e.type, obj: e, y: toIso(e.x, e.y).y }); }
    for(const t of trapsRef.current) { if (Math.abs(t.x - pX) < cullingDist && Math.abs(t.y - pY) < cullingDist) renderList.push({ type: t.type, obj: t, y: toIso(t.x, t.y).y }); }
    for(const p of particlesRef.current) { renderList.push({ type: p.type || 'PARTICLE', obj: p, y: toIso(p.x, p.y).y }); }
    if (gameStateRef.current === GameState.ISLAND) { staticObjectsRef.current.forEach(obj => { if (Math.abs(obj.x - pX) < cullingDist && Math.abs(obj.y - pY) < cullingDist) renderList.push({ type: obj.type, obj, y: toIso(obj.x, obj.y).y }); }); }
    renderList.sort((a, b) => a.y - b.y);

    for (const item of renderList) {
        if (['PARTICLE','RAIN','BLOOD','SPARK','POISON','TELEPORT','TRAIL','MAGIC','FIRE','IMPACT','FOG','SAND','SNOW','ASH'].includes(item.type)) {
             const { x, y } = toIso(item.obj.x, item.obj.y, item.obj.z); ctx.fillStyle = item.obj.color;
             if (item.type === 'RAIN') { const windX = windForceRef.current.x * 15; ctx.strokeStyle = item.obj.color; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x-2 + windX, y+15); ctx.stroke(); } 
             else if (item.type === 'IMPACT') { ctx.globalAlpha = item.obj.life / item.obj.maxLife; ctx.beginPath(); ctx.arc(x, y, item.obj.size, 0, Math.PI*2); ctx.fill(); ctx.globalAlpha = 1.0; }
             else { ctx.beginPath(); ctx.arc(x, y, item.obj.size, 0, Math.PI*2); ctx.fill(); }
        } else {
             drawIsoSprite(ctx, item.obj, item.type);
             if (item.obj.hp < item.obj.maxHp && item.obj.hp > 0 && !['PARTICLE','SPIKES','LAVA','POISON_VENT','BEAR_TRAP'].includes(item.type)) {
                 const isBoss = item.type.includes('BOSS'); const offsetZ = isBoss ? 150 : (item.type.includes('BAT') ? 80 : 40); const { x, y } = toIso(item.obj.x, item.obj.y, item.obj.z + offsetZ); const w = isBoss ? 120 : 20; const h = isBoss ? 6 : 3;
                 ctx.fillStyle = '#0f172a'; ctx.fillRect(x - w/2, y - 5, w, h); ctx.fillStyle = '#b91c1c'; ctx.fillRect(x - w/2, y - 5, w * (item.obj.hp/item.obj.maxHp), h); 
             }
             if (item.obj.frozenTimer > 0) { const { x, y } = toIso(item.obj.x, item.obj.y, item.obj.z + 20); ctx.fillStyle = 'rgba(200, 240, 255, 0.5)'; ctx.beginPath(); ctx.arc(x, y, item.obj.radius, 0, Math.PI*2); ctx.fill(); }
        }
    }

    for(const p of projectilesRef.current) {
        const { x, y } = toIso(p.x, p.y, p.z); ctx.fillStyle = p.color; ctx.shadowBlur = 10; ctx.shadowColor = p.color;
        if (p.type === 'SWORD_SLASH') { const progress = 1 - (p.duration / 0.3); ctx.strokeStyle = '#fff'; ctx.lineWidth = 4 * (1 - progress); ctx.beginPath(); ctx.ellipse(x, y, p.radius, p.radius*0.5, 0, 0, Math.PI*2); ctx.stroke(); } 
        else if (p.type === 'FIRE_ZONE' || p.type === 'GODDESS_SEAL') { const pulse = 1 + Math.sin(timeRef.current * 10) * 0.1; ctx.fillStyle = p.type === 'GODDESS_SEAL' ? 'rgba(216, 180, 254, 0.3)' : 'rgba(220, 38, 38, 0.2)'; ctx.beginPath(); ctx.ellipse(x, y, p.radius * pulse, p.radius * 0.5 * pulse, 0, 0, Math.PI*2); ctx.fill(); } 
        else if (p.type === 'ARROW' || p.type === 'MAGIC_ORB' || p.type === 'ENEMY_BOLT') { const tailX = x - p.vx * 0.04; const tailY = y - p.vy * 0.04; ctx.strokeStyle = p.color; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(tailX, tailY); ctx.stroke(); ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI*2); ctx.fill(); } 
        else { ctx.beginPath(); ctx.arc(x, y, 4, 0, Math.PI*2); ctx.fill(); }
        ctx.shadowBlur = 0;
    }

    ctx.restore(); 

    // Weather Visuals
    const isFog = weatherTypeRef.current === 'FOG'; const isSandstorm = weatherTypeRef.current === 'SANDSTORM';
    if (gameStateRef.current === GameState.TOWER && (isFog || isSandstorm) && weatherIntensityRef.current > 0.1) {
        const grad = ctx.createRadialGradient(cx, cy, 100, cx, cy, 350 * 2.5);
        grad.addColorStop(0, `rgba(200, 215, 210, 0)`); grad.addColorStop(1, isSandstorm ? `rgba(180, 130, 80, 0.9)` : `rgba(200, 215, 210, 0.9)`);
        ctx.fillStyle = grad; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    }

    // Player Aim Line (Desktop only)
    if (!isMobile) {
        const pIso = toIso(playerRef.current.x, playerRef.current.y);
        const playerScreenX = cx + (cameraRef.current.x + shakeX + pIso.x) * ZOOM_LEVEL;
        const playerScreenY = cy + (cameraRef.current.y + shakeY + pIso.y - (playerRef.current.z || 0)) * ZOOM_LEVEL;
        const mouseScreenX = cx + mouseScreenRef.current.x; const mouseScreenY = cy + mouseScreenRef.current.y;
        ctx.save(); ctx.strokeStyle = 'rgba(255, 255, 255, 0.2)'; ctx.setLineDash([4, 4]); ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(playerScreenX, playerScreenY - 20); ctx.lineTo(mouseScreenX, mouseScreenY); ctx.stroke(); ctx.restore();
    }

    // Damage Numbers
    for(const dn of damageNumbersRef.current) { const pos = toIso(dn.x, dn.y, dn.z); const sx = cx + (pos.x + cameraRef.current.x) * ZOOM_LEVEL; const sy = cy + (pos.y + cameraRef.current.y) * ZOOM_LEVEL; ctx.fillStyle = dn.isPlayerDamage ? '#ef4444' : (dn.isCrit ? '#fbbf24' : 'white'); ctx.strokeStyle = '#020617'; ctx.lineWidth = 4; ctx.lineJoin = 'round'; const offset = (1 - dn.life) * 80; const alpha = Math.min(1, dn.life * 3); ctx.save(); ctx.globalAlpha = alpha; ctx.translate(sx, sy - offset); ctx.font = 'bold 20px "Cinzel", serif'; const text = Math.floor(dn.value).toString(); ctx.strokeText(text, 0, 0); ctx.fillText(text, 0, 0); ctx.restore(); }
  };

  const formatTime = (s: number) => `${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;

  return (
    <div className="relative w-full h-full bg-[#020617] cursor-none select-none overflow-hidden font-mono touch-none">
      <canvas ref={canvasRef} className="block w-full h-full cursor-none touch-none" />

      {/* --- HUD --- */}
      <div className={`absolute inset-x-0 bottom-6 flex flex-col items-center pointer-events-none z-10 transition-transform origin-bottom ${isMobile ? 'scale-[0.65] bottom-20' : 'scale-[0.80]'}`}>
          {hudData.bossHp > 0 && (
              <div className="mb-10 w-[700px] pointer-events-none animate-in fade-in slide-in-from-top-10 duration-700">
                  <div className="flex justify-between items-end text-red-500 font-bold mb-2 px-4 uppercase tracking-widest font-serif drop-shadow-md">
                      <span className="text-2xl">{enemiesRef.current.find(e => e.isBoss)?.type === 'BOSS_GOBLIN' ? 'Rei Goblin' : 'Terror da Torre'}</span>
                      <span className="text-sm opacity-80">{Math.ceil(hudData.bossHp)}/{Math.ceil(hudData.bossMaxHp)}</span>
                  </div>
                  <div className="relative h-6 w-full bg-slate-900 border-2 border-slate-700 rounded-sm shadow-[0_0_30px_rgba(220,38,38,0.3)] overflow-hidden">
                      <div className="absolute inset-0 bg-red-950/50"></div>
                      <div className="h-full bg-gradient-to-r from-red-900 via-red-600 to-red-500 transition-all duration-200" style={{width: `${(hudData.bossHp/hudData.bossMaxHp)*100}%`}}></div>
                  </div>
              </div>
          )}

          <div className="flex items-end gap-6 pb-2">
              <div className="bg-slate-900/95 border border-slate-700 rounded-2xl p-5 backdrop-blur-md shadow-2xl w-72 transform transition-transform">
                   <div className="flex items-center justify-between gap-2 text-white font-bold text-2xl mb-3 font-serif">
                       <span className="flex items-center gap-2 text-red-400"><Heart fill="currentColor" /> {Math.ceil(hudData.hp)}</span>
                       <span className="text-sm font-mono text-slate-500">LVL {hudData.level}</span>
                   </div>
                   <div className="relative h-4 bg-slate-950 rounded-full overflow-hidden border border-slate-800 mb-2 shadow-inner">
                       <div className="h-full bg-gradient-to-r from-red-800 to-red-500 transition-all duration-300" style={{width: `${(hudData.hp/hudData.maxHp)*100}%`}}></div>
                   </div>
                   <div className="flex justify-between text-[10px] text-slate-400 font-mono tracking-wide uppercase">
                       <span>XP Progresso</span>
                       <span className="text-amber-500">{Math.floor(hudData.xp)} / {Math.floor(hudData.xpNext)}</span>
                   </div>
                   <div className="mt-1 h-1 w-full bg-slate-800 rounded-full overflow-hidden">
                       <div className="h-full bg-amber-500 shadow-[0_0_10px_#f59e0b]" style={{width: `${(hudData.xp/hudData.xpNext)*100}%`}}></div>
                   </div>
              </div>

              {!isMobile && (
              <div className="flex gap-3 p-4 bg-slate-900/95 border border-slate-700 rounded-2xl backdrop-blur-md shadow-2xl">
                  {/* ... Existing Desktop Skills HUD ... */}
                  <div className="w-20 h-20 bg-slate-800 rounded-xl border border-slate-600 flex flex-col items-center justify-center grayscale opacity-60">
                      <Sword size={32} />
                  </div>
                  <div className={`relative w-20 h-20 rounded-xl border-2 flex flex-col items-center justify-center overflow-hidden transition-all duration-200
                      ${hudData.skill1Cd <= 0 ? 'bg-blue-950/80 border-blue-400 shadow-[0_0_15px_rgba(59,130,246,0.3)]' : 'bg-slate-800 border-slate-700 grayscale'}`}>
                      <Crosshair size={32} className={hudData.skill1Cd <= 0 ? "text-blue-400" : "text-slate-500"} />
                      <span className="absolute bottom-1 right-2 text-[10px] font-bold text-slate-400">Q</span>
                      {hudData.skill1Cd > 0 && <div className="absolute inset-0 bg-black/70 flex items-center justify-center font-bold text-white text-2xl font-mono animate-in fade-in">{Math.ceil(hudData.skill1Cd)}</div>}
                  </div>
                  <div className={`relative w-20 h-20 rounded-xl border-2 flex flex-col items-center justify-center overflow-hidden transition-all duration-200
                      ${hudData.dashCharges > 0 ? 'bg-emerald-950/80 border-emerald-400 shadow-[0_0_15px_rgba(52,211,153,0.3)]' : 'bg-slate-800 border-slate-700 grayscale'}`}>
                      <Wind size={32} className={hudData.dashCharges > 0 ? "text-emerald-400" : "text-slate-500"} />
                      <span className="absolute bottom-1 right-2 text-[10px] font-bold text-slate-400">E</span>
                      <div className="absolute top-2 left-0 right-0 flex justify-center gap-1">
                          {Array.from({length: Math.max(hudData.dashMax, 2)}).map((_, i) => (
                             <div key={i} className={`w-2 h-2 rounded-full shadow-sm transition-colors duration-300 ${i < hudData.dashCharges ? 'bg-emerald-400 shadow-[0_0_8px_#34d399]' : 'bg-slate-700 border border-slate-600'}`}></div>
                          ))}
                      </div>
                      {hudData.dashCd > 0 && hudData.dashCharges < hudData.dashMax && <div className="absolute inset-0 bg-black/70 flex items-center justify-center font-bold text-white text-2xl font-mono">{Math.ceil(hudData.dashCd)}</div>}
                  </div>
                  <div className={`relative w-20 h-20 rounded-xl border-2 flex flex-col items-center justify-center overflow-hidden transition-all duration-200
                      ${hudData.activeItem ? 'bg-amber-950/60 border-amber-500' : 'bg-slate-900 border-slate-800 opacity-40 border-dashed'}`}>
                      {hudData.activeItem ? (<> <span className="text-3xl filter drop-shadow-lg">{hudData.activeItem.icon}</span> <span className="absolute bottom-1 right-2 text-[10px] font-bold text-amber-200">R</span> </>) : <Box size={24} className="text-slate-600" />}
                      {hudData.itemCd > 0 && <div className="absolute inset-0 bg-black/70 flex items-center justify-center font-bold text-white text-2xl font-mono">{Math.ceil(hudData.itemCd)}</div>}
                  </div>
              </div>
              )}

              <div className="flex flex-col gap-2">
                 {hudData.autoItems.map((item, idx) => (
                    <div key={idx} className={`w-12 h-12 border rounded-lg flex items-center justify-center relative overflow-hidden
                       ${item.id.includes('leg_') ? 'bg-amber-950/60 border-amber-500/50 shadow-amber-500/20 shadow-lg' : 'bg-purple-950/60 border-purple-500/50'}
                    `}>
                        <span className="text-xl z-10">{item.icon}</span>
                        <div className={`absolute bottom-0 left-0 h-1 transition-all duration-100 ${item.id.includes('leg_') ? 'bg-amber-400' : 'bg-purple-400'}`} style={{width: `${(1 - (item.timer / item.cooldown)) * 100}%`}}></div>
                    </div>
                 ))}
                 {hudData.autoItems.length === 0 && <div className="w-12 h-12 border border-slate-800 border-dashed rounded-lg flex items-center justify-center opacity-30"><Zap size={16} /></div>}
              </div>

              {hudData.state === GameState.TOWER && (
                  <div className="bg-slate-900/95 border border-slate-700 rounded-2xl p-5 backdrop-blur-md shadow-2xl w-40 text-center flex flex-col justify-center h-[124px]">
                      <div className="text-3xl font-mono font-bold text-white mb-2 tracking-widest">{formatTime(hudData.time)}</div>
                      <div className="text-xs text-slate-400 flex items-center justify-center gap-2 font-serif uppercase tracking-wider border-t border-slate-800 pt-2">
                          <Skull size={14} className="text-red-500" /> WAVE {hudData.wave}
                      </div>
                      {hudData.weather !== 'NONE' && (
                          <div className={`text-[10px] animate-pulse mt-1 font-serif font-bold uppercase
                              ${hudData.weather === 'RAIN' ? 'text-blue-300' : ''}
                              ${hudData.weather === 'STORM' ? 'text-purple-300' : ''}
                              ${hudData.weather === 'SANDSTORM' ? 'text-amber-500' : ''}
                              ${hudData.weather === 'FOG' ? 'text-emerald-200' : ''}
                              ${hudData.weather === 'WIND' ? 'text-slate-300' : ''}
                              ${hudData.weather === 'SNOW' ? 'text-white' : ''}
                              ${hudData.weather === 'ASH' ? 'text-gray-400' : ''}
                          `}>
                              {hudData.weather === 'SANDSTORM' ? 'Tempestade de Areia' : 
                               hudData.weather === 'FOG' ? 'Neblina Densa' :
                               hudData.weather === 'WIND' ? 'Vendaval' :
                               hudData.weather === 'SNOW' ? 'Nevasca' :
                               hudData.weather === 'ASH' ? 'Chuva de Cinzas' :
                               hudData.weather === 'STORM' ? 'Tempestade' : 'Chuva'}
                          </div>
                      )}
                  </div>
              )}
          </div>
      </div>

      {/* --- MOBILE CONTROLS OVERLAY --- */}
      {isMobile && gameStateRef.current === GameState.TOWER && (
        <div className="absolute inset-0 z-40 pointer-events-none touch-none">
            {/* VIRTUAL JOYSTICK AREA */}
            <div 
                className="absolute bottom-8 left-8 w-48 h-48 bg-white/5 border-2 border-white/10 rounded-full flex items-center justify-center pointer-events-auto backdrop-blur-sm touch-none"
                onTouchStart={handleJoystickStart}
                onTouchMove={handleJoystickMove}
                onTouchEnd={handleJoystickEnd}
            >
                <div 
                   className="w-16 h-16 bg-white/20 rounded-full shadow-[0_0_15px_rgba(255,255,255,0.2)]"
                   style={{
                       transform: `translate(${joystickRef.current.vectorX * 50}px, ${joystickRef.current.vectorY * 50}px)`
                   }}
                ></div>
                <Move className="absolute text-white/20" size={32} />
            </div>

            {/* ACTION BUTTONS */}
            <div className="absolute bottom-8 right-8 flex gap-4 items-end pointer-events-auto">
                 {/* Skill 1 (Q) */}
                 <button 
                    className={`w-20 h-20 rounded-full border-4 flex items-center justify-center active:scale-95 transition-transform bg-slate-900/80 backdrop-blur
                       ${hudData.skill1Cd <= 0 ? 'border-blue-400 text-blue-400 shadow-[0_0_20px_rgba(59,130,246,0.4)]' : 'border-slate-600 text-slate-600 bg-slate-800'}
                    `}
                    onTouchStart={() => handleMobileSkill('Q')}
                 >
                    {hudData.skill1Cd > 0 
                      ? <span className="text-xl font-bold">{Math.ceil(hudData.skill1Cd)}</span> 
                      : <Crosshair size={32} />
                    }
                 </button>

                 {/* Dash (E) */}
                 <button 
                    className={`w-16 h-16 rounded-full border-4 flex items-center justify-center active:scale-95 transition-transform bg-slate-900/80 backdrop-blur mb-12
                       ${hudData.dashCharges > 0 ? 'border-emerald-400 text-emerald-400 shadow-[0_0_20px_rgba(52,211,153,0.4)]' : 'border-slate-600 text-slate-600 bg-slate-800'}
                    `}
                    onTouchStart={() => handleMobileSkill('E')}
                 >
                    {hudData.dashCharges > 0 
                      ? <Wind size={28} />
                      : (hudData.dashCd > 0 ? <span className="text-sm font-bold">{Math.ceil(hudData.dashCd)}</span> : <Wind size={28} />)
                    }
                    {hudData.dashCharges > 0 && <span className="absolute -top-2 -right-2 bg-emerald-500 text-black text-xs font-bold w-5 h-5 rounded-full flex items-center justify-center">{hudData.dashCharges}</span>}
                 </button>

                 {/* Item (R) */}
                 <button 
                    className={`w-20 h-20 rounded-full border-4 flex items-center justify-center active:scale-95 transition-transform bg-slate-900/80 backdrop-blur
                       ${hudData.activeItem && hudData.itemCd <= 0 ? 'border-amber-400 text-amber-400 shadow-[0_0_20px_rgba(251,191,36,0.4)]' : 'border-slate-700 text-slate-700 bg-slate-800 opacity-50'}
                    `}
                    onTouchStart={() => handleMobileSkill('R')}
                 >
                     {hudData.itemCd > 0 
                       ? <span className="text-xl font-bold">{Math.ceil(hudData.itemCd)}</span>
                       : (hudData.activeItem ? <span className="text-3xl">{hudData.activeItem.icon}</span> : <Box size={32} />)
                     }
                 </button>
            </div>
        </div>
      )}

      {hudData.buffTime > 0 && (
          <div className="absolute top-20 w-full flex justify-center pointer-events-none">
               <div className="bg-amber-500/20 border border-amber-400/50 px-6 py-2 rounded-full backdrop-blur-sm text-amber-200 font-bold animate-pulse shadow-[0_0_20px_rgba(251,191,36,0.4)]">
                   AVATAR DA DEUSA: {Math.ceil(hudData.buffTime)}s
               </div>
          </div>
      )}

      {hudData.state === GameState.ISLAND && (
          <div className="absolute top-20 w-full text-center pointer-events-none animate-bounce">
              <span className="bg-slate-900/90 px-8 py-4 rounded-full text-slate-100 border border-blue-500/50 shadow-[0_0_20px_rgba(59,130,246,0.4)] font-serif tracking-widest text-lg">
                  Siga para o Portal Azul
              </span>
          </div>
      )}

      {showUpgrade && (
        <UpgradeModal options={upgradeOptions} memoryOption={lastUpgrade} onSelect={applyUpgrade} currentLegendaries={getLegendaryItems()} />
      )}
    </div>
  );
};
